/****** Object:  View [dbo].[DynamicListofZedPaymentReceived]    Script Date: 9/19/2026 4:33:05 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create view  [dbo].[DynamicListofZedPaymentReceived] as
SELECT m.ZedId,P.Certification, PUnitName PUnitName,m.pstatename StateName,m.PDistrictName DistrictName,m.EnterpriseTypee Size,case when (M.IsCouponUsed)=1 then 'Yes' when IsCouponUsed is null then 'No' end as JoiningReward,
		B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName,
		P.GstinNumber, P.TanNumber, P.UtrNumber, P.Id TransactionId, P.TransactionStatus,convert(varchar, P.CreatedDate, 9) as TransactionDate, P.PaymentType, P.SubsidyPercentage,P.Tds,ISNULL(Amount,0) AmountPaid
		--Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments
		
	FROM MsmePaymentInfo P inner join Msme M on (P.ZedId=M.ZedId)
	inner join MsmeBasicInformation B on (P.ZedId=B.ZedId )
	left join PaymentGateWayTransactions T on (M.ZedId=T.ZedId and P.Certification=T.Certification and PaymentStatus='Success')
	WHERE P.ZedId=M.ZedId AND M.ZedId=B.ZedId 
	
GO
