create PROCEDURE [dbo].[SP_ADD_CERTIFICATION_ID] --'<redacted>', '<redacted>', '<redacted>'
(
	
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
	
)
AS
BEGIN
	
	SET NOCOUNT ON;

				DECLARE @CertificationTblId int = NULL
				select @CertificationTblId=Id from MsmeCertifications where ZedId=@ZedId and Certification=@Certification

				update SaRequirementPhotos SET SaReqCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND SaReqCertId IS NULL
