				update PaymentGateWayTransactions SET PmtGtCertId=@CertificationTblId WHERE ZedId=@ZedId AND Certification=@Certification AND PmtGtCertId IS NULL

				--IF EXISTS(select * from MsmeBasicInformation where ZedId=@ZedId and ReCertificationLevel=@Certification and ReCertification>0)
