/****** Object:  StoredProcedure [dbo].[SP_API_FINANCE_GET_INVOICE_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_API_FINANCE_GET_INVOICE_DETAILS] '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_API_FINANCE_GET_INVOICE_DETAILS] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
	
	--DECLARE @Etag varchar(50) = NULL
	--SELECT @Etag = JSON_VALUE(SuccessResponse, '<redacted>') FROM ApiFinanceUnitDetailsResponse where ZedId=@ZedId and ApiType='<redacted>' and StatusCode='<redacted>'

	IF NOT EXISTS (SELECT * FROM ZEDCS_V2_LIVE.dbo.ApiFinanceUnitDetailsResponse where ZedId=@ZedId AND Certification=@Certification and ApiType='InvoiceData' and StatusCode='Created' AND ModuleName='SURVEILLANCE')

	AND EXISTS (SELECT * FROM MsmeBasicInformation WHERE ZedId=@ZedId and UdyogAadharNo not IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	)
	BEGIN
		select top 1
		--convert(date,P.CreatedDate) AS Posting_Date,
		format(P.CreatedDate, 'yyyy-MM-dd') AS Posting_Date,
		NULL AS Error_Text,
		'ZED' AS Board,
		'NDIE' AS Portal,
		M.ZedId AS Login_Name,
		format(P.CreatedDate, 'yyyy-MM-dd') AS Voucher_Date,
		'NDIE' AS Location_Code,
		--'<redacted>' AS Line_Comments,
		CONCAT('ZED "',P.Certification,'" Surveillance Fee (',M.ZedId,')') AS Line_Comments,
		NULL [NABL4],
		1 AS Quantity,
		NULL AS Ledger_Name,
		0 AS Ledger_Amount,
		'ASSESSMENT FEE' AS TA_DA_LedgerName,
		NULL AS Assessor_Name,
		NULL AS Assessor_ID,
		NULL AS Assessor_Type,
		NULL AS Discipline_Name,
		CASE WHEN P.Certification='Bronze' then 'ZMS - ZED BRONZE SURVEILLANCE' 
		WHEN P.Certification='Silver' then 'ZMS - ZED SILVER SURVEILLANCE'
		WHEN P.Certification='Gold' then 'ZMS - ZED GOLD SURVEILLANCE' END AS Sub_Discipline_Name,
		NULL AS Other_Discipline,
		NULL AS Assessment_Period_From,
		NULL AS Assessment_Period_To,
		NULL AS Due_Period_Start_From,
		NULL AS Due_Period_Period_To,
		NULL AS TADA_Amount,
		P.SubsidyAmount AS Other_Amount,
		NULL AS Overhead_Charges,
		NULL AS Invoice_No,
		P.TadaInvoiceNo AS TADA_Invoice_No,
		NULL AS Assessment_Type,
		NULL AS HONORARIUM_Yes_No,
		convert(varchar,P.Id) Entry_No,
		'' Etag

		from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		inner join msmepaymentinfo P on (M.ZedId=P.ZedId) 
		inner join PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and T.PaymentStatus='SUCCESS') 
		where M.ZedId=@ZedId and P.Certification=@Certification order by P.Id desc
	END

	ELSE
	BEGIN
		SELECT 
		NULL AS Posting_Date,
		NULL AS Error_Text,
		NULL AS Board,
		NULL AS Portal,
		NULL AS Login_Name,
		NULL AS Voucher_Date,
		NULL AS Location_Code,
		NULL AS Line_Comments,
		NULL [NABL4],
		NULL AS Quantity,
		NULL AS Ledger_Name,
		NULL AS Ledger_Amount,
		NULL AS TA_DA_LedgerName,
		NULL AS Assessor_Name,
		NULL AS Assessor_ID,
		NULL AS Assessor_Type,
		NULL AS Discipline_Name,
		NULL AS Sub_Discipline_Name,
		NULL AS Other_Discipline,
		NULL AS Assessment_Period_From,
		NULL AS Assessment_Period_To,
		NULL AS Due_Period_Start_From,
		NULL AS Due_Period_Period_To,
		NULL AS TA_DA_Amount,
		NULL AS Other_Amount,
		NULL AS Overhead_Charges,
		NULL AS Invoice_No,
		NULL AS TADA_Invoice_No,
		NULL AS Assessment_Type,
		NULL AS HONORARIUM_Yes_No,
		NULL AS Entry_No,
		NULL AS Etag
		WHERE 
			1=2
	END
END

GO
/****** Object:  StoredProcedure [dbo].[SP_API_FINANCE_GET_RECEIPT_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_API_FINANCE_GET_RECEIPT_DETAILS] '<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_API_FINANCE_GET_RECEIPT_DETAILS] --'<redacted>','<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	--DECLARE @Etag varchar(50) = NULL
	--SELECT @Etag = JSON_VALUE(SuccessResponse, '<redacted>') FROM ApiFinanceUnitDetailsResponse where ZedId=@ZedId and ApiType='<redacted>' and StatusCode='<redacted>'

	IF NOT EXISTS (SELECT * FROM ZEDCS_V2_LIVE.dbo.ApiFinanceUnitDetailsResponse where ZedId=@ZedId AND Certification=@Certification and ApiType='ReceiptData' and StatusCode='Created' AND ModuleName='SURVEILLANCE')

	AND EXISTS (SELECT * FROM MsmeBasicInformation WHERE ZedId=@ZedId and UdyogAadharNo not IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476'))
	BEGIN
		select top 1
		format(P.CreatedDate, 'yyyy-MM-dd') Posting_Date,
		NULL Error_Text,
		convert(varchar,T.Id) Order_ID,
		M.ZedId Reference_ID,
		'ZED' Board,
		convert(bit,CASE WHEN P.TdsDeductible='Yes' then 1 ELSE 0 END) AS TDS_Deducted,
		  SUBSTRING(
			paymentresponse,
			CHARINDEX('payment_mode=', paymentresponse) + LEN('payment_mode='),
			CHARINDEX('&', paymentresponse + '&', CHARINDEX('payment_mode=', paymentresponse)) 
			  - (CHARINDEX('payment_mode=', paymentresponse) + LEN('payment_mode='))
		  ) AS  Payment_Mode,
		P.TanNumber [TAN],
		CASE 
		WHEN P.Tds = 1.5 THEN NetPaybleTds15
		WHEN P.Tds = 7.5 THEN NetPaybleTds75
		ELSE P.ApplicantContributionAfterSubsidy 
		END AS Amount_Received,
		P.ApplicantContributionAfterSubsidy AS Invoice_1_Amount,
		NULL Invoice_2_Amount,
		CASE 
		WHEN P.Tds = 1.5 THEN Tds15
		WHEN P.Tds = 7.5 THEN Tds75
		ELSE 0
		END AS TDS_Amount,
		format(P.CreatedDate, 'yyyy-MM-dd') Payment_Date,
		SUBSTRING(
        paymentresponse,
        CHARINDEX('tracking_id=', paymentresponse) + LEN('tracking_id='),
        CHARINDEX('&', paymentresponse, CHARINDEX('tracking_id=', paymentresponse)) 
            - (CHARINDEX('tracking_id=', paymentresponse) + LEN('tracking_id='))
		 ) AS UTR_No,
		FORMAT(P.CreatedDate, 'yyyy-MM-ddTHH:mm:ss') + '+05:30' AS  Created_At,
		P.TadaInvoiceNo Applied_to_invoice,
		NULL Applied_to_invoice2,
		NULL [NABL4],
		CASE WHEN P.Certification='Bronze' then 'ZMS - ZED BRONZE SURVEILLANCE' 
		WHEN P.Certification='Silver' then 'ZMS - ZED SILVER SURVEILLANCE'
		WHEN P.Certification='Gold' then 'ZMS - ZED GOLD SURVEILLANCE' END AS Sub_Discipline_Name,
		convert(varchar,P.Id) Entry_No,
		'' Etag,
		'NDIE' PortalName

		from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		inner join msmepaymentinfo P on (M.ZedId=P.ZedId) 
		inner join PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification and T.PaymentStatus='SUCCESS') 
		where M.ZedId=@ZedId and P.Certification=@Certification order by P.Id desc
	END

	ELSE
	BEGIN
		SELECT 
		NULL AS Posting_Date,
		NULL AS Error_Text,
		NULL AS Order_ID,
		NULL AS Reference_ID,
		NULL AS Board,
		NULL AS TDS_Deducted,
		NULL AS Payment_Mode,
		NULL AS TAN,
		NULL AS Amount_Received,
		NULL AS Invoice_1_Amount,
		NULL AS Invoice_2_Amount,
		NULL AS TDS_Amount,
		NULL AS Payment_Date,
		NULL AS UTR_No,
		NULL AS Created_At,
		NULL AS Applied_to_invoice,
		NULL AS Applied_to_invoice2,
		NULL AS NABL4,
		NULL AS Sub_Discipline_Name,
		NULL AS Entry_No,
		NULL AS Etag,
		'' PortalName
		WHERE 
			1=2
	END
END

GO
/****** Object:  StoredProcedure [dbo].[SP_API_GET_CERTIFIED_UNIT_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_GET_CERTIFIED_UNIT_DETAILS] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Email varchar(500) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SELECT * FROM Msme WHERE ZedId=@ZedId AND PledgeEmailId=@Email
	
    SELECT * FROM MsmeBasicInformation WHERE ZedId=@ZedId

	select
	(select convert(varchar, CreatedDate, 103) from Msme where ZedId=@ZedId) RegisteredDate, 
	isnull((select case when DaCertificateNo is not null then 'Yes' else 'No' end as BronzeCertified from MsmeCertifications where Certification='Bronze' and ZedId=@ZedId),'No') BronzeCertified, 
	isnull((select case when SaCertificateNo is not null then 'Yes' else 'No' end as BronzeCertified from MsmeCertifications where Certification='Silver' and ZedId=@ZedId),'No') SilverCertified, 
	isnull((select case when SaCertificateNo is not null then 'Yes' else 'No' end as BronzeCertified from MsmeCertifications where Certification='Gold' and ZedId=@ZedId),'No') GoldCertified 

END
GO
/****** Object:  StoredProcedure [dbo].[SP_API_GET_CERTIFIED_UNIT_DETAILS_BY_UDYAM]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_GET_CERTIFIED_UNIT_DETAILS_BY_UDYAM] --'<redacted>', '<redacted>'
(
	@UdyamNumber varchar(50) = NULL,
	@CertificationNumber varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @ZedId varchar(50) = NULL
	DECLARE @ExpiryDate varchar(50) = NULL
	DECLARE @LatestCertificateNo varchar(100) = NULL
	DECLARE @CertificationFee DECIMAL(20, 2) = 0
	DECLARE @SubsidyAmount DECIMAL(20, 2) = 0
	DECLARE @AmountPaid DECIMAL(20, 2) = 0
	DECLARE @LastestCertification varchar(100) = NULL

	SELECT @ZedId=M.ZedId FROM Msme M Inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
	inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	WHERE B.UdyogAadharNo=@UdyamNumber and ((C.DaCertificateNo IS NOT NULL AND C.DaCertificateNo=@CertificationNumber) OR (C.SaCertificateNo IS NOT NULL AND C.SaCertificateNo=@CertificationNumber))

	SELECT TOP 1 @LatestCertificateNo=isnull(DaCertificateNo,SaCertificateNo),
	@ExpiryDate=convert(varchar,(convert(date,dateadd(yy,3,CertificationStatusDate))),103)
	FROM MsmeCertifications WHERE ZedId=@ZedId AND isnull(DaCertificateNo,SaCertificateNo) is not null ORDER BY CreatedDate DESC

	IF @CertificationNumber!=@LatestCertificateNo
	SET @ZedId='000'
	

	SELECT M.*,	convert(varchar,CertificationStatusDate,103) CertificationStatusDate FROM Msme M Inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
	inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	WHERE M.ZedId=@ZedId and isnull(DaCertificateNo,SaCertificateNo)=@LatestCertificateNo
	
    SELECT B.* FROM Msme M Inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
	inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	WHERE B.ZedId=@ZedId and isnull(DaCertificateNo,SaCertificateNo)=@LatestCertificateNo

	SELECT @LastestCertification=LastestCertification from MsmeBasicInformation where ZedId=@ZedId
	--SELECT @AmountPaid=Amount from PaymentGateWayTransactions where ZedId=@ZedId and Certification=@LastestCertification and PaymentStatus='<redacted>'
	SELECT top 1 @CertificationFee=Total, @AmountPaid=ApplicantContributionAfterSubsidy from MsmePaymentInfo where ZedId=@ZedId and Certification=@LastestCertification order by id
	SET @SubsidyAmount = @CertificationFee-@AmountPaid

	--select
	--(select convert(varchar, CreatedDate, 103) from Msme where ZedId=@ZedId) RegisteredDate, 
	--isnull((select case when DaCertificateNo is not null then '<redacted>' else '<redacted>' end as BronzeCertified from MsmeCertifications where Certification='<redacted>' and ZedId=@ZedId),'<redacted>') BronzeCertified, 
	--isnull((select case when SaCertificateNo is not null then '<redacted>' else '<redacted>' end as BronzeCertified from MsmeCertifications where Certification='<redacted>' and ZedId=@ZedId),'<redacted>') SilverCertified, 
	--isnull((select case when SaCertificateNo is not null then '<redacted>' else '<redacted>' end as BronzeCertified from MsmeCertifications where Certification='<redacted>' and ZedId=@ZedId),'<redacted>') GoldCertified,
	--@ExpiryDate AS ExpiryDate

	 select convert(varchar, CreatedDate, 103) RegisteredDate,Bronze BronzeCertified,Silver SilverCertified,Gold GoldCertified,@ExpiryDate AS ExpiryDate,
	 @CertificationFee CertificationFee, @SubsidyAmount SubsidyAmount, @AmountPaid AmountPaid
	 from Msme M 
	LEFT JOIN
 
	(select ZedId, case when Bronze is not null and Silver is null and Gold is null then 'Yes' else 'No' end as Bronze,
	case when Silver is not null and Gold is null then 'Yes' else 'No' end as Silver,
	case when Gold is not null then 'Yes' else 'No' end as Gold
	from 
	(
	select ZedId,Certification,isnull(DaCertificateNo,SaCertificateNo) CertificateNo from MsmeCertifications where ZedId=@ZedId
	) X

	pivot 
	(
	max(CertificateNo) for certification in ([Bronze],[Silver],[Gold])
	) p
	) Y
	ON (M.ZedId=Y.ZedId)
	where M.ZedId=@ZedId

END
GO
