(
	@SelfCertificationDate varchar(50) = NULL,
	@NextWeekDate varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT Category,RegistrationNumber, CASE WHEN SelfCertificateNo IS NOT NULL THEN  'SELF CERTIFIED ZEDCS_V2' ELSE NULL END AS SelfCertificationStatus, 
