-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_KEY_MAKER] --'<redacted>'
(
	@ClientName varchar(50) = NULL
)
AS
BEGIN
	
	DECLARE @ApiKey varchar(100) = NULL

	SET NOCOUNT ON;

	SET @ApiKey=left(concat((REPLACE(NEWID(),'-','')),(REPLACE(NEWID(),'-','')),(REPLACE(NEWID(),'-',''))),75)

	IF(select count(*) from ApiClientTokens where token=@ApiKey)=0
	BEGIN
		insert into ApiClientTokens (Client,Token,CreatedDate,BaseUrl)
		values (@ClientName,@ApiKey,getdate(),concat('https://loginzed.msme.gov.in/msme/GetDetailsByUdyam?token=',@ApiKey,'&udyamNumber=UDYAM-MH-23-0006117&certificationNumber=02052022_002612'))
	END
	ELSE
	SELECT 'ID ALREADY EXISTS'
END

