			AppliedDate,
			ApprovalId,
			ApprovedDate,
			IncentiveName,
			DisbursedDate,
			DisbursedAmount

		)
		VALUES (
			@UdyamNo,
			@Certificateno,
			@Pin,
			@ApplicationId,
			@UnitName,
			@District,
			@FCI,
			@DateOfProduction,
			@ServiceName,
			@AppliedDate,
			@ApprovalId,
			@ApprovedDate,
			@IncentiveName,
			@DisbursedDate,
			@DisbursedAmount
		)

	END	

END
