	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType

	IF @NcCount=0
	BEGIN
		
		INSERT INTO AdditionalSupportQuestions(ZedId, Certification, SuitableForSilverUpgrade, HandholdingSupport, CreatedDate)
		VALUES (@ZedId, @CertificationType, @SuitableForSilverUpgrade,@HandholdingSupport, GETDATE())

		UPDATE MsmeCertifications set CertificationStatus=2, EvidenceSubmissionDate=getdate(),CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType

		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Submitted on  ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'BasicInfoStatus')

		EXEC [dbo].[SP_UPDATING_OPENEDFLAG] @ZedId, @CertificationType, @NcCount

		--Update A set A.OpenedFlag=1  from MsmeRequirements A inner join 
		--(SELECT Distinct SectionCode,RequirementCode,SectionType,NcCount FROM MsmeEvidences where ValidationRequired=1 and ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and SyncedDate is null) B
		--on (A.SectionCode=B.SectionCode and A.RequirementCode=B.RequirementCode and A.SectionType=B.SectionType and A.NcCount=B.NcCount) 
		--left join 
		--(SELECT Distinct SectionCode,RequirementCode,SectionType,NcCount FROM MsmeEvidences where  ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and SyncedDate is not null) C
		--on (A.SectionCode=C.SectionCode and A.RequirementCode=C.RequirementCode and A.SectionType=C.SectionType and A.NcCount=C.NcCount) 
		--where ZedId=@ZedId and A.SectionType=@CertificationType and A.NcCount=@NcCount AND C.SectionCode IS NULL AND C.RequirementCode IS NULL


		--Update A set A.IsAssessmentExcempted='<redacted>'  from MsmeSections A inner join 
		--(SELECT Distinct SectionCode,RequirementCode,SectionType,NcCount FROM MsmeEvidences where ValidationRequired=1 and ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and SyncedDate is null) B
		--on (A.SectionCode=B.SectionCode and A.SectionType=B.SectionType and A.NcCount=B.NcCount) 
		--left join 
		--(SELECT Distinct SectionCode,RequirementCode,SectionType,NcCount FROM MsmeEvidences where  ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and SyncedDate is not null) C
		--on (A.SectionCode=C.SectionCode and A.SectionType=C.SectionType and A.NcCount=C.NcCount) 
		--where ZedId=@ZedId and A.SectionType=@CertificationType and A.NcCount=@NcCount AND C.SectionCode IS NULL AND C.RequirementCode IS NULL

		--IF @NcCount=0
		--BEGIN
		--	UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and OpenedFlag is null and SectionType=@CertificationType and NcCount=0 and concat(sectioncode,'<redacted>',RequirementCode) not in 
		--	(SELECT DISTINCT CONCAT(SectionCode,'<redacted>',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@CertificationType and NcCount=0)
		--END

	END

	--ELSE IF @NcCount=5
	--BEGIN
	--	UPDATE MsmeCertifications set CertificationStatus=7, EvidenceSubmissionDate=getdate(),CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType

	--	insert into MsmeHistory(ZedId,Descrip,CreatedDate)
	--	values (@ZedId,concat('<redacted>',@CertificationType),getdate())
	--END

	ELSE
	BEGIN
		UPDATE MsmeCertifications set NcStatus=2, EvidenceSubmissionDate=getdate(),CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType

		IF @NcCount = 1
		UPDATE MsmeCertifications set Nc1Status=2 where ZedId=@ZedId and Certification=@CertificationType
		IF @NcCount = 2
		UPDATE MsmeCertifications set Nc2Status=2 where ZedId=@ZedId and Certification=@CertificationType
		IF @NcCount = 3
		UPDATE MsmeCertifications set Nc3Status=2 where ZedId=@ZedId and Certification=@CertificationType
		IF @NcCount = 4
		UPDATE MsmeCertifications set Nc4Status=2 where ZedId=@ZedId and Certification=@CertificationType
		IF @NcCount = 5
		UPDATE MsmeCertifications set Nc5Status=2 where ZedId=@ZedId and Certification=@CertificationType

		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('NC ',@NcCount,' Submitted On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,concat('Nc',@NcCount,'Submitted' ))
	END

END
