/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_GET_NC_DETAILS_BY_TYPE]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_GET_NC_DETAILS_BY_TYPE] --'<redacted>',3, '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@NcCount int = NULL,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN

	--Declare @NcCount int  = NULL

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	IF @CertificationType = 'Bronze'
	BEGIN
		
		IF @NcCount IS NULL
		BEGIN
			Select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType and CertificationStatus=4
		END
	
		SET NOCOUNT ON;

		select Id,ZedId,Certification,PhotoId,Name,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorRemarks,UpdatedDate,NcCount,concat(@CurrentUrl,'/mobileapi/Photos/',@ZedId,'/',@CertificationType,'/SiteExteriorPhotos/',PhotoId,'.jpg') PhotoPath from MsmePhotos where PhotoType='SiteExteriorPhotos' and Certification=@CertificationType and ZedId=@ZedId and IsVerified ='No' and NcCount=@NcCount-1

		select Id,ZedId,Certification,ProductName,Exported,ProductPhoto,ProductDescriptionPhoto,IsVerified,PreviousAssessorRemarks AssessorRemarks,NcCount,UpdatedDate,case when ProductPhoto is null then NULL ELSE concat(@CurrentUrl,'/mobileapi/Photos/',@ZedId,'/',@CertificationType,'/BasicInfo/',ProductPhoto,'.jpg') END  ProductPhotoPath,CASE WHEN ProductDescriptionPhoto IS NULL THEN NULL ELSE concat(@CurrentUrl,'/mobileapi/Photos/',@ZedId,'/',@CertificationType,'/BasicInfo/',ProductDescriptionPhoto,'.jpg') END ProductDescriptionPhotoPath from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId  and NcCount=@NcCount

		select S.SectionId Id,S.SectionCode,S.SectionName,iButton,S.OrderNo,S.SectionType from MsmeSections S
		where S.SectionType=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		order by S.OrderNo

		SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode) SNo, RequirementId Id, SectionCode, SectionName,RequirementCode,RequirementName,Q.OrderNo,Q.SectionType, PreviousAssessorRemarks as AssessorRemarks
		FROM MsmeRequirements Q
		where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		ORDER By cast(SectionCode as int), RequirementCode

		SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, OptionCode) SNo, OptionId Id,SectionCode, RequirementCode,OptionCode,OptionName,OptionImage,Q.SectionType
		FROM MsmeOptions Q
		where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		ORDER By cast(SectionCode as int), RequirementCode, OptionCode

		SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode) SNo, SubOptionId Id, SectionCode,
			RequirementCode,OptionCode,SubOptionCode,SubOptionName,SubOptionImage,Q.SectionType
		FROM MsmeSubOptions Q
		where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		ORDER By SectionCode, RequirementCode, OptionCode, SubOptionCode

		SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, EvidenceCode) SNo, EvidenceId Id,SectionCode, RequirementCode,EvidenceCode,EvidenceName,E.SectionType, ValidationRequired
		FROM MsmeEvidences E
		where E.SectionType=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		ORDER By cast(SectionCode as int), RequirementCode, EvidenceCode
	END


	ELSE
	BEGIN
		
		IF @NcCount IS NULL 
		BEGIN
			Select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType and CertificationStatus=14
		END
	
		SET NOCOUNT ON;

		select S.Id,S.ZedId,S.Certification,PhotoId,Name,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,S.AssessorRemarks,UpdatedDate,S.NcCount,Photo PhotoPath from SaPhotos S inner join MsmeCertifications C on (S.ZedId=C.ZedId and S.Certification=C.Certification) where PhotoType='SiteExteriorPhotos' and S.Certification=@CertificationType and S.ZedId=@ZedId and IsSaVerified ='No' and S.NcCount=@NcCount-1

		IF @CertificationType='Silver'
		select Id,ZedId,Certification,ProductName,Exported,SaProductPhoto ProductPhoto,SaProductDescriptionPhoto ProductDescriptionPhoto,IsSaVerified IsVerified,PreviousAssessorRemarks AssessorRemarks,NcCount,SaUpdatedDate UpdatedDate,concat(@CurrentUrl,'/mobileapi/Photos/',@ZedId,'/',@CertificationType,'/BasicInfo/',ProductPhoto,'.jpg')  ProductPhotoPath,concat(@CurrentUrl,'/mobileapi/Photos/',@ZedId,'/',@CertificationType,'/BasicInfo/',ProductDescriptionPhoto,'.jpg') ProductDescriptionPhotoPath from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		IF @CertificationType='Gold'
		select Id,ZedId,Certification,ProductName,Exported,ProductPhoto,ProductDescriptionPhoto,IsVerified,AssessorRemarks,NcCount,UpdatedDate,concat(@CurrentUrl,'/mobileapi/Photos/',@ZedId,'/',@CertificationType,'/BasicInfo/',ProductPhoto,'.jpg')  ProductPhotoPath,concat(@CurrentUrl,'/mobileapi/Photos/',@ZedId,'/',@CertificationType,'/BasicInfo/',ProductDescriptionPhoto,'.jpg') ProductDescriptionPhotoPath from SaProducts where Certification=@CertificationType and ZedId=@ZedId and NcCount=@NcCount

		select S.SectionId Id,S.SectionCode,S.SectionName,iButton,S.OrderNo,S.SectionType from MsmeSections S
		where S.SectionType=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		order by S.OrderNo

		SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode) SNo, RequirementId Id, SectionCode, SectionName,RequirementCode,RequirementName,Q.OrderNo,Q.SectionType, PreviousAssessorRemarks as AssessorRemarks
		FROM MsmeRequirements Q
		where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		ORDER By cast(SectionCode as int), RequirementCode

		SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, OptionCode) SNo, OptionId Id,SectionCode, RequirementCode,OptionCode,OptionName,OptionImage,Q.SectionType
		FROM MsmeOptions Q
		where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		ORDER By cast(SectionCode as int), RequirementCode, OptionCode

		SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode) SNo, SubOptionId Id, SectionCode,
			RequirementCode,OptionCode,SubOptionCode,SubOptionName,SubOptionImage,Q.SectionType
		FROM MsmeSubOptions Q
		where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		ORDER By SectionCode, RequirementCode, OptionCode, SubOptionCode

		--SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, EvidenceCode) SNo, EvidenceId Id,SectionCode, RequirementCode,EvidenceCode,EvidenceName,E.SectionType, ValidationRequired
		--FROM MsmeEvidences E
		--where E.SectionType=@CertificationType and ZedId=@ZedId and NcCount=@NcCount
		--ORDER By cast(SectionCode as int), RequirementCode, EvidenceCode
	END

END

GO
