SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_BASIC_INFO] 
(
	@ZedId VarChar(50)						= NULL,
	@RefId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL,
	@AuditsConducted VarChar(50)			= NULL,
	@DomesticCustomers VarChar(2000)		= NULL,	
	@InternationalCustomers varchar(2000)	= NULL, 
	@RawMaterialImported varchar(50)		= NULL, 
	@OutsourcedProcesses varchar(2000)		= NULL,
	@EnergySources varchar(2000)            = NULL,	
	@ManufacturingCapacityUnits VarChar(50)	= NULL,
	@ManufacturingCapacityValue VarChar(50)	= NULL,
	@MonthlyUtilizationUnits VarChar(50)	= NULL,
	@MonthlyUtilizationValue VarChar(50)	= NULL,

	@ProductList		ProductDetails2		READONLY,
	@RawMaterialList	RawMaterial			READONLY,

	@ProductDescriptionPhotos	DynamicPhotoList2	READONLY,
	@ProductPhotos				DynamicPhotoList2	READONLY,
	@SiteExteriorPhotos			DynamicPhotoList2	READONLY,
	@Selfie						DynamicPhotoList2	READONLY
)
AS
BEGIN

	DECLARE @ProductId varchar(50) = NULL
	
	IF EXISTS (select * from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType)
		BEGIN
			UPDATE MsmeCertifications SET AuditsConducted=@AuditsConducted, DomesticCustomers=@DomesticCustomers, InternationalCustomers=@InternationalCustomers, RawMaterialImported=@RawMaterialImported,
			OutsourcedProcesses=@OutsourcedProcesses, EnergySources=@EnergySources,
			ManufacturingCapacityUnits=@ManufacturingCapacityUnits, ManufacturingCapacityValue=@ManufacturingCapacityValue,
			MonthlyUtilizationUnits=@MonthlyUtilizationUnits, MonthlyUtilizationValue=@MonthlyUtilizationValue
			where ZedId=@ZedId and Certification=@CertificationType
		END
		ELSE
		BEGIN
			INSERT INTO MsmeCertifications (ZedId, Certification, AuditsConducted, DomesticCustomers, InternationalCustomers, RawMaterialImported, OutsourcedProcesses, EnergySources,
			ManufacturingCapacityUnits,	ManufacturingCapacityValue,	MonthlyUtilizationUnits, MonthlyUtilizationValue)
			VALUES (@ZedId, @CertificationType, @AuditsConducted, @DomesticCustomers, @InternationalCustomers, @RawMaterialImported, @OutsourcedProcesses, @EnergySources,
			@ManufacturingCapacityUnits, @ManufacturingCapacityValue, @MonthlyUtilizationUnits, @MonthlyUtilizationValue)
		END

	IF EXISTS(select * from @ProductList)
		BEGIN
			DELETE FROM MsmeProducts WHERE ZedId=@ZedId and Certification=@CertificationType
			INSERT INTO MsmeProducts (ZedId, Certification, ProductName, Exported, ProductPhoto, ProductDescriptionPhoto)
			SELECT @ZedId, @CertificationType, ProductName, Exported,ProductPhoto, ProductDescriptionPhoto FROM @ProductList

			UPDATE MsmeProducts SET ProductParentId=Id where ZedId=@ZedId and Certification=@CertificationType and NcCount=0
		END
	ELSE
		BEGIN
			INSERT INTO MsmeProducts (ZedId, Certification, ProductName, Exported, ProductPhoto, ProductDescriptionPhoto)
			SELECT @ZedId, @CertificationType, ProductName, Exported,ProductPhoto, ProductDescriptionPhoto FROM @ProductList

			UPDATE MsmeProducts SET ProductParentId=Id where ZedId=@ZedId and Certification=@CertificationType and NcCount=0
		END

	IF EXISTS(select * from @RawMaterialList)
		BEGIN
			DELETE FROM MsmeRawMaterials WHERE ZedId=@ZedId and Certification=@CertificationType
			INSERT INTO MsmeRawMaterials (ZedId, Certification, RawMaterialName, Percentage, CountryName)
			SELECT @ZedId, @CertificationType, Name, Percentage, CountryName FROM @RawMaterialList
		END
		ELSE
		BEGIN
			INSERT INTO MsmeRawMaterials (ZedId, Certification, RawMaterialName, Percentage, CountryName)
			SELECT @ZedId, @CertificationType, Name, Percentage, CountryName FROM @RawMaterialList
		END

	IF EXISTS(select * from @SiteExteriorPhotos)
		BEGIN
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='SiteExteriorPhotos'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'SiteExteriorPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,1 FROM @SiteExteriorPhotos
		END
		ELSE
		BEGIN
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'SiteExteriorPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,1 FROM @SiteExteriorPhotos
		END


	IF EXISTS(select * from @Selfie)
		BEGIN
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='Selfie'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'Selfie', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,2 FROM @Selfie
		END
		ELSE
		BEGIN
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'Selfie', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,2 FROM @Selfie
		END
	
	IF EXISTS(select * from @ProductPhotos)
		BEGIN									
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='ProductPhotos'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductPhotos', PhotoId, 'ProductPhoto', TimeStamp, Latitude, Longitude, PhotoType,3 FROM @ProductPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 


		END
		ELSE
		BEGIN			
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductPhotos', PhotoId, 'ProductPhoto', TimeStamp, Latitude, Longitude, PhotoType,3 FROM @ProductPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 
		END

		IF EXISTS(select * from @ProductDescriptionPhotos)
		BEGIN		
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='ProductDescriptionPhotos'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,ProductId,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductDescriptionPhotos', PhotoId, 'ProductDescriptionPhoto', TimeStamp, Latitude, Longitude, PhotoType,@ProductId,3 FROM @ProductDescriptionPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductDescriptionPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 
		END
		ELSE
		BEGIN			
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,ProductId,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductDescriptionPhotos', PhotoId, 'ProductDescriptionPhoto', TimeStamp, Latitude, Longitude, PhotoType,@ProductId,3 FROM @ProductDescriptionPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductDescriptionPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 
		END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_INSERT_EVIDENCE]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_EVIDENCE] 
(
	@ZedId VarChar(50)			= NULL,
	@RefId VarChar(50)			= NULL,
	@EvidenceId VarChar(50)		= NULL,	
	@CertificationType VarChar(50)		= NULL,
	@IsFirst bit	 NULL,
	@PhotoList	DynamicPhotoList2	READONLY,
	@IsLast bit	 NULL

)
AS
BEGIN
	
	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType

	IF @IsFirst = 1
	BEGIN
		DELETE FROM MsmePhotos WHERE ZedId=@ZedId and EvidenceId=@EvidenceId and Certification=@CertificationType and NcCount=@NcCount
	END

	INSERT INTO MsmePhotos (ZedId, EvidenceId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount)
	SELECT @ZedId, @EvidenceId, @CertificationType, 'EvidencePhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,@NcCount FROM @PhotoList
	
	IF @IsLast = 1
	BEGIN
		UPDATE MsmeEvidences set SyncedDate=GETDATE() WHERE ZedId=@ZedId and EvidenceId=@EvidenceId and SectionType=@CertificationType and NcCount=@NcCount
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_INSERT_FINANCIAL_ASSISTANCE]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_FINANCIAL_ASSISTANCE] 
(
	@RefId VarChar(50)						= NULL,
	@ZedId VarChar(50)						= NULL,

	@CategoryOfCertificate VarChar(50)		= NULL,
	@NameOfCertficate VarChar(200)			= NULL,
	@CertificationAgency VarChar(200)		= NULL,
	@CertficateNumber VarChar(50)			= NULL,
	@DateOfIssue VarChar(50)				= NULL,
	@ValidityOfCertificate VarChar(50)		= NULL,
	@AnyOtherInformation VarChar(5000)		= NULL,

	@ExpenditureCertficate VarChar(200)		= NULL,
	@AgencyOrSupplier VarChar(200)			= NULL,
	@InvoiceNo VarChar(50)					= NULL,
	@InvoiceBillDate VarChar(50)			= NULL,
	@AmountPaid VarChar(50)					= NULL,
	@EligibleAmount VarChar(50)				= NULL,
	@ModeOfPayment VarChar(50)				= NULL,

	@AccountNo VarChar(50)					= NULL,
	@IfscCode VarChar(50)					= NULL,
	@BranchAddress VarChar(2000)			= NULL,
	@BankName VarChar(200)					= NULL,

	@SubmittedFrom VarChar(50)				= NULL,
			
	@PhotoListWeb	DynamicPhotoList	READONLY,
	@PhotoListApp	DynamicPhotoList2	READONLY
)
AS
BEGIN

	DECLARE @FinancialAssistanceId varchar(200),
	@CertificationType varchar(50) = NULL

	SET @FinancialAssistanceId =Next Value For FinancialIdSequence
	

	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Gold' AND CertificationStatus=16 )
	BEGIN
		select @CertificationType='Gold'
	END
	ELSE
	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Silver' AND CertificationStatus=16 )
	BEGIN
		select @CertificationType='Silver'
	END
	ELSE
	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Bronze' AND CertificationStatus=6 )
	BEGIN
		select @CertificationType='Bronze' 
	END


	IF (SELECT count(*) FROM MSME WHERE ZedId=@ZedId and FinancialAssistanceStatus=0)>0
	BEGIN
		UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'
	END

	ELSE
	BEGIN
		INSERT INTO FinancialAssistance (
			ZedId, CategoryOfCertificate, NameOfCertficate, CertificationAgency, CertficateNumber, DateOfIssue, ValidityOfCertificate, AnyOtherInformation,
			ExpenditureCertficate, AgencyOrSupplier, InvoiceNo, InvoiceBillDate, AmountPaid, EligibleAmount, ModeOfPayment, 
			AccountNo, IfscCode, BranchAddress, BankName, SubmittedFrom,CertificationType,FinancialAssistanceId
		)
		VALUES (
			@ZedId, @CategoryOfCertificate, @NameOfCertficate, @CertificationAgency, @CertficateNumber, @DateOfIssue, @ValidityOfCertificate, @AnyOtherInformation,
			@ExpenditureCertficate, @AgencyOrSupplier, @InvoiceNo, @InvoiceBillDate, @AmountPaid, @EligibleAmount, @ModeOfPayment, 
			@AccountNo, @IfscCode, @BranchAddress, @BankName, @SubmittedFrom,@CertificationType,@FinancialAssistanceId
		)

		INSERT INTO [FinancialAssistancePhotos] ([ZedId], [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],FinancialAssistanceId,CertificationType)
		SELECT @ZedId, [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],@FinancialAssistanceId,@CertificationType FROM @PhotoListApp

		INSERT INTO [FinancialAssistancePhotos] ([ZedId], [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],FinancialAssistanceId,CertificationType)
		SELECT @ZedId, [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [Name],@FinancialAssistanceId,@CertificationType FROM @PhotoListWeb

		UPDATE Msme SET FinancialAssistanceStatus=0 WHERE ZedId=@ZedId
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_INSERT_PRODUCT_INFO]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_PRODUCT_INFO] 
(
	@ZedId VarChar(50)						= NULL,
	@RefId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL,
	@ProductId VarChar(50)					= NULL,
	@MsmeRemarks VarChar(2000)				= NULL,
	@ProductPhoto VarChar(50)				= NULL,	
	@ProductDescriptionPhoto varchar(50)	= NULL, 

	@ProductDescriptionPhotos	DynamicPhotoList2	READONLY,
	@ProductPhotos				DynamicPhotoList2	READONLY
)
AS
BEGIN
	
		DECLARE @ProductName varchar(50) = NULL,
				@Exported varchar(50) = NULL,
				@NcCount int = NULL

		IF @CertificationType='Bronze'
		BEGIN			
		
			SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType


			UPDATE MsmeProducts set ProductPhoto=@ProductPhoto,ProductDescriptionPhoto=@ProductDescriptionPhoto,MsmeRemarks=@MsmeRemarks,MsmeUpdatedDate=getdate(), ProductOpenedTime=null,ProductDescOpenedTime=null,IsVerified=null where ZedId=@ZedId and Certification=@CertificationType and Id=@ProductId and NcCount=@NcCount

			DELETE FROM MsmePhotos where ZedId=@ZedId and Certification=@CertificationType and Id=@ProductId and NcCount=@NcCount and PhotoType in ('ProductPhotos','ProductDescriptionPhotos')

			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount,ProductId)
			SELECT @ZedId, @CertificationType, 'ProductPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType, @NcCount,@ProductId FROM @ProductPhotos

			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount,ProductId)
			SELECT @ZedId, @CertificationType, 'ProductDescriptionPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType, @NcCount,@ProductId FROM @ProductDescriptionPhotos
		END

		ELSE
		BEGIN

			DECLARE @CurrentUrl varchar(100) = NULL
		
			SELECT @CurrentUrl=UrlName from UrlsMasterData
			SET @CurrentUrl=CONCAT(@CurrentUrl,'/mobileapi/Photos/',@ZedId,'/',@CertificationType,'/BasicInfo/')

			SELECT @ProductName=ProductName,@Exported=Exported FROM MsmeProducts WHERE ZedId=@ZedId and Certification=@CertificationType and Id=@ProductId
		
			SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType

			IF @CertificationType='Silver'
			UPDATE MsmeProducts set SaProductPhoto=concat(@CurrentUrl,@ProductPhoto),SaProductDescriptionPhoto=concat(@CurrentUrl,@ProductDescriptionPhoto),MsmeRemarks=@MsmeRemarks,MsmeUpdatedDate=getdate(), ProductOpenedTime=null,ProductDescOpenedTime=null,IsSaVerified=null where ZedId=@ZedId and Certification=@CertificationType and Id=@ProductId and NcCount=@NcCount
			IF @CertificationType='Gold'
			UPDATE SaProducts set ProductPhoto=@ProductPhoto,ProductDescriptionPhoto=@ProductDescriptionPhoto,MsmeRemarks=@MsmeRemarks,MsmeUpdatedDate=getdate(), ProductOpenedTime=null,ProductDescOpenedTime=null,IsVerified=null where ZedId=@ZedId and Certification=@CertificationType and Id=@ProductId and NcCount=@NcCount

			DELETE FROM SaPhotos where ZedId=@ZedId and Certification=@CertificationType and ProductId=@ProductId and NcCount=@NcCount and PhotoType in ('ProductPhotos','ProductDescriptionPhotos')

			INSERT INTO SaPhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount,ProductId,Photo)
			SELECT @ZedId, @CertificationType, 'ProductPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType, @NcCount,@ProductId,concat(@CurrentUrl,PhotoId,'.',PhotoType) FROM @ProductPhotos

			INSERT INTO SaPhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount,ProductId,Photo)
			SELECT @ZedId, @CertificationType, 'ProductDescriptionPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType, @NcCount,@ProductId,concat(@CurrentUrl,PhotoId,'.',PhotoType) FROM @ProductDescriptionPhotos
		END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_INSERT_REQUIREMENT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_REQUIREMENT] 
(
	@ZedId VarChar(50)				= NULL,
	@Id VarChar(50)					= NULL,
	@CertificationType VarChar(50)	= NULL,
	@Code VarChar(50)				= NULL,
	@MsmeRemarks VarChar(2000)		= NULL,
	@IsFirst bit	 = NULL,
	@IsLast bit	 = NULL,
			
	@PhotoList	DynamicPhotoList2	READONLY
)
AS
BEGIN
	DECLARE @EvidenceId varchar(50) = NULL
	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType

	SELECT @EvidenceId=EvidenceId From MsmeEvidences WHERE ZedId=@ZedId AND SectionType=@CertificationType AND RequirementId=@Id AND NcCount=@NcCount

	IF @CertificationType = 'Bronze'
	BEGIN

		IF @IsFirst = 1 
		BEGIN
			
			DELETE FROM MsmePhotos WHERE  ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and Certification=@CertificationType
		END

		update MsmeRequirements set MsmeRemarks=@MsmeRemarks,MsmeUpdatedDate=getdate(), AssessorRemarks=null,Conformance=null,OpenedFlag=null where ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and SectionType=@CertificationType

		INSERT INTO MsmePhotos (ZedId, RequirementId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount,EvidenceId)
		SELECT @ZedId, @Id, @CertificationType, 'EvidencePhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,@NcCount,@EvidenceId FROM @PhotoList

		IF @IsLast = 1 
		BEGIN
			UPDATE MsmeEvidences set SyncedDate=GETDATE(),DocumentOpenedTime=null WHERE ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and SectionType=@CertificationType

		END

	END

	ELSE
	BEGIN

	IF @IsFirst = 1 
		BEGIN
			
			DELETE FROM SaRequirementPhotos WHERE  ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and Certification=@CertificationType
		END

		update MsmeRequirements set MsmeRemarks=@MsmeRemarks,MsmeUpdatedDate=getdate(),SaAssessorRemarks=null,SaConformance=null,OpenedFlag=null where ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and SectionType=@CertificationType

		INSERT INTO SaRequirementPhotos (ZedId, RequirementId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude,SaPhotoExtension, NcCount)
		SELECT @ZedId, @Id, @CertificationType, 'EvidencePhotos', PhotoId, Name, TimeStamp, Latitude, Longitude,PhotoType, @NcCount FROM @PhotoList

		IF @IsLast = 1 
		BEGIN
			UPDATE MsmeEvidences set SyncedDate=GETDATE(),DocumentOpenedTime=null WHERE ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and SectionType=@CertificationType

		END
	END
END
GO
