-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_SITE_EXTERIOR] 
(
	@ZedId VarChar(50)						= NULL,
	@RefId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL,
	@MsmeRemarks VarChar(2000)				= NULL,

	@SiteExteriorPhotos			DynamicPhotoList2	READONLY
)
AS
BEGIN

	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType
	
	IF @CertificationType = 'Bronze'
	BEGIN

		DELETE FROM MsmePhotos where ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and PhotoType in ('SiteExteriorPhotos')

		INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,NcCount,MsmeRemarks)
		SELECT @ZedId, @CertificationType, 'SiteExteriorPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType, @NcCount,@MsmeRemarks FROM @SiteExteriorPhotos
	END

	ELSE
	BEGIN

	DECLARE @CurrentUrl varchar(100) = NULL
		
		SELECT @CurrentUrl=UrlName from UrlsMasterData
		SET @CurrentUrl=CONCAT(@CurrentUrl,'/mobileapi/Photos/',@ZedId,'/',@CertificationType,'/SiteExteriorPhotos/')
		

		DELETE FROM SaPhotos where ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and PhotoType in ('SiteExteriorPhotos')
		--http://zedcs.umon.in/mobileapi/Photos/ZEDMSME000586/Silver/SiteExteriorPhotos/ZEDMSME0005861628336767579.jpg

		INSERT INTO SaPhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,NcCount,Photo)
		SELECT @ZedId, @CertificationType, 'SiteExteriorPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType, @NcCount,concat(@CurrentUrl,PhotoId,'.',PhotoType) FROM @SiteExteriorPhotos
	END

END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_INSERT_TECHNOLOGY_UPGRADATION]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_TECHNOLOGY_UPGRADATION] 
(
	@RefId VarChar(50)						= NULL,
	@ZedId VarChar(50)						= NULL,

	@CategoryOfCertificate VarChar(50)		= NULL,
	@NameOfCertficate VarChar(200)			= NULL,
	@CertificationAgency VarChar(200)		= NULL,
	@CertficateNumber VarChar(50)			= NULL,
	@DateOfIssue VarChar(50)				= NULL,
	@ValidityOfCertificate VarChar(50)		= NULL,
	@AnyOtherInformation VarChar(5000)		= NULL,

	@ExpenditureCertficate VarChar(200)		= NULL,
	@AgencyOrSupplier VarChar(200)			= NULL,
	@InvoiceNo VarChar(50)					= NULL,
	@InvoiceBillDate VarChar(50)			= NULL,
	@AmountPaid VarChar(50)					= NULL,
	@EligibleAmount VarChar(50)				= NULL,
	@ModeOfPayment VarChar(50)				= NULL,

	@AccountNo VarChar(50)					= NULL,
	@IfscCode VarChar(50)					= NULL,
	@BranchAddress VarChar(2000)			= NULL,
	@BankName VarChar(200)					= NULL,

	@SubmittedFrom VarChar(50)				= NULL,
			
	@PhotoListWeb	DynamicPhotoList	READONLY,
	@PhotoListApp	DynamicPhotoList2	READONLY
)
AS
BEGIN

	DECLARE @FinancialAssistanceId varchar(200),
	@CertificationType varchar(50) = NULL

	SET @FinancialAssistanceId =Next Value For FinancialIdSequence
	

	IF EXISTS (SELECT Certification from ZED_CONSULTANT.DBO.MsmeCertifications where ZedId=@Zedid AND Certification='Gold' AND CertificationStatus=100 )
	BEGIN
		select @CertificationType='Gold'
	END
	ELSE
	IF EXISTS (SELECT Certification from ZED_CONSULTANT.DBO.MsmeCertifications where ZedId=@Zedid AND Certification='Silver' AND CertificationStatus=100 )
	BEGIN
		select @CertificationType='Silver'
	END
	ELSE
	IF EXISTS (SELECT Certification from ZED_CONSULTANT.DBO.MsmeCertifications where ZedId=@Zedid AND Certification='Bronze' AND CertificationStatus=100 )
	BEGIN
		select @CertificationType='Bronze' 
	END


	IF (SELECT count(*) FROM ZED_CONSULTANT.DBO.MSME WHERE ZedId=@ZedId and TechnologyUpgradation=0)>0
	BEGIN
		UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'
	END

	ELSE
	BEGIN
		INSERT INTO ZED_CONSULTANT.DBO.FinancialAssistance (
			ZedId, CategoryOfCertificate, NameOfCertficate, CertificationAgency, CertficateNumber, DateOfIssue, ValidityOfCertificate, AnyOtherInformation,
			ExpenditureCertficate, AgencyOrSupplier, InvoiceNo, InvoiceBillDate, AmountPaid, EligibleAmount, ModeOfPayment, 
			AccountNo, IfscCode, BranchAddress, BankName, SubmittedFrom,CertificationType,FinancialAssistanceId
		)
		VALUES (
			@ZedId, @CategoryOfCertificate, @NameOfCertficate, @CertificationAgency, @CertficateNumber, @DateOfIssue, @ValidityOfCertificate, @AnyOtherInformation,
			@ExpenditureCertficate, @AgencyOrSupplier, @InvoiceNo, @InvoiceBillDate, @AmountPaid, @EligibleAmount, @ModeOfPayment, 
			@AccountNo, @IfscCode, @BranchAddress, @BankName, @SubmittedFrom,@CertificationType,@FinancialAssistanceId
		)

		INSERT INTO ZED_CONSULTANT.DBO.[FinancialAssistancePhotos] ([ZedId], [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],FinancialAssistanceId,CertificationType)
		SELECT @ZedId, [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],@FinancialAssistanceId,@CertificationType FROM @PhotoListApp

		INSERT INTO ZED_CONSULTANT.DBO.[FinancialAssistancePhotos] ([ZedId], [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],FinancialAssistanceId,CertificationType)
		SELECT @ZedId, [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [Name],@FinancialAssistanceId,@CertificationType FROM @PhotoListWeb

		UPDATE ZED_CONSULTANT.DBO.Msme SET TechnologyUpgradation=0 WHERE ZedId=@ZedId
	END
END
GO
