CREATE PROC [dbo].[SP_APP_SA_ALLOT_SECTIONS_TO_COASSESSOR]
(
	@ZedId varchar(50) = NULL,
	@CertificationType VarChar(50)	= NULL,


	@AllotList	DynamicSectionAllot	READONLY
)
AS
BEGIN
	
	IF EXISTS (select * from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType and CertificationStatus=8)

	BEGIN

		--update S set S.AssessorId=A.AssessorId from MsmeSections S inner join @AllotList A 
		--on ( S.SectionId=A.SectionId and S.SectionCode=A.SectionCode) where ZedId=@ZedId and SectionType=@CertificationType and NcCount=0

		update S set S.AssessorId=A.AssessorId from MsmeSections S inner join @AllotList A 
		on ( S.SectionId=A.SectionId and S.SectionCode=A.SectionCode) where ZedId=@ZedId and  NcCount=0

		Update MsmeCertifications set CertificationStatus=9 where ZedId=@ZedId and Certification=@CertificationType

		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,'Sections allocation done by Lead assessor to Co assessor',getdate(),@CertificationType,NULL)

	END

	ELSE
	BEGIN
		UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'
	END


END



GO
/****** Object:  StoredProcedure [dbo].[SP_APP_SA_CHECK_LOGIN]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SA_CHECK_LOGIN] --'<redacted>', '<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@Password varchar(50) = NULL,
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SET @UserId=replace(@UserId,' ','_')
	SET @ZedId=replace(@ZedId,' ','_')

	DECLARE @CertificationStatus int = NULL,
			@CertificationType varchar(50) = NULL,
			@NcCount int = NULL
	SELECT @CertificationStatus=CertificationStatus,@CertificationType=Certification,@NcCount=NcCount FROM MsmeCertifications where ZedId=@ZedId and  SiteAssessorId is not null and SaCertificateNo is null


	SELECT * FROM Users WHERE RoleId=3  AND UserId=@UserId AND Password=@Password and SiteVerification=1 AND IsActive=1  --type of assessor to be load

	SELECT FORMAT(AssessmentDate,'MM/dd/yyyy hh:mm:ss tt') AssessmentDate, B.EnterpriseName, TwoDigitActivity Sector, concat(E.PAddress,E.PDistrictName,E.PStateName,e.PPin) UnitAddress, 
		B.EmailId Email, E.MobileNo PhoneNumber,
		case when SiteAssessorId=@UserId then 1 when CoAssessorId=@UserId then 2 end as UserType, CertificationStatus,
		SiteAssessorId LeadAssessorId, U.UserName LeadAssessorName,CoAssessorId, US.UserName CoAssessorName, B.ZedId, Certification CertificationType,
		M.AuditsConducted, M.DomesticCustomers, M.InternationalCustomers, M.RawMaterialImported, M.OutsourcedProcesses, M.EnergySources,
		convert(bit,1) as IsSurveillance, MinimumParameters
	FROM MsmeBasicInformation B inner join MsmeCertifications M on (B.ZedId=m.ZedId) 
	inner join Msme E on (B.ZedId=E.ZedId)
	left join Users U on (M.SiteAssessorId=U.UserId)
	left join Users US on (M.CoAssessorId=US.UserId)
	WHERE M.ZedId=@ZedId and (SiteAssessorId=@UserId or CoAssessorId=@UserId) and CertificationStatus>=8 and Certification=@CertificationType	


	IF @CertificationStatus = 8
		SELECT * FROM MsmeSections where ZedId=@ZedId and SectionType=@CertificationType order by cast(SectionId as int)
	ELSE 
		SELECT * FROM MsmeSections where AssessorId=@UserId and ZedId=@ZedId and SectionType=@CertificationType order by cast(SectionId as int)

	SELECT * FROM msmeProducts WHERE ZedId=@ZedId and Certification=@CertificationType

	SELECT Id, ZedId, Certification, RawMaterialName, Percentage RawMaterialPercentage, CountryName FROM MsmeRawMaterials WHERE ZedId=@ZedId and Certification=@CertificationType

	IF @CertificationStatus = 9
	BEGIN

		select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,R.SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,R.OrderNo,R.SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag from MsmeSections S inner join MsmeRequirements R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType)
		where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int),cast(RequirementId as int)

		select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,R.SectionType from MsmeSections S inner join MsmeOptions R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType)
		where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int)

		select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,R.SectionType from MsmeSections S inner join MsmeSubOptions R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType)
		where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int)
		 
	END
	ELSE
	BEGIN
		select  NULL Id,NULL ZedId,NULL Certification,NULL SectionCode,NULL SectionName,NULL QuestionCode,NULL QuestionName,NULL RequirementCode,NULL RequirementName,NULL OrderNo,NULL SectionType,
		NULL Conformance,NULL AssessorRemarks,NULL TableName,NULL OpenedFlag 
		where 1=2

		select NULL Id,NULL ZedId,NULL Certification,NULL SectionCode,NULL QuestionCode,NULL OptionCode,NULL OptionName,NULL OptionImage,NULL RequirementCode,NULL SectionType 
		where 1=2

		select NULL Id,NULL ZedId,NULL Certification,NULL SectionCode,NULL QuestionCode,NULL OptionCode,NULL SubOptionCode,NULL SubOptionName,NULL RequirementCode,NULL SubOptionImage,NULL SectionType 
		where 1=2
	END



	DECLARE @LeadAssessor varchar(50) = NULL,
			@CoAssessor   varchar(50) = NULL,
			@True bit = 1,
			@False bit = 0

	SELECT @LeadAssessor=SiteAssessorId,@CoAssessor=CoAssessorId FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType

	SELECT 		
		CASE WHEN 
		(select count(*) from Meetings  where zedid=@ZedId and certificationtype=@CertificationType and AssessorId=@LeadAssessor and MeetingType='Open Meeting')>0 THEN @True ELSE @False end as OpenMeetingSubmitted, 
		
		CASE WHEN
		(SELECT count(*) FROM SaPhotos WHERE ZedId=@ZedId and Certification=@CertificationType and AssessorId=@UserId and PhotoType='Selfie')>0 THEN @True ELSE @False end as SelfieSubmitted,

		
		(SELECT AllowFinalSubmitManual FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType) AllowFinalSubmitManual
		 



END

GO
