/****** Object:  StoredProcedure [dbo].[SP_APP_SA_SAVE_PARAMETER]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SA_SAVE_PARAMETER] 
(
	@ZedId VarChar(50)				= NULL,
	@AssessorId VarChar(50)			= NULL,
	@ParameterId VarChar(50)		= NULL,
	@ParameterCode VarChar(50)		= NULL,
	@CertificationType VarChar(50)	= NULL,
	@Phototype VarChar(50)			= NULL,
			
	@PhotoList	DynamicPhotoList2	READONLY,
	@RequirementsList DynamicRequirementsList READONLY
)
AS
BEGIN
	
	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and  SiteAssessorId is not null and SaCertificateNo is null

	--SELECT @EvidenceId=EvidenceId From MsmeEvidences WHERE ZedId=@ZedId AND SectionType=@CertificationType AND RequirementId=@Id AND NcCount=@NcCount

	update M set M.SaConformance=replace(replace(R.Conformance,'True','Yes'),'False','No'),M.SaAssessorRemarks=R.AssessorRemarks,SaUpdatedDate=getdate() from MsmeRequirements M inner join @RequirementsList R on (M.Id=R.RequirementId) where M.ZedId=@ZedId and M.SectionCode=@ParameterCode and M.SectionType=@CertificationType

	DELETE from SaRequirementPhotos WHERE ZedId=@ZedId and Certification=@CertificationType and NcCount=0 and RequirementId in (select PhotoType from @PhotoList)

	INSERT INTO SaRequirementPhotos(ZedId, RequirementId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, NcCount)
	SELECT @ZedId, Phototype, @CertificationType, 'Evidence Photo', PhotoId, Name, TimeStamp, Latitude, Longitude,@NcCount FROM @PhotoList


	
	--select * from SaRequirementPhotos where zedid='<redacted>' order by id
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_SA_SAVE_PHOTOS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SA_SAVE_PHOTOS]  --'<redacted>','<redacted>','<redacted>','<redacted>'
(
	@ZedId VarChar(50)			= NULL,
	@AssessorId VarChar(50)		= NULL,
	@PhotoType VarChar(50)		= NULL,	
	@CertificationType VarChar(50)		= NULL,
	@RefId VarChar(50)			= NULL,
	@EvidenceId VarChar(50)		= NULL,	
			
	@PhotoList	DynamicPhotoList2	READONLY
)
AS
BEGIN
	
	DECLARE @NcCount int = NULL
	DECLARE @CertificationStatus int = NULL
	SELECT @NcCount=NcCount, @CertificationStatus=CertificationStatus FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and  SiteAssessorId is not null and SaCertificateNo is null

	
	IF @PhotoType='Open Meeting' and exists(select * from @PhotoList where name='Selfie on Site')
	BEGIN
		DELETE FROM SaPhotos WHERE ZedId=@ZedId and Certification=@CertificationType and name='Selfie on Site' and PhotoType='Open Meeting'
	END

		DELETE FROM SaPhotos WHERE ZedId=@ZedId and Certification=@CertificationType and PhotoId IN (SELECT PhotoId FROM @PhotoList)
		INSERT INTO SaPhotos (ZedId,AssessorId, EvidenceId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount)
		SELECT @ZedId, @AssessorId, @EvidenceId, @CertificationType, @PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,@NcCount FROM @PhotoList


		IF @PhotoType='Open Meeting'
	BEGIN
		Update MsmeCertifications set IsSelfieSynced=1 where ZedId=@ZedId and Certification=@CertificationType and IsSelfieSynced=0
	END

	
END
GO
