/****** Object:  StoredProcedure [dbo].[SP_APP_SURVEILLANCE_CHECK_LOGIN]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SURVEILLANCE_CHECK_LOGIN] --'<redacted>','<redacted>', '<redacted>'
(
	@AssessorId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Password varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SET @AssessorId=replace(@AssessorId,' ','_')

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	DECLARE @StateId int = NULL
	SELECT @StateId=StateId from Msme where ZedId=@ZedId

	DECLARE @LatestCertification varchar(100) = NULL,
			@DateOfAvail varchar(50) = NULL,
			@JoiningRewardAmount varchar(50) = '10000',
			@CompletedCertification varchar(50) = NULL

			--select top 1 @LatestCertification=Certification,@DateOfAvail=FORMAT(CreatedDate, '<redacted>') from MsmePaymentInfo where ZedId=@UserId and UseCoupon='<redacted>' order by CreatedDate desc

			--select top 1 @CompletedCertification=Certification from MsmeCertifications where CertificationStatus=16 and ZedId=@UserId order by CreatedDate desc

	SELECT * FROM Users WHERE RoleId=3  AND UserId=@AssessorId AND IsActive=1 AND (Password=@Password or @Password='#REMOVED-HARDCODED-PASSWORD#')

    SELECT *, ZedId PledgeCertificateNo, CreatedDate DateOfPledge FROM Msme WHERE ZedId=@ZedId
	
    SELECT * FROM MsmeBasicInformation WHERE ZedId=@ZedId

	--STATUS CHECKING FOR ENABLE AND DISABLE OF BUTTONS IN APP
	SELECT 
		1 BronzeStatus,
		0 SilverStatus,
		0 GoldStatus, 
		
		0 BronzeStatusOfNc,
		0 SilverStatusOfNc,
		0 GoldStatusOfNc,

		'' BronzeCertificatePath,
		'' BronzeReportPath, 
		'' BronzeIncentives,
		'' SilverCertificatePath,
		'' SilverReportPath, '' SilverIncentives,
		'' GoldCertificatePath,
		'' GoldReportPath, concat(@CurrentUrl,'/Incentive/Details/',@StateId,'?ct=Gold') GoldIncentives,

		0 BronzeStatusOfNc1,
		0 BronzeStatusOfNc2,
		0 BronzeStatusOfNc3,
		0 BronzeStatusOfNc4,
		0 BronzeStatusOfNc5,
		0 BronzeSelfieStatus,

		0 SilverStatusOfNc1,
		0 SilverStatusOfNc2,
		0 SilverStatusOfNc3,
		0 SilverStatusOfNc4,
		0 SilverStatusOfNc5,
		0 SilverSelfieStatus,

		0 GoldStatusOfNc1,
		0 GoldStatusOfNc2,
		0 GoldStatusOfNc3,
		0 GoldStatusOfNc4,
		0 GoldStatusOfNc5,
		0 GoldSelfieStatus,

		'' Nc1StatusTextBronze,
		'' Nc2StatusTextBronze,
		'' Nc3StatusTextBronze,
		'' Nc4StatusTextBronze,
		'' Nc5StatusTextBronze,
  															
		'' Nc1StatusTextSilver,
		'' Nc2StatusTextSilver,
		'' Nc3StatusTextSilver,
		'' Nc4StatusTextSilver,
		'' Nc5StatusTextSilver,
 															
		'' Nc1StatusTextGold,
		'' Nc2StatusTextGold,
		'' Nc3StatusTextGold,
		'' Nc4StatusTextGold,
		'' Nc5StatusTextGold,
		'Bronze' LatestCertification,NULL DateOfAvail,@JoiningRewardAmount JoiningRewardAmount,
		convert(bit,1) IsCouponUsed,
		0 FinancialAssistanceStatus


		SELECT * FROM MsmeCertifications where ZedId=@ZedId and DesktopAssessorId=@AssessorId and CertificationStatus=1

END

GO
/****** Object:  StoredProcedure [dbo].[SP_APP_SURVEILLANCE_GET_QUESTIONS_BY_TYPE]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SURVEILLANCE_GET_QUESTIONS_BY_TYPE] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = 'Bronze'
)
AS
BEGIN
	
	SET NOCOUNT ON;

	select S.SectionId Id,S.SectionCode,S.SectionName,iButton,S.OrderNo,S.SectionType from MsmeSections S
	where S.SectionType=@CertificationType and ZedId=@ZedId and NcCount=0
	order by S.OrderNo

	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode) SNo, RequirementId Id, SectionCode, SectionName,RequirementCode,RequirementName,Q.OrderNo,Q.SectionType
	FROM MsmeRequirements Q
	where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=0
	ORDER By cast(SectionCode as int), RequirementCode

	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, OptionCode) SNo, OptionId Id,SectionCode, RequirementCode,OptionCode,OptionName,OptionImage,Q.SectionType
	FROM MsmeOptions Q
	where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=0
	ORDER By cast(SectionCode as int), RequirementCode, OptionCode

	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode) SNo, SubOptionId Id, SectionCode,
		RequirementCode,OptionCode,SubOptionCode,SubOptionName,SubOptionImage,Q.SectionType
	FROM MsmeSubOptions Q
	where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=0
	ORDER By SectionCode, RequirementCode, OptionCode, SubOptionCode

	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, EvidenceCode) SNo, EvidenceId Id,SectionCode, RequirementCode,EvidenceCode,EvidenceName,E.SectionType, ValidationRequired,EvidenceHelpText
	FROM MsmeEvidences E
	where E.SectionType=@CertificationType and ZedId=@ZedId and NcCount=0
	ORDER By cast(SectionCode as int), RequirementCode, EvidenceCode



END

GO
/****** Object:  StoredProcedure [dbo].[SP_APP_SURVEILLANCE_INSERT_BASIC_INFO]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SURVEILLANCE_INSERT_BASIC_INFO] 
(
	@ZedId VarChar(50)						= NULL,
	@RefId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL,
	@AuditsConducted VarChar(50)			= NULL,
	@DomesticCustomers VarChar(2000)		= NULL,	
	@InternationalCustomers varchar(2000)	= NULL, 
	@RawMaterialImported varchar(50)		= NULL, 
	@OutsourcedProcesses varchar(2000)		= NULL,
	@EnergySources varchar(2000)            = NULL,	
	@ManufacturingCapacityUnits VarChar(50)	= NULL,
	@ManufacturingCapacityValue VarChar(50)	= NULL,
	@MonthlyUtilizationUnits VarChar(50)	= NULL,
	@MonthlyUtilizationValue VarChar(50)	= NULL,

	@ProductList		ProductDetails2		READONLY,
	@RawMaterialList	RawMaterial			READONLY,

	@ProductDescriptionPhotos	DynamicPhotoList2	READONLY,
	@ProductPhotos				DynamicPhotoList2	READONLY,
	@SiteExteriorPhotos			DynamicPhotoList2	READONLY,
	@Selfie						DynamicPhotoList2	READONLY
)
AS
BEGIN

	DECLARE @ProductId varchar(50) = NULL
	
	IF EXISTS (select * from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType)
		BEGIN
			UPDATE MsmeCertifications SET AuditsConducted=@AuditsConducted, DomesticCustomers=@DomesticCustomers, InternationalCustomers=@InternationalCustomers, RawMaterialImported=@RawMaterialImported,
			OutsourcedProcesses=@OutsourcedProcesses, EnergySources=@EnergySources,
			ManufacturingCapacityUnits=@ManufacturingCapacityUnits, ManufacturingCapacityValue=@ManufacturingCapacityValue,
			MonthlyUtilizationUnits=@MonthlyUtilizationUnits, MonthlyUtilizationValue=@MonthlyUtilizationValue
			where ZedId=@ZedId and Certification=@CertificationType
		END
		ELSE
		BEGIN
			INSERT INTO MsmeCertifications (ZedId, Certification, AuditsConducted, DomesticCustomers, InternationalCustomers, RawMaterialImported, OutsourcedProcesses, EnergySources,
			ManufacturingCapacityUnits,	ManufacturingCapacityValue,	MonthlyUtilizationUnits, MonthlyUtilizationValue)
			VALUES (@ZedId, @CertificationType, @AuditsConducted, @DomesticCustomers, @InternationalCustomers, @RawMaterialImported, @OutsourcedProcesses, @EnergySources,
			@ManufacturingCapacityUnits, @ManufacturingCapacityValue, @MonthlyUtilizationUnits, @MonthlyUtilizationValue)
		END

	IF EXISTS(select * from @ProductList)
		BEGIN
			DELETE FROM MsmeProducts WHERE ZedId=@ZedId and Certification=@CertificationType
			INSERT INTO MsmeProducts (ZedId, Certification, ProductName, Exported, ProductPhoto, ProductDescriptionPhoto)
			SELECT @ZedId, @CertificationType, ProductName, Exported,ProductPhoto, ProductDescriptionPhoto FROM @ProductList

			UPDATE MsmeProducts SET ProductParentId=Id where ZedId=@ZedId and Certification=@CertificationType and NcCount=0
		END
	ELSE
		BEGIN
			INSERT INTO MsmeProducts (ZedId, Certification, ProductName, Exported, ProductPhoto, ProductDescriptionPhoto)
			SELECT @ZedId, @CertificationType, ProductName, Exported,ProductPhoto, ProductDescriptionPhoto FROM @ProductList

			UPDATE MsmeProducts SET ProductParentId=Id where ZedId=@ZedId and Certification=@CertificationType and NcCount=0
		END

	IF EXISTS(select * from @RawMaterialList)
		BEGIN
			DELETE FROM MsmeRawMaterials WHERE ZedId=@ZedId and Certification=@CertificationType
			INSERT INTO MsmeRawMaterials (ZedId, Certification, RawMaterialName, Percentage, CountryName)
			SELECT @ZedId, @CertificationType, Name, Percentage, CountryName FROM @RawMaterialList
		END
		ELSE
		BEGIN
			INSERT INTO MsmeRawMaterials (ZedId, Certification, RawMaterialName, Percentage, CountryName)
			SELECT @ZedId, @CertificationType, Name, Percentage, CountryName FROM @RawMaterialList
		END

	IF EXISTS(select * from @SiteExteriorPhotos)
		BEGIN
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='SiteExteriorPhotos'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'SiteExteriorPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,1 FROM @SiteExteriorPhotos
		END
		ELSE
		BEGIN
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'SiteExteriorPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,1 FROM @SiteExteriorPhotos
		END


	IF EXISTS(select * from @Selfie)
		BEGIN
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='Selfie'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'Selfie', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,2 FROM @Selfie
		END
		ELSE
		BEGIN
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'Selfie', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,2 FROM @Selfie
		END
	
	IF EXISTS(select * from @ProductPhotos)
		BEGIN									
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='ProductPhotos'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductPhotos', PhotoId, 'ProductPhoto', TimeStamp, Latitude, Longitude, PhotoType,3 FROM @ProductPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 


		END
		ELSE
		BEGIN			
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductPhotos', PhotoId, 'ProductPhoto', TimeStamp, Latitude, Longitude, PhotoType,3 FROM @ProductPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 
		END

		IF EXISTS(select * from @ProductDescriptionPhotos)
		BEGIN		
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='ProductDescriptionPhotos'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,ProductId,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductDescriptionPhotos', PhotoId, 'ProductDescriptionPhoto', TimeStamp, Latitude, Longitude, PhotoType,@ProductId,3 FROM @ProductDescriptionPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductDescriptionPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 
		END
		ELSE
		BEGIN			
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,ProductId,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductDescriptionPhotos', PhotoId, 'ProductDescriptionPhoto', TimeStamp, Latitude, Longitude, PhotoType,@ProductId,3 FROM @ProductDescriptionPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductDescriptionPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 
		END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_SURVEILLANCE_INSERT_ESG_CHECKLIST]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SURVEILLANCE_INSERT_ESG_CHECKLIST] 
(
	@RefId VarChar(50)						= NULL,
	@ZedId VarChar(50)						= NULL,	
	@CertificationType VarChar(50)			= NULL,
	
	@EsgChecklist	DynamicEsgCheckList	READONLY,
	@SocialOhsChecklist	DynamicEsgCheckList	READONLY
)
AS
BEGIN		IF EXISTS(SELECT * FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType)
			BEGIN
				DELETE FROM EsgCheckList WHERE ZedId=@ZedId and Certification=@CertificationType and CheckListType='ESG'
				INSERT INTO EsgCheckList (RefId,ZedId,Certification,Code,Question,Answer,IfYesQuestion,IfYesAnswer,IfNoQuestion,IfNoAnswer,CheckListType)
				SELECT @RefId, @ZedId, @CertificationType,Code,Question,Answer,IfYesQuestion,IfYesAnswer,IfNoQuestion,IfNoAnswer,'ESG' FROM @EsgChecklist

				DELETE FROM EsgCheckList WHERE ZedId=@ZedId and Certification=@CertificationType and CheckListType='SOCIAL/OHS'
				INSERT INTO EsgCheckList (RefId,ZedId,Certification,Code,Question,Answer,IfYesQuestion,IfYesAnswer,IfNoQuestion,IfNoAnswer,CheckListType)
				SELECT @RefId, @ZedId, @CertificationType,Code,Question,Answer,IfYesQuestion,IfYesAnswer,IfNoQuestion,IfNoAnswer,'SOCIAL/OHS' FROM @SocialOhsChecklist

				SELECT 1 Status, 'Data submitted Successfully.' ErrorMessage

				--------ADDING NEW CODE FOR ESG REPORT START HERE------------------
				insert into CheckListReport (
				   [ZedId]
				  ,[Certification]
				  ,[SubmissionDate]
				  ,[1. Are you registered under the Factories Act, 1948?]
				  ,[2. Is Consent to Establish (COE) and Consent to Operate (COO) applicable to you?]
				  ,[If yes, have you acquired the Certificate?]
				  ,[If No, what Environmental management measures have been taken?]
				  ,[3. Does the unit generate solid waste? (e.g sludge, oils, waste chemicals)]
				  ,[If yes, have you applied for Solid Waste Management Authorization?]
				  ,[4. Does the unit operations involve handling of hazardous/ dangerous chemicals?]
				  ,[If yes, have your applied for Hazardous Waste Management Authorization?]
				  ,[5. Does the unit operations produce  E waste?]
				  ,[If yes, do you have Authorised agency for E-waste management and handling?]
				  ,[6. Does the unit operations produce  Plastic waste?]
				  ,[If yes,  do you have any EPR authorisation agency for waste management / recycle?]
				  ,[1. Has the unit/project caused or will cause any health hazard to employees?]
				  ,[If yes, specify likely occupational hazards.]
				  ,[2. Has the unit/project comply with Fire Safety rules and Regulations?]
				  ,[If yes, specify potential source of fire hazard and mitigation measures.]
				  ,[3. Do you comply with the State’s Minimum Wage regulation?]
				  ,[4. Do you abide by Child Labour (Prohibition & Regulation) Act?]
				  ,[5. Do you have safe drinking water arrangements?]
				  ,[If No, the reasons]
				  ,[6. Do you have First Aid kits?]
				  ,[7. Is there a separate toilet for women workers?]
				  ,[8. Are there any arrangements for disposal of sanitary pads?]
				
				)
				select * from
				(
				select @ZedId ZedId,@CertificationType Certification,convert(date,GETDATE()) SubmissionDate,Question,Answer from @EsgChecklist
				UNION ALL
				select @ZedId,@CertificationType,convert(date,GETDATE()) SubmissionDate,IfYesQuestion,IfYesAnswer from @EsgChecklist
				UNION ALL
				select @ZedId,@CertificationType,convert(date,GETDATE()) SubmissionDate,IfNoQuestion,IfNoAnswer from @EsgChecklist
				UNION ALL
				select @ZedId,@CertificationType,convert(date,GETDATE()) SubmissionDate,Question,Answer from @SocialOhsChecklist
				UNION ALL
				select @ZedId,@CertificationType,convert(date,GETDATE()) SubmissionDate,IfYesQuestion,IfYesAnswer from @SocialOhsChecklist
				UNION ALL
				select @ZedId,@CertificationType,convert(date,GETDATE()) SubmissionDate,IfNoQuestion,IfNoAnswer from @SocialOhsChecklist
				) A
				pivot 
				(
				max(answer) for question in (
				[1. Are you registered under the Factories Act, 1948?],
				[2. Is Consent to Establish (COE) and Consent to Operate (COO) applicable to you?],
				[If yes, have you acquired the Certificate?],
				[If No, what Environmental management measures have been taken?],
				[3. Does the unit generate solid waste? (e.g sludge, oils, waste chemicals)],
				[If yes, have you applied for Solid Waste Management Authorization?],
				[4. Does the unit operations involve handling of hazardous/ dangerous chemicals?],
				[If yes, have your applied for Hazardous Waste Management Authorization?],
				[5. Does the unit operations produce  E waste?],
				[If yes, do you have Authorised agency for E-waste management and handling?],
				[6. Does the unit operations produce  Plastic waste?],
				[If yes,  do you have any EPR authorisation agency for waste management / recycle?],
				[1. Has the unit/project caused or will cause any health hazard to employees?],
				[If yes, specify likely occupational hazards.],
				[2. Has the unit/project comply with Fire Safety rules and Regulations?],
				[If yes, specify potential source of fire hazard and mitigation measures.],
				[3. Do you comply with the State’s Minimum Wage regulation?],
				[4. Do you abide by Child Labour (Prohibition & Regulation) Act?],
				[5. Do you have safe drinking water arrangements?],
				[If No, the reasons],
				[6. Do you have First Aid kits?],
				[7. Is there a separate toilet for women workers?],
				[8. Are there any arrangements for disposal of sanitary pads?]
				)
				)
				as p

				--------ADDING NEW CODE FOR ESG REPORT END   HERE------------------
		    END

			ELSE

			BEGIN
				SELECT 0 Status, 'Invalid Details.' ErrorMessage
			END
	
	
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_SYNC_SUVEILLANCE_PHOTOS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SYNC_SUVEILLANCE_PHOTOS] 
(
	@ZedId VarChar(50)			= NULL,
	@AssessorId VarChar(50)		= NULL,
	@PhotoType VarChar(50)		= NULL,	
	@CertificationType VarChar(50)		= NULL,
	@RefId VarChar(50)			= NULL,
	@EvidenceId VarChar(50)		= NULL,	
			
	@PhotoList	DynamicPhotoList2	READONLY
)
AS
BEGIN
	
	DECLARE @NcCount int = NULL
	DECLARE @CertificationStatus int = NULL
	SELECT @NcCount=NcCount, @CertificationStatus=CertificationStatus FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and  SiteAssessorId is not null and SaCertificateNo is null

	IF (@CertificationStatus>13 OR @CertificationStatus<9)
	BEGIN
	SELECT 0 StatusCode, 'Cannot Sync Now. Please check with Assessor as final submission done from their end.' Message
	END

	ELSE
	BEGIN
		DELETE FROM SaPhotos WHERE ZedId=@ZedId and Certification=@CertificationType and PhotoId IN (SELECT PhotoId FROM @PhotoList)
		INSERT INTO SaPhotos (ZedId,AssessorId, EvidenceId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount)
		SELECT @ZedId, @AssessorId, @EvidenceId, @CertificationType, @PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,@NcCount FROM @PhotoList

		SELECT 1 StatusCode, 'Success' Message
	END
	
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APPLY_BRONZE_SURVEILLANCE_FROM_BACKEND]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create PROCEDURE [dbo].[SP_APPLY_BRONZE_SURVEILLANCE_FROM_BACKEND] 
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	SET NOCOUNT ON; -- This stops "rows affected" messages from slowing down the loop
	
	DECLARE @PaymentRefId INT = NULL,
	        @MsmeId varchar(50) = NULL,
            @CertGstNo varchar(50) = null, 
            @CertTanNo varchar(50) = null, 
            @CertTds varchar(50) = null, 
            @CertUnitGstin varchar(50) = null, 
            @CertTdsDeductable varchar(50) = null,
            @EnterpriseTypee varchar(50), 
            @SpecialCategory varchar(50), 
            @IsAspirationalDt varchar(50), 
            @SubsidyUsed bit = 0;

    -- 1. Combined lookup: Fetch all metadata in ONE hit to the tables
	SELECT 
        @CertGstNo = GstinNumber,
        @CertTanNo = TanNumber,
        @CertTds = Tds,
        @CertUnitGstin = UnitGstin,
        @CertTdsDeductable = TdsDeductible  
    FROM ZEDCS_V2_LIVE.DBO.MsmePaymentInfo 
    WHERE ZedId = @ZedId AND Certification = @Certification;

	SELECT 
        @MsmeId = m.MsmeId,
        @EnterpriseTypee = m.EnterpriseTypee,
        @IsAspirationalDt = d.IsAspirationalDt
    FROM msme m
    LEFT JOIN Districts d ON d.DistrictCode = m.PLgDistrictCode
    WHERE m.ZedId = @ZedId;

    -- 2. Check for Subsidy
    IF EXISTS(SELECT 1 FROM PaymentGateWayTransactions WHERE Certification = @Certification AND PaymentStatus = 'success' AND ZedId = CONCAT(@ZedId,'_D'))
    BEGIN
		SET @SubsidyUsed = 1;
    END

    -- 3. Calculate Special Category
	SELECT @SpecialCategory = CASE 
        WHEN Gender = 'Female' THEN 1 
        WHEN SocialCategoryName IN ('SC','ST') THEN 1 
        WHEN @IsAspirationalDt = '1' THEN 1 
        ELSE 0 END 
    FROM MsmeBasicInformation 
    WHERE MsmeId = @MsmeId;

    -- 4. Logic for PaymentRefId (REMOVED the SELECT * result sets)
	IF EXISTS(SELECT 1 FROM MsmeCertifications WHERE ZedId = CONCAT(@ZedId,'_D') AND Certification = @Certification) AND @SubsidyUsed = 1
	BEGIN
		SELECT TOP 1 @PaymentRefId = Id 
        FROM AssessmentFee 
        WHERE EnterpriseTypee = 'REJECTED' AND Certification = @Certification AND Coupon IS NOT NULL;
	END
	ELSE
	BEGIN
		SELECT TOP 1 @PaymentRefId = Id 
        FROM AssessmentFee 
        WHERE EnterpriseTypee = @EnterpriseTypee AND Certification = @Certification AND Coupon IS NOT NULL AND SpecialCategory = @SpecialCategory;
	END

    -- 5. Final Execution
	EXEC [SP_MSME_ZERO_PAYMENT_DETAILS] @ZedId, @Certification, NULL, @CertUnitGstin, @CertGstNo, @CertTdsDeductable, @CertTds, @CertTanNo, @PaymentRefId;

    -- Return only one final message (Optional: Comment this out for maximum speed)
	-- SELECT '<redacted>' as Status; 
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APPLY_BRONZE_SURVEILLANCE_FROM_BACKEND_BY_STATE_DISTRICT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_APPLY_BRONZE_SURVEILLANCE_FROM_BACKEND_BY_STATE_DISTRICT] --'<redacted>'
(
    @StateName     VARCHAR(100)
   -- @DistrictList  VARCHAR(MAX)  -- '<redacted>'  --FIRST DISABLE AUTO ALLOCATION IN ZERO PAYMENT DETAILS 
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE 
        @ZedId VARCHAR(50),
        @Certification VARCHAR(50) = 'Bronze';

    
    --DECLARE @Districts TABLE (DistrictName VARCHAR(100));

    --INSERT INTO @Districts (DistrictName)
    --SELECT LTRIM(RTRIM(value))
    --FROM STRING_SPLIT(@DistrictList, '<redacted>');

    
    DECLARE cur_apply CURSOR FAST_FORWARD FOR
    SELECT DISTINCT TOP 2000
           C.ZedId
    FROM zedcs_v2_live.dbo.MsmeCertifications C
    INNER JOIN zedcs_v2_live.dbo.Msme M 
            ON M.ZedId = C.ZedId
    --INNER JOIN @Districts D 
    --        ON D.DistrictName = M.PDistrictName
    WHERE C.Certification = 'Bronze'
      AND C.CertificationStatus = 6
      AND M.PStateName = @StateName
	  AND M.IsSurBronzePaymentDone is null
     -- AND DATEDIFF(DAY, C.CertificationStatusDate, GETDATE()) BETWEEN 451 AND 899
	 and convert(date,C.CertificationStatusDate)>'2024-09-18'
	 AND C.CertificationStatusDate <= DATEADD(MONTH, -14, GETDATE())

      -- Exclude Silver / Gold upgraded MSMEs
      AND NOT EXISTS (
            SELECT 1
            FROM zedcs_v2_live.dbo.MsmeCertifications C2
            WHERE C2.ZedId = C.ZedId
              AND C2.Certification IN ('Gold','Silver')
              AND C2.CertificationStatus = 16
      )

      -- Exclude already applied Bronze Surveillance
      AND NOT EXISTS (
            SELECT 1
            FROM ZED_SURVEILLANCE.dbo.MsmeCertifications SC
            WHERE SC.ZedId = C.ZedId
              AND SC.Certification = 'Bronze'
      );

    OPEN cur_apply;
    FETCH NEXT FROM cur_apply INTO @ZedId;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        BEGIN TRY
            EXEC dbo.SP_APPLY_BRONZE_SURVEILLANCE_FROM_BACKEND
                 @ZedId = @ZedId,
                 @Certification = @Certification;
        END TRY
        BEGIN CATCH
            PRINT 'Failed for ZedId: ' + ISNULL(@ZedId,'');
        END CATCH;

        FETCH NEXT FROM cur_apply INTO @ZedId;
    END

    CLOSE cur_apply;
    DEALLOCATE cur_apply;
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APPLY_BRONZE_SURVEILLANCE_FROM_BACKEND_old]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_APPLY_BRONZE_SURVEILLANCE_FROM_BACKEND_old] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
	DECLARE @PaymentRefId VARCHAR(50) = NULL,
	@MsmeId varchar(50) = NULL

	--IF NOT EXISTS (
	--SELECT 1 FROM ZED_SURVEILLANCE.dbo.MsmePaymentInfo 
	--WHERE ZedId = @ZedId AND Certification = @Certification
	--)
	--AND EXISTS (
	--	SELECT 1 FROM ZEDCS_V2_LIVE.dbo.MsmeCertifications 
	--	WHERE ZedId = @ZedId AND Certification = @Certification 
	--	AND RestrictMail IS NULL AND CertificationPhase = '<redacted>'
	--)
	BEGIN

	DECLARE @CertGstNo varchar(50) = null, @CertTanNo varchar(50) = null, @CertTds varchar(50) = null, @CertUnitGstin varchar(50) = null, @CertTdsDeductable varchar(50) = null
	print @CertGstNo
	select @CertGstNo=GstinNumber,@CertTanNo=TanNumber,@CertTds=Tds,@CertUnitGstin=UnitGstin,@CertTdsDeductable=TdsDeductible  from ZEDCS_V2_LIVE.DBO.MsmePaymentInfo where ZedId=@ZedId AND Certification=@Certification
	--print concat('<redacted>',@CertGstNo,'<redacted>', @CertTanNo,'<redacted>', @CertTds)


	DECLARE @EnterpriseTypee varchar(50), @SpecialCategory varchar(50), @IsAspirationalDt varchar(50), @SubsidyUsed bit = 0
	
	select @IsAspirationalDt=IsAspirationalDt from Districts where DistrictCode in (select PLgDistrictCode from Msme where ZedId=@ZedId)

	if @MsmeId IS NULL
		SELECT @MsmeId = MsmeId from msme where ZedId=@ZedId

		SELECT @EnterpriseTypee=EnterpriseTypee FROM Msme Where ZedId=@ZedId

		IF EXISTS(SELECT * FROM PaymentGateWayTransactions  where Certification=@Certification and PaymentStatus='success' and ZedId=CONCAT(@ZedId,'_D'))
		SET @SubsidyUsed = 1


	SELECT  @SpecialCategory = CASE WHEN Gender='Female' then 1 WHEN SocialCategoryName in ('SC','ST') THEN 1 WHEN @IsAspirationalDt=1 then 1 else 0 END FROM MsmeBasicInformation Where MsmeId=@MsmeId

	IF (select count(*) from MsmeCertifications where ZedId=CONCAT(@ZedId,'_D') and Certification=@Certification)>0 AND @SubsidyUsed=1
	BEGIN
		
		SELECT *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel, @CertGstNo CertGstNo ,@CertTanNo CertTanNo,@CertTds CertTds,@CertUnitGstin CertUnitGstin, @CertTdsDeductable CertTdsDeductable  FROM AssessmentFee WHERE EnterpriseTypee='REJECTED' AND Certification=@Certification AND Coupon IS NOT NULL --AND SpecialCategory IS  NULL	
		select @PaymentRefId=Id FROM AssessmentFee WHERE EnterpriseTypee='REJECTED' AND Certification=@Certification AND Coupon IS NOT NULL
		print 1
		

	END

	ELSE
	BEGIN
		
		SELECT *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel, @CertGstNo CertGstNo ,@CertTanNo CertTanNo,@CertTds CertTds,@CertUnitGstin CertUnitGstin, @CertTdsDeductable CertTdsDeductable  FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory = @SpecialCategory
		select @PaymentRefId=Id FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory = @SpecialCategory
		print 3

		
	END

	SELECT  case when IsCouponUsed=1 then 1 else 0 end as IsCouponUsed from msme where ZedId=@ZedId


	EXEC [SP_MSME_ZERO_PAYMENT_DETAILS] @ZedId, @Certification, NULL, @CertUnitGstin, @CertGstNo, @CertTdsDeductable, @CertTds, @CertTanNo, @PaymentRefId

	SELECT 'RECORD INSERTED SUCCESSFULLY'

	END

	--ELSE
	--BEGIN
	--	PRINT '<redacted>'
	--END
	
END

GO
