CREATE PROC [dbo].[SP_ASSESSMENT_ACCEPT_UNIT_FOR_DA_VERIFICATION]
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	UPDATE MsmeCertifications SET DesktopAccepted = 1, DesktopAcceptOrRejectDate=getdate() where ZedId=@ZedId AND Certification=@Certification

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
	values (@ZedId,concat('DA for ',@Certification, ' Accepted by Assessor '),getdate(),@Certification,NULL)

	EXEC [SP_UPDATING_OPENEDFLAG] @ZedId,@Certification,0

END



