CREATE PROC [dbo].[SP_ASSESSMENT_ACCEPT_UNIT_FOR_SA]
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@SiteAssessorId varchar(100) = NULL,
	@AssessmentDate varchar(50) = NULL,
	@ModeOfAssessment varchar(100) = NULL,
	@CoAssessorId varchar(100) = NULL,
	@MeetingLink varchar(5000) = NULL
)
AS
BEGIN

	Declare @NcCount int  = NULL
	Select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId AND Certification=@Certification

	Declare @LeadAssessorName varchar(200)  = NULL
	Select @LeadAssessorName=UserName from Users where UserId=@SiteAssessorId AND RoleId=3
	
	UPDATE MsmeSections SET AssessorId=@SiteAssessorId where ZedId=@ZedId AND SectionType=@Certification

	UPDATE MsmeCertifications
	SET SiteAssessorId = @SiteAssessorId,CoAssessorId = @CoAssessorId, AssessmentDate=@AssessmentDate, ModeOfAssessment=@ModeOfAssessment, MeetingLink=@MeetingLink,
	CertificationStatus=9, DesktopAccepted=1
	where ZedId=@ZedId AND Certification=@Certification

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
	values (@ZedId,concat('Scheduled on  ',@AssessmentDate),getdate(),@Certification,'ScheduledOn')

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
	values (@ZedId,concat('SA for ',@Certification, ' Alotted to',@SiteAssessorId,' and ',@CoAssessorId ),getdate(),@Certification,NULL)


	--insert into MsmeEvidences(EvidenceId, ZedId,SectionCode,RequirementCode,EvidenceCode,SectionType,EvidenceName,NcCount,RequirementId)
	--select (next value for EvidenceIdSequence),M.ZedId,M.SectionCode,RequirementCode,concat('<redacted>',@NcCount),M.SectionType,
	--concat('<redacted>',@NcCount),@NcCount,RequirementId from MsmeRequirements M inner join  MsmeSections S on (M.ZedId=S.ZedId and M.SectionType=S.SectionType and M.SectionCode=S.SectionCode and M.NcCount=S.NcCount) 
	--where M.zedid=@ZedId  and M.NcCount=@NcCount and (IsAssessmentExcempted is null or IsAssessmentExcempted='<redacted>')
		
	--IF @ModeOfAssessment='<redacted>'
	--	BEGIN
			--update MsmeSections set AssessorId=@SiteAssessorId where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and (IsAssessmentExcempted='<redacted>' or IsAssessmentExcempted is null)

			--UPDATE MsmeCertifications SET  CertificationStatus=9 where ZedId=@ZedId AND Certification=@Certification

			DELETE from Meetings where ZedId=@ZedId and CertificationType=@Certification
			DELETE from MeetingParticipants where ZedId=@ZedId and CertificationType=@Certification
			
			INSERT INTO Meetings (ZedId,CertificationType,AssessorId,MeetingType)
			VALUES (@ZedId,@Certification,@SiteAssessorId,'Open Meeting')

			INSERT INTO Meetings (ZedId,CertificationType,AssessorId,MeetingType)
			VALUES (@ZedId,@Certification,@SiteAssessorId,'Close Meeting')

			INSERT INTO MeetingParticipants (ZedId,Name,Designation,MeetingType,CertificationType)
			VALUES (@ZedId,@LeadAssessorName,'Lead Assessor','Open Meeting',@Certification)

			INSERT INTO MeetingParticipants (ZedId,Name,Designation,MeetingType,CertificationType)
			VALUES (@ZedId,@LeadAssessorName,'Lead Assessor','Close Meeting',@Certification)

			--insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			--values (@ZedId,concat('<redacted>',@AssessmentDate),getdate(),@Certification,'<redacted>')

		--END

END



