/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_AGENCIES_TO_ALLOT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--[SP_ASSESSMENT_AGENCIES_TO_ALLOT] '<redacted>'
CREATE PROC [dbo].[SP_ASSESSMENT_AGENCIES_TO_ALLOT] --'<redacted>'
(
	@ZedId varchar(50) = NULL
)
AS
BEGIN

	DECLARE @Certification varchar(50) = NULL
	select TOP 1 @Certification=Certification from MsmeCertifications where ZedId=@ZedId order by id desc

	--declare @UnitState int
	--select @UnitState=StateId from Msme where ZedId=@ZedId

	IF @Certification='Bronze'
	BEGIN
		
		select U.UserId,UserName,DesktopVerification, SiteVerification, FinancialVerification, AllowBronzeSurveillance 
		from Users U where RoleId=2 AND AllowBronzeSurveillance=1 AND TuPreferredState=(SELECT StateId FROM Msme WHERE ZedId=@ZedId)
		--AND States in (SELECT PStateName FROM Msme WHERE ZedId=@ZedId)) A

		INTERSECT

		SELECT UserId,UserName,DesktopVerification, SiteVerification, FinancialVerification,AllowBronzeSurveillance from
		(SELECT UserId, UserName,DesktopVerification, SiteVerification, FinancialVerification,AllowBronzeSurveillance FROM Users WHERE RoleId=2 AND IsActive = 1 AND AllowBronzeSurveillance=1 and UserId not in (select distinct UserId from UserNicSectors where RoleId=2) 
		UNION
		select U.UserId,UserName,DesktopVerification, SiteVerification, FinancialVerification,AllowBronzeSurveillance from UserNicSectors A inner join Users U on (A.UserId=U.UserId) where A.RoleId=2 AND AllowBronzeSurveillance=1 AND NicSectorCode in (SELECT SUBSTRING(TwoDigitActivity,1,2) FROM Msme WHERE ZedId=@ZedId))B
		order by UserName
	END
	ELSE
	BEGIN
		SELECT UserId,UserName,DesktopVerification, SiteVerification, FinancialVerification,AllowBronzeSurveillance from 
		(SELECT UserId, UserName,DesktopVerification, SiteVerification, FinancialVerification,AllowBronzeSurveillance  FROM Users WHERE RoleId=2 AND IsActive = 1 AND AllowBronzeSurveillance=0 and UserId not in (select distinct UserId from AgencyUserStates where RoleId=2) 
		UNION
		select U.UserId,UserName,DesktopVerification, SiteVerification, FinancialVerification, AllowBronzeSurveillance from AgencyUserStates A inner join Users U on (A.UserId=U.UserId) where A.RoleId=2 AND AllowBronzeSurveillance=0 AND States in (SELECT PStateName FROM Msme WHERE ZedId=@ZedId)) A

		INTERSECT

		SELECT UserId,UserName,DesktopVerification, SiteVerification, FinancialVerification,AllowBronzeSurveillance from
		(SELECT UserId, UserName,DesktopVerification, SiteVerification, FinancialVerification,AllowBronzeSurveillance FROM Users WHERE RoleId=2 AND IsActive = 1 AND AllowBronzeSurveillance=0 and UserId not in (select distinct UserId from UserNicSectors where RoleId=2) 
		UNION
		select U.UserId,UserName,DesktopVerification, SiteVerification, FinancialVerification,AllowBronzeSurveillance from UserNicSectors A inner join Users U on (A.UserId=U.UserId) where A.RoleId=2 AND AllowBronzeSurveillance=0 AND NicSectorCode in (SELECT SUBSTRING(TwoDigitActivity,1,2) FROM Msme WHERE ZedId=@ZedId))B
		order by UserName
	END

	

END



