CREATE PROC [dbo].[SP_ASSESSMENT_ALLOT_TO_AGENCY]
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@CertificationBodyUserId varchar(100) = NULL
)
AS
BEGIN
	
	UPDATE [MsmeCertifications] 
	SET CertificationBodyUserId=@CertificationBodyUserId,AcceptOrRejectDate=NULL,ReasonForRejection=NULL,DesktopAssessorId=null,DesktopAccepted=null,
	DesktopAcceptOrRejectDate=null, CertificationStatus=case when CertificationStatus=3 then 2 else CertificationStatus end
	where  ZedId=@ZedId AND Certification=@Certification

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
	values (@ZedId,concat('DA for ',@Certification, ' Alotted to Agency ',@CertificationBodyUserId),getdate(),@Certification,NULL)

END



