/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_CHECK_NC_PHOTO_AVAILABILITY]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_ASSESSMENT_CHECK_NC_PHOTO_AVAILABILITY] --'<redacted>','<redacted>'
(
	
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
	
)
AS
BEGIN

	DECLARE @NcCount int = NULL,
			@CertStatus int = NULL
	
	select @NcCount=NcCount, @CertStatus=CertificationStatus from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType
	print @NcCount

	SET NOCOUNT ON;

	IF @CertStatus<6
	BEGIN

		SELECT CONCAT('E:\Publish\ZED_SURVEILLANCE\ZED_SURVEILLANCE_SERVICES\Photos/',@ZedId,'/',@CertificationType,'/SiteExteriorPhotos/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos where name='SiteExteriorPhotos' and ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and NcCount>0 order by Id

		SELECT CONCAT('E:\Publish\ZED_SURVEILLANCE\ZED_SURVEILLANCE_SERVICES\Photos/',@ZedId,'/',@CertificationType,'/BasicInfo/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos where name='BasicInfo' and ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and NcCount>0 order by Id

		SELECT CONCAT('E:\Publish\ZED_SURVEILLANCE\ZED_SURVEILLANCE_SERVICES\Photos/',@ZedId,'/',@CertificationType,'/Evidences/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos where name='Evidences' and ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and NcCount>0 order by Id
	
	END

	IF  @CertStatus>6
	BEGIN

		SELECT CONCAT('Photos/',@ZedId,'/SiteExteriorPhotos/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos where 1=2

		SELECT CONCAT('Photos/',@ZedId,'/BasicInfo/',PhotoId,'.jpg') as PhotoPath, PhotoId from MsmePhotos where 1=2
		
		--SELECT PhotoId, CONCAT('<redacted>',@ZedId,@CertificationType,'<redacted>',PhotoId,'<redacted>') as PhotoPath from SaRequirementPhotos where RequirementId in (SELECT RequirementId from MsmeRequirements where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and NcCount>0) 
		--and ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and NcCount>0
		
		SELECT CONCAT('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos/',@ZedId,'/',@CertificationType,'/Evidences/',PhotoId,'.jpg') as PhotoPath, PhotoId from SaRequirementPhotos where 
		ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and NcCount>0 and 1=2
	
	END

END



GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_DA_AUTO_REJECT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_DA_AUTO_REJECT] 
(
	@ZedId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL,
	@AssessorRemarks VarChar(5000)			= NULL
)
AS
BEGIN
	
	Declare @NcCount int  = NULL
	Declare @ErrorStatus bit = 0

	Declare @EvidenceId varchar(50) = NULL
	

	--Select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType

			--UPDATE MsmeCertifications set PreviousCertificationStatus=CertificationStatus where ZedId=@ZedId and Certification=@CertificationType

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			select ZedId,concat('Auto Rejected On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),Certification,'Certification auto Rejected due to NC closure time is exceeded' from MsmeCertifications where certificationstatus=4 and NcFinalClosureDt<GETDATE() and Certification='Bronze' 
			UPDATE MsmeCertifications set PreviousCertificationStatus = CertificationStatus, NcCount=6, CertificationStatus=7,CertificationStatusDate=getdate(),IsAutoReject=1 where certificationstatus<=4 and NcFinalClosureDt<GETDATE() and Certification='Bronze'
			
			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			select ZedId,concat('Auto Rejected On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),Certification,'Certification auto Rejected due to NC closure time is exceeded' from MsmeCertifications where certificationstatus=14 and NcFinalClosureDt<GETDATE() and Certification in ('Silver','Gold') 
			UPDATE MsmeCertifications set PreviousCertificationStatus = CertificationStatus, NcCount=6, CertificationStatus=17,CertificationStatusDate=getdate(),IsAutoReject=1 where certificationstatus<=14 and NcFinalClosureDt<GETDATE() and Certification in ('Silver','Gold')


END
GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_DA_CONFIRM_FINAL_SUBMIT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_DA_CONFIRM_FINAL_SUBMIT] --'<redacted>','<redacted>'
(
	@ZedId VarChar(50)				= NULL,
	@CertificationType VarChar(50)	= NULL
)
AS
BEGIN

	Declare @NcCount int  = NULL

	Select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType

	IF
	(select count(*) from MsmePhotos where PhotoType='SiteExteriorPhotos' and Certification=@CertificationType and ZedId=@ZedId and IsVerified IS NULL and NcCount=@NcCount)>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more Exterior Photos. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsVerified IS NULL and NcCount=@NcCount)>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more products. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeRequirements where SectionType=@CertificationType and ZedId=@ZedId and Conformance IS NULL and NcCount=@NcCount)>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more parameters. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeSections S inner join MsmeEvidences E on (S.SectionCode=E.SectionCode ) where E.zedid=@ZedId and S.zedid=@ZedId and ValidationRequired=1 and E.SectionType=s.SectionType and S.SectionType=@CertificationType and IsAssessmentExcempted IS NULL and S.NcCount=@NcCount)>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more Exemptions. Please review.' ErrorMessage

	ELSE 
	select 1 AllowFinalSubmit, '' ErrorMessage

	IF @NcCount>=5
	SELECT 0 RaisedForNc
	
	ELSE IF @CertificationType='Bronze' and (select count(*) from MsmePhotos where PhotoType='SiteExteriorPhotos' and Certification=@CertificationType and ZedId=@ZedId and IsVerified='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc

	ELSE IF @CertificationType='Bronze' and (select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsVerified='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc
	
	ELSE IF @CertificationType='Bronze' and (select count(*) from MsmeRequirements where SectionType=@CertificationType and ZedId=@ZedId and Conformance='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc

	ELSE 
		SELECT 0 RaisedForNc
	

END
GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_DA_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_ASSESSMENT_DA_DETAILS] '<redacted>',7,'<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_DA_DETAILS] --'<redacted>','<redacted>','<redacted>','<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @Certification='SilverMilestone1'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_DA_DETAILS] @UserId, @RoleId, @ZedId, 'Silver', 1
	END

	ELSE IF @Certification='SilverMilestone2'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_DA_DETAILS] @UserId, @RoleId, @ZedId, 'Silver', 2
	END

	ELSE IF @Certification='SilverMilestone3'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_DA_DETAILS] @UserId, @RoleId, @ZedId, 'Silver', 3
	END

	ELSE IF @Certification='GoldMilestone1'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_DA_DETAILS] @UserId, @RoleId, @ZedId, 'Gold', 1
	END

	ELSE IF @Certification='GoldMilestone2'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_DA_DETAILS] @UserId, @RoleId, @ZedId, 'Gold', 2
	END

	ELSE IF @Certification='GoldMilestone3'
	BEGIN 
		
		exec ZED_CONSULTANT.[dbo].[SP_ASSESSMENT_DA_DETAILS] @UserId, @RoleId, @ZedId, 'Gold', 3
	END




	ELSE
	BEGIN

		DECLARE @CurrentUrl varchar(100) = NULL,
		@ModeOfAssessment varchar(50) = NULL,
		@TargetCertification VARCHAR(50)

	    select @TargetCertification=LastestCertification from MsmeBasicinformation where ZedId=@ZedId

		IF(select count(*) from MsmeCertifications where zedid=@ZedId and Certification=@Certification and ((SiteAssessorId=@UserId and @RoleId=3) OR (DesktopAssessorId=@UserId and @RoleId=3) OR (CoAssessorId=@UserId and @RoleId=3) OR (CertificationBodyUserId=@UserId AND @RoleId=2) OR (@RoleId=10) OR (@RoleId=11) OR (@RoleId=7) OR (@RoleId=8) OR (ZedId=@ZedId AND (@RoleId is null OR @RoleId=5))))=0
		BEGIN
			SET @ZedId='000'
		END

		SELECT @CurrentUrl=UrlName from UrlsMasterData
		SELECT @ModeOfAssessment=ModeOfAssessment from MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

		-------FOR REJECTION RECORD ------------------------
		IF @ZedId LIKE '%[_]D%' OR @ZedId LIKE '%[_]S%'
		BEGIN
			SELECT C.Id, C.ZedId, C.Certification, M.EnterpriseName,M.PUnitName, UdyogAadharNo, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) PlantAddress,
				CertificationBodyUserId,UB.UserName AgencyName,
				C.DesktopAssessorId, U.UserName DesktopAssessorName,SiteAssessorId ,UL.UserName SiteAssessorName,CoAssessorId,UC.UserName CoAssessorName, C.AuditsConducted, C.DomesticCustomers, ISNULL(C.InternationalCustomers,'-') InternationalCustomers, C.RawMaterialImported, C.OutsourcedProcesses, replace(C.EnergySources,',',', ') EnergySources,
				 FORMAT(DesktopAcceptOrRejectDate, 'MMMM d, yyyy') DaAllocationDate, C.CertificationStatus,SendBackStatus,IsAutoReject,
				 (select top 1 AssessorRemarks from AssessorComments ASSC where NcCount=0 and ZedId=@ZedId and Assc.Certification=@Certification and AssessmentType='DA' order by CertificationStatusDate desc) AssessorRemarks,
				 (select top 1 AssessorRemarks from AssessorComments ASSC where NcCount=6 and ZedId=@ZedId and Assc.Certification=@Certification and AssessmentType='RJ' order by CertificationStatusDate desc) SendBackRemarks,
				 'MsmeCertifications' TableName, C.NcCount, FORMAT(CertificationStatusDate, 'MMMM d, yyyy') DaVerificationDate,
				 NcStatus,Nc1Status,Nc2Status,Nc3Status,Nc4Status,Nc5Status,MeetingLink,
				 C.IsSaVerified,
				 (select top 1 SaAssessorRemarks from AssessorComments ASSC where NcCount=0 and ZedId=@ZedId and Assc.Certification=@Certification and AssessmentType='SA' order by CertificationStatusDate desc) SaAssessorRemarks,
				 C.CertificationBodyUserId, UB.UserName, FORMAT(EvidenceSubmissionDate, 'MMMM d, yyyy') EvidenceSubmissionDate,FORMAT(AssessmentDate, 'MMMM d, yyyy') AssessmentDate,
				 SaAuditsConducted,	SaDomesticCustomers,	SaInternationalCustomers,	SaRawMaterialImported,	SaOutsourcedProcesses,	SaEnergySources, ModeOfAssessment, 
				-- (select max(NcCount) SecNcCount from MsmeSections where ZedId=@ZedId and SectionType=@Certification) SecNcCount, 

				( select max(NcCount) from 
				 (select max(NcCount) NcCount from MsmeProducts  where ZedId=@ZedId and Certification=@Certification union
				 select max(NcCount) NcCount from MsmeSections where ZedId=@ZedId and SectionType=@Certification union
				 select max(NcCount) NcCount from MsmePhotos where ZedId=@ZedId and Certification=@Certification union

				 select NcCount1 from (
				select max(P.NcCount)+1 as NcCount1,c.NcCount from MsmePhotos P inner join MsmeCertifications C on (P.ZedId=C.ZedId and P.Certification=C.Certification)
				where C.ZedId=@ZedId and C.Certification=@Certification and PhotoType='SiteExteriorPhotos' and IsVerified='No'
				group by P.ZedId,C.NcCount) A
				where NcCount1<=NcCount

				 )a
				 ) SecNcCount,

				 PV.BasicInfoStatus, PV.DocVerifiAllot, PV.DesktopVerification DesktopVerificationCompleted, Completed SaCompletedOn
				,PVD.BasicInfoStatus
				,PVD.DesktopVerification
				,PVD.BronzeDesktopVerification
				,PVD.ScheduledOn
				,PVD.CompletedOn
				,PVD.Nc1Raised
				,PVD.Nc1Submitted
				,PVD.Nc2Raised
				,PVD.Nc2Submitted
				,PVD.Nc3Raised
				,PVD.Nc3Submitted
				,PVD.Nc4Raised
				,PVD.Nc4Submitted
				,PVD.Nc5Raised
				,PVD.Nc5Submitted
				,PVD.NcClosed
				,PVD.GetCertified
				,PVD.ApplicationReceived
				,PVD.NcFinalClosureDate,
				case when @UserId=CoAssessorId then 0 else 1 end as IsCoAssessorLogin,
				ManufacturingCapacityUnits,	ManufacturingCapacityValue,	MonthlyUtilizationUnits,	MonthlyUtilizationValue,		
				SaManufacturingCapacityUnits,	SaManufacturingCapacityValue,	SaMonthlyUtilizationUnits,	SaMonthlyUtilizationValue,
				PhotosPath, case when PhotosPath is not null then 'https://loginzed.msme.gov.in/surveillancemobileapi/CertifiedPhotos/' else 'https://loginzed.msme.gov.in/surveillancemobileapi/Photos/' end as PhotosBasePath

				FROM MsmeCertifications C 
				--INNER JOIN Msme M ON (C.ZedId=concat(M.ZedId,'<redacted>'))
				INNER JOIN Msme M ON (replace(REPLACE(REPLACE(C.zedid,'_D',''),'_S',''),concat('_',C.Id),'')=M.ZedId)
				INNER JOIN MsmeBasicInformation B ON (M.ZedId=B.ZedId )
				LEFT JOIN Users U ON (C.DesktopAssessorId=U.UserId)
				LEFT JOIN Users UB ON (C.CertificationBodyUserId=UB.UserId)
				LEFT JOIN Users UL ON (C.SiteAssessorId=UL.UserId)
				LEFT JOIN Users UC ON (C.CoAssessorId=UC.UserId)
				LEFT JOIN
				(select * from 
				(
				  select ZedId, StatusType, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,CertificationType
				  from MsmeHistory where CertificationType is not null and StatusType is not null
				) src
				pivot
				(
				  max(CreatedOn)
				  for StatusType in ([BasicInfoStatus], [DocVerifiAllot], [DesktopVerification],[Completed])
				) piv) PV
				on (C.ZedId=PV.ZedId and C.Certification=PV.CertificationType and PV.CertificationType=@Certification)

				LEFT JOIN
				(
				select ZedId,CertificationType,
					ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
					case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
					case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],
					[ScheduledOn],
					Completed as [CompletedOn],
					[Nc1Raised],
					[Nc1Submitted],
					[Nc2Raised],
					[Nc2Submitted],
					[Nc3Raised],
					[Nc3Submitted],
					[Nc4Raised],
					[Nc4Submitted],
					[Nc5Raised],
					[Nc5Submitted],
					[NcClosed],
					[GetCertified],
					[ApplicationReceived],
					[NcFinalClosureDate]			
					from 
					(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where ZedId=@ZedId and CertificationType=@Certification and statustype is not null) A
					pivot (
					max(CreatedOn) for StatusType in (
					[BasicInfoStatus],
					[DesktopVerification],
					[ScheduledOn],
					[Completed],
					[Nc1Raised],
					[Nc1Submitted],
					[Nc2Raised],
					[Nc2Submitted],
					[Nc3Raised],
					[Nc3Submitted],
					[Nc4Raised],
					[Nc4Submitted],
					[Nc5Raised],
					[Nc5Submitted],
					[NcClosed],
					[GetCertified],
					[ApplicationReceived],
					[NcFinalClosureDate]) ) as Pvt
				) PVD
				on (C.ZedId=PVD.ZedId and C.Certification=PVD.CertificationType and PVD.CertificationType=@Certification) 

			WHERE c.Certification=@Certification 
				AND C.ZedId=@ZedId
        END

		----------NORMAL QUERY ---------------------------------
		ELSE
		BEGIN
				SELECT C.Id, C.ZedId, C.Certification, M.EnterpriseName,M.PUnitName, UdyogAadharNo, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) PlantAddress,
				CertificationBodyUserId,UB.UserName AgencyName,
				C.DesktopAssessorId, U.UserName DesktopAssessorName,SiteAssessorId ,UL.UserName SiteAssessorName,CoAssessorId,UC.UserName CoAssessorName, C.AuditsConducted, C.DomesticCustomers, ISNULL(C.InternationalCustomers,'-') InternationalCustomers, C.RawMaterialImported, C.OutsourcedProcesses, replace(C.EnergySources,',',', ') EnergySources,
				 FORMAT(DesktopAcceptOrRejectDate, 'MMMM d, yyyy') DaAllocationDate, C.CertificationStatus,SendBackStatus,IsAutoReject,
				 (select top 1 AssessorRemarks from AssessorComments ASSC where NcCount=0 and ZedId=@ZedId and Assc.Certification=@Certification and AssessmentType='DA' order by CertificationStatusDate desc) AssessorRemarks,
				 (select top 1 AssessorRemarks from AssessorComments ASSC where NcCount=6 and ZedId=@ZedId and Assc.Certification=@Certification and AssessmentType='RJ' order by CertificationStatusDate desc) SendBackRemarks,
				 'MsmeCertifications' TableName, C.NcCount, FORMAT(CertificationStatusDate, 'MMMM d, yyyy') DaVerificationDate,
				 NcStatus,Nc1Status,Nc2Status,Nc3Status,Nc4Status,Nc5Status,MeetingLink,
				 C.IsSaVerified,
				 (select top 1 SaAssessorRemarks from AssessorComments ASSC where NcCount=0 and ZedId=@ZedId and Assc.Certification=@Certification and AssessmentType='SA' order by CertificationStatusDate desc) SaAssessorRemarks,
				 C.CertificationBodyUserId, UB.UserName, FORMAT(EvidenceSubmissionDate, 'MMMM d, yyyy') EvidenceSubmissionDate,FORMAT(AssessmentDate, 'MMMM d, yyyy') AssessmentDate,
				 SaAuditsConducted,	SaDomesticCustomers,	SaInternationalCustomers,	SaRawMaterialImported,	SaOutsourcedProcesses,	SaEnergySources, ModeOfAssessment, 
				-- (select max(NcCount) SecNcCount from MsmeSections where ZedId=@ZedId and SectionType=@Certification) SecNcCount, 

				( select max(NcCount) from 
				 (select max(NcCount) NcCount from MsmeProducts  where ZedId=@ZedId and Certification=@Certification union
				 select max(NcCount) NcCount from MsmeSections where ZedId=@ZedId and SectionType=@Certification union
				 select max(NcCount) NcCount from MsmePhotos where ZedId=@ZedId and Certification=@Certification union

				 select NcCount1 from (
				select max(P.NcCount)+1 as NcCount1,c.NcCount from MsmePhotos P inner join MsmeCertifications C on (P.ZedId=C.ZedId and P.Certification=C.Certification)
				where C.ZedId=@ZedId and C.Certification=@Certification and PhotoType='SiteExteriorPhotos' and IsVerified='No'
				group by P.ZedId,C.NcCount) A
				where NcCount1<=NcCount

				 )a
				 ) SecNcCount,

				 PV.BasicInfoStatus, PV.DocVerifiAllot, PV.DesktopVerification DesktopVerificationCompleted, Completed SaCompletedOn
				,PVD.BasicInfoStatus
				,PVD.DesktopVerification
				,PVD.BronzeDesktopVerification
				,PVD.ScheduledOn
				,PVD.CompletedOn
				,PVD.Nc1Raised
				,PVD.Nc1Submitted
				,PVD.Nc2Raised
				,PVD.Nc2Submitted
				,PVD.Nc3Raised
				,PVD.Nc3Submitted
				,PVD.Nc4Raised
				,PVD.Nc4Submitted
				,PVD.Nc5Raised
				,PVD.Nc5Submitted
				,PVD.NcClosed
				,PVD.GetCertified
				,PVD.ApplicationReceived
				,PVD.NcFinalClosureDate,
				case when @UserId=CoAssessorId then 0 else 1 end as IsCoAssessorLogin,
				ManufacturingCapacityUnits,	ManufacturingCapacityValue,	MonthlyUtilizationUnits,	MonthlyUtilizationValue,		
				SaManufacturingCapacityUnits,	SaManufacturingCapacityValue,	SaMonthlyUtilizationUnits,	SaMonthlyUtilizationValue,
				PhotosPath, case when PhotosPath is not null then 'https://loginzed.msme.gov.in/surveillancemobileapi/CertifiedPhotos/' else 'https://loginzed.msme.gov.in/surveillancemobileapi/Photos/' end as PhotosBasePath

				FROM MsmeCertifications C 
				INNER JOIN Msme M ON (C.ZedId=M.ZedId)
				INNER JOIN MsmeBasicInformation B ON (M.ZedId=B.ZedId )
				LEFT JOIN Users U ON (C.DesktopAssessorId=U.UserId)
				LEFT JOIN Users UB ON (C.CertificationBodyUserId=UB.UserId)
				LEFT JOIN Users UL ON (C.SiteAssessorId=UL.UserId)
				LEFT JOIN Users UC ON (C.CoAssessorId=UC.UserId)
				LEFT JOIN
				(select * from 
				(
				  select ZedId, StatusType, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,CertificationType
				  from MsmeHistory where CertificationType is not null and StatusType is not null
				) src
				pivot
				(
				  max(CreatedOn)
				  for StatusType in ([BasicInfoStatus], [DocVerifiAllot], [DesktopVerification],[Completed])
				) piv) PV
				on (C.ZedId=PV.ZedId and C.Certification=PV.CertificationType and PV.CertificationType=@Certification)

				LEFT JOIN
				(
				select ZedId,CertificationType,
					ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
					case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
					case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],
					[ScheduledOn],
					Completed as [CompletedOn],
					[Nc1Raised],
					[Nc1Submitted],
					[Nc2Raised],
					[Nc2Submitted],
					[Nc3Raised],
					[Nc3Submitted],
					[Nc4Raised],
					[Nc4Submitted],
					[Nc5Raised],
					[Nc5Submitted],
					[NcClosed],
					[GetCertified],
					[ApplicationReceived],
					[NcFinalClosureDate]			
					from 
					(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where ZedId=@ZedId and CertificationType=@Certification and statustype is not null) A
					pivot (
					max(CreatedOn) for StatusType in (
					[BasicInfoStatus],
					[DesktopVerification],
					[ScheduledOn],
					[Completed],
					[Nc1Raised],
					[Nc1Submitted],
					[Nc2Raised],
					[Nc2Submitted],
					[Nc3Raised],
					[Nc3Submitted],
					[Nc4Raised],
					[Nc4Submitted],
					[Nc5Raised],
					[Nc5Submitted],
					[NcClosed],
					[GetCertified],
					[ApplicationReceived],
					[NcFinalClosureDate]) ) as Pvt
				) PVD
				on (C.ZedId=PVD.ZedId and C.Certification=PVD.CertificationType and PVD.CertificationType=@Certification) 

			WHERE c.Certification=@Certification 
				AND C.ZedId=@ZedId
		END
	
	---------------SECOND QUERY --------------------------------------------------
		SELECT *,'MsmeProducts' TableName FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=0

		--IF @ModeOfAssessment='<redacted>'
		--BEGIN
		--SELECT * FROM SaRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId
		--END
		--ELSE
		--BEGIN
		--SELECT * FROM MsmeRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId
		--END

		SELECT 'DA' ModeOfAssessment,Id,ZedId,Certification,RawMaterialName,Percentage,CountryName,NcCount FROM MsmeRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId
		UNION
		SELECT 'SA' ModeOfAssessment,Id,ZedId,Certification,RawMaterialName,Percentage,CountryName,NcCount FROM SaRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId


		IF (SELECT count(*) from MsmeCertifications where ZedId=@ZedId and Certification=@Certification and CoAssessorId=@UserId)>0
		BEGIN
			SELECT s.Id,s.ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,
			(select count(*) ValidationRequired from MsmeEvidences E where ZedId=@ZedId and SectionType=@Certification and validationrequired=1 and E.SectionCode=S.SectionCode group by sectioncode) ValidationRequired,
			IsAssessmentExcempted,'MsmeSections' TableName, OfiComments,isnull(S.AssessorId,'Exempted from Assessment') AllotedAssessorId,U.UserName AllotedAssessorName,
			case when C.SiteAssessorId=S.AssessorId then 'Lead Assessor' when C.CoAssessorId=S.AssessorId then 'Co Assessor' end as AssessorRank
			FROM MsmeSections S left join Users U on (S.AssessorId=U.UserId) left join MsmeCertifications C on (S.ZedId=C.ZedId and S.SectionType=C.Certification)
			WHERE SectionType=@Certification AND s.ZedId=@ZedId AND s.NcCount=0 and AssessorId=@UserId ORDER BY cast(SectionCode as int)
		END
		ELSE
		BEGIN
			SELECT s.Id,S.ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,
			(select count(*) ValidationRequired from MsmeEvidences E where ZedId=@ZedId and SectionType=@Certification and validationrequired=1 and E.SectionCode=S.SectionCode group by sectioncode) ValidationRequired,
			IsAssessmentExcempted,'MsmeSections' TableName, OfiComments,isnull(S.AssessorId,'Exempted from Asssessment') AllotedAssessorId,U.UserName AllotedAssessorName,
			case when C.SiteAssessorId=S.AssessorId then 'Lead Assessor' when C.CoAssessorId=S.AssessorId then 'Co Assessor' end as AssessorRank
			FROM MsmeSections S left join Users U on (S.AssessorId=U.UserId) left join MsmeCertifications C on (S.ZedId=C.ZedId and S.SectionType=C.Certification)
			WHERE SectionType=@Certification AND S.ZedId=@ZedId AND S.NcCount=0  ORDER BY cast(SectionCode as int)
		END
	
		SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks,FORMAT(UpdatedDate, 'MMMM dd, yyyy HH:mm tt') UpdatedDate,FORMAT(SaUpdatedDate, 'MMMM dd, yyyy HH:mm tt') SaUpdatedDate FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
	
		SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
	
		SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
	
		SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,FORMAT(SyncedDate, 'MMMM dd, yyyy HH:mm tt')  SyncedDate,FORMAT(SyncedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)

		
		SELECT Id,ZedId,Certification,PhotoId,Name,CONVERT(varchar,TimeStamp,100) TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorRemarks,FORMAT(UpdatedDate,  'MMMM dd, yyyy HH:mm tt') UpdatedDate,NcCount,PhotoExtension,RequirementId,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate, ProductId,
		'MsmePhotos' TableName,(SELECT count(*) DocumentOpenedTime from MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType in ('SiteExteriorPhotos') AND NcCount=0 and DocumentOpenedTime is null)  DocumentOpenedTime  FROM MsmePhotos 
		WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType in ('SiteExteriorPhotos','Selfie', 'ProductPhotos', 'ProductDescriptionPhotos') AND NcCount=0 order by PhotosOrder

		--SELECT *,'<redacted>' TableName,CONCAT(@CurrentUrl,'<redacted>','<redacted>',AssessorId,'<redacted>') as PhotoPath  FROM SaPhotos WHERE Name in ('<redacted>','<redacted>') AND ZedId=@ZedId --AND Certification=@Certification
	
		-- Lat Longs
		IF @ModeOfAssessment='Remote Assessment'
		BEGIN
			SELECT TOP 1 M.Latitude, M.Longitude,S.Latitude SaLatitude, S.Longitude SaLongitude FROM MsmePhotos M 
			left join MsmeLocations S on (M.ZedId=S.ZedId and M.Certification=S.Certification )	
			WHERE M.Certification=@Certification AND M.ZedId=@ZedId AND M.PhotoType='ProductPhotos' AND M.NcCount=0
		END
		ELSE
		BEGIN
			
			if @Certification='Bronze'
			BEGIN
				SELECT TOP 1 M.Latitude, M.Longitude,S.Latitude SaLatitude, S.Longitude SaLongitude FROM MsmePhotos M 
				left join SaPhotos S on (M.ZedId=S.ZedId and M.Certification=S.Certification and M.NcCount=S.NcCount and M.PhotoType=S.PhotoType)	
				WHERE M.Certification=@Certification AND M.ZedId=@ZedId AND M.PhotoType='ProductPhotos' AND M.NcCount=0
			END
			ELSE
			BEGIN
				SELECT TOP 1 Latitude SurLatitude, Longitude SurLongitude FROM SaPhotos where PhotoType='SiteTour' and ZedId=@ZedId and Certification=@Certification and NcCount=0
			END
		END




		IF @Certification!='Bronze'
		BEGIN

			SELECT 
			Id,	ZedId,	Certification,	PhotoId,	Name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId,	
			isnull(Photo,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/',Name,'.jpg')) Photo,CreatedDate	
			,'SaPhotos' TableName
			FROM SaPhotos WHERE (name in ('Site Exterior Photo','Site Interior Photo') or (PhotoType='SiteExteriorPhotos')) and Certification=@Certification AND ZedId=@ZedId	AND NcCount=0

			SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Open Meeting' AND ZedId=@ZedId --AND Certification=@Certification
			SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Open Meeting' AND ZedId=@ZedId --AND Certification=@Certification
			SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Close Meeting' AND ZedId=@ZedId --AND Certification=@Certification
			SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Close Meeting' AND ZedId=@ZedId --AND Certification=@Certification

	
			SELECT *,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/',AssessorId,'.jpg') as PhotoPath  FROM SaPhotos WHERE Name in ('Selfie on Site') AND ZedId=@ZedId AND Certification=@Certification
			union
			SELECT *,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/Opening Meeting Photo.jpg') as PhotoPath  FROM SaPhotos WHERE Name in ('Opening Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification
	
			SELECT *,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/SiteTour/',PhotoId,'.jpg') as PhotoPath  FROM SaPhotos WHERE PhotoType='SiteTour' AND ZedId=@ZedId AND Certification=@Certification


			SELECT 
			Id,	ZedId,	Certification,	PhotoId,	Name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,FORMAT(UpdatedDate,  'MMMM dd, yyyy HH:mm tt')	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId, null RequirementCode, null SectionCode,	
			Photo,CreatedDate	
			,'SaPhotos' TableName
			FROM SaPhotos WHERE  (PhotoType='Evidence Photos') and Certification=@Certification AND ZedId=@ZedId	AND NcCount=0
			union
			SELECT 
			S.Id,	S.ZedId,	S.Certification,	S.PhotoId,	S.Name,	S.TimeStamp,	S.Latitude,	S.Longitude,	S.PhotoType,	EvidenceId,IsVerified,	AssessorId,	S.AssessorRemarks,	S.UpdatedDate,	S.NcCount,	PhotoExtension,	M.RequirementId, M.RequirementCode, M.SectionCode,	
			case when S.PhotoType='Evidences' then isnull(S.Photo,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/',@Certification,'/Evidences/',S.PhotoId,'.jpg')) else
			isnull(S.Photo,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/SiteTour/',S.PhotoId,'.jpg')) end as Photo,S.CreatedDate	
			,'SaPhotos' TableName
			FROM SaPhotos S
			inner join SaRequirementPhotos R on (S.ZedId=R.ZedId and S.Certification=R.Certification and S.PhotoId=R.PhotoId)
			inner join MsmeRequirements M on (R.RequirementId=M.Id)
			WHERE  S.Certification=@Certification AND S.ZedId=@ZedId	AND S.NcCount=0

			SELECT *,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/Closing Meeting Photo.jpg') as PhotoPath  FROM SaPhotos WHERE Name in ('Closing Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification

			IF @Certification='Gold'
			BEGIN
				select Id,	ZedId, Certification, ProductName, Exported, 
				CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BasicInfo/',ProductPhoto) ProductPhoto,
				CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BasicInfo/',ProductDescriptionPhoto) ProductDescriptionPhoto, 
				IsVerified, AssessorRemarks, UpdatedDate,	NcCount, MsmeRemarks, MsmeUpdatedDate, ProductOpenedTime, ProductDescOpenedTime,'SaProducts' TableName 
				from SaProducts where ZedId=@ZedId AND Certification=@Certification
			END
			ELSE
			BEGIN
				select *,'SaProducts' TableName from SaProducts where ZedId=@ZedId AND Certification=@Certification
			END

			select *,'SaRawMaterials' TableName from SaRawMaterials where ZedId=@ZedId AND Certification=@Certification
		END

		select * from screenshotphotos where ZedId=@ZedId AND Certification=@Certification order by id

	END

		-----------LOADING LATLONGS OF ZED ASSESSMENT------------------------
		SELECT TOP 1 M.Latitude AS ZedLatitude, M.Longitude AS ZedLongitude,  ISNULL(S.Latitude, M.Latitude) AS ZedSaLatitude, ISNULL(S.Longitude, M.Longitude) AS ZedSaLongitude, 0 AS NcCount 
        FROM ZEDCS_V2_LIVE.DBO.MsmePhotos M LEFT JOIN ZEDCS_V2_LIVE.DBO.SaPhotos S ON M.ZedId = S.ZedId AND M.Certification = S.Certification AND S.NcCount = 0 AND S.Name = 'Site Exterior Photo'
		WHERE M.Certification = @TargetCertification AND M.ZedId = @ZedId AND M.PhotoType = 'SiteExteriorPhotos' AND M.NcCount = 0

		SELECT Id,RefId,ZedId,Certification,Code,Question,Answer,IfYesQuestion,IfYesAnswer,IfNoQuestion,IfNoAnswer,CheckListType,SubmissionDate FROM EsgCheckList where ZedId=@ZedId AND Certification=@Certification order by Id

		--SELECT Id,ZedId,Certification,FinancialAssistanceAvailed,AnyDocuments,DocumentTypes,CreatedDate FROM AvailedFinancialSupport where ZedId=@ZedId AND Certification=@Certification order by Id
		-- Replace your third SELECT with this block:

		SELECT Id, ZedId, Certification, FinancialAssistanceAvailed, AnyDocuments, DocumentTypes, CreatedDate FROM AvailedFinancialSupport WHERE ZedId = @ZedId AND Certification = @Certification

		UNION ALL

		SELECT     NULL AS Id,     @ZedId AS ZedId,     @Certification AS Certification,     'Yes' AS FinancialAssistanceAvailed,     '' AS AnyDocuments,                
			NULL AS DocumentTypes,     GETDATE() AS CreatedDate WHERE NOT EXISTS (SELECT 1 FROM AvailedFinancialSupport WHERE ZedId = @ZedId AND Certification = @Certification)

		SELECT Id,ZedId,Certification,SuitableForSilverUpgrade,HandholdingSupport,CreatedDate FROM AdditionalSupportQuestions where ZedId=@ZedId AND Certification=@Certification order by Id

END




GO
