/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_RA_CONFIRM_FINAL_SUBMIT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_RA_CONFIRM_FINAL_SUBMIT] --'<redacted>','<redacted>'
(
	@ZedId VarChar(50)				= NULL,
	@CertificationType VarChar(50)	= NULL
)
AS
BEGIN

	Declare @NcCount int  = NULL
	Declare @ModeOfAssessment varchar(100)  = NULL

	Select @NcCount=NcCount,@ModeOfAssessment=ModeOfAssessment from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType


	IF
	(select count(*) from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId and IsSaVerified IS NULL and NcCount=@NcCount and ModeOfAssessment='Remote Assessment')>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more Exterior Photos. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsSaVerified IS NULL and NcCount=@NcCount and @ModeOfAssessment='Remote Assessment')>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more products. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeRequirements M inner join MsmeSections S on (M.ZedId=S.ZedId and M.SectionType=S.SectionType and M.NcCount=S.NcCount and M.SectionCode=S.SectionCode)
	inner join MsmeCertifications C on (S.ZedId=C.ZedId and S.SectionType=C.Certification and S.AssessorId=C.CoAssessorId)
	where M.SectionType=@CertificationType and M.ZedId=@ZedId and SaConformance IS NULL and M.NcCount=@NcCount and( S.IsAssessmentExcempted='No' or  S.IsAssessmentExcempted is null))>0
	select 0 AllowFinalSubmit, 'Co-Assessor missed assessment of one or more parameters. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeRequirements M inner join MsmeSections S on (M.ZedId=S.ZedId and M.SectionType=S.SectionType and M.NcCount=S.NcCount and M.SectionCode=S.SectionCode) where M.SectionType=@CertificationType and M.ZedId=@ZedId and SaConformance IS NULL and M.NcCount=@NcCount and( S.IsAssessmentExcempted='No' or  S.IsAssessmentExcempted is null))>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more parameters. Please review.' ErrorMessage

	ELSE IF (select count(*) from MsmeSections where SectionType=@CertificationType and ZedId=@ZedId and OfiComments is null and NcCount=0 and IsAssessmentExcempted='No')>0
				select 0 AllowFinalSubmit, 'You may have missed one or more OFI comments. Please review.' ErrorMessage	

	--ELSE IF (select count(*) from Meetings where CertificationType=@CertificationType and ZedId=@ZedId and MeetingType='<redacted>')=0
	--			select 0 AllowFinalSubmit, '<redacted>' ErrorMessage
				
	ELSE IF (select count(*) from SaPhotos where Certification=@CertificationType and ZedId=@ZedId and PhotoType='Open Meeting')=0
				select 0 AllowFinalSubmit, 'Please submit the opening meeting photo.' ErrorMessage

	ELSE IF (select count(*) from Meetings where CertificationType=@CertificationType and ZedId=@ZedId and MeetingType='Open Meeting' and FieldComments IS NULL)!=0
				select 0 AllowFinalSubmit, 'Please submit opening meeting comments.' ErrorMessage

	ELSE IF (select count(*) from MeetingParticipants where CertificationType=@CertificationType and ZedId=@ZedId and MeetingType='Open Meeting')<2
				select 0 AllowFinalSubmit, 'Minimum two participants needed in opening meeting.' ErrorMessage

	ELSE IF (select count(*) from SaPhotos where Certification=@CertificationType and ZedId=@ZedId and PhotoType='Close Meeting')=0
				select 0 AllowFinalSubmit, 'Please submit the closing meeting photo.' ErrorMessage

	--ELSE IF (select count(*) from Meetings where CertificationType=@CertificationType and ZedId=@ZedId and MeetingType='<redacted>' and MeetingRecordingLink IS NULL)!=0
	--			select 0 AllowFinalSubmit, '<redacted>' ErrorMessage

	ELSE IF (select count(*) from MeetingRecordingLinks where CertificationType=@CertificationType and ZedId=@ZedId)=0
				select 0 AllowFinalSubmit, 'Please submit Meeting recording link.' ErrorMessage

	ELSE IF (select count(*) from Meetings where CertificationType=@CertificationType and ZedId=@ZedId and MeetingType='Close Meeting' and FieldComments IS NULL)!=0
				select 0 AllowFinalSubmit, 'Please submit closing meeting comments.' ErrorMessage

	ELSE IF (select count(*) from MeetingParticipants where CertificationType=@CertificationType and ZedId=@ZedId and MeetingType='Close Meeting')<2
				select 0 AllowFinalSubmit, 'Minimum two participants needed in closing meeting.' ErrorMessage

	ELSE IF (select count(*) from MsmeRequirements  where SectionType=@CertificationType and ZedId=@ZedId and SaConformance = 'No' and SaAssessorRemarks IS NULL)>0
				select 0 AllowFinalSubmit, 'Please provide remarks for the parameters with SaConformance as "No"' ErrorMessage

	--ELSE IF @CertificationType = '<redacted>'
	--	BEGIN
	--		IF (select SaAuditsConducted from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId and NcCount=@NcCount) IS NULL
	--			select 0 AllowFinalSubmit, '<redacted>' ErrorMessage	
	--		ELSE IF (select SaDomesticCustomers from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId and NcCount=@NcCount) IS NULL
	--			select 0 AllowFinalSubmit, '<redacted>' ErrorMessage		
	--		ELSE IF (select SaInternationalCustomers from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId  and NcCount=@NcCount) IS NULL
	--			select 0 AllowFinalSubmit, '<redacted>' ErrorMessage
	--		--ELSE IF (select SaRawMaterialImported from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId  and NcCount=@NcCount) IS NULL
	--		--	select 0 AllowFinalSubmit, '<redacted>' ErrorMessage
	--		ELSE IF (select SaOutsourcedProcesses from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId  and NcCount=@NcCount) IS NULL
	--			select 0 AllowFinalSubmit, '<redacted>' ErrorMessage
	--		ELSE IF (select SaEnergySources from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId and NcCount=@NcCount) IS NULL
	--			select 0 AllowFinalSubmit, '<redacted>' ErrorMessage
	--	   ELSE IF (select count(*) from MeetingParticipants where CertificationType=@CertificationType and ZedId=@ZedId and MeetingType='<redacted>')=0
	--			select 0 AllowFinalSubmit, '<redacted>' ErrorMessage
 --          ELSE IF (select count(*) from SaPhotos where Certification=@CertificationType and ZedId=@ZedId and PhotoType='<redacted>')=0
	--			select 0 AllowFinalSubmit, '<redacted>' ErrorMessage
		   
	--		ELSE 
	--			select 1 AllowFinalSubmit, '' ErrorMessage
	--	END
	ELSE 
		select 1 AllowFinalSubmit, '' ErrorMessage

	IF @NcCount>=5
	SELECT 0 RaisedForNc

	IF(select count(*) from SaPhotos where PhotoType='SiteExteriorPhotos' and Certification=@CertificationType and ZedId=@ZedId and IsVerified='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc

	ELSE IF(select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsSaVerified='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc
	
	ELSE IF(select count(*) from MsmeRequirements where SectionType=@CertificationType and ZedId=@ZedId and SaConformance='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc

	ELSE 
		SELECT 0 RaisedForNc
END
GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_RA_DELETE_PHOTOS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_ASSESSMENT_RA_DELETE_PHOTOS]
(
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@Id varchar(50) = NULL
)
AS
BEGIN

	DELETE FROM SaPhotos WHERE ZedId=@ZedId AND Certification=@CertificationType AND Id=@Id
	DELETE FROM SaRequirementPhotos WHERE ZedId=@ZedId AND Certification=@CertificationType AND Id=@Id and PhotoType='Evidence Photo'

END

GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_RA_FINAL_SUBMIT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_RA_FINAL_SUBMIT] --'<redacted>','<redacted>','<redacted>'
(
	@ZedId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL,
	@AssessorRemarks VarChar(5000)			= NULL
)
AS
BEGIN
	
	Declare @NcCount int  = NULL
	Declare @ErrorStatus bit = 0

	Declare @EvidenceId varchar(50) = NULL
	

	Select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType

	--IF @CertificationType='<redacted>'
	--BEGIN
		--CHECKING FOR ERRORS IN SITE EXTERIOR PHOTOS
		IF @NcCount=0
		BEGIN
			IF(select count(*) from MsmeCertifications where Certification=@CertificationType and ZedId=@ZedId and IsSaVerified='No' and NcCount=@NcCount)>0
			SET @ErrorStatus=1
		END
		ELSE
		BEGIN
			IF(select count(*) from SaPhotos where Certification=@CertificationType and ZedId=@ZedId and IsVerified='No' and NcCount=@NcCount)>0
			SET @ErrorStatus=1
		END


		--CHECKING FOR ERRORS IN PRODUCTS
		IF(select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsSaVerified='No' and NcCount=@NcCount)>0
		SET @ErrorStatus=1
	
		--CHECKING FOR ERRORS IN EVIDENCES
		IF(select count(*) from MsmeRequirements where SectionType=@CertificationType and ZedId=@ZedId and SaConformance='No' and NcCount=@NcCount)>0
		BEGIN		
			SET @ErrorStatus=1
			IF @NcCount<5
			BEGIN
				insert into MsmeSections(SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,NcCount,IsAssessmentExcempted,AssessorId)
				select Distinct SectionId,S.ZedId,S.SectionCode,S.SectionName,S.OrderNo,iButton,SectionImage,S.SectionType,@NcCount+1,IsAssessmentExcempted,AssessorId from MsmeRequirements R  inner join MsmeSections S on (R.SectionCode=S.SectionCode and R.NcCount=S.NcCount and s.SectionType=r.SectionType) where R.zedid=@ZedId and S.zedid=@ZedId and SaConformance='No'  and S.NcCount=@NcCount and s.SectionType=@CertificationType
		
				insert into MsmeRequirements(RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,NcCount,PreviousAssessorRemarks)
				select RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,@NcCount+1,SaAssessorRemarks from MsmeRequirements where zedid=@ZedId and SaConformance='No' and NcCount=@NcCount and SectionType=@CertificationType
		
				insert into MsmeOptions(OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType,NcCount)
				select OptionId,O.ZedId,O.SectionCode,O.QuestionCode,OptionCode,OptionName,OptionImage,O.RequirementCode,O.SectionType,@NcCount+1 from MsmeRequirements R  inner join MsmeOptions O on (R.SectionCode=O.SectionCode and R.RequirementCode=O.RequirementCode and R.NcCount=O.NcCount and R.SectionType=O.SectionType) where R.zedid=@ZedId and O.zedid=@ZedId and SaConformance='No' and O.NcCount=@NcCount and R.SectionType=@CertificationType
		
				insert into MsmeSubOptions(SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType,NcCount)
				select O.SubOptionId,O.ZedId,O.SectionCode,O.QuestionCode,OptionCode,SubOptionCode,SubOptionName,O.RequirementCode,SubOptionImage,O.SectionType,@NcCount+1 from MsmeRequirements R  inner join MsmeSubOptions O on (R.SectionCode=O.SectionCode and R.RequirementCode=O.RequirementCode  and R.NcCount=O.NcCount and R.SectionType=O.SectionType) where R.zedid=@ZedId and O.zedid=@ZedId and SaConformance='No' and O.NcCount=@NcCount and R.SectionType=@CertificationType
		
				insert into MsmeEvidences(EvidenceId, ZedId,SectionCode,RequirementCode,EvidenceCode,SectionType,EvidenceName,NcCount,RequirementId)
				select (next value for EvidenceIdSequence),ZedId,SectionCode,RequirementCode,concat('9',@NcCount+1),SectionType,concat('NC',@NcCount+1),@NcCount+1,RequirementId from MsmeRequirements where zedid=@ZedId and SaConformance='No' and NcCount=@NcCount and SectionType=@CertificationType
			END
		END

		IF(select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsSaVerified='No' and NcCount=@NcCount)>0
		BEGIN		
			SET @ErrorStatus=1
			IF @NcCount<5
			BEGIN
				INSERT INTO MsmeProducts (ZedId, Certification, ProductName, Exported, NcCount, PreviousAssessorRemarks,ProductParentId,PreviousAssessorUpdatedDate)
				SELECT ZedId, Certification, ProductName, Exported,  @NcCount+1, SaAssessorRemarks, ProductParentId,UpdatedDate FROM MsmeProducts WHERE zedid=@ZedId and IsSaVerified='No' and NcCount=@NcCount and Certification=@CertificationType
			END
		END

		IF (@ErrorStatus=1 and @NcCount=0)
		BEGIN
			DECLARE @MaxSchemeDeadline DATETIME
			SELECT @MaxSchemeDeadline = NcFinalClosureDt FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification=@CertificationType

			insert into AssessorComments (ZedId,Certification,NcCount,SaAssessorRemarks,CertificationStatusDate,AssessmentType)
			Values(@ZedId,@CertificationType,@NcCount,@AssessorRemarks,getdate(),'SA')

			UPDATE MsmeCertifications set CertificationStatus=14,NcCount=@NcCount+1,CertificationStatusDate=getdate(),NcStatus=1,Nc1Status=1,
			NcFinalClosureDt = CASE WHEN DATEADD(MONTH, 2, GETDATE()) < @MaxSchemeDeadline THEN DATEADD(MONTH, 2, GETDATE()) ELSE @MaxSchemeDeadline END where ZedId=@ZedId AND Certification=@CertificationType

			DECLARE @NewDeadline DATETIME
            SELECT @NewDeadline = NcFinalClosureDt FROM MsmeCertifications WHERE ZedId=@ZedId AND Certification=@CertificationType
			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('NC ',@NcCount+1,' Raised On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,concat('Nc',@NcCount+1,'Raised' ))

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,CONCAT('NC 1 Raised. Final Deadline set to: ', FORMAT(@NewDeadline, 'MMMM d, yyyy')),getdate(),@CertificationType,'NcFinalClosureDate')

			insert into NcClosureDateHistory (ZedId,Certification,NoOfDays,FnNcCloseDt)
			values (@ZedId,@CertificationType,0,getdate())

			--insert into MsmeHistory(ZedId,Descrip,CreatedDate)
			--values (@ZedId,concat('<redacted>','<redacted>',@NcCount ,'<redacted>',@NcCount+1 ),getdate())
		END

		IF (@ErrorStatus=1 and @NcCount>0)
		BEGIN

			insert into AssessorComments (ZedId,Certification,NcCount,SaAssessorRemarks,CertificationStatusDate,AssessmentType)
			Values(@ZedId,@CertificationType,@NcCount,@AssessorRemarks,getdate(),'SA')

			SET @NcCount=@NcCount+1

			UPDATE MsmeCertifications set NcStatus=1,NcCount=@NcCount,CertificationStatusDate=getdate()  where ZedId=@ZedId AND Certification=@CertificationType

			IF @NcCount = 1
			UPDATE MsmeCertifications set Nc1Status=1 where ZedId=@ZedId and Certification=@CertificationType
			IF @NcCount = 2
			UPDATE MsmeCertifications set Nc2Status=1 where ZedId=@ZedId and Certification=@CertificationType
			IF @NcCount = 3
			UPDATE MsmeCertifications set Nc3Status=1 where ZedId=@ZedId and Certification=@CertificationType
			IF @NcCount = 4
			UPDATE MsmeCertifications set Nc4Status=1 where ZedId=@ZedId and Certification=@CertificationType
			IF @NcCount = 5
			UPDATE MsmeCertifications set Nc5Status=1 where ZedId=@ZedId and Certification=@CertificationType
			IF @NcCount > 5
			UPDATE MsmeCertifications set CertificationStatus=17 where ZedId=@ZedId and Certification=@CertificationType

			IF @NcCount<6
			BEGIN
			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('NC ',@NcCount,' Raised On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,concat('Nc',@NcCount,'Raised' ))
			END

			ELSE
			BEGIN
				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('Assessor Rejected On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Assessor Rejected in NC 5' )
			END
		END

		IF @ErrorStatus=0
		BEGIN
		
			insert into AssessorComments (ZedId,Certification,NcCount,SaAssessorRemarks,CertificationStatusDate,AssessmentType)
			Values(@ZedId,@CertificationType,@NcCount,@AssessorRemarks,getdate(),'SA')

			UPDATE MsmeCertifications set CertificationStatus=15,CertificationStatusDate=getdate(),SaAssessorRemarks=@AssessorRemarks  where ZedId=@ZedId AND Certification=@CertificationType

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('NC(s) Closed On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'NcClosed')
		END
	--END

	--ELSE 
	--BEGIN
		
	--		insert into AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate)
	--		Values(@ZedId,@CertificationType,@NcCount,@AssessorRemarks,getdate())

	--		UPDATE MsmeCertifications set CertificationStatus=5,CertificationStatusDate=getdate(),AssessorRemarks=@AssessorRemarks  where ZedId=@ZedId AND Certification=@CertificationType

	--		insert into MsmeHistory(ZedId,Descrip,CreatedDate)
	--		values (@ZedId,concat('<redacted>','<redacted>',@NcCount, '<redacted>'),getdate())
	--	END

	

END
GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_RA_GET_UPDATED_PHOTOS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_ASSESSMENT_RA_GET_UPDATED_PHOTOS]
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@TableName varchar(50) = NULL,
	@Id varchar(50) = NULL,
	@Name varchar(500) = NULL
)
AS
BEGIN

	IF @TableName='MsmeProducts'
	BEGIN
		SELECT *, 'SaPhotos' TableName FROM SaPhotos
		WHERE ZedId=@ZedId AND Certification=@CertificationType AND ProductId=@Id
		ORDER By 1 
	END

	ELSE IF @TableName='MsmeRequirements'
	BEGIN
		
		DECLARE @RequirementId varchar(50) = NULL
		select @RequirementId=RequirementId from MsmeRequirements where Id=@Id

		SELECT *, 'SaPhotos' TableName FROM SaPhotos
		WHERE ZedId=@ZedId AND Certification=@CertificationType AND RequirementId=@RequirementId
		ORDER By 1 
	END

	ELSE IF @TableName='SiteExteriorPhotos'
	BEGIN
		SELECT *, 'SaPhotos' TableName FROM SaPhotos
		WHERE ZedId=@ZedId AND Certification=@CertificationType AND PhotoType='SiteExteriorPhotos'
		ORDER By 1 
	END

	ELSE IF @TableName='Meetings'
	BEGIN

		SELECT S.*, 'SaPhotos' TableName FROM Meetings M 
		INNER JOIN SaPhotos S on (M.ZedId=s.ZedId AND M.CertificationType=s.Certification AND M.MeetingType=S.PhotoType) 
		WHERE M.Id=@Id
		ORDER By 1 

	END

	ELSE
	BEGIN
		SELECT *, 'SaPhotos' TableName FROM SaPhotos
		WHERE ZedId=@ZedId AND Certification=@CertificationType AND PhotoType='SiteTour'
		ORDER By 1 
	END

END

GO
