	@Certification varchar(50) = NULL,
	@Id varchar(50) = NULL,
	@Comments varchar(5000) = NULL,
	@TableName varchar(50) = NULL
	
)
AS
BEGIN

	IF @TableName='Meetings'
	BEGIN
		UPDATE Meetings SET  Comments=@Comments,FieldComments=@Comments, UpdatedDate=getdate() where  Id=@Id AND ZedId=@ZedId AND CertificationType=@Certification
	END

	ELSE IF @TableName='MsmeSections'
	BEGIN
		UPDATE MsmeSections SET  OfiComments=@Comments,FieldOfiComments=@Comments, UpdatedDate=getdate() where  Id=@Id AND ZedId=@ZedId AND SectionType=@Certification
	END

	IF @TableName='MeetingRecordingLink'
	BEGIN
		--UPDATE Meetings SET MeetingRecordingLink=@Comments where  Id=@Id AND ZedId=@ZedId AND CertificationType=@Certification
		INSERT INTO MeetingRecordingLinks (ZedId, CertificationType, MeetingsId, RecordingLink, CreatedDate)
		VALUES (@ZedId, @Certification, @Id, @Comments, GETDATE())
	END

END

