/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_RA_UPDATE_SITE_EXTERIOR]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_RA_UPDATE_SITE_EXTERIOR] 
(

	@ZedId VarChar(50)					= NULL,
	@CertificationType VarChar(50)		    = NULL,
	@IsSaVerified VarChar(50)	            = NULL,
	@SaAssessorRemarks VarChar(2000)	    = NULL

)
AS
BEGIN

	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType
	
	IF @NcCount=0
		UPDATE MsmeCertifications SET IsSaVerified=@IsSaVerified, SaAssessorRemarks=@SaAssessorRemarks where ZedId=@ZedId and Certification=@CertificationType
	ELSE
		UPDATE SaPhotos SET IsVerified=@IsSaVerified, AssessorRemarks=@SaAssessorRemarks, UpdatedDate=getdate()  where PhotoType in ('SiteExteriorPhotos') and ZedId=@ZedId AND Certification=@CertificationType and NcCount=@NcCount



	--IF @NcCount=0
	--BEGIN
	--UPDATE MsmeCertifications SET CertificationStatus=3 where ZedId=@ZedId AND Certification=@CertificationType
	--END

	--IF @NcCount>0
	--BEGIN
	--UPDATE MsmeCertifications SET NcStatus=3 where ZedId=@ZedId AND Certification=@CertificationType
	--END
	
END
