/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_SA_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_ASSESSMENT_SA_DETAILS]  '<redacted>',null,'<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_SA_DETAILS] --'<redacted>','<redacted>','<redacted>','<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
		SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL,
	@ModeOfAssessment varchar(50) = NULL

	IF(select count(*) from MsmeCertifications where zedid=@ZedId and Certification=@Certification and ((SiteAssessorId=@UserId and @RoleId=3) OR (CoAssessorId=@UserId and @RoleId=3) OR (CertificationBodyUserId=@UserId AND @RoleId=2) OR (@RoleId=10) OR (@RoleId=11) OR (@RoleId=7) OR (@RoleId=8) OR (ZedId=@ZedId AND (@RoleId is null OR @RoleId=5))))=0
	BEGIN
		SET @ZedId='000'
	END

	SELECT @CurrentUrl=UrlName from UrlsMasterData
	SELECT @ModeOfAssessment=ModeOfAssessment from MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

	IF @ModeOfAssessment='Onsite Assessment'
	BEGIN
		SELECT 
		Id,	ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId,	
		isnull(Photo,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg')) src,CreatedDate	
		,'SaPhotos' TableName
		FROM SaPhotos WHERE (name in ('Site Exterior Photo', 'Site Exteripr Photo','Site Interior Photo') and (PhotoType='SiteTour')) and Certification=@Certification AND ZedId=@ZedId	AND NcCount=0

		SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
		SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
		SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
		SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification

		--SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'<redacted>' TableName,CONCAT(@CurrentUrl,'<redacted>','<redacted>',@ZedId,'<redacted>',AssessorId,'<redacted>') as PhotoPath,Photo src,name  FROM SaPhotos WHERE PhotoType in ('<redacted>') AND ZedId=@ZedId AND Certification=@Certification
		--union
		SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/',Name,'.jpg') as PhotoPath,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/',Name,'.jpg') src,name  FROM SaPhotos WHERE Name like 'Opening Meeting Photo%' AND ZedId=@ZedId AND Certification=@Certification
	
		SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg') as PhotoPath,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg') src,name  FROM SaPhotos WHERE PhotoType in ('SiteTour') 
		AND [Name] not in ('Site Exteripr Photo','Site Interior Photo','Selfie','Site Exterior Photo')   AND ZedId=@ZedId AND Certification=@Certification order by TimeStamp
			
		SELECT 
		Id,	ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId, null RequirementCode, null SectionCode,	
		Photo,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate	
		,'SaPhotos' TableName,Photo src
		FROM SaPhotos WHERE  (PhotoType in ('Evidence Photo')) and Certification=@Certification AND ZedId=@ZedId	AND NcCount=0
		union
		SELECT 
		R.Id,	R.ZedId,	R.Certification,	R.PhotoId,	R.Name name,	R.TimeStamp,	R.Latitude,	R.Longitude,	R.PhotoType, null EvidenceId,null IsVerified,null 	AssessorId,	null AssessorRemarks,	R.UpdatedDate,	R.NcCount,	null PhotoExtension,	M.RequirementId, M.RequirementCode, M.SectionCode,	
		case when R.PhotoType='Evidences' then isnull(R.Photo,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) else
		isnull(R.Photo,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) end as Photo,FORMAT(R.CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate	
		,'SaPhotos' TableName,isnull(R.Photo,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) src
		FROM  SaRequirementPhotos R	inner join MsmeRequirements M on (R.RequirementId=M.Id)
		WHERE  R.Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=0 and (R.PhotoType='Evidence Photo') order by TimeStamp

		SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',Name,'.jpg') as PhotoPath,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/',Name,'.jpg') src,name  FROM SaPhotos WHERE Name like 'Closing Meeting Photo%' AND ZedId=@ZedId AND Certification=@Certification

		select *,'SaProducts' TableName from SaProducts where ZedId=@ZedId AND Certification=@Certification

		select *,'SaRawMaterials' TableName from SaRawMaterials where ZedId=@ZedId AND Certification=@Certification

		SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId, CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BasicInfo/', PhotoId,'.',PhotoExtension) Photo,CreatedDate,'SaPhotos' TableName, CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BasicInfo/', PhotoId,'.',PhotoExtension) src,name,ProductId  FROM SaPhotos WHERE PhotoType in ('ProductPhotos','ProductDescriptionPhotos') AND ZedId=@ZedId AND Certification=@Certification order by PhotoType desc

		--SELECT TOP 1 Id,	ZedId,	Certification,	Timestamp,	CONCAT(@CurrentUrl,'<redacted>',PhotoPath) PhotoPath,	Latitude,	Longitude,	CreatedDate,	RepresentativeName,	Designation FROM MsmeSelfies WHERE ZedId=@ZedId AND Certification=@Certification ORDER BY ID DESC
		SELECT Id, ZedId, Certification, PhotoId, TimeStamp, Latitude, Longitude, PhotoType, EvidenceId, IsVerified, AssessorId, AssessorRemarks, UpdatedDate, NcCount, PhotoExtension,RequirementId, Photo, CreatedDate, 'SaPhotos' TableName, 
		CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg') as PhotoPath,Photo src,'MSME Representative Selfie' [name]  
		FROM SaPhotos WHERE [Name] in ('Selfie') and PhotoType in ('SiteTour') AND ZedId=@ZedId AND Certification=@Certification
		union
		SELECT Id, ZedId, Certification, PhotoId, TimeStamp, Latitude, Longitude, PhotoType, EvidenceId, IsVerified, AssessorId, AssessorRemarks, UpdatedDate, NcCount, PhotoExtension,RequirementId, Photo, CreatedDate, 'SaPhotos' TableName, 
		CONCAT(@CurrentUrl,'/surveillancemobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/',Name,'.jpg') as PhotoPath,Photo src,'Assessor Selfie' [name]  
		FROM SaPhotos WHERE [Name] like 'Selfie on Site%' and PhotoType in ('Open Meeting') AND ZedId=@ZedId AND Certification=@Certification

		SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks,FORMAT(UpdatedDate, 'MMMM dd, yyyy HH:mm tt') UpdatedDate,FORMAT(SaUpdatedDate, 'MMMM dd, yyyy HH:mm tt') SaUpdatedDate FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)

		SELECT s.Id,S.ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,
			'MsmeSections' TableName, OfiComments,isnull(S.AssessorId,'Exempted from Asssessment') AllotedAssessorId,U.UserName AllotedAssessorName,
			case when C.SiteAssessorId=S.AssessorId then 'Lead Assessor' when C.CoAssessorId=S.AssessorId then 'Co Assessor' end as AssessorRank
			FROM MsmeSections S left join Users U on (S.AssessorId=U.UserId) left join MsmeCertifications C on (S.ZedId=C.ZedId and S.SectionType=C.Certification)
			WHERE SectionType=@Certification AND S.ZedId=@ZedId AND S.NcCount=0  ORDER BY cast(SectionCode as int)

			select * from MeetingRecordingLinks where ZedId=@ZedId AND CertificationType=@Certification order by createddate
	END

	ELSE
	BEGIN
		SELECT 
		Id,	ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId,	
		isnull(Photo,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SA/SaPhotos/',@ZedId,'/',Name,'.jpg')) src,CreatedDate	
		,'SaPhotos' TableName
		FROM SaPhotos WHERE (name in ('Site Exterior Photo','Site Interior Photo') or (PhotoType='SiteExteriorPhotos')) and Certification=@Certification AND ZedId=@ZedId	AND NcCount=0

		SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
		SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
		SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification
		SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification

	
		--SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'<redacted>' TableName,CONCAT(@CurrentUrl,'<redacted>','<redacted>',@ZedId,'<redacted>',AssessorId,'<redacted>') as PhotoPath,Photo src,name  FROM SaPhotos WHERE Name in ('<redacted>') AND ZedId=@ZedId AND Certification=@Certification
		--union
		SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SA/SaPhotos/',@ZedId,'/Opening Meeting Photo.jpg') as PhotoPath,Photo src,name  FROM SaPhotos WHERE Name in ('Opening Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification
	
		SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SA/SaPhotos/',@ZedId,'/SiteTour/',PhotoId,'.jpg') as PhotoPath,Photo src,name  FROM SaPhotos WHERE PhotoType in ('SiteTour') AND ZedId=@ZedId AND Certification=@Certification


		SELECT 
		R.Id,	R.ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	R.AssessorRemarks,	R.UpdatedDate,	R.NcCount,	PhotoExtension,	R.RequirementId, M.RequirementCode, M.SectionCode,	
		Photo,CreatedDate	
		,'SaPhotos' TableName,Photo src,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime
		FROM SaPhotos R inner join MsmeRequirements M on (R.RequirementId=M.RequirementId and r.NcCount=m.NcCount and r.ZedId=m.ZedId and r.Certification=m.SectionType) WHERE  (PhotoType in ('Evidence Photo')) and Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=0
		union
		SELECT 
		R.Id,	R.ZedId,	R.Certification,	R.PhotoId,	R.Name name,	R.TimeStamp,	R.Latitude,	R.Longitude,	R.PhotoType, null EvidenceId,null IsVerified,null 	AssessorId,	null AssessorRemarks,	R.UpdatedDate,	R.NcCount,	null PhotoExtension,	M.RequirementId, M.RequirementCode, M.SectionCode,	
		case when R.PhotoType='Evidences' then isnull(R.Photo,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SA/SaPhotos/',@ZedId,'/',@Certification,'/Evidences/',R.PhotoId,'.jpg')) else
		isnull(R.Photo,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SA/SaPhotos/',@ZedId,'/SiteTour/',R.PhotoId,'.jpg')) end as Photo,R.CreatedDate	
		,'SaPhotos' TableName,R.Photo src,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime
		FROM  SaRequirementPhotos R	inner join MsmeRequirements M on (R.RequirementId=M.Id)
		WHERE  R.Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=0 and (R.PhotoType='Evidence Photo')

		SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/surveillancemobileapi/','SA/SaPhotos/',@ZedId,'/Closing Meeting Photo.jpg') as PhotoPath,Photo src,name  FROM SaPhotos WHERE Name in ('Closing Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification

		select *,'SaProducts' TableName from SaProducts where ZedId=@ZedId AND Certification=@Certification

		select *,'SaRawMaterials' TableName from SaRawMaterials where ZedId=@ZedId AND Certification=@Certification

		SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName, Photo,Photo src,name,ProductId  FROM SaPhotos WHERE PhotoType in ('ProductPhotos','ProductDescriptionPhotos') AND ZedId=@ZedId AND Certification=@Certification order by PhotoType desc

		SELECT TOP 1	Id,	ZedId,	Certification,	Timestamp,	CONCAT(@CurrentUrl,'/surveillancemobileapi/',PhotoPath) PhotoPath,	Latitude,	Longitude,	CreatedDate,	RepresentativeName,	Designation FROM MsmeSelfies WHERE ZedId=@ZedId AND Certification=@Certification ORDER BY ID DESC

		SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks,FORMAT(UpdatedDate, 'MMMM dd, yyyy HH:mm tt') UpdatedDate,FORMAT(SaUpdatedDate, 'MMMM dd, yyyy HH:mm tt') SaUpdatedDate FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)

		SELECT s.Id,S.ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,
			'MsmeSections' TableName, OfiComments,isnull(S.AssessorId,'Exempted from Asssessment') AllotedAssessorId,U.UserName AllotedAssessorName,
			case when C.SiteAssessorId=S.AssessorId then 'Lead Assessor' when C.CoAssessorId=S.AssessorId then 'Co Assessor' end as AssessorRank
			FROM MsmeSections S left join Users U on (S.AssessorId=U.UserId) left join MsmeCertifications C on (S.ZedId=C.ZedId and S.SectionType=C.Certification)
			WHERE SectionType=@Certification AND S.ZedId=@ZedId AND S.NcCount=0  ORDER BY cast(SectionCode as int)

		select * from MeetingRecordingLinks where ZedId=@ZedId AND CertificationType=@Certification order by createddate

	END
END



GO
