/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_VIEW_PROFILE]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_ASSESSMENT_VIEW_PROFILE] --'<redacted>', '<redacted>', '<redacted>'
(
	
	@ZedId varchar(50) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	IF @RoleId IN ('2','3')
	BEGIN
	IF(select count(*) from MsmeCertifications where ZedId=@ZedId AND ((@RoleId=2 AND CertificationBodyUserId=@UserId) OR (@RoleId=3 AND DesktopAssessorId=@UserId) OR (@RoleId=3 AND SiteAssessorId=@UserId) OR (@RoleId=3 AND CoAssessorId=@UserId) )   )=0
		SET @ZedId='000'
	END
						

    SELECT 
	M.MsmeId, M.ZedId, M.StateId, M.StateName, M.DistrictId, M.DistrictName, M.OwnerName, M.EnterpriseName,
	M.OrganisationType, M.OrganisationTypeName, M.EnterpriseType, M.EnterpriseTypee, M.MobileNo, M.EmailId,
	M.ApplicationId, M.UamNumber, M.PFlat, M.PBuilding, M.PRoad, M.PArea, M.PCity, M.PAddress, M.PPin,
	M.PStateId, M.PStateName, M.PLgDistrictCode, M.PDistrictName, M.PPlantDetailId, M.Activity,
	M.TwoDigitActivity, M.FourDigitActivity, M.FiveDigitActivity, M.ActivityDetailId, M.PledgeEmailId,
	M.IsBronzePaymentDone, M.IsSilverPaymentDone, M.IsGoldPaymentDone, M.IsCouponUsed, M.PledgeCertificateNo,
	M.RegistrationType, M.IncorporationDate, M.WhetherProdCommenced, M.PlantIdNo, M.PUnitName, M.PUnitIdNo,
	M.CreatedDate, M.RegistrationFrom, M.FinancialAssistanceStatus, M.WashWebinarCertificateNo, M.WashCertificateNo, M.QrCodeNo,	
	FORMAT(CreatedDate, 'MMMM d, yyyy') as PledgeOn FROM Msme M Where ZedId=@ZedId


    SELECT Id, MsmeId, ApplicationId, UdyogAadharNo, OwnerName, EnterpriseName, OrganisationType, OrganisationTypeName, SocialCategory, SocialCategoryName,
	Gender, PH, PanNo, Address, StateId, StateName, DistrictId, DistrictName, LgDistrictCode, Pincode, MobileNo, EmailId, MajorActivity, MajorActivityName,
	EnterpriseType, EnterpriseTypee, CommmenceDate, PreviousEMType, PreviousEMNumber, TotalEmp, InvestmentCost, DicName, AppliedDate, ZedId, LastestCertification FROM MsmeBasicInformation Where ZedId=@ZedId


	END

GO
/****** Object:  StoredProcedure [dbo].[SP_AUTO_FINAL_REJECT_EXPIRED_NC]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_AUTO_FINAL_REJECT_EXPIRED_NC]
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Get the list of units to reject. We include '<redacted>' because your rename logic needs it.
    CREATE TABLE #ExpiredCertifications (
        ZedId VARCHAR(50),
        CertificationType VARCHAR(50),
        InternalId INT 
    )

    INSERT INTO #ExpiredCertifications (ZedId, CertificationType, InternalId)
    SELECT ZedId, Certification, Id
    FROM MsmeCertifications
    WHERE (CertificationStatus = 7 OR (CertificationStatus = 17 AND (PreviousCertificationStatus>8 OR PreviousCertificationStatus IS NULL)))
      AND DATEDIFF(day, CertificationStatusDate, GETDATE()) > 40
	 -- and ZedId='<redacted>'

    DECLARE @CurrentZedId VARCHAR(50)
    DECLARE @CurrentCertType VARCHAR(50)
    DECLARE @CurrentInternalId INT

    WHILE EXISTS (SELECT 1 FROM #ExpiredCertifications)
    BEGIN
        SELECT TOP 1 
            @CurrentZedId = ZedId, 
            @CurrentCertType = CertificationType,
            @CurrentInternalId = InternalId
        FROM #ExpiredCertifications

        -- 2. Run your existing status update logic
        EXEC [dbo].[SP_MONITORING_REJECT_FINAL_SUBMIT] @ZedId = @CurrentZedId, @CertificationType = @CurrentCertType

        -- 3. Run your existing renaming logic (This renames the ID in the tables)
        EXEC [dbo].[SP_MONITORING_REJECT_CERTIFICATION] @ZedId = @CurrentZedId, @CertificationType = @CurrentCertType

        ---------------------------------------------------------------------------
        -- PREPARING THE @RenamedZedId HERE
        ---------------------------------------------------------------------------
        -- We combine the original ID and the Internal ID to match: concat(ZedId,'<redacted>',Id)
        DECLARE @RenamedZedId VARCHAR(100) = CONCAT(@CurrentZedId, '_D_', @CurrentInternalId)
        ---------------------------------------------------------------------------

        -- 4. Pass the prepared @RenamedZedId into the mail procedure
        EXEC [dbo].[SP_SEND_MAIL_AUTO_REJECT_NC_FROM_PARTIAL_REJECTION] 
            @OriginalZedId = @CurrentZedId, 
            @RenamedZedId = @RenamedZedId, 
            @Certification = @CurrentCertType

        DELETE FROM #ExpiredCertifications WHERE ZedId = @CurrentZedId AND CertificationType = @CurrentCertType
    END

    DROP TABLE #ExpiredCertifications
END
GO
/****** Object:  StoredProcedure [dbo].[SP_AUTO_REJECT_BRONZE_SURVEILLANCE_BEFORE_EXPIRY]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_AUTO_REJECT_BRONZE_SURVEILLANCE_BEFORE_EXPIRY]
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Get the list of active Bronze surveillance units whose main certificate expires in 4-7 days
    CREATE TABLE #ExpiringCertifications (
        ZedId VARCHAR(50),
        CertificationType VARCHAR(50),
        InternalId INT 
    )

    INSERT INTO #ExpiringCertifications (ZedId, CertificationType, InternalId)
    SELECT surv.ZedId, surv.Certification, surv.Id
	--,surv.certificationstatus,main.certificationstatusdate
    FROM dbo.MsmeCertifications surv
    INNER JOIN ZEDCS_V2_LIVE.dbo.MsmeCertifications main 
        ON surv.ZedId = main.ZedId
     WHERE surv.Certification = 'Bronze'
      AND (surv.CertificationStatus < 6 OR surv.CertificationStatus = 7) -- Active or Partial Surveillance
      AND main.Certification = 'Bronze'
      
      -- SAFETY SHIELD: Upgraded tracking skip cheyadaniki
      AND NOT EXISTS (
          SELECT 1 FROM ZEDCS_V2_LIVE.dbo.MsmeCertifications S 
          WHERE S.ZedId = main.ZedId 
            AND S.Certification IN ('Silver', 'Gold') 
            AND S.CertificationStatus = 16
      )
      
      -- DIRECT DATE BOUNDARY CHECK
      AND (
          -- Condition A: Already Completed 3 Years (Past Expiry - handles missing IDs)
          main.CertificationStatusDate <= DATEADD(year, -3, CAST(GETDATE() AS DATE))
          OR
          -- Condition B: Upcoming Expiry Window (4 to 7 Days remaining)
          (
              main.CertificationStatus = 6 
              AND main.CertificationStatusDate >= DATEADD(day, 4, DATEADD(year, -3, CAST(GETDATE() AS DATE)))
              AND main.CertificationStatusDate <  DATEADD(day, 8, DATEADD(year, -3, CAST(GETDATE() AS DATE)))
          )
      );

    DECLARE @CurrentZedId VARCHAR(50)
    DECLARE @CurrentCertType VARCHAR(50)
    DECLARE @CurrentInternalId INT

    -- 2. Loop through each expiring unit and process using standard SPs
    WHILE EXISTS (SELECT 1 FROM #ExpiringCertifications)
    BEGIN
        SELECT TOP 1 
            @CurrentZedId = ZedId, 
            @CurrentCertType = CertificationType,
            @CurrentInternalId = InternalId
        FROM #ExpiringCertifications

        BEGIN TRY
            BEGIN TRANSACTION;

				UPDATE MsmeCertifications 
                SET PreviousCertificationStatus = CertificationStatus
                WHERE PreviousCertificationStatus IS NULL 
                  AND ZedId = @CurrentZedId 
                  AND Certification = @CurrentCertType;

                -- Run your existing final submission rejection logic (resets payments, drops benefits, sets status 99)
                EXEC [dbo].[SP_MONITORING_REJECT_FINAL_SUBMIT] @ZedId = @CurrentZedId, @CertificationType = @CurrentCertType

                -- Run your renaming logic (renames IDs across tables if applicable)
                EXEC [dbo].[SP_MONITORING_REJECT_CERTIFICATION] @ZedId = @CurrentZedId, @CertificationType = @CurrentCertType

                ---------------------------------------------------------------------------
                -- OPTIONAL: MAIL TRIGGER SECTION
                ---------------------------------------------------------------------------
                -- If you have a specific mail procedure for expiry, you can call it here.
                -- Otherwise, you can adapt the renamed ID logic to notify the client:
                -- DECLARE @RenamedZedId VARCHAR(100) = CONCAT(@CurrentZedId, '<redacted>', @CurrentInternalId)
                -- EXEC [dbo].[SP_SEND_MAIL_AUTO_REJECT_EXPIRY] @OriginalZedId = @CurrentZedId, @RenamedZedId = @RenamedZedId, @Certification = @CurrentCertType
                ---------------------------------------------------------------------------

               -- 3. EXPLICIT CUSTOM HISTORY LOG (Chala safety hand istundi track cheyadaniki)
                INSERT INTO MsmeHistory (ZedId, Descrip, CreatedDate, CertificationType, StatusType)
                VALUES (
                    @CurrentZedId,
                    CONCAT('Surveillance Closed Automatically: Main Bronze certificate is expiring within 4-7 days. Actioned via System Job on ', FORMAT(GETDATE(), 'MMMM d, yyyy')),
                    GETDATE(),
                    @CurrentCertType,
                    'Surveillance Expiry Rejection'
                );
			   
			   -- Update comments on the local surveillance record to specify *why* it was auto-rejected
                --UPDATE MsmeCertifications
                --SET Comments = CONCAT(ISNULL(Comments, ''), '<redacted>')
                --WHERE Id = @CurrentInternalId;

            COMMIT TRANSACTION;
        END TRY
        BEGIN CATCH
            IF @@TRANCOUNT > 0
                ROLLBACK TRANSACTION;
            
            -- Keep a record of the error in SQL Server Logs but continue processing other records
            PRINT 'Error processing ZedId: ' + @CurrentZedId;
        END CATCH

        DELETE FROM #ExpiringCertifications WHERE ZedId = @CurrentZedId AND CertificationType = @CurrentCertType
    END

    DROP TABLE #ExpiringCertifications
END
GO
/****** Object:  StoredProcedure [dbo].[SP_BACKEND_APPLY_BRONZE_SURVEILLANCE_BY_STATE_PRIORITY]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Keerti Sreenivas
-- Create date: 14-05-2026
-- Description:	Apply Bronze Surveillance from backend with priority sorting
--              (Medium > Small > Micro) using Reset Queue data.
-- =============================================
CREATE PROCEDURE [dbo].[SP_BACKEND_APPLY_BRONZE_SURVEILLANCE_BY_STATE_PRIORITY] --'<redacted>'
(
    @StateName     VARCHAR(100)
   -- @DistrictList  VARCHAR(MAX)  -- '<redacted>'  --FIRST DISABLE AUTO ALLOCATION IN ZERO PAYMENT DETAILS 
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE 
        @ZedId VARCHAR(50),
        @Certification VARCHAR(50) = 'Bronze',
        @Priority INT,
        @CertDate DATETIME;

    -- Cursor with corrected Priority Logic and Reset Table Join
    DECLARE cur_apply CURSOR FAST_FORWARD FOR
    SELECT DISTINCT TOP 2000
        C.ZedId,
        CASE 
            WHEN M.EnterpriseType = 'Medium' THEN 1 
            WHEN M.EnterpriseType = 'Small' THEN 2 
            WHEN M.EnterpriseType = 'Micro' THEN 3 
            ELSE 4 
        END AS Priority,
        C.CertificationStatusDate
    FROM zedcs_v2_live.dbo.MsmeCertifications C
    INNER JOIN zedcs_v2_live.dbo.Msme M 
        ON M.ZedId = C.ZedId
    INNER JOIN ZED_SURVEILLANCE.dbo.Temp_Reset_Queue TRQ 
        ON C.ZedId = TRQ.zedid
    WHERE 
        C.Certification = 'Bronze'
        AND C.CertificationStatus = 6
        AND M.PStateName = @StateName
        AND M.IsSurBronzePaymentDone IS NULL
        AND TRQ.IsProcessed = 1
        AND NOT EXISTS (
            SELECT 1
            FROM zedcs_v2_live.dbo.MsmeCertifications C2
            WHERE C2.ZedId = C.ZedId
              AND C2.Certification IN ('Gold','Silver')
              AND C2.CertificationStatus = 16
        )
        AND NOT EXISTS (
            SELECT 1
            FROM ZED_SURVEILLANCE.dbo.MsmeCertifications SC
            WHERE SC.ZedId = C.ZedId
              AND SC.Certification = 'Bronze'
        )
    ORDER BY 
        Priority ASC,
        C.CertificationStatusDate DESC;

    OPEN cur_apply;
    
    -- Fetching all selected columns into variables
    FETCH NEXT FROM cur_apply INTO @ZedId, @Priority, @CertDate;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        BEGIN TRY
            EXEC dbo.SP_APPLY_BRONZE_SURVEILLANCE_FROM_BACKEND
                 @ZedId = @ZedId,
                 @Certification = @Certification;
        END TRY
        BEGIN CATCH
            PRINT 'Failed for ZedId: ' + ISNULL(@ZedId,'');
        END CATCH;

        FETCH NEXT FROM cur_apply INTO @ZedId, @Priority, @CertDate;
    END

    CLOSE cur_apply;
    DEALLOCATE cur_apply;
END







