/****** Object:  StoredProcedure [dbo].[SP_CONSULTANCY_APP_MSME_STATUS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
-- [SP_CONSULTANCY_APP_MSME_STATUS] '<redacted>'
CREATE PROCEDURE [dbo].[SP_CONSULTANCY_APP_MSME_STATUS] --'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @StateId int = NULL
	SELECT @StateId=StateId from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from ZED_CONSULTANT.dbo.UrlsMasterData

	DECLARE @LatestCertification varchar(100) = NULL,
			@DateOfAvail varchar(50) = NULL,
			@JoiningRewardAmount varchar(50) = '10000',
			@CompletedCertification varchar(50) = NULL

	DECLARE @LatestCertificationCon varchar(50) = null,
			@NcCountSilver int = NULL,
			@NcCountGold int = NULL,
			@CertiStatusSilver int = NULL,
			@CertiStatusGold int = NULL			

			select @LatestCertificationCon=LastestCertification from ZED_CONSULTANT.dbo.msme M inner join ZED_CONSULTANT.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId) where M.ZedId=@ZedId

			SELECT @CertiStatusSilver=min(CertificationStatus),@NcCountSilver=max(NcCount) FROM ZED_CONSULTANT.dbo.MsmeCertifications WHERE ZEDID=@ZedId and Certification='Silver'
			SELECT @CertiStatusGold=min(CertificationStatus),@NcCountGold=max(NcCount) FROM ZED_CONSULTANT.dbo.MsmeCertifications WHERE ZEDID=@ZedId and Certification='Gold'




			select top 1 @LatestCertification=Certification,@DateOfAvail=FORMAT(CreatedDate, 'MMMM d, yyyy') from ZED_CONSULTANT.dbo.MsmePaymentInfo where ZedId=@ZedId order by CreatedDate desc

			select top 1 @CompletedCertification=Certification from ZED_CONSULTANT.dbo.MsmeCertifications where CertificationStatus=100 and ZedId=@ZedId order by CreatedDate desc


	--STATUS CHECKING FOR ENABLE AND DISABLE OF BUTTONS IN APP
	SELECT 
		(select CASE WHEN (@CompletedCertification = 'Silver' or @CompletedCertification = 'gold') Then 5 WHEN CertificationStatus>5 THEN 3 WHEN CertificationStatus>2 THEN 2 when IsBronzePaymentDone=1 then 1 else 0 END AS CertificationStatus from ZED_CONSULTANT.dbo.Msme M LEFT JOIN  ZED_CONSULTANT.dbo.MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Bronze' and C.NcCount=1) where M.zedid=@ZedId ) BronzeStatus,
		(select CASE WHEN (@CompletedCertification = 'gold') Then 5 WHEN CertificationStatus>16 THEN 4 WHEN CertificationStatus>8 THEN 3 WHEN CertificationStatus>=6 THEN 2 when IsSilverPaymentDone=1 then 1 else 0 END AS CertificationStatus from ZED_CONSULTANT.dbo.Msme M LEFT JOIN  ZED_CONSULTANT.dbo.MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Silver' and C.NcCount=1) where M.zedid=@ZedId ) SilverStatus,
		(select CASE WHEN (@CompletedCertification = 'gold') Then 5 WHEN CertificationStatus>16 THEN 4 WHEN CertificationStatus>8 THEN 3 WHEN CertificationStatus>=6 THEN 2 when IsSilverPaymentDone=1 then 1 else 0 END AS CertificationStatus from ZED_CONSULTANT.dbo.Msme M LEFT JOIN  ZED_CONSULTANT.dbo.MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Silver' and C.NcCount=2) where M.zedid=@ZedId ) SilverStatus2,
		(select CASE WHEN (@CompletedCertification = 'gold') Then 5 WHEN CertificationStatus>16 THEN 4 WHEN CertificationStatus>8 THEN 3 WHEN CertificationStatus>=6 THEN 2 when IsSilverPaymentDone=1 then 1 else 0 END AS CertificationStatus from ZED_CONSULTANT.dbo.Msme M LEFT JOIN  ZED_CONSULTANT.dbo.MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Silver' and C.NcCount=3) where M.zedid=@ZedId ) SilverStatus3,
		(select CASE WHEN CertificationStatus>16 THEN 4 WHEN CertificationStatus>8 THEN 3 WHEN CertificationStatus>2 THEN 2 when IsGoldPaymentDone=1 then 1 else 0 END AS CertificationStatus from ZED_CONSULTANT.dbo.Msme M LEFT JOIN  ZED_CONSULTANT.dbo.MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Gold' and C.NcCount=1) where M.zedid=@ZedId ) GoldStatus,
		(select CASE WHEN CertificationStatus>16 THEN 4 WHEN CertificationStatus>8 THEN 3 WHEN CertificationStatus>2 THEN 2 when IsGoldPaymentDone=1 then 1 else 0 END AS CertificationStatus from ZED_CONSULTANT.dbo.Msme M LEFT JOIN  ZED_CONSULTANT.dbo.MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Gold' and C.NcCount=2) where M.zedid=@ZedId ) GoldStatus2,
		(select CASE WHEN CertificationStatus>16 THEN 4 WHEN CertificationStatus>8 THEN 3 WHEN CertificationStatus>2 THEN 2 when IsGoldPaymentDone=1 then 1 else 0 END AS CertificationStatus from ZED_CONSULTANT.dbo.Msme M LEFT JOIN  ZED_CONSULTANT.dbo.MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Gold' and C.NcCount=3) where M.zedid=@ZedId ) GoldStatus3, 
		
		0 BronzeStatusOfNc,
		isnull((select max(NcCount) NcCount from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Silver'),0) SilverStatusOfNc,
		isnull( (select max(NcCount) NcCount from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Gold'),0) GoldStatusOfNc,
		

		NULL BronzeCertificatePath, --isnull((select case when DaCertificateNo is null then '' else concat(@CurrentUrl,'<redacted>',@ZedId,'<redacted>') end as BronzeCertificatePath from  ZED_CONSULTANT.dbo.MsmeCertifications  where ZedId=@ZedId and Certification='<redacted>' ),'') BronzeCertificatePath,
		 '' BronzeReportPath, concat(@CurrentUrl,'/Incentive/Details/',@StateId,'?ct=Bronze') BronzeIncentives,
		NULL SilverCertificatePath,--isnull((select case when SaCertificateNo is null then '' else concat(@CurrentUrl,'<redacted>',@ZedId,'<redacted>') end as BronzeCertificatePath from  ZED_CONSULTANT.dbo.MsmeCertifications  where ZedId=@ZedId and Certification='<redacted>' ),'') SilverCertificatePath,
		'' SilverReportPath, concat(@CurrentUrl,'/Incentive/Details/',@StateId,'?ct=Silver') SilverIncentives,
		NULL GoldCertificatePath, -- isnull((select case when SaCertificateNo is null then '' else concat(@CurrentUrl,'<redacted>',@ZedId,'<redacted>') end as BronzeCertificatePath from  ZED_CONSULTANT.dbo.MsmeCertifications  where ZedId=@ZedId and Certification='<redacted>' ),'') GoldCertificatePath,
		'' GoldReportPath, concat(@CurrentUrl,'/Incentive/Details/',@StateId,'?ct=Gold') GoldIncentives,
		

		0 BronzeStatusOfNc1,
		0 BronzeStatusOfNc2,
		0 BronzeStatusOfNc3,
		0 BronzeStatusOfNc4,
		0 BronzeStatusOfNc5,
		0 BronzeSelfieStatus,
		0 BronzeRemoteStatus,

		isnull((select TOP 1 NcStatus from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Silver' and NcCount=1),0) SilverStatusOfNc1,
		isnull((select TOP 1 NcStatus from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Silver' and NcCount=2),0) SilverStatusOfNc2,
		isnull((select TOP 1 NcStatus from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Silver' and NcCount=3),0) SilverStatusOfNc3,
		0 SilverStatusOfNc4,
		0 SilverStatusOfNc5,
		isnull((select TOP 1 IsSaSelfieSubmitted from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Silver'),0) SilverSelfieStatus,
		isnull((select case when ModeOfAssessment='Remote Assessment' and CertificationStatus>9 then 2  when ModeOfAssessment='Remote Assessment' and CertificationStatus=9 then 1 else 0 end as RemoteStatus from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Silver' and NcCount=1),0) SilverRemoteStatus,

		isnull((select NcStatus from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Gold' and NcCount=1),0) GoldStatusOfNc1,
		isnull((select NcStatus from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Gold' and NcCount=2),0) GoldStatusOfNc2,
		isnull((select NcStatus from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Gold' and NcCount=3),0) GoldStatusOfNc3,
		0 GoldStatusOfNc4,
		0 GoldStatusOfNc5,
		isnull((select top 1 IsSaSelfieSubmitted from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and Certification='Gold'),0) GoldSelfieStatus,
		0 GoldRemoteStatus,

		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc1Raised','Nc1Submitted') and CertificationType='Bronze' order by Id desc) Nc1StatusTextBronze,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc2Raised','Nc2Submitted') and CertificationType='Bronze' order by Id desc) Nc2StatusTextBronze,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc3Raised','Nc3Submitted') and CertificationType='Bronze' order by Id desc) Nc3StatusTextBronze,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc4Raised','Nc4Submitted') and CertificationType='Bronze' order by Id desc) Nc4StatusTextBronze,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc5Raised','Nc5Submitted') and CertificationType='Bronze' order by Id desc) Nc5StatusTextBronze,
  
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc1Raised','Nc1Submitted') and CertificationType='Silver' order by Id desc) Nc1StatusTextSilver,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc2Raised','Nc2Submitted') and CertificationType='Silver' order by Id desc) Nc2StatusTextSilver,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc3Raised','Nc3Submitted') and CertificationType='Silver' order by Id desc) Nc3StatusTextSilver,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc4Raised','Nc4Submitted') and CertificationType='Silver' order by Id desc) Nc4StatusTextSilver,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc5Raised','Nc5Submitted') and CertificationType='Silver' order by Id desc) Nc5StatusTextSilver,
 
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc1Raised','Nc1Submitted') and CertificationType='Gold' order by Id desc)   Nc1StatusTextGold,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc2Raised','Nc2Submitted') and CertificationType='Gold' order by Id desc)   Nc2StatusTextGold,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc3Raised','Nc3Submitted') and CertificationType='Gold' order by Id desc)   Nc3StatusTextGold,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc4Raised','Nc4Submitted') and CertificationType='Gold' order by Id desc)   Nc4StatusTextGold,
		(select top 1  Descrip from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc5Raised','Nc5Submitted') and CertificationType='Gold' order by Id desc)   Nc5StatusTextGold,

		(select FinancialAssistanceStatus from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId)  FinancialAssistanceStatus,
		@LatestCertification LatestCertification,@DateOfAvail DateOfAvail,@JoiningRewardAmount JoiningRewardAmount,
		(select isnull(IsCouponUsed,0) from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId) IsCouponUsed,

		isnull((select top 1 CertificationStatus from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and NcCount=1 order by CertificationStatusDate desc),0) MilestoneCompletionStatus1,
		isnull((select top 1 CertificationStatus from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and NcCount=2 order by CertificationStatusDate desc),0) MilestoneCompletionStatus2,
		isnull((select top 1 CertificationStatus from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and NcCount=3 order by CertificationStatusDate desc),0) MilestoneCompletionStatus3,

		(select top 1 Certification from MsmeCertifications where zedid=@ZedId and (((Certification in ('Silver','Gold') and CertificationStatus=16)) OR ((Certification='Bronze' and CertificationStatus=6))) order by CertificationStatusDate desc) ZedCertificate,

		(select case when @LatestCertificationCon='Bronze' and @CertiStatusGold is null then 1 else 0 end as EnableSilver) EnableSilver,
		(select case when @LatestCertificationCon in ('Bronze','Silver') and (@CertiStatusSilver is null OR (@CertiStatusSilver=100 AND @NcCountSilver=3)) then 1 ELSE 0 end as EnableGold) EnableGold


END

GO
/****** Object:  StoredProcedure [dbo].[SP_CONSULTANCY_MSME_GET_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_CONSULTANCY_MSME_GET_DETAILS] null, '<redacted>', null
CREATE PROCEDURE [dbo].[SP_CONSULTANCY_MSME_GET_DETAILS] --null, '<redacted>', '<redacted>'
(
	@MsmeId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from ZED_CONSULTANT.dbo.UrlsMasterData

	DECLARE @LatestCertification varchar(100) = NULL,
			@DateOfAvail varchar(50) = NULL,
			@JoiningRewardAmount varchar(50) = '10000',
			@MileStoneNo int

			select top 1 @LatestCertification=Certification,@DateOfAvail=FORMAT(CreatedDate, 'MMMM d, yyyy') from ZED_CONSULTANT.dbo.MsmePaymentInfo where ZedId=@ZedId  order by CreatedDate desc
			select @MileStoneNo=isnull(max(NcCount),0) from ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@ZedId

	if @MsmeId IS NULL
		SELECT @MsmeId = MsmeId from ZED_CONSULTANT.dbo.msme where ZedId=@ZedId

	if @CertificationType IS NULL 
	set @CertificationType=@LatestCertification

    SELECT concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin) Address,*,FORMAT(CreatedDate, 'MMMM d, yyyy') as PledgeOn,@LatestCertification LatestCertification,@DateOfAvail DateOfAvail,@JoiningRewardAmount JoiningRewardAmount,@MileStoneNo MileStoneNo
	FROM ZED_CONSULTANT.dbo.Msme Where MsmeId=@MsmeId
    SELECT * FROM ZED_CONSULTANT.dbo.MsmeBasicInformation Where MsmeId=@MsmeId

	DECLARE @StateId int = NULL
	SELECT @StateId=StateId from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId

	--SELECT
	--	(SELECT ISNULL((SELECT ISNULL(CertificationStatus,0) BronzeStatus FROM ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@ZedId AND Certification='<redacted>'),0)) BronzeStatus,
	--	(SELECT ISNULL((SELECT ISNULL(CertificationStatus,0) SilverStatus FROM ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@ZedId AND Certification='<redacted>'),0)) SilverStatus,
	--	(SELECT ISNULL((SELECT ISNULL(CertificationStatus,0) GoldStatus FROM ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@ZedId AND Certification='<redacted>'),0)) GoldStatus


			SELECT
		CASE WHEN EXISTS (SELECT CertificationStatus from ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@Zedid AND Certification='Bronze' ) THEN 
			(SELECT ISNULL((SELECT TOP 1 ISNULL(CertificationStatus,0) BronzeStatus FROM ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@Zedid AND Certification='Bronze'  ORDER BY ID DESC),0))
		ELSE
		(SELECT ISNULL(IsBronzePaymentDone,0) BronzeStatus from ZED_CONSULTANT.dbo.Msme where ZedId=@Zedid) END AS BronzeStatus,

		CASE WHEN EXISTS (SELECT CertificationStatus from ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@Zedid AND Certification='Silver' ) THEN 
			(SELECT ISNULL((SELECT TOP 1 ISNULL(CertificationStatus,0) SilverStatus FROM ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@Zedid AND Certification='Silver'  ORDER BY ID DESC),0))
		ELSE
		(SELECT ISNULL(IsSilverPaymentDone,0) SilverStatus from ZED_CONSULTANT.dbo.Msme where ZedId=@Zedid) END AS SilverStatus,

		CASE WHEN EXISTS (SELECT CertificationStatus from ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@Zedid AND Certification='Gold' ) THEN 
			(SELECT ISNULL((SELECT TOP 1 ISNULL(CertificationStatus,0) GoldStatus FROM ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@Zedid AND Certification='Gold'  ORDER BY ID DESC),0))
		ELSE
		(SELECT ISNULL(IsGoldPaymentDone,0) GoldStatus from ZED_CONSULTANT.dbo.Msme where ZedId=@Zedid) END AS GoldStatus,
		(select FinancialAssistanceStatus from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId)  FinancialAssistanceStatus



		----------------**** --------------------------------------
			-- SELECT 
			--concat('<redacted>',FORMAT(EvidenceSubmissionDate, '<redacted>')) BasicInfoStatus,
			--case when CertificationStatus<6 then '<redacted>' else concat('<redacted>',FORMAT(EvidenceSubmissionDate, '<redacted>')) end as DesktopVerification,
			--'<redacted>' ScheduledOn,
			--'<redacted>' CompletedOn,
			--'<redacted>' NcFinalClosureDate,
			--'<redacted>' Nc1Raised,
			--'<redacted>' Nc1Submitted,
			--'<redacted>' Nc2Raised,
			--'<redacted>' Nc2Submitted,
			--'<redacted>' Nc3Raised,
			--'<redacted>' Nc3Submitted,
			--'<redacted>' Nc4Raised,
			--'<redacted>' Nc4Submitted,
			--'<redacted>' Nc5Raised,
			--'<redacted>' Nc5Submitted,
			--'<redacted>' NcClosed,
			--'<redacted>' Completed,
			--'<redacted>' GetCertified,
			--@CurrentUrl + '<redacted>' AvailIncentive
	
	
			--FROM ZED_CONSULTANT.dbo.MsmeCertifications  where ZedId=@ZedId and Certification=@CertificationType

			select 
			ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
			case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
			case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],
			[ScheduledOn],
			Completed as [CompletedOn],
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			[GetCertified],			
			case when @CertificationType='Bronze' then concat(@CurrentUrl + '/Incentive/Details/',@StateId,'?ct=Bronze') 
			     when @CertificationType='Silver' then concat(@CurrentUrl + '/Incentive/Details/',@StateId,'?ct=Silver') 
			     when @CertificationType='Gold' then concat(@CurrentUrl + '/Incentive/Details/',@StateId,'?ct=Gold') end as AvailIncentive,
			[ApplicationReceived],
			[NcFinalClosureDate]			
			from 
			(select Descrip,StatusType from ZED_CONSULTANT.dbo.MsmeHistory where ZedId=@ZedId and CertificationType=@CertificationType and statustype is not null and NcCount=@MileStoneNo) A
			pivot (
			max(descrip) for StatusType in (
			[BasicInfoStatus],
			[DesktopVerification],
			[ScheduledOn],
			[Completed],
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			[GetCertified],
			[ApplicationReceived],
			[NcFinalClosureDate]) ) as Pvt
	print @MileStoneNo

	select top 1 *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) SubsidyCoupon,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel from ZED_CONSULTANT.dbo.MsmePaymentInfo where ZedId=@ZedId and (@CertificationType is null OR Certification=@CertificationType) order by id desc

	select U.Email AutoEmailForAgency from ZED_CONSULTANT.dbo.MsmeCertifications M
	inner join ZED_CONSULTANT.dbo.Users U on (M.CertificationBodyUserId=U.UserId and RoleId=2)
	where ZedId=@zedid and Certification=@CertificationType and NcCount=@MileStoneNo AND NcCount>1
END

GO
/****** Object:  StoredProcedure [dbo].[SP_CONSULTANCY_MSME_GET_PAYMENT_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_CONSULTANCY_MSME_GET_PAYMENT_DETAILS] --null, '<redacted>','<redacted>'
(
	@MsmeId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
	DECLARE @EnterpriseTypee varchar(50), @SpecialCategory varchar(50), @IsAspirationalDt varchar(50), @SubsidyUsed bit = 0, @MileStoneNo int = 0

	select @MileStoneNo=isnull(max(NcCount),0)+1 from ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@ZedId and Certification=@Certification
	
	select @IsAspirationalDt=IsAspirationalDt from ZED_CONSULTANT.dbo.Districts where DistrictCode in (select PLgDistrictCode from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId)

	if @MsmeId IS NULL
		SELECT @MsmeId = MsmeId from ZED_CONSULTANT.dbo.msme where ZedId=@ZedId

		SELECT @EnterpriseTypee=EnterpriseTypee FROM ZED_CONSULTANT.dbo.Msme Where ZedId=@ZedId

    --SELECT @SpecialCategory=1 FROM ZED_CONSULTANT.dbo.MsmeBasicInformation Where MsmeId=@MsmeId
	SELECT  @SpecialCategory = CASE WHEN SocialCategoryName in ('SC','ST') THEN 1 WHEN Gender='Female' then 1 WHEN @IsAspirationalDt=1 then 1 else 0 END FROM ZED_CONSULTANT.dbo.MsmeBasicInformation Where MsmeId=@MsmeId

	


	IF @SpecialCategory = 1
	BEGIN
		SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM ZED_CONSULTANT.dbo.AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Coupon IS NULL AND SpecialCategory IS NOT NULL AND Milestone=@MileStoneNo
		SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM ZED_CONSULTANT.dbo.AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Coupon IS NULL AND SpecialCategory IS NOT NULL AND Milestone=@MileStoneNo
	END
	ELSE
	BEGIN
		SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM ZED_CONSULTANT.dbo.AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Coupon IS NULL AND SpecialCategory IS  NULL AND Milestone=@MileStoneNo
		SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM ZED_CONSULTANT.dbo.AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Coupon IS NULL AND SpecialCategory IS  NULL AND Milestone=@MileStoneNo
		END

	SELECT  case when IsCouponUsed=1 then 1 else 0 end as IsCouponUsed from ZED_CONSULTANT.dbo.msme where ZedId=@ZedId
END
GO
/****** Object:  StoredProcedure [dbo].[SP_CONSULTANCY_MSME_PAYMENT_BASIC_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_CONSULTANCY_MSME_PAYMENT_BASIC_DETAILS] --'<redacted>'
(
	@ZedId	varchar(50)	= NULL,
	@Certification	varchar(50)	= NULL,
	@UseCoupon	varchar(100)	= NULL,
	@UnitGstin	varchar(50)	= NULL,
	@Gstin	varchar(100)	= NULL,
	@TdsDeductible	varchar(200)	= NULL,
	@Tds	varchar(250)	= NULL,
	@Tan	varchar(50)	= NULL,
	@UtrNumber	varchar(50)	= NULL,
	@PaymentRefId	varchar(50)	= NULL,
	@TransactionId varchar(50) = NULL
)
AS
BEGIN
	DECLARE @AmountToBePaid varchar(50),
	    	@MileStoneNo int
	
	IF @TransactionId IS NULL 
		SET @TransactionId = Next Value For PaymentSequence; 

	IF @TdsDeductible='No'
		BEGIN
			select @AmountToBePaid=ApplicantContributionAfterSubsidy,@MileStoneNo=MileStone from ZED_CONSULTANT.dbo.AssessmentFee where Id=@PaymentRefId
		END
	IF @TdsDeductible='Yes'
		BEGIN			
				select @AmountToBePaid = CASE WHEN @Tds='1.5' THEN NetPaybleTds15 WHEN @Tds='7.5' THEN NetPaybleTds75 END,@MileStoneNo=MileStone from ZED_CONSULTANT.dbo.AssessmentFee where Id=@PaymentRefId
		END

	Insert into ZED_CONSULTANT.dbo.PaymentGatewayTransactions (ZedId,TransactionId,TransactionStatus,Amount,TransactionDate, Certification, UseCoupon, UnitGstin, Gstin, TdsDeductible, Tds, TanNumber, PaymentRefId,MileStoneNumber)
	values (@ZedId,@TransactionId,1,@AmountToBePaid,getdate(), @Certification, @UseCoupon, @UnitGstin, @Gstin, @TdsDeductible, @Tds, @Tan, @PaymentRefId,@MileStoneNo)

	IF @ZedId in ('ZEDMSME053104','ZEDMSME017215','ZEDMSME017214','ZEDMSME012646','ZEDMSME013590','ZEDMSME018692','ZEDMSME018700','ZEDMSME018746','ZEDMSME002612','ZEDMSME019486','ZEDMSME021377','ZEDMSME022100','ZEDMSME022094','ZEDMSME031062','ZEDMSME021670','ZEDMSME110098')
	BEGIN
	SET @AmountToBePaid=1.00  ---to test the payment gateway
	END

	IF (select count(*) from ZED_CONSULTANT.dbo.MsmePaymentInfo where zedid=@ZedId and Certification=@Certification and MileStoneNum=@MileStoneNo)>0
	BEGIN
		SET @ZedId='0000'
	END

	SELECT @AmountToBePaid AmountToBePaid, @TransactionId TransactionId, * FROM ZED_CONSULTANT.dbo.Msme WHERE ZedId=@ZedId



END



GO
/****** Object:  StoredProcedure [dbo].[SP_CONSULTANCY_MSME_PAYMENT_GATEWAY_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_CONSULTANCY_MSME_PAYMENT_GATEWAY_DETAILS] --'<redacted>','<redacted>','<redacted>',null,null,null,null,null,null,null,'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	@PaymentStatus varchar(50) = NULL,
	@PaymentResponse varchar(5000) = NULL,
	@IpAddress varchar(50) = NULL,
	@PgType varchar(50) = NULL,
	@BankRefNumber varchar(50) = NULL,
	@BankCode varchar(50) = NULL,
	@ErrorMessage varchar(2000) = NULL,
	@AmountPaid varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN

	DECLARE @NcCount int = NULL
	SELECT @NcCount=isnull(max(NcCount),0)+1 FROM ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@ZedId and Certification= @Certification
	
		declare @CertificationTblId int = NULL

		declare @CertificationLevel varchar(100) = NULL
	
		declare @Agency varchar(100) = NULL

		select @Agency=CertificationBodyUserId from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and CertificationStatus=100

		IF NOT EXISTS (select * from ZED_CONSULTANT.dbo.Users where UserId=@Agency and IsActive=1 and RoleId=2)
		BEGIN
		set @Agency=NULL
		END

		IF NOT EXISTS (SELECT * FROM ZED_CONSULTANT.dbo.PaymentGatewayTransactions WHERE ZedId=@ZedId and TransactionId=@TransactionId	AND PaymentStatus='Success')	
		 BEGIN
					UPDATE ZED_CONSULTANT.dbo.PaymentGatewayTransactions 
					SET PaymentStatus	= @PaymentStatus,
						PaymentResponse	= @PaymentResponse,
						IpAddress		= @IpAddress,
						PgType			= @PgType,
						BankRefNumber   = @BankRefNumber,
						BankCode        = @BankCode,
						ErrorMessage    = @ErrorMessage,
						UpdatedDate		= GETDATE()
					WHERE ZedId=@ZedId and TransactionId=@TransactionId	

				IF @PaymentStatus='success'
				BEGIN
					IF @Certification = 'Bronze'
						UPDATE ZED_CONSULTANT.dbo.Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
					ELSE IF @Certification = 'Silver'
						UPDATE ZED_CONSULTANT.dbo.Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
					ELSE IF @Certification = 'Gold'
						UPDATE ZED_CONSULTANT.dbo.Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId
		
	
					IF (SELECT UseCoupon FROM ZED_CONSULTANT.dbo.PaymentGatewayTransactions WHERE ZedId=@ZedId and TransactionId=@TransactionId) = 'Yes'
						UPDATE ZED_CONSULTANT.dbo.Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId


					INSERT INTO ZED_CONSULTANT.dbo.MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
						[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
						[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [PaymentType], [SubsidyPercentage],MileStoneNum
					)
					SELECT @ZedId, [EnterpriseTypee], @Certification, UseCoupon, UnitGstin, Gstin, TdsDeductible, Tds, TanNumber, 
						PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
						[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], 'PaymentGateway', [SubsidyPercentage], MileStoneNumber
					FROM ZED_CONSULTANT.dbo.AssessmentFee F, ZED_CONSULTANT.dbo.PaymentGatewayTransactions P
					WHERE F.Id=P.PaymentRefId AND TransactionId=@TransactionId AND ZedId=@ZedId

		
				END


				IF @PaymentStatus='success'
					BEGIN
					declare @PaidAmount varchar(50) = NULL
					select @PaidAmount=Amount from ZED_CONSULTANT.dbo.PaymentGateWayTransactions where ZedId=@ZedId and Certification=@Certification and TransactionId=@TransactionId and PaymentStatus='Success'

					select @CertificationLevel=LastestCertification from MsmeBasicInformation where ZedId=@ZedId

					Insert into ZED_CONSULTANT.dbo.MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType, NcCount)
					values (@ZedId,concat('Payment of Rs. ',@PaidAmount ,' successfully received on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@Certification,'ApplicationReceived', @NcCount)

					Insert into ZED_CONSULTANT.dbo.MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType, NcCount)
					values (@ZedId,concat('Payment is done through PaymentGateway for ',@Certification),getdate(),@Certification,NULL, @NcCount)

					---blocking the old id here---
					UPDATE ZED_CONSULTANT.dbo.MsmeCertifications set IdDisabled='Yes' where ZedId=@ZedId and Certification= @Certification and CertificationStatus<16

					INSERT INTO ZED_CONSULTANT.dbo.MsmeCertifications (ZedId, Certification, NcCount, NcStatus, CertificationBodyUserId, CertificationLevel)
					SELECT ZedId,Certification,@NcCount,1, @Agency, @CertificationLevel FROM ZED_CONSULTANT.dbo.PaymentGatewayTransactions WHERE TransactionId=@TransactionId AND ZedId=@ZedId and Certification=@Certification and PaymentStatus='Success'

					select @CertificationTblId=Id from ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@ZedId and Certification=@Certification and NcCount=@NcCount


					--INSERTION OF ELEMENTS DATA
					INSERT INTO ZED_CONSULTANT.dbo.MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,NcCount, SecCertId)
					SELECT Id,@ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,@NcCount,@CertificationTblId FROM Sections WHERE SectionType=@Certification ORDER BY SectionCode

					INSERT INTO ZED_CONSULTANT.dbo.MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,NcCount, ReqCertId)
					SELECT Id,@ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,@NcCount,@CertificationTblId FROM Requirements WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode

					INSERT INTO ZED_CONSULTANT.dbo.MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType,NcCount,OptCertId)
					SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType,@NcCount,@CertificationTblId FROM Options WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode

					INSERT INTO ZED_CONSULTANT.dbo.MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType,NcCount,SubCertId)
					SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType,@NcCount,@CertificationTblId FROM SubOptions WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

					INSERT INTO ZED_CONSULTANT.dbo.MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText,NcCount,EviCertId)
					SELECT Id,@ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,HelpText,@NcCount,@CertificationTblId FROM Evidences WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, EvidenceCode

					UPDATE ZED_CONSULTANT.dbo.MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=@NcCount and concat(sectioncode,'_',RequirementCode) not in 
					(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from ZED_CONSULTANT.dbo.MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=@NcCount)

					END
				ELSE
					BEGIN
					Insert into ZED_CONSULTANT.dbo.MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
					values (@ZedId,concat('Payment failed through PaymentGateway for ',@Certification),getdate(),@Certification,NULL,@NcCount)
					END

		END
		ELSE
		BEGIN
			 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'
		END

END
GO
/****** Object:  StoredProcedure [dbo].[SP_DA_GET_CERTIFICATE_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DA_GET_CERTIFICATE_DETAILS]  --'<redacted>','<redacted>'
(
	@ZedId Varchar(100) =NULL,
	@CertificationType Varchar(100) =NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @DateOfCertification varchar(50) = NULL
	select @DateOfCertification=FORMAT(CertificationStatusDate, 'MMMM d, yyyy')  from ZEDCS_V2_LIVE.dbo.MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType and CertificationStatus=6

	SELECT   M.PUnitName EnterpriseName,DaCertificateNo, @DateOfCertification DateOfCertification,
		case when RegistrationType='UAM' THEN B.Address ELSE concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin) end as Address ,	
		B.UdyogAadharNo,M.MobileNo,M.EmailId,M.EnterpriseName EstablishmentName, TwoDigitActivity NicCode, 
		case when Certification='Bronze' then '' else U.UserName end as AssessmentAgency, U.Email AgencyEmailId,
		concat('https://loginzed.msme.gov.in/Verify/BC/',QrCodeSeqNo) QrCodeSeqNo,
		UPPER(PUnitName) PUnitName, concat(C.ZedId,'_D_',C.Id) as RejectedZedId,
		FORMAT(CertificationStatusDate, 'MMMM d, yyyy') DateOfSurveillance, 1 SurveillanceNo
	from Msme M inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
	left join Users U on (U.UserId=C.CertificationBodyUserId)
	where Certification=@CertificationType and C.ZedId=@ZedId

	--select * from MsmeBasicInformation

END


GO
