			(select count(*) from ZEDCS_V2_LIVE.dbo.Msme M inner join ZEDCS_V2_LIVE.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join ZEDCS_V2_LIVE.dbo.MsmeCertifications C on (M.ZedId=C.ZedId) where (@State IS NULL OR M.PStateName=@State) AND (@Size IS NULL OR M.EnterpriseTypee=@Size) AND (@SocialCategory IS NULL OR SocialCategoryName=@SocialCategory) AND (@Gender IS NULL OR Gender=@Gender) AND UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915') AND C.CertificationStatus=16 and C.Certification='Silver') Silver,
			(select count(*) from ZEDCS_V2_LIVE.dbo.Msme M inner join ZEDCS_V2_LIVE.dbo.MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join ZEDCS_V2_LIVE.dbo.MsmeCertifications C on (M.ZedId=C.ZedId) where (@State IS NULL OR M.PStateName=@State) AND (@Size IS NULL OR M.EnterpriseTypee=@Size) AND (@SocialCategory IS NULL OR SocialCategoryName=@SocialCategory) AND (@Gender IS NULL OR Gender=@Gender) AND UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915') AND C.CertificationStatus=16 and C.Certification='Gold') Gold
