/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_DASHBOARD_GET_DETAILS] --'<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @RID INT = TRY_CAST(@RoleId AS INT);

    --------------------------------------------------------------------------------
    -- CASE 1: ADMIN (Cache for Roles 7, 10, 11)
    --------------------------------------------------------------------------------
    IF @RID IN (7, 10, 11)
    BEGIN
        SELECT 
            AssessmentAgencies, DesktopAssessors, SiteAssessors, FinancialAssessors,
            BronzeCompleted, FaBronzeCompleted, BronzePending,
            SilverCompleted, FaSilverCompleted, SilverPending,
            GoldCompleted, FaGoldCompleted, GoldPending,
            BronzeTotal, SilverTotal, GoldTotal,
            0 AS FaTotal, 0 AS FaPending, 0 AS FaCompleted, 0 AS FaRejected,
            SaSilverCompleted, SaGoldCompleted, SaSilverNcRaised, SaGoldNcRaised,
            BronzeRejected, SilverRejected, GoldRejected,
            LastUpdated AS CacheRefreshedAt
        FROM [ZED_ADMIN_STATS_CACHE]
        WHERE Id = 1;
    END

    --------------------------------------------------------------------------------
    -- CASE 2: STATE ADMIN (Role 8 - Live Query because of @State filter)
    --------------------------------------------------------------------------------
    ELSE IF @RID = 8
    BEGIN
        DECLARE @State varchar(100) = NULL;
        SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8;

        SELECT (select count(*) from Users where RoleId=2) AssessmentAgencies,
        (select count(*) from Users where RoleId=3 and DesktopVerification=1) DesktopAssessors, 
        (select count(*) from Users where RoleId=3 and SiteVerification=1) SiteAssessors,  
        (select count(*) from Users where RoleId=3 and FinancialVerification=1) FinancialAssessors,
        (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus=6 AND (M.StateId=@State)) BronzeCompleted,
        (select count(*) from FinancialAssistance where CertificationType='Bronze' and IsApproved=1) FaBronzeCompleted,
        (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus<6 and CertificationStatus>1 AND (M.StateId=@State)) BronzePending,
        (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=16 AND (M.StateId=@State)) SilverCompleted, 
        (select count(*) from FinancialAssistance where CertificationType='Silver' and IsApproved=1) FaSilverCompleted,
        (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus>8 and CertificationStatus<14 AND (M.StateId=@State)) SilverPending, 
        (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=16 AND (M.StateId=@State)) GoldCompleted,
        (select count(*) from FinancialAssistance where CertificationType='Gold' and IsApproved=1) FaGoldCompleted,
        (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus>8 and CertificationStatus<14 AND (M.StateId=@State)) GoldPending,
        (select count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification) where P.Certification='Bronze' AND (M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) BronzeTotal,
        (select count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification) where P.Certification='Silver' AND (M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) SilverTotal,
        (select count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification) where P.Certification='Gold' AND (M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) GoldTotal,
        0 FaTotal, 0 FaPending, 0 FaCompleted, 0 FaRejected,
        (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=16 AND (M.StateId=@State)) SaSilverCompleted, 
        (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=16 AND (M.StateId=@State)) SaGoldCompleted,
        (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=14 AND (M.StateId=@State)) SaSilverNcRaised, 
        (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=14 AND (M.StateId=@State)) SaGoldNcRaised,
        (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (M.StateId=@State)) BronzeRejected,
        (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 AND (M.StateId=@State)) SilverRejected,
        (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 AND (M.StateId=@State)) GoldRejected;
    END

    --------------------------------------------------------------------------------
    -- CASE 3: AGENCY (Role 2 - Live)
    --------------------------------------------------------------------------------
    ELSE IF @RID=2
    BEGIN
        SELECT 0 AssessmentAgencies,
        (select count(*) from Users where RoleId=3 and DesktopVerification=1 and CreatedBy=@UserId) DesktopAssessors, 
        (select count(*) from Users where RoleId=3 and SiteVerification=1 and  CreatedBy=@UserId) SiteAssessors,
        (select count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null ) BronzeCompleted,
        (select count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus<6 and CertificationStatus>1) BronzePending, 
        (select count(*) from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) SilverCompleted, 
        (select count(*) from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus>8 and CertificationStatus<14) SilverPending, 
        (select count(*) from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) GoldCompleted,
        (select count(*) from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus>8 and CertificationStatus<14) GoldPending,
        (select count(*) from MsmeCertifications where Certification='Silver' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is not null) SaSilverCompleted, 
        (select count(*) from MsmeCertifications where Certification='Silver' and CertificationStatus=14 and CertificationBodyUserId=@UserId and SaCertificateNo is null) SaSilverNcRaised, 
        (select count(*) from MsmeCertifications where Certification='Gold' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is not null) SaGoldCompleted,
        (select count(*) from MsmeCertifications where Certification='Gold' and CertificationStatus=14 and CertificationBodyUserId=@UserId and SaCertificateNo is null) SaGoldNcRaised,
        (select sum(counts) from ((select count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all (select count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) BronzeTotal, 
        (select sum(counts) from ((select count(*) counts from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all (select count(*) counts from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) SilverTotal, 
        (select sum(counts) from ((select count(*) counts from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all (select count(*) counts from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) GoldTotal,
        (select count(*) from Users where RoleId=3 and FinancialVerification=1 and  CreatedBy=@UserId) FinancialAssessors,
        (select count(*) from FinancialAssistance where VerificationStatus!=5 and CertificationBodyUserId=@UserId) FaTotal,
        (select count(*) from FinancialAssistance where VerificationStatus<5  and CertificationBodyUserId=@UserId) FaPending,
        (select count(*) from FinancialAssistance where VerificationStatus=6  and CertificationBodyUserId=@UserId) FaCompleted,
        (select count(*) from FinancialAssistance where VerificationStatus=5  and CertificationBodyUserId=@UserId) FaRejected,
        (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 and CertificationBodyUserId=@UserId) BronzeRejected,
        (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 and  CertificationBodyUserId=@UserId) SilverRejected,
        (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 and CertificationBodyUserId=@UserId) GoldRejected;
    END

    --------------------------------------------------------------------------------
    -- CASE 4: ASSESSOR (Role 3 - Live)
    --------------------------------------------------------------------------------
    ELSE IF @RID=3
    BEGIN
        SELECT 0 AssessmentAgencies, 0 DesktopAssessors, 0 SiteAssessors,
        (select count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null) BronzeCompleted,
        (select count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null) BronzePending, 
        (select count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is not null) SilverCompleted, 
        (select count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is null) SilverPending, 
        (select count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is not null) GoldCompleted,
        (select count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is null) GoldPending,
        (select count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null) SaSilverCompleted, 
        (select count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and CertificationStatus=14) SaSilverNcRaised, 
        (select count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null) SaGoldCompleted,
        (select count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and CertificationStatus=14) SaGoldNcRaised,
        (select sum(counts) from ((select count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null) union all (select count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null))A) BronzeTotal, 
        (select sum(counts) from ((select count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null) union all (select count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null))A) SilverTotal, 
        (select sum(counts) from ((select count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null) union all (select count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null))A) GoldTotal,
        (select count(*) from FinancialAssistance where VerificationStatus!=5 and FinancialAssessorId=@UserId) FaTotal,
        (select count(*) from FinancialAssistance where VerificationStatus<5  and FinancialAssessorId=@UserId) FaPending,
        (select count(*) from FinancialAssistance where VerificationStatus=6  and FinancialAssessorId=@UserId) FaCompleted,
        (select count(*) from FinancialAssistance where VerificationStatus=5  and FinancialAssessorId=@UserId) FaRejected,
        (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) BronzeRejected,
        (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 and  (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) SilverRejected,
        (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldRejected;
    END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS_bkp]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--[SP_DASHBOARD_GET_DETAILS] '<redacted>','<redacted>'
create PROC [dbo].[SP_DASHBOARD_GET_DETAILS_bkp] --'<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @State varchar(100) = NULL;
	DECLARE @RID int = TRY_CAST(@RoleId as int);

	-- Get StateCode for State Admin roles
	IF @RID = 8
	BEGIN
		SELECT @State = StateCode FROM USERS WHERE UserId = @UserId AND RoleId = 8;
	END

	--------------------------------------------------------------------------------
	-- CASE 1: ADMIN / STATE ROLES (7, 10, 8, 11)
	--------------------------------------------------------------------------------
	IF @RID IN (7, 10, 8, 11)
	BEGIN
		-- 1. Fetch Assessor Counts
		DECLARE @Agencies int, @DA int, @SA int, @FA int;
		SELECT 
			@Agencies = SUM(CASE WHEN RoleId = 2 THEN 1 ELSE 0 END),
			@DA = SUM(CASE WHEN RoleId = 3 AND DesktopVerification = 1 THEN 1 ELSE 0 END),
			@SA = SUM(CASE WHEN RoleId = 3 AND SiteVerification = 1 THEN 1 ELSE 0 END),
			@FA = SUM(CASE WHEN RoleId = 3 AND FinancialVerification = 1 THEN 1 ELSE 0 END)
		FROM Users;

		-- 2. Main Stats Block
		SELECT 
			@Agencies AS AssessmentAgencies, 
            @DA AS DesktopAssessors, 
			@SA AS SiteAssessors, 
            @FA AS FinancialAssessors,

			-- Bronze Counts
			SUM(CASE WHEN C.Certification = 'Bronze' AND C.CertificationStatus = 6 THEN 1 ELSE 0 END) AS BronzeCompleted,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE CertificationType = 'Bronze' AND IsApproved = 1) AS FaBronzeCompleted,
			SUM(CASE WHEN C.Certification = 'Bronze' AND C.CertificationStatus > 1 AND C.CertificationStatus < 6 THEN 1 ELSE 0 END) AS BronzePending,
			
			-- Silver Counts
			SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 16 THEN 1 ELSE 0 END) AS SilverCompleted,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE CertificationType = 'Silver' AND IsApproved = 1) AS FaSilverCompleted,
			SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus > 8 AND C.CertificationStatus < 14 THEN 1 ELSE 0 END) AS SilverPending,

			-- Gold Counts
			SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 16 THEN 1 ELSE 0 END) AS GoldCompleted,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE CertificationType = 'Gold' AND IsApproved = 1) AS FaGoldCompleted,
			SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus > 8 AND C.CertificationStatus < 14 THEN 1 ELSE 0 END) AS GoldPending,

			-- Totals (REPLICATING ORIGINAL JOIN LOGIC FOR EXACT MATCH)
			(SELECT COUNT(*) FROM Msme M INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId 
			 INNER JOIN MsmeCertifications C2 ON (M.ZedId = REPLACE(REPLACE(C2.Zedid,'_D',''), CONCAT('_', C2.Id), ''))
			 INNER JOIN MsmePaymentInfo P ON (C2.Zedid = P.Zedid AND C2.Certification = P.Certification)
			 WHERE P.Certification = 'Bronze' AND (@State IS NULL OR M.StateId = @State)
			 AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) AS BronzeTotal,

			(SELECT COUNT(*) FROM Msme M INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId 
			 INNER JOIN MsmeCertifications C2 ON (M.ZedId = REPLACE(REPLACE(C2.Zedid,'_D',''), CONCAT('_', C2.Id), ''))
			 INNER JOIN MsmePaymentInfo P ON (C2.Zedid = P.Zedid AND C2.Certification = P.Certification)
			 WHERE P.Certification = 'Silver' AND (@State IS NULL OR M.StateId = @State)
			 AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) AS SilverTotal,

			(SELECT COUNT(*) FROM Msme M INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId 
			 INNER JOIN MsmeCertifications C2 ON (M.ZedId = REPLACE(REPLACE(C2.Zedid,'_D',''), CONCAT('_', C2.Id), ''))
			 INNER JOIN MsmePaymentInfo P ON (C2.Zedid = P.Zedid AND C2.Certification = P.Certification)
			 WHERE P.Certification = 'Gold' AND (@State IS NULL OR M.StateId = @State)
			 AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) AS GoldTotal,

			0 AS FaTotal, 0 AS FaPending, 0 AS FaCompleted, 0 AS FaRejected,

			SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 16 THEN 1 ELSE 0 END) AS SaSilverCompleted,
			SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 16 THEN 1 ELSE 0 END) AS SaGoldCompleted,
			SUM(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 14 THEN 1 ELSE 0 END) AS SaSilverNcRaised,
			SUM(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 14 THEN 1 ELSE 0 END) AS SaGoldNcRaised,

			-- Rejection Logic (REPLICATING ORIGINAL SUBSTRING JOIN)
			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN Msme M ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=M.ZedId) WHERE C2.Certification='Bronze' AND C2.CertificationStatus=99 AND (@State is null or M.StateId=@State)) AS BronzeRejected,
			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN Msme M ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=M.ZedId) WHERE C2.Certification='Silver' AND C2.CertificationStatus=99 AND (@State is null or M.StateId=@State)) AS SilverRejected,
			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN Msme M ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=M.ZedId) WHERE C2.Certification='Gold' AND C2.CertificationStatus=99 AND (@State is null or M.StateId=@State)) AS GoldRejected

		FROM MsmeCertifications C
		INNER JOIN Msme M ON C.ZedId = M.ZedId
		INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
		WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		AND (@State IS NULL OR M.StateId = @State);
	END

	--------------------------------------------------------------------------------
	-- CASE 2: ASSESSMENT AGENCY (Role 2)
	--------------------------------------------------------------------------------
	ELSE IF @RID = 2
	BEGIN
		SELECT 
			0 AS AssessmentAgencies,
			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND DesktopVerification = 1 AND CreatedBy = @UserId) AS DesktopAssessors,
			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND SiteVerification = 1 AND CreatedBy = @UserId) AS SiteAssessors,
			
			SUM(CASE WHEN Certification = 'Bronze' AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS BronzeCompleted,
			SUM(CASE WHEN Certification = 'Bronze' AND DaCertificateNo IS NULL AND CertificationStatus > 1 AND CertificationStatus < 6 THEN 1 ELSE 0 END) AS BronzePending,
			
			SUM(CASE WHEN Certification = 'Silver' AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS SilverCompleted,
			SUM(CASE WHEN Certification = 'Silver' AND DaCertificateNo IS NULL AND CertificationStatus > 8 AND CertificationStatus < 14 THEN 1 ELSE 0 END) AS SilverPending,
			
			SUM(CASE WHEN Certification = 'Gold' AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS GoldCompleted,
			SUM(CASE WHEN Certification = 'Gold' AND DaCertificateNo IS NULL AND CertificationStatus > 8 AND CertificationStatus < 14 THEN 1 ELSE 0 END) AS GoldPending,

			SUM(CASE WHEN Certification = 'Silver' AND ModeOfAssessment IS NOT NULL AND SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS SaSilverCompleted,
			SUM(CASE WHEN Certification = 'Silver' AND CertificationStatus = 14 AND SaCertificateNo IS NULL THEN 1 ELSE 0 END) AS SaSilverNcRaised,
			SUM(CASE WHEN Certification = 'Gold' AND ModeOfAssessment IS NOT NULL AND SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS SaGoldCompleted,
			SUM(CASE WHEN Certification = 'Gold' AND CertificationStatus = 14 AND SaCertificateNo IS NULL THEN 1 ELSE 0 END) AS SaGoldNcRaised,

			(SELECT SUM(counts) FROM (
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Bronze' AND CertificationBodyUserId=@UserId AND DaCertificateNo IS NOT NULL) UNION ALL
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Bronze' AND CertificationBodyUserId=@UserId AND DaCertificateNo IS NULL)
			) A) AS BronzeTotal,
			(SELECT SUM(counts) FROM (
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Silver' AND CertificationBodyUserId=@UserId AND DaCertificateNo IS NOT NULL) UNION ALL
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Silver' AND CertificationBodyUserId=@UserId AND DaCertificateNo IS NULL)
			) A) AS SilverTotal,
			(SELECT SUM(counts) FROM (
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Gold' AND CertificationBodyUserId=@UserId AND DaCertificateNo IS NOT NULL) UNION ALL
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Gold' AND CertificationBodyUserId=@UserId AND DaCertificateNo IS NULL)
			) A) AS GoldTotal,

			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND FinancialVerification = 1 AND CreatedBy = @UserId) AS FinancialAssessors,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus != 5 AND CertificationBodyUserId = @UserId) AS FaTotal,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus < 5 AND CertificationBodyUserId = @UserId) AS FaPending,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 6 AND CertificationBodyUserId = @UserId) AS FaCompleted,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 5 AND CertificationBodyUserId = @UserId) AS FaRejected,

			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN Msme M ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=M.ZedId) WHERE Certification='Bronze' AND CertificationStatus=99 AND CertificationBodyUserId=@UserId) AS BronzeRejected,
			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN Msme M ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=M.ZedId) WHERE Certification='Silver' AND CertificationStatus=99 AND CertificationBodyUserId=@UserId) AS SilverRejected,
			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN Msme M ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=M.ZedId) WHERE Certification='Gold' AND CertificationStatus=99 AND CertificationBodyUserId=@UserId) AS GoldRejected

		FROM MsmeCertifications
		WHERE CertificationBodyUserId = @UserId;
	END

	--------------------------------------------------------------------------------
	-- CASE 3: ASSESSOR (Role 3)
	--------------------------------------------------------------------------------
	ELSE IF @RID = 3
	BEGIN
		SELECT 
			0 AS AssessmentAgencies, 0 AS DesktopAssessors, 0 AS SiteAssessors,
			
			SUM(CASE WHEN Certification = 'Bronze' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS BronzeCompleted,
			SUM(CASE WHEN Certification = 'Bronze' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NULL THEN 1 ELSE 0 END) AS BronzePending,
			
			SUM(CASE WHEN Certification = 'Silver' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS SilverCompleted,
			SUM(CASE WHEN Certification = 'Silver' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NULL THEN 1 ELSE 0 END) AS SilverPending,
			
			SUM(CASE WHEN Certification = 'Gold' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS GoldCompleted,
			SUM(CASE WHEN Certification = 'Gold' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NULL THEN 1 ELSE 0 END) AS GoldPending,

			SUM(CASE WHEN Certification = 'Silver' AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId) AND SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS SaSilverCompleted,
			SUM(CASE WHEN Certification = 'Silver' AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId) AND CertificationStatus = 14 THEN 1 ELSE 0 END) AS SaSilverNcRaised,
			SUM(CASE WHEN Certification = 'Gold' AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId) AND SaCertificateNo IS NOT NULL THEN 1 ELSE 0 END) AS SaGoldCompleted,
			SUM(CASE WHEN Certification = 'Gold' AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId) AND CertificationStatus = 14 THEN 1 ELSE 0 END) AS SaGoldNcRaised,

			(SELECT SUM(counts) FROM (
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Bronze' AND DesktopAssessorId=@UserId AND DaCertificateNo IS NOT NULL) UNION ALL
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Bronze' AND DesktopAssessorId=@UserId AND DaCertificateNo IS NULL)
			) A) AS BronzeTotal,
			(SELECT SUM(counts) FROM (
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Silver' AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) AND DaCertificateNo IS NOT NULL) UNION ALL
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Silver' AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) AND DaCertificateNo IS NULL)
			) A) AS SilverTotal,
			(SELECT SUM(counts) FROM (
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Gold' AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) AND DaCertificateNo IS NOT NULL) UNION ALL
				(SELECT COUNT(*) counts FROM MsmeCertifications WHERE Certification='Gold' AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) AND DaCertificateNo IS NULL)
			) A) AS GoldTotal,

			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus != 5 AND FinancialAssessorId = @UserId) AS FaTotal,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus < 5 AND FinancialAssessorId = @UserId) AS FaPending,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 6 AND FinancialAssessorId = @UserId) AS FaCompleted,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 5 AND FinancialAssessorId = @UserId) AS FaRejected,

			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN Msme M ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=M.ZedId) WHERE Certification='Bronze' AND CertificationStatus=99 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) AS BronzeRejected,
			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN Msme M ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=M.ZedId) WHERE Certification='Silver' AND CertificationStatus=99 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) AS SilverRejected,
			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN Msme M ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=M.ZedId) WHERE Certification='Gold' AND CertificationStatus=99 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) AS GoldRejected

		FROM MsmeCertifications
		WHERE (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId);
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS_old]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--[SP_DASHBOARD_GET_DETAILS_old] '<redacted>','<redacted>'
CREATE PROC [dbo].[SP_DASHBOARD_GET_DETAILS_old] --'<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
	
		DECLARE @State varchar(100) =NULL

		IF @State IS NULL OR @State=''
		BEGIN
		SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
		END

		IF @RoleId=7 OR @RoleId=10 OR @RoleId=8 OR @RoleId=11
		BEGIN
				SELECT (select count(*) from Users where RoleId=2) AssessmentAgencies,
			   (select count(*) from Users where RoleId=3 and DesktopVerification=1) DesktopAssessors, (select count(*) from Users where RoleId=3 and SiteVerification=1) SiteAssessors,  
			   (select count(*) from Users where RoleId=3 and FinancialVerification=1) FinancialAssessors,
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus=6 AND (@State is null or M.StateId=@State)) BronzeCompleted,
			   (select count(*) from FinancialAssistance where CertificationType='Bronze' and IsApproved=1) FaBronzeCompleted,

			   (		
				(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus<6 and CertificationStatus>1 AND (@State is null or M.StateId=@State))) BronzePending,
				
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=16 AND (@State is null or M.StateId=@State)) SilverCompleted, 
			   (select count(*) from FinancialAssistance where CertificationType='Silver' and IsApproved=1) FaSilverCompleted,

			   
				(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus>8 and CertificationStatus<14 AND (@State is null or M.StateId=@State)) SilverPending, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=16 AND (@State is null or M.StateId=@State)) GoldCompleted,
			   (select count(*) from FinancialAssistance where CertificationType='Gold' and IsApproved=1) FaGoldCompleted,

			   
				(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus>8 and CertificationStatus<14 AND (@State is null or M.StateId=@State)) GoldPending,

			

			   (select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId) 
			    inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
			   inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
				where P.Certification='Bronze' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) BronzeTotal,

				(select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId) 
				 inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
			   inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
				where P.Certification='Silver' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) SilverTotal,

				(select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId) 
				 inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) 
			   inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
				where P.Certification='Gold' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) GoldTotal,

				
			

			  0 FaTotal,
			  0 FaPending,
			  0 FaCompleted,
			  0 FaRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=16 AND (@State is null or M.StateId=@State)) SaSilverCompleted, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=16 AND (@State is null or M.StateId=@State)) SaGoldCompleted,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=14 AND (@State is null or M.StateId=@State)) SaSilverNcRaised, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=14 AND (@State is null or M.StateId=@State)) SaGoldNcRaised,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (@State is null or M.StateId=@State)) BronzeRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 AND (@State is null or M.StateId=@State)) SilverRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 AND (@State is null or M.StateId=@State)) GoldRejected
		END

		ELSE IF @RoleId=2
		BEGIN
		SELECT 0 AssessmentAgencies,
			   (select count(*) from Users where RoleId=3 and DesktopVerification=1 and CreatedBy=@UserId) DesktopAssessors, 
			   (select count(*) from Users where RoleId=3 and SiteVerification=1 and  CreatedBy=@UserId) SiteAssessors,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null ) BronzeCompleted,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus<6 and CertificationStatus>1) BronzePending, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) SilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus>8 and CertificationStatus<14) SilverPending, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) GoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus>8 and CertificationStatus<14) GoldPending,

			   (select count(*) from MsmeCertifications where Certification='Silver' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is not null) SaSilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and CertificationStatus=14 and CertificationBodyUserId=@UserId and SaCertificateNo is null) SaSilverNcRaised, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is not null) SaGoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and CertificationStatus=14 and CertificationBodyUserId=@UserId and SaCertificateNo is null) SaGoldNcRaised,

			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) BronzeTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) SilverTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) GoldTotal,
			   (select count(*) from Users where RoleId=3 and FinancialVerification=1 and  CreatedBy=@UserId) FinancialAssessors,

			   (select count(*) from FinancialAssistance where VerificationStatus!=5 and CertificationBodyUserId=@UserId) FaTotal,
			   (select count(*) from FinancialAssistance where VerificationStatus<5  and CertificationBodyUserId=@UserId) FaPending,
			   (select count(*) from FinancialAssistance where VerificationStatus=6  and CertificationBodyUserId=@UserId) FaCompleted,
			   (select count(*) from FinancialAssistance where VerificationStatus=5  and CertificationBodyUserId=@UserId) FaRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 and CertificationBodyUserId=@UserId) BronzeRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 and  CertificationBodyUserId=@UserId) SilverRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 and CertificationBodyUserId=@UserId) GoldRejected
		END

		ELSE IF @RoleId=3
		BEGIN
		SELECT 0 AssessmentAgencies,
			   0 DesktopAssessors,	
			   0 SiteAssessors,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null) BronzeCompleted,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null) BronzePending, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is not null) SilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is null) SilverPending, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is not null) GoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is null) GoldPending,

			   (select count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null) SaSilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and CertificationStatus=14) SaSilverNcRaised, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null) SaGoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and CertificationStatus=14) SaGoldNcRaised,

			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null))A) BronzeTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null))A) SilverTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null))A) GoldTotal,

			    (select count(*) from FinancialAssistance where VerificationStatus!=5 and FinancialAssessorId=@UserId) FaTotal,
			   (select count(*) from FinancialAssistance where VerificationStatus<5  and FinancialAssessorId=@UserId) FaPending,
			   (select count(*) from FinancialAssistance where VerificationStatus=6  and FinancialAssessorId=@UserId) FaCompleted,
			   (select count(*) from FinancialAssistance where VerificationStatus=5  and FinancialAssessorId=@UserId) FaRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) BronzeRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 and  (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) SilverRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldRejected

		END
		

END





GO
/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS_optmized]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROC [dbo].[SP_DASHBOARD_GET_DETAILS_optmized] --'<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @State varchar(100) = NULL;
	DECLARE @RID int = TRY_CAST(@RoleId as int);

	-- 1. Identify State for State Admin
	IF @RID = 8
	BEGIN
		SELECT @State = StateCode FROM USERS WHERE UserId = @UserId AND RoleId = 8;
	END

	--------------------------------------------------------------------------------
	-- CASE 1: ADMIN / STATE ROLES (7, 10, 8, 11)
	--------------------------------------------------------------------------------
	IF @RID IN (7, 10, 8, 11)
	BEGIN
		-- Pre-filter MSMEs once to maintain exclusion logic and state filters
		DECLARE @FilteredMSMEs TABLE (ZedId varchar(100) PRIMARY KEY);
		
		INSERT INTO @FilteredMSMEs (ZedId)
		SELECT M.ZedId
		FROM Msme M
		INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
		WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		AND (@State IS NULL OR M.StateId = @State);

		-- Fetch Assessor Counts
		DECLARE @Agencies int, @DA int, @SA int, @FA int;
		SELECT 
			@Agencies = SUM(CASE WHEN RoleId = 2 THEN 1 ELSE 0 END),
			@DA = SUM(CASE WHEN RoleId = 3 AND DesktopVerification = 1 THEN 1 ELSE 0 END),
			@SA = SUM(CASE WHEN RoleId = 3 AND SiteVerification = 1 THEN 1 ELSE 0 END),
			@FA = SUM(CASE WHEN RoleId = 3 AND FinancialVerification = 1 THEN 1 ELSE 0 END)
		FROM Users;

		-- Main Stats Query
		SELECT 
			@Agencies AS AssessmentAgencies, 
			@DA AS DesktopAssessors, 
			@SA AS SiteAssessors, 
			@FA AS FinancialAssessors,

			-- Bronze Counts
			COUNT(CASE WHEN C.Certification = 'Bronze' AND C.CertificationStatus = 6 THEN 1 END) AS BronzeCompleted,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE CertificationType = 'Bronze' AND IsApproved = 1) AS FaBronzeCompleted,
			COUNT(CASE WHEN C.Certification = 'Bronze' AND C.CertificationStatus > 1 AND C.CertificationStatus < 6 THEN 1 END) AS BronzePending,
			
			-- Silver Counts
			COUNT(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 16 THEN 1 END) AS SilverCompleted,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE CertificationType = 'Silver' AND IsApproved = 1) AS FaSilverCompleted,
			COUNT(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus > 8 AND C.CertificationStatus < 14 THEN 1 END) AS SilverPending,

			-- Gold Counts
			COUNT(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 16 THEN 1 END) AS GoldCompleted,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE CertificationType = 'Gold' AND IsApproved = 1) AS FaGoldCompleted,
			COUNT(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus > 8 AND C.CertificationStatus < 14 THEN 1 END) AS GoldPending,

			-- Totals (Using your original REPLACE logic for 100% data match)
			(SELECT COUNT(*) FROM @FilteredMSMEs FM 
			 INNER JOIN MsmeCertifications C2 ON FM.ZedId = REPLACE(REPLACE(C2.Zedid,'_D',''), CONCAT('_', C2.Id), '')
			 INNER JOIN MsmePaymentInfo P ON (C2.Zedid = P.Zedid AND C2.Certification = P.Certification)
			 WHERE P.Certification = 'Bronze') AS BronzeTotal,

			(SELECT COUNT(*) FROM @FilteredMSMEs FM 
			 INNER JOIN MsmeCertifications C2 ON FM.ZedId = REPLACE(REPLACE(C2.Zedid,'_D',''), CONCAT('_', C2.Id), '')
			 INNER JOIN MsmePaymentInfo P ON (C2.Zedid = P.Zedid AND C2.Certification = P.Certification)
			 WHERE P.Certification = 'Silver') AS SilverTotal,

			(SELECT COUNT(*) FROM @FilteredMSMEs FM 
			 INNER JOIN MsmeCertifications C2 ON FM.ZedId = REPLACE(REPLACE(C2.Zedid,'_D',''), CONCAT('_', C2.Id), '')
			 INNER JOIN MsmePaymentInfo P ON (C2.Zedid = P.Zedid AND C2.Certification = P.Certification)
			 WHERE P.Certification = 'Gold') AS GoldTotal,

			0 AS FaTotal, 0 AS FaPending, 0 AS FaCompleted, 0 AS FaRejected,

			COUNT(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 16 THEN 1 END) AS SaSilverCompleted,
			COUNT(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 16 THEN 1 END) AS SaGoldCompleted,
			COUNT(CASE WHEN C.Certification = 'Silver' AND C.CertificationStatus = 14 THEN 1 END) AS SaSilverNcRaised,
			COUNT(CASE WHEN C.Certification = 'Gold' AND C.CertificationStatus = 14 THEN 1 END) AS SaGoldNcRaised,

			-- Rejection Logic (Using your original SUBSTRING logic)
			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN @FilteredMSMEs FM ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=FM.ZedId) WHERE C2.Certification='Bronze' AND C2.CertificationStatus=99) AS BronzeRejected,
			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN @FilteredMSMEs FM ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=FM.ZedId) WHERE C2.Certification='Silver' AND C2.CertificationStatus=99) AS SilverRejected,
			(SELECT COUNT(*) FROM MsmeCertifications C2 INNER JOIN @FilteredMSMEs FM ON (SUBSTRING(C2.ZedId, 1, CHARINDEX('_D', C2.ZedId + '_D') - 1)=FM.ZedId) WHERE C2.Certification='Gold' AND C2.CertificationStatus=99) AS GoldRejected

		FROM MsmeCertifications C
		INNER JOIN @FilteredMSMEs M ON C.ZedId = M.ZedId;
	END

	--------------------------------------------------------------------------------
	-- CASE 2: ASSESSMENT AGENCY (Role 2)
	--------------------------------------------------------------------------------
	ELSE IF @RID = 2
	BEGIN
		SELECT 
			0 AS AssessmentAgencies,
			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND DesktopVerification = 1 AND CreatedBy = @UserId) AS DesktopAssessors,
			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND SiteVerification = 1 AND CreatedBy = @UserId) AS SiteAssessors,
			
			COUNT(CASE WHEN Certification = 'Bronze' AND DaCertificateNo IS NOT NULL THEN 1 END) AS BronzeCompleted,
			COUNT(CASE WHEN Certification = 'Bronze' AND DaCertificateNo IS NULL AND CertificationStatus BETWEEN 2 AND 5 THEN 1 END) AS BronzePending,
			
			COUNT(CASE WHEN Certification = 'Silver' AND DaCertificateNo IS NOT NULL THEN 1 END) AS SilverCompleted,
			COUNT(CASE WHEN Certification = 'Silver' AND DaCertificateNo IS NULL AND CertificationStatus BETWEEN 9 AND 13 THEN 1 END) AS SilverPending,
			
			COUNT(CASE WHEN Certification = 'Gold' AND DaCertificateNo IS NOT NULL THEN 1 END) AS GoldCompleted,
			COUNT(CASE WHEN Certification = 'Gold' AND DaCertificateNo IS NULL AND CertificationStatus BETWEEN 9 AND 13 THEN 1 END) AS GoldPending,

			COUNT(CASE WHEN Certification = 'Silver' AND SaCertificateNo IS NOT NULL THEN 1 END) AS SaSilverCompleted,
			COUNT(CASE WHEN Certification = 'Silver' AND CertificationStatus = 14 THEN 1 END) AS SaSilverNcRaised,
			COUNT(CASE WHEN Certification = 'Gold' AND SaCertificateNo IS NOT NULL THEN 1 END) AS SaGoldCompleted,
			COUNT(CASE WHEN Certification = 'Gold' AND CertificationStatus = 14 THEN 1 END) AS SaGoldNcRaised,

			(SELECT COUNT(*) FROM MsmeCertifications WHERE Certification='Bronze' AND CertificationBodyUserId=@UserId) AS BronzeTotal,
			(SELECT COUNT(*) FROM MsmeCertifications WHERE Certification='Silver' AND CertificationBodyUserId=@UserId) AS SilverTotal,
			(SELECT COUNT(*) FROM MsmeCertifications WHERE Certification='Gold' AND CertificationBodyUserId=@UserId) AS GoldTotal,

			(SELECT COUNT(*) FROM Users WHERE RoleId = 3 AND FinancialVerification = 1 AND CreatedBy = @UserId) AS FinancialAssessors,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus != 5 AND CertificationBodyUserId = @UserId) AS FaTotal,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus < 5 AND CertificationBodyUserId = @UserId) AS FaPending,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 6 AND CertificationBodyUserId = @UserId) AS FaCompleted,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 5 AND CertificationBodyUserId = @UserId) AS FaRejected,

			(SELECT COUNT(*) FROM MsmeCertifications C2 WHERE Certification='Bronze' AND CertificationStatus=99 AND CertificationBodyUserId=@UserId) AS BronzeRejected,
			(SELECT COUNT(*) FROM MsmeCertifications C2 WHERE Certification='Silver' AND CertificationStatus=99 AND CertificationBodyUserId=@UserId) AS SilverRejected,
			(SELECT COUNT(*) FROM MsmeCertifications C2 WHERE Certification='Gold' AND CertificationStatus=99 AND CertificationBodyUserId=@UserId) AS GoldRejected

		FROM MsmeCertifications
		WHERE CertificationBodyUserId = @UserId;
	END

	--------------------------------------------------------------------------------
	-- CASE 3: ASSESSOR (Role 3)
	--------------------------------------------------------------------------------
	ELSE IF @RID = 3
	BEGIN
		SELECT 
			0 AS AssessmentAgencies, 0 AS DesktopAssessors, 0 AS SiteAssessors,
			
			COUNT(CASE WHEN Certification = 'Bronze' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NOT NULL THEN 1 END) AS BronzeCompleted,
			COUNT(CASE WHEN Certification = 'Bronze' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NULL THEN 1 END) AS BronzePending,
			
			COUNT(CASE WHEN Certification = 'Silver' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NOT NULL THEN 1 END) AS SilverCompleted,
			COUNT(CASE WHEN Certification = 'Silver' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NULL THEN 1 END) AS SilverPending,
			
			COUNT(CASE WHEN Certification = 'Gold' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NOT NULL THEN 1 END) AS GoldCompleted,
			COUNT(CASE WHEN Certification = 'Gold' AND DesktopAssessorId = @UserId AND DaCertificateNo IS NULL THEN 1 END) AS GoldPending,

			COUNT(CASE WHEN (Certification = 'Silver') AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId) AND SaCertificateNo IS NOT NULL THEN 1 END) AS SaSilverCompleted,
			COUNT(CASE WHEN (Certification = 'Silver') AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId) AND CertificationStatus = 14 THEN 1 END) AS SaSilverNcRaised,
			COUNT(CASE WHEN (Certification = 'Gold') AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId) AND SaCertificateNo IS NOT NULL THEN 1 END) AS SaGoldCompleted,
			COUNT(CASE WHEN (Certification = 'Gold') AND (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId) AND CertificationStatus = 14 THEN 1 END) AS SaGoldNcRaised,

			(SELECT COUNT(*) FROM MsmeCertifications WHERE Certification='Bronze' AND DesktopAssessorId=@UserId) AS BronzeTotal,
			(SELECT COUNT(*) FROM MsmeCertifications WHERE Certification='Silver' AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) AS SilverTotal,
			(SELECT COUNT(*) FROM MsmeCertifications WHERE Certification='Gold' AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) AS GoldTotal,

			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus != 5 AND FinancialAssessorId = @UserId) AS FaTotal,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus < 5 AND FinancialAssessorId = @UserId) AS FaPending,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 6 AND FinancialAssessorId = @UserId) AS FaCompleted,
			(SELECT COUNT(*) FROM FinancialAssistance WHERE VerificationStatus = 5 AND FinancialAssessorId = @UserId) AS FaRejected,

			COUNT(CASE WHEN CertificationStatus=99 AND Certification='Bronze' THEN 1 END) AS BronzeRejected,
			COUNT(CASE WHEN CertificationStatus=99 AND Certification='Silver' THEN 1 END) AS SilverRejected,
			COUNT(CASE WHEN CertificationStatus=99 AND Certification='Gold' THEN 1 END) AS GoldRejected

		FROM MsmeCertifications
		WHERE (DesktopAssessorId = @UserId OR SiteAssessorId = @UserId);
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_PAYMENT_FAILED_TRANSACTIONS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DASHBOARD_PAYMENT_FAILED_TRANSACTIONS] --0
(
	@Status varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@State varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@Gender varchar(50) = NULL,
	@MsmeSize varchar(50) = NULL,
	@PageNo int = 1,
	@NoOfRecords int = 25000
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @State='' 
	SET @State = NULL

	IF @CertificationType='' 
	SET @CertificationType = NULL

	IF @Gender='' 
	SET @Gender = NULL

	IF @MsmeSize='' 
	SET @MsmeSize = NULL


	 
		SELECT 
				M.MsmeId, M.ZedId, M.StateId, M.StateName, M.DistrictId, M.DistrictName, M.OwnerName, M.EnterpriseName,
				M.OrganisationType, M.OrganisationTypeName, M.EnterpriseType, M.EnterpriseTypee, M.MobileNo, M.EmailId,
				M.ApplicationId, M.UamNumber, M.PFlat, M.PBuilding, M.PRoad, M.PArea, M.PCity, M.PAddress, M.PPin,
				M.PStateId, M.PStateName, M.PLgDistrictCode, M.PDistrictName, M.PPlantDetailId, M.Activity,
				M.TwoDigitActivity, M.FourDigitActivity, M.FiveDigitActivity, M.ActivityDetailId, M.PledgeEmailId,
				M.IsBronzePaymentDone, M.IsSilverPaymentDone, M.IsGoldPaymentDone, M.IsCouponUsed, M.PledgeCertificateNo,
				M.RegistrationType, M.IncorporationDate, M.WhetherProdCommenced, M.PlantIdNo, M.PUnitName, M.PUnitIdNo,
				M.CreatedDate, M.RegistrationFrom, M.FinancialAssistanceStatus, M.WashWebinarCertificateNo, M.WashCertificateNo, M.QrCodeNo,
				B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName,
				P.GstinNumber,A.UnitGstin, A.Gstin,A.TanNumber TanNo,B.PanNo, P.TanNumber, P.UtrNumber, P.AmountPaid, P.TransactionStatus,convert(varchar, A.TransactionDate, 9) TransactionDate,a.TransactionDate newdate, P.PaymentType, P.SubsidyPercentage,P.Tds,
				Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments, PaymentType, M.EnterpriseTypee,
				m.PDistrictName,A.Certification,ISNULL(Amount,0) FinalAmountPaid,
				ROW_NUMBER() OVER (order by  A.ZedId,A.TransactionDate desc) as RowNumber,
				A.TransactionId, TransactionDate,A.UseCoupon,
				case when A.Certification='Gold' and M.IsSilverPaymentDone is null and IsBronzePaymentDone is null then 1
					 when A.Certification='Gold' and M.IsSilverPaymentDone=1 and B.LastestCertification='Silver' then 1
					 when A.Certification='Gold' and M.IsBronzePaymentDone=1 and B.LastestCertification='Bronze' and M.IsSilverPaymentDone is null then 1

					 when A.Certification='Silver' and M.IsGoldPaymentDone is null and IsBronzePaymentDone is null then 1
					 when A.Certification='Silver' and M.IsBronzePaymentDone=1 and B.LastestCertification='Bronze' then 1

					 when A.Certification='Bronze' and M.IsGoldPaymentDone is null and M.IsSilverPaymentDone is null then 1
					 else 0 end as AllowManualUpdate,a.ZedId
		from PaymentGateWayTransactions A 
		left Join MsmePaymentInfo P on (A.ZedId=P.ZedId and A.Certification=P.Certification and P.ReSurveillance=a.GwReSurveillance)
		INNER JOIN Msme M on (A.ZedId=M.ZedId)
		INNER JOIN MsmeBasicInformation B on (A.ZedId=B.ZedId )
		where A.PaymentStatus is null and P.ZedId is null
		--and P.ReSurveillance=0
		--and GwReSurveillance=0

	    AND	(@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR A.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender) 
		ORDER BY A.ZedId,A.TransactionDate
	--offset ((@PageNo-1) * @NoOfRecords) rows fetch next @NoOfRecords rows only

 
END

