(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

		select B.BatchNo,VenueName,StartDate,EndDate,B.QpCode,J.QpName
		CandidateId,concat(FirstName,LastName) as CandidateName,C.MobileNo,EmailId,ZEDTAC as CertificateNo, R.State,R.District
		from ZED_CENTER_AUDIT_V2.dbo.Batches B 
		inner join ZED_CENTER_AUDIT_V2.dbo.Candidates C on (B.BatchNo=C.BatchNo)
		inner join ZED_CENTER_AUDIT_V2.dbo.JobRoles J on (B.QpCode=J.QpCode)
		inner join  ZED_CENTER_AUDIT_V2.dbo.Registrations R on (R.Email=C.EmailId )
		where CertificateIssuedOn is not null
		order by BatchNo,CandidateName


		


END


