-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS]  --NULL,'<redacted>',8
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME1

	SET NOCOUNT ON;

	--select * from MsmePaymentInfo order by id desc
	--select * from Districts
	--select * from msme 
	--select * from PaymentGateWayTransactions order by id desc
	
		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName, Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Bronze' Certification, case when RIGHT(C.ZedId,2)='_D' then 'Rejected' else 'Active' end as ZedIdStatus, 10000 CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, 10000-ApplicantContributionAfterSubsidy FinancialSupport,
		T.UnitGstin,T.TanNumber,Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName
		from msme M inner join MsmeCertifications C  on (M.ZedId=C.ZedId) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy,SubsidyPercentage,UseCoupon from MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (C.ZedId=T.ZedId and C.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Bronze' and CertificationStatus>=2 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')

		UNION ALL

		select M.ZedId,PUnitName,Paddress UnitAddress, PStateName,PDistrictName,Ppin as Pincode,  M.EnterpriseTypee EnterpriseType, 'Bronze' Certification, case when RIGHT(C.ZedId,2)='_D' then 'Rejected' else 'Active' end as ZedIdStatus, 10000 CertificationFee,ApplicantContributionAfterSubsidy,T.Amount as AmountPaid, 10000-ApplicantContributionAfterSubsidy FinancialSupport,
		T.UnitGstin,T.TanNumber,Tds,P.UseCoupon as JoiningReward, SubsidyPercentage,Gender,SocialCategoryName
		from msme M inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy,SubsidyPercentage ,UseCoupon from MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		left join 
