		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy,SubsidyPercentage, UseCoupon from MsmePaymentInfo) P on (C.ZedId=P.ZedId and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (C.ZedId=T.ZedId and C.Certification=T.Certification and P.PaymentRefId=T.PaymentRefId and PaymentStatus='Success' )
		where P.Certification='Silver' and CertificationStatus>=2 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')

		UNION ALL 

