		where P.Certification='Gold' and CertificationStatus=99 and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')


		UNION ALL

		
		--select null,null,null,isnull(FApproverAmount,0) FinancialSupport
