/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_FAILED_TRANSACTIONS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_FAILED_TRANSACTIONS]  --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	SELECT 
				M.MsmeId, M.ZedId, M.StateId, M.StateName, M.DistrictId, M.DistrictName, M.OwnerName, M.EnterpriseName,
				M.OrganisationType, M.OrganisationTypeName, M.EnterpriseType, M.EnterpriseTypee, M.MobileNo, M.EmailId,
				M.ApplicationId, M.UamNumber, M.PFlat, M.PBuilding, M.PRoad, M.PArea, M.PCity, M.PAddress, M.PPin,
				M.PStateId, M.PStateName, M.PLgDistrictCode, M.PDistrictName, M.PPlantDetailId, M.Activity,
				M.TwoDigitActivity, M.FourDigitActivity, M.FiveDigitActivity, M.ActivityDetailId, M.PledgeEmailId,
				M.IsBronzePaymentDone, M.IsSilverPaymentDone, M.IsGoldPaymentDone, M.IsCouponUsed, M.PledgeCertificateNo,
				M.RegistrationType, M.IncorporationDate, M.WhetherProdCommenced, M.PlantIdNo, M.PUnitName, M.PUnitIdNo,
				M.CreatedDate, M.RegistrationFrom, M.FinancialAssistanceStatus, M.WashWebinarCertificateNo, M.WashCertificateNo, M.QrCodeNo,
				B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName,
				P.GstinNumber, P.TanNumber, P.UtrNumber, P.AmountPaid, P.TransactionStatus,convert(varchar, A.TransactionDate, 9) TransactionDate, P.PaymentType, P.SubsidyPercentage,P.Tds,
				Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments, PaymentType, M.EnterpriseTypee,
				m.PDistrictName,A.Certification,ISNULL(Amount,0) FinalAmountPaid,
				ROW_NUMBER() OVER (order by  A.ZedId,A.TransactionDate desc) as RowNumber,
				A.TransactionId, TransactionDate,A.UseCoupon,
				case when A.Certification='Gold' and M.IsSilverPaymentDone is null and IsBronzePaymentDone is null then 'Yes'
					 when A.Certification='Gold' and M.IsSilverPaymentDone=1 and B.LastestCertification='Silver' then 'Yes'
					 when A.Certification='Gold' and M.IsBronzePaymentDone=1 and B.LastestCertification='Bronze' and M.IsSilverPaymentDone is null then 'Yes'

					 when A.Certification='Silver' and M.IsGoldPaymentDone is null and IsBronzePaymentDone is null then 'Yes'
					 when A.Certification='Silver' and M.IsBronzePaymentDone=1 and B.LastestCertification='Bronze' then 'Yes'

					 when A.Certification='Bronze' and M.IsGoldPaymentDone is null and M.IsSilverPaymentDone is null then 'Yes'
					 else 'No' end as AllowManualUpdate,a.ZedId
				from PaymentGateWayTransactions A 
				left Join MsmePaymentInfo P on (A.ZedId=P.ZedId and A.Certification=P.Certification)
				INNER JOIN Msme M on (A.ZedId=M.ZedId)
				INNER JOIN MsmeBasicInformation B on (A.ZedId=B.ZedId )
				where A.PaymentStatus is null and P.ZedId is null
				ORDER BY A.ZedId,A.TransactionDate

END


GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_NOT_SUCCESS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
create PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_NOT_SUCCESS]  --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL


		SELECT m.ZedId,A.Certification, PUnitName PUnitName,m.pstatename StateName,m.PDistrictName DistrictName,m.EnterpriseTypee Size,case when (M.IsCouponUsed)=1 then 'Yes' when IsCouponUsed is null then 'No' end as JoiningReward,
		B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName,
		P.GstinNumber, P.TanNumber, P.UtrNumber, P.Id TransactionId, P.TransactionStatus, P.PaymentType, P.SubsidyPercentage,P.Tds,ISNULL(Amount,0) AmountPaid,
		--Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments
		ROW_NUMBER() OVER (order by P.Id desc) as RowNumber,
		A.TransactionId,A.PaymentResponse, TransactionDate,PaymentStatus
		from PaymentGateWayTransactions A 
		left Join MsmePaymentInfo P on (A.ZedId=P.ZedId and A.Certification=P.Certification)
		INNER JOIN Msme M on (A.ZedId=M.ZedId)
		INNER JOIN MsmeBasicInformation B on (A.ZedId=B.ZedId )
		where A.PaymentStatus is null and P.ZedId is null
		ORDER BY ZedId,TransactionDate

END


