/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_RECEIVED]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_RECEIVED] -- NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 8
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END


	SELECT m.ZedId,P.Certification, PUnitName PUnitName,
	--PAddress,m.pstatename StateName,m.PDistrictName DistrictName,PPin,
	m.EnterpriseTypee Size,UdyogAadharNo,TotalEmp,
	case when P.UseCoupon is null then 'No' else P.UseCoupon end as JoiningReward,
		B.Gender, B.SocialCategoryName,PanNo,
		P.Id TransactionId, P.TransactionStatus,
		case when P.GstinNumber='No' then NULL when P.GstinNumber='Yes' then P.UnitGstin else GstinNumber end as GstinNumber, P.TanNumber, 
		--P.UtrNumber, P.PaymentType,
		convert(varchar, P.CreatedDate, 9) as TransactionDate,
		P.SubsidyPercentage,
		P.Tds,ApplicantContributionAfterSubsidy,
		ISNULL(Amount,0) AmountPaid,
		T.TrackingId [CCAvenue Ref#],
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS TransactionDate,
		--CASE WHEN P.ZedId LIKE '<redacted>' THEN '<redacted>' ELSE '<redacted>' END AS SurveillanceNo
		  CASE 
            WHEN P.ZedId LIKE '%\_S\_%' ESCAPE '\' THEN '1st Surveillance'
            WHEN B.ReSurveillance = 2 THEN '2nd Surveillance'
			ELSE '1st Surveillance'
        END AS SurveillanceNo
		--Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments
	FROM Msme M 
	INNER JOIN MsmeBasicInformation B ON (M.ZedId = B.ZedId)
	inner join MsmePaymentInfo P ON (M.ZedId = REPLACE(REPLACE(REPLACE(P.ZedId, CONCAT('_D_', P.MsmePmtCertId), ''), CONCAT('_S_', P.MsmePmtCertId), ''), '_D',''))
	LEFT JOIN PaymentGateWayTransactions T ON (
    P.ZedId = T.ZedId
    AND P.PaymentRefId = T.PaymentRefId 
    AND P.Certification = T.Certification 
    AND PaymentStatus = 'Success'
)
	WHERE SUBSTRING(P.ZedId, 1, CHARINDEX('_', P.ZedId + '_') - 1) = M.ZedId
	--AND P.Certification != '<redacted>'
	AND (@State is null or M.StateId=@State)
	and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	and (@RoleId=10 OR @RoleId=11) 
	ORDER By ZedId desc


END


GO
