	m.EnterpriseTypee Size,UdyogAadharNo,TotalEmp,
	case when P.UseCoupon is null then 'No' else P.UseCoupon end as JoiningReward,
		B.Gender, B.SocialCategoryName,PanNo,
		P.Id TransactionId, P.TransactionStatus,
		case when P.GstinNumber='No' then NULL when P.GstinNumber='Yes' then P.UnitGstin else GstinNumber end as GstinNumber, P.TanNumber, 
		--P.UtrNumber, P.PaymentType,
		convert(varchar, P.CreatedDate, 9) as TransactionDate,
		P.SubsidyPercentage,
		P.Tds,ApplicantContributionAfterSubsidy,
		ISNULL(Amount,0) AmountPaid,
		T.TrackingId [CCAvenue Ref#],
		DATEDIFF(DAY, '18991230', P.CreatedDate) AS TransactionDate
		--Case when  B.ReSurveillance = 2 Then '<redacted>'else '<redacted>' end as SurvellianceNo

		   --CASE 
     --       WHEN P.ZedId LIKE '<redacted>' ESCAPE '<redacted>' THEN '<redacted>'
     --       WHEN B.ReSurveillance = 2 THEN '<redacted>'
     --       ELSE '<redacted>' 
     --   END AS SurveillanceNo

		--Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments
		
	--FROM MsmePaymentInfo P inner join Msme M on (replace(P.ZedId,'<redacted>','')=M.ZedId)
	--inner join MsmeBasicInformation B on (replace(P.ZedId,'<redacted>','')=B.ZedId )
	--left join PaymentGateWayTransactions T on (M.ZedId=replace(T.ZedId,'<redacted>','') and P.PaymentRefId=T.PaymentRefId and P.Certification=T.Certification and PaymentStatus='<redacted>')
	--WHERE replace(P.ZedId,'<redacted>','')=M.ZedId AND M.ZedId=B.ZedId 

	FROM MsmePaymentInfo P
	--INNER JOIN Msme M ON (SUBSTRING(P.ZedId, 1, CHARINDEX('<redacted>', P.ZedId + '<redacted>') - 1) = M.ZedId)
	INNER JOIN Msme M ON LEFT(P.ZedId, CHARINDEX('_', P.ZedId + '_') - 1) = M.ZedId
	--INNER JOIN MsmeBasicInformation B ON (SUBSTRING(P.ZedId, 1, CHARINDEX('<redacted>', P.ZedId + '<redacted>') - 1) = B.ZedId)
	INNER JOIN MsmeBasicInformation B ON LEFT(P.ZedId, CHARINDEX('_', P.ZedId + '_') - 1) = B.ZedId


	--LEFT JOIN PaymentGateWayTransactions T ON (M.ZedId = SUBSTRING(T.ZedId, 1, CHARINDEX('<redacted>', T.ZedId + '<redacted>') - 1)
	LEFT JOIN PaymentGateWayTransactions T ON M.ZedId = LEFT(T.ZedId, CHARINDEX('_', T.ZedId + '_') - 1) 
	AND P.PaymentRefId = T.PaymentRefId AND P.Certification = T.Certification AND PaymentStatus = 'Success'
	--WHERE SUBSTRING(P.ZedId, 1, CHARINDEX('<redacted>', P.ZedId + '<redacted>') - 1) = M.ZedId
	WHERE LEFT(P.ZedId, CHARINDEX('_', P.ZedId + '_') - 1) = M.ZedId --and p.ZedId in ('<redacted>','<redacted>')











	and
	(@State is null or M.StateId=@State)
	and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	and (@RoleId=10 OR @RoleId=11)
	ORDER By ZedId desc



	--SELECT m.ZedId,P.Certification, PUnitName PUnitName,m.pstatename StateName,m.PDistrictName DistrictName,m.EnterpriseTypee Size,
	--case when P.UseCoupon is null then '<redacted>' else P.UseCoupon end as JoiningReward,
	--	B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName,
	--	case when P.GstinNumber='<redacted>' then NULL when P.GstinNumber='<redacted>' then P.UnitGstin else GstinNumber end as GstinNumber, P.TanNumber, P.UtrNumber, P.Id TransactionId, P.TransactionStatus,convert(varchar, P.CreatedDate, 9) as TransactionDate, P.PaymentType, P.SubsidyPercentage,P.Tds,ApplicantContributionAfterSubsidy,
	--	ISNULL(Amount,0) AmountPaid
	--	--Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments
		
	--FROM MsmePaymentInfo P inner join Msme M on (replace(P.ZedId,'<redacted>','')=M.ZedId)
	--inner join MsmeBasicInformation B on (replace(P.ZedId,'<redacted>','')=B.ZedId )
	--left join PaymentGateWayTransactions T on (M.ZedId=replace(T.ZedId,'<redacted>','') and P.PaymentRefId=T.PaymentRefId and P.Certification=T.Certification and PaymentStatus='<redacted>')
	--WHERE replace(P.ZedId,'<redacted>','')=M.ZedId AND M.ZedId=B.ZedId 
	--AND (@State is null or M.StateId=@State)
	--and UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>')
	--ORDER By ZedId desc

END


