GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME]  NULL,'<redacted>',10
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_NEW]  --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 8
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	IF @RoleId = 10
	BEGIN
		SELECT M.ZedId,M.CreatedDate as RegistrationDate, B.lastestCertification CertificationLevel,
		DATEDIFF(DAY, '18991230', ZP.CertificationStatusDate) ZedCertifiedDate, DATEDIFF(DAY, ZP.CertificationStatusDate, GETDATE()) AS DaysSinceCertified,
		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending'			
				when P.CertificationStatus=1 then 'Payment Received'
				when (P.certification='Bronze' and P.CertificationStatus=6) then 'Certified' 
				--when (certification in ('<redacted>','<redacted>') and CertificationStatus=6) then '<redacted>'
				when P.CertificationStatus=7 then 'Partially Rejected'
				when P.CertificationStatus=99 then 'Expired'
				when P.CertificationStatus=8 then 'Surveillance Planned'
				when P.CertificationStatus=9 then 'Surveillance Planned'
				when P.CertificationStatus=13 then 'Surveillance in progress'
				when P.CertificationStatus=14 then 'NC raised in Surveillance'
				when P.CertificationStatus=15 then 'Surveillance Completed'
				when (P.certification='Silver' and P.CertificationStatus=16) then 'Silver Certified' 
				when (P.certification='Gold' and P.CertificationStatus=16) then 'Gold Certified' 
				when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Received'
			end as AssessmentStatus,
			--BasicInfoStatus DocsubmissionDate,DocVerifiAllot,
			DATEDIFF(DAY, '18991230', P.AssessmentDate) as DateOfSurveillanceAssessment,
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				CompletedOn,
			PUnitName,	case when P.Certification is null and IsBronzePaymentDone=1 then 'Bronze'
			when P.Certification is null and IsSilverPaymentDone=1 then 'Silver' when P.Certification is null and IsGoldPaymentDone=1 then 'Gold' else P.Certification end as Certification,
		M.OwnerName,	M.EnterpriseTypee,	M.MobileNo, U.UserName as AgencyName, P.DesktopAssessorId,P.SiteAssessorId,P.CoAssessorId,
		M.EmailId, TwoDigitActivity,
		B.UdyogAadharNo, B.SocialCategoryName,	B.Gender,	B.PanNo,	PAddress,	PStateName,	PDistrictName

		FROM Msme M
		inner join msmebasicinformation B on (B.ZedId=M.ZedId)
		left join MsmeCertifications P on (P.ZedId=M.ZedId)	
		left join ZEDCS_V2_LIVE.dbo.MsmeCertifications ZP on (ZP.ZedId=M.ZedId and ZP.Certification=B.LastestCertification)	
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		left join
				(select ZedId,CertificationType,
				ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
				case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
				case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
				[ScheduledOn],
				Completed as [CompletedOn],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]			
				from 
				(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
				pivot (
				max(CreatedOn) for StatusType in (
				[BasicInfoStatus],
				[DesktopVerification],
				[ScheduledOn],
				DocVerifiAllot,
				[Completed],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]) ) as Pvt
			) PVD
			on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType ) 
		where (@State is null or M.StateId=@State) 
		and (P.CertificationStatus IS NULL OR (NOT (P.CertificationStatus = 16 OR (P.CertificationStatus = 6 AND P.Certification = 'Bronze')))) 
		--and UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>')
		ORDER By M.MsmeId desc
	END

	ELSE IF @RoleId=2
	BEGIN
		SELECT M.ZedId,M.CreatedDate as RegistrationDate, B.lastestCertification CertificationLevel, 
		DATEDIFF(DAY, '18991230', ZP.CertificationStatusDate) ZedCertifiedDate, DATEDIFF(DAY, ZP.CertificationStatusDate, GETDATE()) AS DaysSinceCertified,
		US.UserName as DesktopAssessorName, UK.UserName as SiteAssessorName,
		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending'			
				when P.CertificationStatus=1 then 'Payment Received'
				--when CertificationStatus=2 then '<redacted>'
				--when CertificationStatus=3 then '<redacted>'
				--when CertificationStatus=4 then '<redacted>'
				--when CertificationStatus=5 then '<redacted>'
				when (P.certification='Bronze' and P.CertificationStatus=6) then 'Certified' 
				--when (certification in ('<redacted>','<redacted>') and CertificationStatus=6) then '<redacted>'
				when P.CertificationStatus in (7,99) then 'Rejected'
				when P.CertificationStatus=8 then 'Surveillance Planned'
				when P.CertificationStatus=9 then 'Surveillance Planned'
				when P.CertificationStatus=13 then 'Surveillance in progress'
				when P.CertificationStatus=14 then 'NC raised in Surveillance'
				when P.CertificationStatus=15 then 'Surveillance Completed'
				when (P.certification='Silver' and P.CertificationStatus=16) then 'Silver Certified' 
				when (P.certification='Gold' and P.CertificationStatus=16) then 'Gold Certified' 
				when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Received'
			end as AssessmentStatus,
			--BasicInfoStatus DocsubmissionDate,DocVerifiAllot,
			DATEDIFF(DAY, '18991230', P.AssessmentDate) as DateOfSurveillanceAssessment,
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				CompletedOn,
			PUnitName,	case when P.Certification is null and IsBronzePaymentDone=1 then 'Bronze'
			when P.Certification is null and IsSilverPaymentDone=1 then 'Silver' when P.Certification is null and IsGoldPaymentDone=1 then 'Gold' else P.Certification end as Certification,
		M.OwnerName,	M.EnterpriseTypee,	M.MobileNo,
		M.EmailId,	TwoDigitActivity,	
		B.UdyogAadharNo, B.SocialCategoryName,	B.Gender,	B.PanNo,	PAddress,	PStateName,	PDistrictName
		FROM Msme M
		inner join msmebasicinformation B on (B.ZedId=M.ZedId)
		left join MsmeCertifications P on (P.ZedId=M.ZedId)		
		left join ZEDCS_V2_LIVE.dbo.MsmeCertifications ZP on (ZP.ZedId=M.ZedId and ZP.Certification=B.LastestCertification)	
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users US on (P.DesktopAssessorId=US.UserId)
		LEFT JOIN Users UK on (P.SiteAssessorId=UK.UserId)
		left join
				(select ZedId,CertificationType,
				ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
				case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
				case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
				[ScheduledOn],
				Completed as [CompletedOn],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]			
				from 
				(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
				pivot (
				max(CreatedOn) for StatusType in (
				[BasicInfoStatus],
				[DesktopVerification],
				[ScheduledOn],
				DocVerifiAllot,
				[Completed],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]) ) as Pvt
			) PVD
			on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType ) 
		where (@State is null or M.StateId=@State) AND P.CertificationBodyUserId=@Userid 
		and (P.CertificationStatus IS NULL OR (NOT (P.CertificationStatus = 16 OR (P.CertificationStatus = 6 AND P.Certification = 'Bronze')))) 
		--and UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>')
		ORDER By M.MsmeId desc
	END

	ELSE IF (@RoleId=8 OR @RoleId=11)
	BEGIN
		SELECT M.ZedId,M.CreatedDate as RegistrationDate, B.lastestCertification CertificationLevel,
		DATEDIFF(DAY, '18991230', ZP.CertificationStatusDate) ZedCertifiedDate, DATEDIFF(DAY, ZP.CertificationStatusDate, GETDATE()) AS DaysSinceCertified,
		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending'			
				when P.CertificationStatus=1 then 'Payment Received'
				--when CertificationStatus=2 then '<redacted>'
				--when CertificationStatus=3 then '<redacted>'
				--when CertificationStatus=4 then '<redacted>'
				--when CertificationStatus=5 then '<redacted>'
				when (P.certification='Bronze' and P.CertificationStatus=6) then 'Certified' 
				--when (certification in ('<redacted>','<redacted>') and CertificationStatus=6) then '<redacted>'
				when P.CertificationStatus in (7,99) then 'Rejected'
				when P.CertificationStatus=8 then 'Surveillance Planned'
				when P.CertificationStatus=9 then 'Surveillance Planned'
				when P.CertificationStatus=13 then 'Surveillance in progress'
				when P.CertificationStatus=14 then 'NC raised in Surveillance'
				when P.CertificationStatus=15 then 'Surveillance Completed'
				when (P.certification='Silver' and P.CertificationStatus=16) then 'Silver Certified' 
				when (P.certification='Gold' and P.CertificationStatus=16) then 'Gold Certified' 
				when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Received'
			end as AssessmentStatus,
		--NULL AssessmentStatus,
			--BasicInfoStatus DocsubmissionDate,DocVerifiAllot,
			DATEDIFF(DAY, '18991230', P.AssessmentDate) as DateOfSurveillanceAssessment,
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				CompletedOn,
			PUnitName,	case when P.Certification is null and IsBronzePaymentDone=1 then 'Bronze'
			when P.Certification is null and IsSilverPaymentDone=1 then 'Silver' when P.Certification is null and IsGoldPaymentDone=1 then 'Gold' else P.Certification end as Certification,
		M.OwnerName,	M.EnterpriseTypee,	M.MobileNo,
		M.EmailId,	TwoDigitActivity,	
		B.UdyogAadharNo, B.SocialCategoryName,	B.Gender,	B.PanNo,	PAddress,	PStateName,	PDistrictName
		
		FROM Msme M
		inner join msmebasicinformation B on (B.ZedId=M.ZedId)
		left join MsmeCertifications P on (P.ZedId=M.ZedId)		
		left join ZEDCS_V2_LIVE.dbo.MsmeCertifications ZP on (ZP.ZedId=M.ZedId and ZP.Certification=B.LastestCertification)	
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		left join
				(select ZedId,CertificationType,
				ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
				case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
				case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
				[ScheduledOn],
				Completed as [CompletedOn],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]			
				from 
				(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
				pivot (
				max(CreatedOn) for StatusType in (
				[BasicInfoStatus],
				[DesktopVerification],
				[ScheduledOn],
				DocVerifiAllot,
				[Completed],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]) ) as Pvt
			) PVD
			on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType ) 
		where (@State is null or M.StateId=@State) 
		and (P.CertificationStatus IS NULL OR (NOT (P.CertificationStatus = 16 OR (P.CertificationStatus = 6 AND P.Certification = 'Bronze')))) 
		--and UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>')
		ORDER By M.MsmeId desc
	END

	ELSE
	BEGIN

	SELECT NULL DATAS

	END

END


GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_newopt]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_newopt]
(
    @UlbCode VARCHAR(100) = NULL,
    @Userid  VARCHAR(100) = NULL,
    @RoleId  VARCHAR(100) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    DECLARE @State VARCHAR(100) = NULL;

    IF @RoleId = 8
    BEGIN
        SELECT @State = StateCode FROM USERS WHERE UserId = @Userid AND RoleId = 8;
    END;

    /* STEP 1: PRE-PROCESS LIVE DATA (Optimization) */
    -- Pulling relevant live data into a local temp table first to avoid slow cross-db joins in the main loop
    IF OBJECT_ID('tempdb..#LIVE_DATA_PRE') IS NOT NULL DROP TABLE #LIVE_DATA_PRE;

    SELECT 
        ZedId, 
        lastestCertification, 
        SurvCertificationLevel, 
        Recertification
    INTO #LIVE_DATA_PRE
    FROM ZEDCS_V2_LIVE.dbo.msmebasicinformation
    WHERE ZedId IN (SELECT ZedId FROM Msme);

    CREATE CLUSTERED INDEX IX_Temp_Live_Zed ON #LIVE_DATA_PRE(ZedId);

    /* STEP 2: PRE-PROCESS HISTORY */
    IF OBJECT_ID('tempdb..#MSME_HISTORY_PRE') IS NOT NULL DROP TABLE #MSME_HISTORY_PRE;

    SELECT
        ZedId,
        CertificationType,
        MAX(CASE WHEN StatusType = 'Nc1Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc1Raised,
        MAX(CASE WHEN StatusType = 'Nc1Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc1Submitted,
        MAX(CASE WHEN StatusType = 'Nc2Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc2Raised,
        MAX(CASE WHEN StatusType = 'Nc2Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc2Submitted,
        MAX(CASE WHEN StatusType = 'Nc3Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc3Raised,
        MAX(CASE WHEN StatusType = 'Nc3Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc3Submitted,
        MAX(CASE WHEN StatusType = 'Nc4Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc4Raised,
        MAX(CASE WHEN StatusType = 'Nc4Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc4Submitted,
        MAX(CASE WHEN StatusType = 'Nc5Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc5Raised,
        MAX(CASE WHEN StatusType = 'Nc5Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc5Submitted,
        MAX(CASE WHEN StatusType = 'NcClosed'      THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS NcClosed,
        MAX(CASE WHEN StatusType = 'Completed'    THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS CompletedOn
    INTO #MSME_HISTORY_PRE
    FROM MsmeHistory
    WHERE StatusType IS NOT NULL
    GROUP BY ZedId, CertificationType;

    CREATE INDEX IX_Temp_History_Zed ON #MSME_HISTORY_PRE(ZedId, CertificationType);

    /* STEP 3: ROLE ID 10 (DASHBOARD) */
    IF @RoleId = 10
    BEGIN
        SELECT
            M.ZedId,
            M.CreatedDate AS RegistrationDate,
            B.lastestCertification AS SurveillanceLevel,
            LIVE_B.lastestCertification AS CurrentLiveLevel,
            LIVE_B.SurvCertificationLevel AS ActiveSurvLevel,
            DATEDIFF(DAY, '18991230', B.ZedCertifiedDate) AS ZedCertifiedDate,
            DATEDIFF(DAY, B.ZedCertifiedDate, GETDATE()) AS DaysSinceCertified,
            CASE
                WHEN B.IsRejected = 1 THEN 'REJECTED'
                WHEN P.CertificationStatus = 6 AND P.Certification = 'Bronze' THEN 'Certified'
                WHEN P.CertificationStatus = 16 AND P.Certification IN ('Silver','Gold') THEN P.Certification + ' Certified'
                WHEN P.CertificationStatus = 2 AND P.Certification = 'Bronze' THEN 'Allocated to Assessor'
                WHEN P.CertificationStatus = 3 AND P.Certification = 'Bronze' THEN 'Verification in progress'
                WHEN P.CertificationStatus = 4 AND P.Certification = 'Bronze' THEN 'NC Raised'
                WHEN P.CertificationStatus = 5 AND P.Certification = 'Bronze' THEN 'Quality Check'
                WHEN P.CertificationStatus IN (7,17) THEN 'Partially Rejected'
                WHEN P.CertificationStatus IN (8,9) THEN 'Surveillance Planned'
                WHEN P.CertificationStatus = 13 THEN 'Surveillance in progress'
                WHEN P.CertificationStatus = 14 THEN 'NC raised in Surveillance'
                WHEN P.CertificationStatus = 15 THEN 'Surveillance Completed'
                WHEN IsBronzePaymentDone = 1 OR IsSilverPaymentDone = 1 OR IsGoldPaymentDone = 1 THEN 'Payment Received'
                ELSE 'Payment Pending'
            END AS AssessmentStatus,
            CASE 
                WHEN LIVE_B.Recertification > 1 THEN 'NO'
                WHEN B.ZedCertifiedDate <= DATEADD(YEAR, -3, GETDATE()) THEN 'YES' 
                ELSE 'NO' 
            END AS IsExpired,
            CASE 
                WHEN B.IsRejected = 1 THEN 'Rejected'
                WHEN LIVE_B.lastestCertification = LIVE_B.SurvCertificationLevel THEN 'Active'
                WHEN (CASE WHEN LIVE_B.lastestCertification = 'Gold' THEN 3 
                           WHEN LIVE_B.lastestCertification = 'Silver' THEN 2 
                           WHEN LIVE_B.lastestCertification = 'Bronze' THEN 1 ELSE 0 END) > 
                     (CASE WHEN LIVE_B.SurvCertificationLevel = 'Gold' THEN 3 
                           WHEN LIVE_B.SurvCertificationLevel = 'Silver' THEN 2 
                           WHEN LIVE_B.SurvCertificationLevel = 'Bronze' THEN 1 ELSE 0 END) 
                     THEN 'Ignore - Upgraded in Live'
                WHEN LIVE_B.Recertification > 1 THEN 'Recertified Unit' 
                WHEN B.ZedCertifiedDate <= DATEADD(YEAR, -3, GETDATE()) THEN 'Ignore - 3 Year Expired'
                ELSE 'Active'
            END AS SurveillanceRemarks,
            CASE 
                WHEN P.Certification = 'Bronze' THEN DATEDIFF(DAY, '18991230', P.EvidenceSubmissionDate)
                WHEN P.Certification IN ('Silver', 'Gold') THEN DATEDIFF(DAY, '18991230', P.AssessmentDate)
                ELSE DATEDIFF(DAY, '18991230', ISNULL(P.AssessmentDate, P.EvidenceSubmissionDate)) 
            END AS DateOfSurveillanceAssessment,
            H.Nc1Raised, H.Nc1Submitted, H.Nc2Raised, H.Nc2Submitted,
            H.Nc3Raised, H.Nc3Submitted, H.Nc4Raised, H.Nc4Submitted,
            H.Nc5Raised, H.Nc5Submitted, H.NcClosed, H.CompletedOn,
            M.PUnitName, P.Certification, M.OwnerName, M.EnterpriseTypee,
            M.MobileNo, U.UserName AS AgencyName, P.DesktopAssessorId,
            P.SiteAssessorId, P.CoAssessorId, M.EmailId, TwoDigitActivity,
            B.UdyogAadharNo, B.SocialCategoryName, B.Gender, B.PanNo,
            PAddress, PStateName, PDistrictName
        FROM Msme M
        INNER JOIN msmebasicinformation B ON B.ZedId = M.ZedId
        LEFT JOIN #LIVE_DATA_PRE LIVE_B ON LIVE_B.ZedId = M.ZedId
        OUTER APPLY (
            SELECT TOP 1 * FROM MsmeCertifications PC
            WHERE PC.ZedId = M.ZedId
            ORDER BY PC.AssessmentDate DESC
        ) P
        LEFT JOIN Users U ON P.CertificationBodyUserId = U.UserId
        LEFT JOIN #MSME_HISTORY_PRE H ON H.ZedId = P.ZedId AND H.CertificationType = P.Certification
        WHERE (@State IS NULL OR M.StateId = @State)
          AND (B.lastestCertification = LIVE_B.lastestCertification OR LIVE_B.SurvCertificationLevel = LIVE_B.lastestCertification)
        ORDER BY M.CreatedDate DESC;
    END

    /* STEP 4: ROLE ID 2 (AGENCY VIEW) */
    ELSE IF @RoleId = 2
    BEGIN
        SELECT 
            M.ZedId, M.CreatedDate AS RegistrationDate, B.lastestCertification AS CertificationLevel,
            DATEDIFF(DAY, '18991230', B.ZedCertifiedDate) AS ZedCertifiedDate,
            DATEDIFF(DAY, B.ZedCertifiedDate, GETDATE()) AS DaysSinceCertified,
            DATEDIFF(DAY, '18991230', p.EvidenceSubmissionDate) AS EvidenceSubmissionDate,
            US.UserName AS DesktopAssessorName, UK.UserName AS SiteAssessorName,
            CASE 
                WHEN B.IsRejected = 1 THEN 'REJECTED'
                WHEN P.CertificationStatus = 6 AND P.Certification = 'Bronze' THEN 'Certified'
                WHEN P.CertificationStatus in (1) AND DesktopAccepted = 1 and P.Certification = 'Bronze' THEN 'Shedule But not started'
                WHEN P.CertificationStatus in (2) AND P.EvidenceSubmissionDate is not null and P.Certification = 'Bronze' THEN 'Evidence Submitted'
                WHEN P.CertificationStatus in (3) AND P.EvidenceSubmissionDate is not null and P.Certification = 'Bronze' THEN 'DA Started'
                WHEN p.CertificationStatus in (2,3) and P.Certification = 'Bronze' and DesktopAccepted = 1 Then 'Inprogress'
                WHEN P.CertificationStatus = 4 AND P.Certification = 'Bronze' THEN 'NC Raised'
                WHEN P.CertificationStatus = 5 AND P.Certification = 'Bronze' THEN 'Quality Check'
                WHEN (P.Certification IN ('Silver','Gold') AND P.CertificationStatus = 16) THEN P.Certification + ' Certified'
                WHEN P.CertificationStatus IN (7,17) THEN 'Rejected'
                WHEN P.CertificationStatus IN (8,9) THEN 'Surveillance Planned'
                WHEN P.CertificationStatus = 13 THEN 'Surveillance in progress'
                WHEN P.CertificationStatus = 14 THEN 'NC raised in Surveillance'
                WHEN P.CertificationStatus = 15 THEN 'Surveillance Completed'
                WHEN IsBronzePaymentDone = 1 OR IsSilverPaymentDone = 1 OR IsGoldPaymentDone = 1 THEN 'Payment Received'
                ELSE 'Payment Pending'
            END AS AssessmentStatus,
            CASE 
                WHEN LIVE_B.Recertification > 1 THEN 'NO'
                WHEN B.ZedCertifiedDate <= DATEADD(YEAR, -3, GETDATE()) THEN 'YES' 
                ELSE 'NO' 
            END AS IsExpired,
            CASE 
                WHEN ISNULL(P.Certification, B.lastestCertification) = 'Bronze' THEN DATEDIFF(DAY, '18991230', P.EvidenceSubmissionDate)
                WHEN ISNULL(P.Certification, B.lastestCertification) IN ('Silver', 'Gold') THEN DATEDIFF(DAY, '18991230', P.AssessmentDate)
                ELSE DATEDIFF(DAY, '18991230', ISNULL(P.AssessmentDate, P.EvidenceSubmissionDate)) 
            END AS DateOfSurveillanceAssessment,
            H.Nc1Raised, H.Nc1Submitted, H.Nc2Raised, H.Nc2Submitted,
            H.Nc3Raised, H.Nc3Submitted, H.Nc4Raised, H.Nc4Submitted,
            H.Nc5Raised, H.Nc5Submitted, H.NcClosed, H.CompletedOn,
            M.PUnitName, 
            ISNULL(P.Certification, 
                CASE WHEN IsBronzePaymentDone=1 THEN 'Bronze' 
                     WHEN IsSilverPaymentDone=1 THEN 'Silver' 
                     WHEN IsGoldPaymentDone=1 THEN 'Gold' END) AS Certification,
            M.OwnerName, M.EnterpriseTypee, M.MobileNo, M.EmailId, TwoDigitActivity,
            B.UdyogAadharNo, B.SocialCategoryName, B.Gender, B.PanNo, 
            PAddress, PStateName, PDistrictName
        FROM Msme M
        INNER JOIN msmebasicinformation B ON B.ZedId = M.ZedId
        LEFT JOIN MsmeCertifications P ON P.ZedId = M.ZedId 
        LEFT JOIN #LIVE_DATA_PRE LIVE_B ON LIVE_B.ZedId = M.ZedId
        LEFT JOIN Users US ON P.DesktopAssessorId = US.UserId
        LEFT JOIN Users UK ON P.SiteAssessorId = UK.UserId
        LEFT JOIN #MSME_HISTORY_PRE H ON H.ZedId = P.ZedId AND H.CertificationType = P.Certification
        WHERE (@State IS NULL OR M.StateId = @State)
          AND P.CertificationBodyUserId = @Userid
          AND (P.CertificationStatus IS NULL OR (NOT (P.CertificationStatus = 16 OR (P.CertificationStatus = 6 AND P.Certification = 'Bronze'))))
          AND B.IsRejected = 0
          AND (B.ZedCertifiedDate > DATEADD(YEAR, -3, GETDATE()) OR LIVE_B.Recertification > 1)
          AND (B.lastestCertification = LIVE_B.lastestCertification OR LIVE_B.SurvCertificationLevel = LIVE_B.lastestCertification)
        ORDER BY M.MsmeId DESC;
    END

    -- Cleanup
    IF OBJECT_ID('tempdb..#MSME_HISTORY_PRE') IS NOT NULL DROP TABLE #MSME_HISTORY_PRE;
    IF OBJECT_ID('tempdb..#LIVE_DATA_PRE') IS NOT NULL DROP TABLE #LIVE_DATA_PRE;
END
GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_old]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_old] --null, '<redacted>',10
(
    @UlbCode VARCHAR(100) = NULL,
    @Userid  VARCHAR(100) = NULL,
    @RoleId  VARCHAR(100) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    DECLARE @State VARCHAR(100) = NULL;

    IF @RoleId = 8
    BEGIN
        SELECT @State = StateCode FROM USERS WHERE UserId = @Userid AND RoleId = 8;
    END;

    /* STEP 1: PRE-PROCESS HISTORY */
    IF OBJECT_ID('tempdb..#MSME_HISTORY_PRE') IS NOT NULL DROP TABLE #MSME_HISTORY_PRE;

    SELECT
        ZedId,
        CertificationType,
        MAX(CASE WHEN StatusType = 'Nc1Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc1Raised,
        MAX(CASE WHEN StatusType = 'Nc1Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc1Submitted,
        MAX(CASE WHEN StatusType = 'Nc2Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc2Raised,
        MAX(CASE WHEN StatusType = 'Nc2Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc2Submitted,
        MAX(CASE WHEN StatusType = 'Nc3Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc3Raised,
        MAX(CASE WHEN StatusType = 'Nc3Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc3Submitted,
        MAX(CASE WHEN StatusType = 'Nc4Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc4Raised,
        MAX(CASE WHEN StatusType = 'Nc4Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc4Submitted,
        MAX(CASE WHEN StatusType = 'Nc5Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc5Raised,
        MAX(CASE WHEN StatusType = 'Nc5Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc5Submitted,
        MAX(CASE WHEN StatusType = 'NcClosed'      THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS NcClosed,
        MAX(CASE WHEN StatusType = 'Completed'    THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS CompletedOn
    INTO #MSME_HISTORY_PRE
    FROM MsmeHistory
    WHERE StatusType IS NOT NULL
    GROUP BY ZedId, CertificationType;

    CREATE INDEX IX_Temp_History_Zed ON #MSME_HISTORY_PRE(ZedId, CertificationType);

    /* STEP 2: ROLE ID 10 (DASHBOARD) */
    IF @RoleId = 10
    BEGIN
        SELECT
            M.ZedId,
            M.CreatedDate AS RegistrationDate,
            --B.lastestCertification AS SurveillanceLevel, -- This is what is in your local DB
			LIVE_B.lastestCertification AS CurrentLiveLevel, -- This is the current level in ZED
			LIVE_B.SurvCertificationLevel AS ActiveSurvLevel, -- The level currently flagged for surveillance
            DATEDIFF(DAY, '18991230', B.ZedCertifiedDate) AS ZedCertifiedDate,
            DATEDIFF(DAY, B.ZedCertifiedDate, GETDATE()) AS DaysSinceCertified,
            CASE
                WHEN B.IsRejected = 1 THEN 'REJECTED'
                WHEN P.CertificationStatus = 6 AND P.Certification = 'Bronze' THEN 'Certified'
                WHEN P.CertificationStatus = 16 AND P.Certification IN ('Silver','Gold') THEN P.Certification + ' Certified'
                WHEN P.CertificationStatus = 2 AND P.Certification = 'Bronze' THEN 'Allocated to Assessor'
                WHEN P.CertificationStatus = 3 AND P.Certification = 'Bronze' THEN 'Verification in progress'
                WHEN P.CertificationStatus = 4 AND P.Certification = 'Bronze' THEN 'NC Raised'
                WHEN P.CertificationStatus = 5 AND P.Certification = 'Bronze' THEN 'Quality Check'
                WHEN P.CertificationStatus IN (7,17) THEN 'Partially Rejected'
                WHEN P.CertificationStatus IN (8,9) THEN 'Surveillance Planned'
                WHEN P.CertificationStatus = 13 THEN 'Surveillance in progress'
                WHEN P.CertificationStatus = 14 THEN 'NC raised in Surveillance'
                WHEN P.CertificationStatus = 15 THEN 'Surveillance Completed'
                WHEN IsBronzePaymentDone = 1 OR IsSilverPaymentDone = 1 OR IsGoldPaymentDone = 1 THEN 'Payment Received'
                ELSE 'Payment Pending'
            END AS AssessmentStatus,
            -- Updated IsExpired Logic
            CASE 
                WHEN LIVE_B.Recertification > 1 THEN 'NO'
                WHEN B.ZedCertifiedDate <= DATEADD(YEAR, -3, GETDATE()) THEN 'YES' 
                ELSE 'NO' 
            END AS IsExpired,
            -- Surveillance Remarks
            CASE 
                WHEN B.IsRejected = 1 THEN 'Rejected'
                WHEN (B.lastestCertification != LIVE_B.lastestCertification and B.LastestCertification=LIVE_B.SurvCertificationLevel) THEN 'Ignore - Upgraded in Live'
                WHEN LIVE_B.Recertification > 1 THEN 'Recertified Unit' 
                WHEN B.ZedCertifiedDate <= DATEADD(YEAR, -3, GETDATE()) THEN 'Ignore - 3 Year Expired'
                ELSE 'Active'
            END AS SurveillanceRemarks,

            --DATEDIFF(DAY, '<redacted>', P.AssessmentDate) AS DateOfSurveillanceAssessment,
			CASE 
			WHEN P.Certification = 'Bronze' THEN DATEDIFF(DAY, '18991230', P.EvidenceSubmissionDate)
			WHEN P.Certification IN ('Silver', 'Gold') THEN DATEDIFF(DAY, '18991230', P.AssessmentDate)
			ELSE DATEDIFF(DAY, '18991230', ISNULL(P.AssessmentDate, P.EvidenceSubmissionDate)) 
			END AS DateOfSurveillanceAssessment,
            H.Nc1Raised, H.Nc1Submitted, H.Nc2Raised, H.Nc2Submitted,
            H.Nc3Raised, H.Nc3Submitted, H.Nc4Raised, H.Nc4Submitted,
            H.Nc5Raised, H.Nc5Submitted, H.NcClosed, H.CompletedOn,
            M.PUnitName, P.Certification, M.OwnerName, M.EnterpriseTypee,
            M.MobileNo, U.UserName AS AgencyName, P.DesktopAssessorId,
            P.SiteAssessorId, P.CoAssessorId, M.EmailId, TwoDigitActivity,
            B.UdyogAadharNo, B.SocialCategoryName, B.Gender, B.PanNo,
            PAddress, PStateName, PDistrictName,
			us.username as DesktopAssessor,
			p.DesktopAssessorId as  DesktopAssessorid,
			uk.Username as SiteAssessor,
			P.SiteAssessorId as SiteAssessor
        FROM Msme M
        INNER JOIN msmebasicinformation B ON B.ZedId = M.ZedId
        OUTER APPLY (
            SELECT TOP 1 * FROM MsmeCertifications PC
            WHERE PC.ZedId = M.ZedId
            ORDER BY PC.AssessmentDate DESC
        ) P
        LEFT JOIN ZEDCS_V2_LIVE.dbo.msmebasicinformation LIVE_B ON LIVE_B.ZedId = M.ZedId
        LEFT JOIN Users U ON P.CertificationBodyUserId = U.UserId

		LEFT JOIN Users US ON P.DesktopAssessorId = US.UserId
        LEFT JOIN Users UK ON P.SiteAssessorId = UK.UserId

        LEFT JOIN #MSME_HISTORY_PRE H ON H.ZedId = P.ZedId AND H.CertificationType = P.Certification
        WHERE (@State IS NULL OR M.StateId = @State)
		--and m.zedid in ('<redacted>','<redacted>','<redacted>','<redacted>')
		--AND (
  --    B.lastestCertification = LIVE_B.lastestCertification 
  --    OR 
  --    LIVE_B.SurvCertificationLevel = LIVE_B.lastestCertification
  --)
        ORDER BY M.CreatedDate DESC;
    END

    /* STEP 3: ROLE ID 2 (AGENCY VIEW) */
    ELSE IF @RoleId = 2
    BEGIN
        SELECT 
            M.ZedId, M.CreatedDate AS RegistrationDate, B.lastestCertification AS CertificationLevel,
            DATEDIFF(DAY, '18991230', B.ZedCertifiedDate) AS ZedCertifiedDate,
            DATEDIFF(DAY, B.ZedCertifiedDate, GETDATE()) AS DaysSinceCertified,
			DATEDIFF(DAY, '18991230', p.EvidenceSubmissionDate) AS EvidenceSubmissionDate,
		    US.UserName AS DesktopAssessor,p.DesktopAssessorId, UK.UserName AS SiteAssessor,P.SiteAssessorId,
            CASE 
                WHEN B.IsRejected = 1 THEN 'REJECTED'
                WHEN P.CertificationStatus = 6 AND P.Certification = 'Bronze' THEN 'Certified'
				--Added new
				WHEN P.CertificationStatus  in (1) AND DesktopAccepted = 1   and CertificationStatus = 1 and  P.Certification in ('Bronze') THEN 'Shedule But not started'
				WHEN P.CertificationStatus  in (2) AND P.EvidenceSubmissionDate is not null and   P.Certification in ('Bronze') THEN 'Evidence Submitted'
				WHEN P.CertificationStatus  in (3) AND P.EvidenceSubmissionDate is not null and   P.Certification in ('Bronze') THEN 'DA Started'
				--when p.CertificationStatus in (2,3) and Certification = '<redacted>'  and DesktopAccepted = 1 Then '<redacted>'
				WHEN P.CertificationStatus = 4 AND P.Certification in ('Bronze') THEN 'NC Raised'
                WHEN P.CertificationStatus = 5 AND P.Certification in ('Bronze') THEN 'Quality Check'
				--
                WHEN (P.Certification IN ('Silver','Gold') AND P.CertificationStatus = 16) THEN P.Certification + ' Certified'
                WHEN P.CertificationStatus IN (7,17) THEN 'Rejected'
                WHEN P.CertificationStatus IN (8,9) THEN 'Surveillance Planned'
                WHEN P.CertificationStatus = 13 THEN 'Surveillance in progress'
                WHEN P.CertificationStatus = 14 THEN 'NC raised in Surveillance'
                WHEN P.CertificationStatus = 15 THEN 'Surveillance Completed'
                WHEN IsBronzePaymentDone = 1 OR IsSilverPaymentDone = 1 OR IsGoldPaymentDone = 1 THEN 'Payment Received'
                ELSE 'Payment Pending'
            END AS AssessmentStatus,
            -- Updated IsExpired Logic for Agencies
            CASE 
                WHEN LIVE_B.Recertification > 1 THEN 'NO'
                WHEN B.ZedCertifiedDate <= DATEADD(YEAR, -3, GETDATE()) THEN 'YES' 
                ELSE 'NO' 
            END AS IsExpired,
            --DATEDIFF(DAY, '<redacted>', P.AssessmentDate) AS DateOfSurveillanceAssessment,
			CASE 
			WHEN P.Certification = 'Bronze' THEN DATEDIFF(DAY, '18991230', P.EvidenceSubmissionDate)
			WHEN P.Certification IN ('Silver', 'Gold') THEN DATEDIFF(DAY, '18991230', P.AssessmentDate)
			ELSE DATEDIFF(DAY, '18991230', ISNULL(P.AssessmentDate, P.EvidenceSubmissionDate)) 
			END AS DateOfSurveillanceAssessment,
            H.Nc1Raised, H.Nc1Submitted, H.Nc2Raised, H.Nc2Submitted,
            H.Nc3Raised, H.Nc3Submitted, H.Nc4Raised, H.Nc4Submitted,
            H.Nc5Raised, H.Nc5Submitted, H.NcClosed, H.CompletedOn,
            M.PUnitName, 
            ISNULL(P.Certification, 
                CASE WHEN IsBronzePaymentDone=1 THEN 'Bronze' 
                     WHEN IsSilverPaymentDone=1 THEN 'Silver' 
                     WHEN IsGoldPaymentDone=1 THEN 'Gold' END) AS Certification,
            M.OwnerName, M.EnterpriseTypee, M.MobileNo, M.EmailId, TwoDigitActivity,
            B.UdyogAadharNo, B.SocialCategoryName, B.Gender, B.PanNo, 
            PAddress, PStateName, PDistrictName
        FROM Msme M
        INNER JOIN msmebasicinformation B ON B.ZedId = M.ZedId
        LEFT JOIN MsmeCertifications P ON P.ZedId = M.ZedId 
        LEFT JOIN ZEDCS_V2_LIVE.dbo.msmebasicinformation LIVE_B ON LIVE_B.ZedId = M.ZedId
        LEFT JOIN Users US ON P.DesktopAssessorId = US.UserId
        LEFT JOIN Users UK ON P.SiteAssessorId = UK.UserId
        LEFT JOIN #MSME_HISTORY_PRE H ON H.ZedId = P.ZedId AND H.CertificationType = P.Certification
        WHERE (@State IS NULL OR M.StateId = @State)
          AND P.CertificationBodyUserId = @Userid
          AND (P.CertificationStatus IS NULL OR (NOT (P.CertificationStatus = 16 OR (P.CertificationStatus = 6 AND P.Certification = 'Bronze'))))
          AND B.IsRejected = 0
          AND (B.ZedCertifiedDate > DATEADD(YEAR, -3, GETDATE()) OR LIVE_B.Recertification > 1)
          AND (
          B.lastestCertification = LIVE_B.lastestCertification 
          OR 
          LIVE_B.SurvCertificationLevel = LIVE_B.lastestCertification
      )
        ORDER BY M.MsmeId DESC;
    END

    IF OBJECT_ID('tempdb..#MSME_HISTORY_PRE') IS NOT NULL DROP TABLE #MSME_HISTORY_PRE;
END
GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_oldnew]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_oldnew] --NULL,'<redacted>',10
(
    @UlbCode VARCHAR(100) = NULL,
    @Userid  VARCHAR(100) = NULL,
    @RoleId  VARCHAR(100) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @State VARCHAR(100) = NULL;

    IF @RoleId = 8
    BEGIN
        SELECT @State = StateCode
        FROM USERS
        WHERE UserId = @Userid
          AND RoleId = 8;
    END;

    --IF @RoleId <> 10
    --    RETURN;

    /* ======================================================
       MSME HISTORY (PIVOTED ONCE)
       ====================================================== */
	IF @RoleId = 10
    BEGIN
    ;WITH MSME_HISTORY AS
    (
        SELECT
            ZedId,
            CertificationType,
            MAX(CASE WHEN StatusType = 'Nc1Raised'     THEN CreatedOn END) AS Nc1Raised,
            MAX(CASE WHEN StatusType = 'Nc1Submitted' THEN CreatedOn END) AS Nc1Submitted,
            MAX(CASE WHEN StatusType = 'Nc2Raised'     THEN CreatedOn END) AS Nc2Raised,
            MAX(CASE WHEN StatusType = 'Nc2Submitted' THEN CreatedOn END) AS Nc2Submitted,
            MAX(CASE WHEN StatusType = 'Nc3Raised'     THEN CreatedOn END) AS Nc3Raised,
            MAX(CASE WHEN StatusType = 'Nc3Submitted' THEN CreatedOn END) AS Nc3Submitted,
            MAX(CASE WHEN StatusType = 'Nc4Raised'     THEN CreatedOn END) AS Nc4Raised,
            MAX(CASE WHEN StatusType = 'Nc4Submitted' THEN CreatedOn END) AS Nc4Submitted,
            MAX(CASE WHEN StatusType = 'Nc5Raised'     THEN CreatedOn END) AS Nc5Raised,
            MAX(CASE WHEN StatusType = 'Nc5Submitted' THEN CreatedOn END) AS Nc5Submitted,
            MAX(CASE WHEN StatusType = 'NcClosed'      THEN CreatedOn END) AS NcClosed,
            MAX(CASE WHEN StatusType = 'Completed'    THEN CreatedOn END) AS CompletedOn
        FROM
        (
            SELECT
                ZedId,
                CertificationType,
                StatusType,
                FORMAT(CreatedDate, 'MMMM d, yyyy') AS CreatedOn
            FROM MsmeHistory
            WHERE StatusType IS NOT NULL
        ) H
        GROUP BY ZedId, CertificationType
    )

    /* ======================================================
       MAIN QUERY
       ====================================================== */
    SELECT
        M.ZedId,
        M.CreatedDate AS RegistrationDate,
        B.lastestCertification AS CertificationLevel,

        DATEDIFF(DAY, '18991230', ZP.CertificationStatusDate) AS ZedCertifiedDate,
        DATEDIFF(DAY, ZP.CertificationStatusDate, GETDATE()) AS DaysSinceCertified,

        CASE
            WHEN P.CertificationStatus = 6
                 AND P.Certification = 'Bronze'
                THEN 'Certified'

            WHEN P.CertificationStatus = 16
                 AND P.Certification IN ('Silver','Gold')
                THEN P.Certification + ' Certified'

				WHEN P.CertificationStatus = 2
			 AND P.Certification = 'Bronze'
			THEN 'Allocated to Assessor'

			WHEN P.CertificationStatus = 3
				 AND P.Certification = 'Bronze'
				THEN 'Verification in progress'

			WHEN P.CertificationStatus = 4
				 AND P.Certification = 'Bronze'
				THEN 'NC Raised'

			WHEN P.CertificationStatus = 5
				 AND P.Certification = 'Bronze'
				THEN 'Quality Check'

            WHEN P.CertificationStatus IN (7,17)
                THEN 'Partially Rejected'

            WHEN P.CertificationStatus = 99
                THEN 'WITHDRAWN'

            WHEN P.CertificationStatus IN (8,9)
                THEN 'Surveillance Planned'

            WHEN P.CertificationStatus = 13
                THEN 'Surveillance in progress'

            WHEN P.CertificationStatus = 14
                THEN 'NC raised in Surveillance'

            WHEN P.CertificationStatus = 15
                THEN 'Surveillance Completed'

            WHEN IsBronzePaymentDone = 1
              OR IsSilverPaymentDone = 1
              OR IsGoldPaymentDone = 1
                THEN 'Payment Received'

            ELSE 'Payment Pending'
        END AS AssessmentStatus,

        DATEDIFF(DAY,'18991230',P.AssessmentDate) AS DateOfSurveillanceAssessment,

        H.Nc1Raised, H.Nc1Submitted,
        H.Nc2Raised, H.Nc2Submitted,
        H.Nc3Raised, H.Nc3Submitted,
        H.Nc4Raised, H.Nc4Submitted,
        H.Nc5Raised, H.Nc5Submitted,
        H.NcClosed,
        H.CompletedOn,

        M.PUnitName,
        P.Certification,

        M.OwnerName,
        M.EnterpriseTypee,
        M.MobileNo,
        U.UserName AS AgencyName,

        P.DesktopAssessorId,
        P.SiteAssessorId,
        P.CoAssessorId,

        M.EmailId,
        TwoDigitActivity,

        B.UdyogAadharNo,
        B.SocialCategoryName,
        B.Gender,
        B.PanNo,

        PAddress,
        PStateName,
        PDistrictName

    FROM Msme M
    INNER JOIN msmebasicinformation B
        ON B.ZedId = M.ZedId

    /* ======================================================
       PICK ONE CERTIFICATION (CERTIFIED > REJECTED > OTHERS)
       ====================================================== */
    OUTER APPLY
    (
        SELECT TOP 1 *
        FROM MsmeCertifications P
        WHERE
        (
            P.ZedId = M.ZedId
            OR
            (
                P.CertificationStatus = 99
                AND M.ZedId =
                    LEFT(P.ZedId,
                         CHARINDEX('_D_', P.ZedId + '_D_') - 1)
            )
        )
        ORDER BY
            CASE
                WHEN P.CertificationStatus IN (6,16) THEN 0
                WHEN P.CertificationStatus = 99     THEN 1
                ELSE 2
            END,
            P.AssessmentDate DESC
    ) P

    LEFT JOIN ZEDCS_V2_LIVE.dbo.MsmeCertifications ZP
        ON ZP.ZedId = M.ZedId
       AND ZP.Certification = B.lastestCertification

    LEFT JOIN Users U
        ON P.CertificationBodyUserId = U.UserId

    LEFT JOIN MSME_HISTORY H
        ON H.ZedId = P.ZedId
       AND H.CertificationType = P.Certification

    /* ======================================================
       SURVEILLANCE VALIDITY (CERTIFIED WITHIN 3 YEARS)
       ====================================================== */
    WHERE
        (@State IS NULL OR M.StateId = @State)
    AND
        ZP.CertificationStatusDate >= DATEADD(YEAR, -3, CONVERT(date, GETDATE()))

    ORDER BY M.CreatedDate DESC;

	END
	/* ======================================================
       ROLE ID 2: AGENCY VIEW
       ====================================================== */
    ELSE IF @RoleId = 2
    BEGIN
        ;WITH MSME_HISTORY AS
        (
            SELECT ZedId, CertificationType,
                MAX(CASE WHEN StatusType = 'Nc1Raised'     THEN CreatedOn END) AS Nc1Raised,
                MAX(CASE WHEN StatusType = 'Nc1Submitted'  THEN CreatedOn END) AS Nc1Submitted,
                MAX(CASE WHEN StatusType = 'Nc2Raised'     THEN CreatedOn END) AS Nc2Raised,
                MAX(CASE WHEN StatusType = 'Nc2Submitted'  THEN CreatedOn END) AS Nc2Submitted,
                MAX(CASE WHEN StatusType = 'Nc3Raised'     THEN CreatedOn END) AS Nc3Raised,
                MAX(CASE WHEN StatusType = 'Nc3Submitted'  THEN CreatedOn END) AS Nc3Submitted,
                MAX(CASE WHEN StatusType = 'Nc4Raised'     THEN CreatedOn END) AS Nc4Raised,
                MAX(CASE WHEN StatusType = 'Nc4Submitted'  THEN CreatedOn END) AS Nc4Submitted,
                MAX(CASE WHEN StatusType = 'Nc5Raised'     THEN CreatedOn END) AS Nc5Raised,
                MAX(CASE WHEN StatusType = 'Nc5Submitted'  THEN CreatedOn END) AS Nc5Submitted,
                MAX(CASE WHEN StatusType = 'NcClosed'      THEN CreatedOn END) AS NcClosed,
                MAX(CASE WHEN StatusType = 'Completed'     THEN CreatedOn END) AS CompletedOn
            FROM (
                SELECT ZedId, CertificationType, StatusType, FORMAT(CreatedDate, 'MMMM d, yyyy') AS CreatedOn
                FROM MsmeHistory WHERE StatusType IS NOT NULL
            ) H GROUP BY ZedId, CertificationType
        )
        SELECT 
            M.ZedId, M.CreatedDate AS RegistrationDate, B.lastestCertification AS CertificationLevel,
            DATEDIFF(DAY, '18991230', ZP.CertificationStatusDate) AS ZedCertifiedDate,
            DATEDIFF(DAY, ZP.CertificationStatusDate, GETDATE()) AS DaysSinceCertified,
            US.UserName AS DesktopAssessorName, 
            UK.UserName AS SiteAssessorName,
            CASE 
                WHEN (P.Certification = 'Bronze' AND P.CertificationStatus = 6) THEN 'Certified'
                WHEN (P.Certification = 'Silver' AND P.CertificationStatus = 16) THEN 'Silver Certified'
                WHEN (P.Certification = 'Gold' AND P.CertificationStatus = 16) THEN 'Gold Certified'
                WHEN P.CertificationStatus IN (7,99) THEN 'Rejected'
                WHEN P.CertificationStatus IN (8,9) THEN 'Surveillance Planned'
                WHEN P.CertificationStatus = 13 THEN 'Surveillance in progress'
                WHEN P.CertificationStatus = 14 THEN 'NC raised in Surveillance'
                WHEN P.CertificationStatus = 15 THEN 'Surveillance Completed'
                WHEN IsBronzePaymentDone = 1 OR IsSilverPaymentDone = 1 OR IsGoldPaymentDone = 1 THEN 'Payment Received'
                ELSE 'Payment Pending'
            END AS AssessmentStatus,
            DATEDIFF(DAY, '18991230', P.AssessmentDate) AS DateOfSurveillanceAssessment,
            H.*, M.PUnitName, 
            ISNULL(P.Certification, CASE WHEN IsBronzePaymentDone=1 THEN 'Bronze' WHEN IsSilverPaymentDone=1 THEN 'Silver' WHEN IsGoldPaymentDone=1 THEN 'Gold' END) AS Certification,
            M.OwnerName, M.EnterpriseTypee, M.MobileNo, M.EmailId, TwoDigitActivity,
            B.UdyogAadharNo, B.SocialCategoryName, B.Gender, B.PanNo, PAddress, PStateName, PDistrictName
        FROM Msme M
        INNER JOIN msmebasicinformation B ON B.ZedId = M.ZedId
        LEFT JOIN MsmeCertifications P ON P.ZedId = M.ZedId 
        LEFT JOIN ZEDCS_V2_LIVE.dbo.MsmeCertifications ZP ON ZP.ZedId = M.ZedId AND ZP.Certification = B.LastestCertification
        LEFT JOIN Users US ON P.DesktopAssessorId = US.UserId
        LEFT JOIN Users UK ON P.SiteAssessorId = UK.UserId
        LEFT JOIN MSME_HISTORY H ON H.ZedId = P.ZedId AND H.CertificationType = P.Certification
        WHERE (@State IS NULL OR M.StateId = @State)
          AND P.CertificationBodyUserId = @Userid -- Filter for the specific Agency
          AND (P.CertificationStatus IS NULL OR (NOT (P.CertificationStatus = 16 OR (P.CertificationStatus = 6 AND P.Certification = 'Bronze'))))
        ORDER BY M.MsmeId DESC;
    END



END
GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_SURAJ]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_SURAJ] --null, '<redacted>',10
(
    @UlbCode VARCHAR(100) = NULL,
    @Userid  VARCHAR(100) = NULL,
    @RoleId  VARCHAR(100) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    DECLARE @State VARCHAR(100) = NULL;

    IF @RoleId = 8
    BEGIN
        SELECT @State = StateCode FROM USERS WHERE UserId = @Userid AND RoleId = 8;
    END;

    /* STEP 1: PRE-PROCESS HISTORY */
    IF OBJECT_ID('tempdb..#MSME_HISTORY_PRE') IS NOT NULL DROP TABLE #MSME_HISTORY_PRE;

    SELECT
        ZedId,
        CertificationType,
        MAX(CASE WHEN StatusType = 'Nc1Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc1Raised,
        MAX(CASE WHEN StatusType = 'Nc1Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc1Submitted,
        MAX(CASE WHEN StatusType = 'Nc2Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc2Raised,
        MAX(CASE WHEN StatusType = 'Nc2Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc2Submitted,
        MAX(CASE WHEN StatusType = 'Nc3Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc3Raised,
        MAX(CASE WHEN StatusType = 'Nc3Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc3Submitted,
        MAX(CASE WHEN StatusType = 'Nc4Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc4Raised,
        MAX(CASE WHEN StatusType = 'Nc4Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc4Submitted,
        MAX(CASE WHEN StatusType = 'Nc5Raised'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc5Raised,
        MAX(CASE WHEN StatusType = 'Nc5Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc5Submitted,
        MAX(CASE WHEN StatusType = 'NcClosed'      THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS NcClosed,
        MAX(CASE WHEN StatusType = 'Completed'    THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS CompletedOn
    INTO #MSME_HISTORY_PRE
    FROM MsmeHistory
    WHERE StatusType IS NOT NULL
    GROUP BY ZedId, CertificationType;

    CREATE INDEX IX_Temp_History_Zed ON #MSME_HISTORY_PRE(ZedId, CertificationType);

    /* STEP 2: ROLE ID 10 (DASHBOARD) */
    IF @RoleId = 10
    BEGIN
        SELECT
            M.ZedId,
            M.CreatedDate AS RegistrationDate,
            --B.lastestCertification AS SurveillanceLevel, -- This is what is in your local DB
			LIVE_B.lastestCertification AS CurrentLiveLevel, -- This is the current level in ZED
			LIVE_B.SurvCertificationLevel AS ActiveSurvLevel, -- The level currently flagged for surveillance
            DATEDIFF(DAY, '18991230', B.ZedCertifiedDate) AS ZedCertifiedDate,
            DATEDIFF(DAY, B.ZedCertifiedDate, GETDATE()) AS DaysSinceCertified,
            CASE
                WHEN B.IsRejected = 1 THEN 'REJECTED'
				WHEN LIVE_C.CertificationPhase = 'Withdrawn' THEN 'Surveillance Withdrawn'
                WHEN P.CertificationStatus = 6 AND P.Certification = 'Bronze' THEN 'Certified'
                WHEN P.CertificationStatus = 16 AND P.Certification IN ('Silver','Gold') THEN P.Certification + ' Certified'
                WHEN P.CertificationStatus = 2 AND P.Certification = 'Bronze' THEN 'Allocated to Assessor'
                WHEN P.CertificationStatus = 3 AND P.Certification = 'Bronze' THEN 'Verification in progress'
                WHEN P.CertificationStatus = 4 AND P.Certification = 'Bronze' THEN 'NC Raised'
                WHEN P.CertificationStatus = 5 AND P.Certification = 'Bronze' THEN 'Quality Check'
                WHEN P.CertificationStatus IN (7,17) THEN 'Partially Rejected'
                WHEN P.CertificationStatus IN (8,9) THEN 'Surveillance Planned'
                WHEN P.CertificationStatus = 13 THEN 'Surveillance in progress'
                WHEN P.CertificationStatus = 14 THEN 'NC raised in Surveillance'
                WHEN P.CertificationStatus = 15 THEN 'Surveillance Completed'
                WHEN IsBronzePaymentDone = 1 OR IsSilverPaymentDone = 1 OR IsGoldPaymentDone = 1 THEN 'Payment Received'
                ELSE 'Payment Pending'
            END AS AssessmentStatus,
            -- Updated IsExpired Logic
            CASE 
                WHEN LIVE_B.Recertification > 1 THEN 'NO'
                WHEN B.ZedCertifiedDate <= DATEADD(YEAR, -3, GETDATE()) THEN 'YES' 
                ELSE 'NO' 
            END AS IsExpired,
            -- Surveillance Remarks
            CASE 
                WHEN B.IsRejected = 1 THEN 'Rejected'
                WHEN (B.lastestCertification != LIVE_B.lastestCertification and B.LastestCertification=LIVE_B.SurvCertificationLevel) THEN 'Ignore - Upgraded in Live'
                WHEN LIVE_B.Recertification > 1 THEN 'Recertified Unit' 
                WHEN B.ZedCertifiedDate <= DATEADD(YEAR, -3, GETDATE()) THEN 'Ignore - 3 Year Expired'
                ELSE 'Active'
            END AS SurveillanceRemarks,

            --DATEDIFF(DAY, '<redacted>', P.AssessmentDate) AS DateOfSurveillanceAssessment,
			CASE 
			WHEN P.Certification = 'Bronze' THEN DATEDIFF(DAY, '18991230', P.EvidenceSubmissionDate)
			WHEN P.Certification IN ('Silver', 'Gold') THEN DATEDIFF(DAY, '18991230', P.AssessmentDate)
			ELSE DATEDIFF(DAY, '18991230', ISNULL(P.AssessmentDate, P.EvidenceSubmissionDate)) 
			END AS DateOfSurveillanceAssessment,
            H.Nc1Raised, H.Nc1Submitted, H.Nc2Raised, H.Nc2Submitted,
            H.Nc3Raised, H.Nc3Submitted, H.Nc4Raised, H.Nc4Submitted,
            H.Nc5Raised, H.Nc5Submitted, H.NcClosed, H.CompletedOn,
            M.PUnitName, P.Certification, M.OwnerName, M.EnterpriseTypee,
            M.MobileNo, U.UserName AS AgencyName, P.DesktopAssessorId,
            P.SiteAssessorId, P.CoAssessorId, M.EmailId, TwoDigitActivity,
            B.UdyogAadharNo, B.SocialCategoryName, B.Gender, B.PanNo,
            PAddress, PStateName, PDistrictName,
			us.username as DesktopAssessor,
			p.DesktopAssessorId as  DesktopAssessorid,
			uk.Username as SiteAssessor,
			P.SiteAssessorId as SiteAssessor,
			--i.CreatedDate as AllocationDate,
		  DATEDIFF(DAY, '18991230', i.CreatedDate ) AS AllotmentDate

        FROM Msme M
        INNER JOIN msmebasicinformation B ON B.ZedId = M.ZedId
		left join MsmePaymentInfo i on (i.ZedId= b.ZedId)
        OUTER APPLY (
            SELECT TOP 1 * FROM MsmeCertifications PC
            WHERE PC.ZedId = M.ZedId
            ORDER BY PC.AssessmentDate DESC
        ) P
		
        inner JOIN ZEDCS_V2_LIVE.dbo.msmebasicinformation LIVE_B ON LIVE_B.ZedId = M.ZedId
		LEFT JOIN ZEDCS_V2_LIVE.dbo.MsmeCertifications LIVE_C 
       ON LIVE_C.ZedId = M.ZedId AND LIVE_C.Certification = P.Certification
        LEFT JOIN Users U ON P.CertificationBodyUserId = U.UserId

		LEFT JOIN Users US ON P.DesktopAssessorId = US.UserId
        LEFT JOIN Users UK ON P.SiteAssessorId = UK.UserId

        LEFT JOIN #MSME_HISTORY_PRE H ON H.ZedId = P.ZedId AND H.CertificationType = P.Certification
        WHERE (@State IS NULL OR M.StateId = @State)
		--and m.zedid in ('<redacted>','<redacted>','<redacted>','<redacted>')
		--AND (
  --    B.lastestCertification = LIVE_B.lastestCertification 
  --    OR 
  --    LIVE_B.SurvCertificationLevel = LIVE_B.lastestCertification
  --)
        ORDER BY M.CreatedDate DESC;
    END

    /* STEP 3: ROLE ID 2 (AGENCY VIEW) */
    ELSE IF @RoleId = 2
    BEGIN
        SELECT 
            M.ZedId, M.CreatedDate AS RegistrationDate, B.lastestCertification AS CertificationLevel,
            DATEDIFF(DAY, '18991230', B.ZedCertifiedDate) AS ZedCertifiedDate,
            DATEDIFF(DAY, B.ZedCertifiedDate, GETDATE()) AS DaysSinceCertified,
			DATEDIFF(DAY, '18991230', p.EvidenceSubmissionDate) AS EvidenceSubmissionDate,
		    US.UserName AS DesktopAssessor,p.DesktopAssessorId, UK.UserName AS SiteAssessor,P.SiteAssessorId,
            CASE 
                WHEN B.IsRejected = 1 THEN 'REJECTED'
				WHEN LIVE_C.CertificationPhase = 'Withdrawn' THEN 'Surveillance Withdrawn'
                WHEN P.CertificationStatus = 6 AND P.Certification = 'Bronze' THEN 'Certified'
				--Added new
				WHEN P.CertificationStatus  in (1) AND p.DesktopAccepted = 1   and p.CertificationStatus = 1 and  P.Certification in ('Bronze') THEN 'Shedule But not started'
				WHEN P.CertificationStatus  in (2) AND P.EvidenceSubmissionDate is not null and   P.Certification in ('Bronze') THEN 'Evidence Submitted'
				WHEN P.CertificationStatus  in (3) AND P.EvidenceSubmissionDate is not null and   P.Certification in ('Bronze') THEN 'DA Started'
				--when p.CertificationStatus in (2,3) and Certification = '<redacted>'  and DesktopAccepted = 1 Then '<redacted>'
				WHEN P.CertificationStatus = 4 AND P.Certification in ('Bronze') THEN 'NC Raised'
                WHEN P.CertificationStatus = 5 AND P.Certification in ('Bronze') THEN 'Quality Check'
				--
                WHEN (P.Certification IN ('Silver','Gold') AND P.CertificationStatus = 16) THEN P.Certification + ' Certified'
                WHEN P.CertificationStatus IN (7,17) THEN 'Rejected'
                WHEN P.CertificationStatus IN (8,9) THEN 'Surveillance Planned'
                WHEN P.CertificationStatus = 13 THEN 'Surveillance in progress'
                WHEN P.CertificationStatus = 14 THEN 'NC raised in Surveillance'
                WHEN P.CertificationStatus = 15 THEN 'Surveillance Completed'
                WHEN IsBronzePaymentDone = 1 OR IsSilverPaymentDone = 1 OR IsGoldPaymentDone = 1 THEN 'Payment Received'
                ELSE 'Payment Pending'
            END AS AssessmentStatus,
            -- Updated IsExpired Logic for Agencies
            CASE 
                WHEN LIVE_B.Recertification > 1 THEN 'NO'
                WHEN B.ZedCertifiedDate <= DATEADD(YEAR, -3, GETDATE()) THEN 'YES' 
                ELSE 'NO' 
            END AS IsExpired,
            --DATEDIFF(DAY, '<redacted>', P.AssessmentDate) AS DateOfSurveillanceAssessment,
			CASE 
			WHEN P.Certification = 'Bronze' THEN DATEDIFF(DAY, '18991230', P.EvidenceSubmissionDate)
			WHEN P.Certification IN ('Silver', 'Gold') THEN DATEDIFF(DAY, '18991230', P.AssessmentDate)
			ELSE DATEDIFF(DAY, '18991230', ISNULL(P.AssessmentDate, P.EvidenceSubmissionDate)) 
			END AS DateOfSurveillanceAssessment,
            H.Nc1Raised, H.Nc1Submitted, H.Nc2Raised, H.Nc2Submitted,
            H.Nc3Raised, H.Nc3Submitted, H.Nc4Raised, H.Nc4Submitted,
            H.Nc5Raised, H.Nc5Submitted, H.NcClosed, H.CompletedOn,
            M.PUnitName, 
            ISNULL(P.Certification, 
                CASE WHEN IsBronzePaymentDone=1 THEN 'Bronze' 
                     WHEN IsSilverPaymentDone=1 THEN 'Silver' 
                     WHEN IsGoldPaymentDone=1 THEN 'Gold' END) AS Certification,
            M.OwnerName, M.EnterpriseTypee, M.MobileNo, M.EmailId, TwoDigitActivity,
            B.UdyogAadharNo, B.SocialCategoryName, B.Gender, B.PanNo, 
            PAddress, PStateName, PDistrictName,		  DATEDIFF(DAY, '18991230', i.CreatedDate ) AS AllocationDate

        FROM Msme M
        INNER JOIN msmebasicinformation B ON B.ZedId = M.ZedId
	  inner join MsmePaymentInfo i on (i.ZedId= b.ZedId)

        LEFT JOIN MsmeCertifications P ON P.ZedId = M.ZedId 
        LEFT JOIN ZEDCS_V2_LIVE.dbo.msmebasicinformation LIVE_B ON LIVE_B.ZedId = M.ZedId
		LEFT JOIN ZEDCS_V2_LIVE.dbo.MsmeCertifications LIVE_C ON LIVE_C.ZedId = M.ZedId AND LIVE_C.Certification = P.Certification
        LEFT JOIN Users US ON P.DesktopAssessorId = US.UserId
        LEFT JOIN Users UK ON P.SiteAssessorId = UK.UserId
        LEFT JOIN #MSME_HISTORY_PRE H ON H.ZedId = P.ZedId AND H.CertificationType = P.Certification
        WHERE (@State IS NULL OR M.StateId = @State)
          AND P.CertificationBodyUserId = @Userid
          AND (P.CertificationStatus IS NULL OR (NOT (P.CertificationStatus = 16 OR (P.CertificationStatus = 6 AND P.Certification = 'Bronze'))))
          AND B.IsRejected = 0
          AND (B.ZedCertifiedDate > DATEADD(YEAR, -3, GETDATE()) OR LIVE_B.Recertification > 1)
          AND (
          B.lastestCertification = LIVE_B.lastestCertification 
          OR 
          LIVE_B.SurvCertificationLevel = LIVE_B.lastestCertification
      )
        ORDER BY M.MsmeId DESC;
    END

    IF OBJECT_ID('tempdb..#MSME_HISTORY_PRE') IS NOT NULL DROP TABLE #MSME_HISTORY_PRE;
END
GO
