/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_SURVEILLANCE_MSME]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_SURVEILLANCE_MSME] --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	SELECT 
		M.ZedId              AS [ZED ID],
		PunitName            AS [MSME NAME],
		PAddress             AS [ADDRESS OF MSME],
		PDistrictName        AS [DISTRICT OF MSME],
		PStateName           AS [STATE OF MSME],
		M.EnterPrisetype     AS [TYPE OF MSME],
		Gender               AS [GENDER],
		B.SocialCategoryName AS [MSME SOCIAL CATEGORY],
		C.Certification      AS [CERTIFICATION LEVEL],

		LatLongs.Latitude    AS [ZED LATITUDE],
		LatLongs.Longitude   AS [ZED LONGITUDE],

		M.EmailId            AS [EMAIL ID OF MSME],
		M.MobileNo           AS [PHONE NO OF MSME],
		CASE WHEN c.ZedId LIKE '%\_S\_%' ESCAPE '\' THEN '1st Surveillance'
            WHEN B.ReSurveillance = 2 THEN '2nd Surveillance'
			ELSE '1st Surveillance'
        END AS SurveillanceNo
	FROM Msme M
	INNER JOIN MsmebasicInformation B  ON M.ZedId = B.ZedId
	----INNER JOIN msmecertifications   C   ON M.ZedId = C.ZedId
	INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId OR M.ZedId = REPLACE(REPLACE(REPLACE(C.ZedId, '_S', ''), '_D', ''), CONCAT('_', C.Id), ''))

	-- get Latitude/Longitude from zedcs_v2_live.dbo.MsmePhotos
	OUTER APPLY (
		SELECT TOP 1 
			   Mp.Latitude ,
			   Mp.Longitude 
		FROM zedcs_v2_live.dbo.MsmePhotos Mp
		WHERE Mp.ZedId        = M.ZedId
		  AND Mp.Certification = C.Certification
		  AND Mp.PhotoType     = 'SiteExteriorPhotos'
		  AND (Mp.NcCount = 0 OR Mp.NcCount IS NULL)
	) AS LatLongs

	WHERE UdyogAadharNo NOT IN (
		'UDYAM-GJ-01-0013310',
		'UDYAM-MH-23-0006117',
		'UDYAM-UP-29-0003915',
		'UDYAM-UP-16-0001476'
	)

END
