/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_ZED_ASSESSORS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_ZED_ASSESSORS] 
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	SET NOCOUNT ON;

	select U.UserId AssessorId,U.UserName as AssessorName,MobileNo,Email, Address,Pincode, CreatedBy as AgencyId,WW.UserName as AgencyName,
case when IsActive=1 then 'Active' when IsActive=0 then 'Blocked' end as Status,case when States is null then 'All States' else States end as ApplicableStates,
NicSector,AreaOfKnowledge,case when DesktopVerification=1 then 'Yes' else 'No' end as DesktopVerification,case when SiteVerification=1 then 'Yes' else 'No' end as SiteVerification,
case when FinancialVerification=1 then 'Yes' else 'No' end as FinancialVerification,
isnull(AllocatedAsDA,0) AllocatedAsDA, isnull(AllotedAsLeadAssessor,0) AllotedAsLeadAssessor, isnull(AllocatedAsCoassessor,0) AllocatedAsCoassessor, isnull(AllocatedforRA,0) AllocatedforRA
from users U  
left join 
	(SELECT UserId, States=STUFF  
	(  
		(  
		  SELECT DISTINCT ', '+ CAST( e.States as VARCHAR(MAX))  
		  FROM Users G,AgencyUserStates E  
		  WHERE G.UserId=E.UserId and E.UserId=T1.UserId   
		  FOR XMl PATH('')  
		),1,1,''  
	)  
	FROM AgencyUserStates t1 
	GROUP BY UserId  ) X
	on (U.UserId=X.Userid)

left join 
	(SELECT UserId, NicSector=STUFF  
	(  
		(  
		  SELECT DISTINCT ', '+ CAST( e.NicSector as VARCHAR(MAX))  
		  FROM Users G,UserNicSectors E  
		  WHERE G.UserId=E.UserId and E.UserId=T1.UserId   
		  FOR XMl PATH('')  
		),1,1,''  
	)  
	FROM UserNicSectors t1 
	GROUP BY UserId  ) Y
	on (U.UserId=Y.UserId)

left join 
	(SELECT UserId, AreaOfKnowledge=STUFF  
	(  
		(  
			SELECT DISTINCT ', '+ CAST( e.AreaOfKnowledge as VARCHAR(MAX))  
			FROM Users G,UserAreaOfKnowledge E  
			WHERE G.UserId=E.UserId and E.UserId=T1.UserId   
			FOR XMl PATH('')  
		),1,1,''  
	)  
	FROM UserAreaOfKnowledge t1 
	GROUP BY UserId  ) Z
	on (U.UserId=Z.UserId)

left join 
(select DesktopAssessorId,count(*) AllocatedAsDA from MsmeCertifications where AcceptOrRejectDate is not null and ReasonForRejection is null group by DesktopAssessorId ) T
on (U.UserId=T.DesktopAssessorId)

left join 
(select SiteAssessorId,count(*) AllotedAsLeadAssessor from MsmeCertifications where ModeOfAssessment='Onsite Assessment'  group by SiteAssessorId  ) Uk
on (U.UserId=Uk.SiteAssessorId)

left join 
(select CoAssessorId,count(*) AllocatedAsCoassessor from MsmeCertifications where ModeOfAssessment='Onsite Assessment'  group by CoAssessorId  ) V
on (U.UserId=V.CoAssessorId)

left join 
(select SiteAssessorId,count(*) AllocatedforRA from MsmeCertifications where ModeOfAssessment='Remote Assessment'  group by SiteAssessorId  ) W
on (U.UserId=W.SiteAssessorId)

left join 
(select UserId,UserName from Users where RoleId=2  ) WW
on (U.CreatedBy=WW.UserId)

where roleid=3 order by Id
	
END

GO
