/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_SA_UNITS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_SA_UNITS] 
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT  ROW_NUMBER() OVER(ORDER BY SelfCertificationDate) [SNo]
	  
	  ,FORMAT(SelfCertificationDate, 'MMMM d, yyyy h:mm tt') [Date of Self Certification]
	  ,EstablishmentName as [Unit Name] 
	  ,[RegistrationNumber] [Hotel Cloud Registration Number]
	  ,S.[Acommodationtype] [Acommodation Type]
      ,[TotalRooms] [Total Rooms]
	  ,RestaurantType
	  ,Category
	  ,SelfCertificateNo CertificateNo
	  ,IsCertificateGenerated as [No. of Self Certification]
	  ,FORMAT(ResetDate, 'MMMM d, yyyy h:mm tt') [Reset Or Retake Date]
	  ,[EstablishmentAddress]
	  ,[EstablishmentCity]
	  ,[DistrictName]
      ,[StateName]
      ,[EstablishmentPinCode]
	  ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[RespondentName]
      ,[MobileNo]
      ,[EmailId]
	  ,CASE WHEN [AmountPaid] is NOT NULL then SaDate ELSE NULL END as [PrefferedSADate]
	  ,[CertificationBodyUserId]
	  ,[ModeOfAssessment]
	  ,[AssessorUserId]
	  ,[FinalSaDate]
	  ,[AcceptOrRejectDate]
	  ,[ReasonForRejection]		
	  ,[IsSaDeclarationAccepted]
	  ,[PaymentDate]	
	  ,[AmountPaid]
	  ,[GstNumber]
	  ,[UtrNumber]
	  ,CASE WHEN SaStatus=0 then 'Not Started' WHEN SaStatus=1 then 'In Progress'  WHEN SaStatus=2 then 'In Quality Check' WHEN SaStatus=3 then 'Completed' End as SaStatus	
	  ,[AgencyComments]
	  ,[SaCertificateNo]
	  ,[SaFinalSubmitDate]


	  --,REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + '<redacted>' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + '<redacted>' end + StateName),'<redacted>','') EstablishmentFullAddress
	FROM SelfAssessments S 
	WHERE IsCertificateGenerated>0 and RegistrationNumber not in ('UC23111823863','UC23111823861','UC13111923860','UC3250522285')
	ORDER BY SelfCertificationDate
END

GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_SECOND_SURVELLIANCE]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_SECOND_SURVELLIANCE] --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL
	--@StartDate Date='<redacted>', 
 --   @EndDate Date='<redacted>'

 		--@StartDate Date='<redacted>', 
	  --  @EndDate Date='<redacted>'
)
AS
BEGIN
	SET NOCOUNT ON;
    --DECLARE @RangeEnd Date = DATEADD(DAY, 1, @EndDate);

	IF @RoleId IN (10, 11)
	BEGIN
        
        -- 1. PRE-FETCH HISTORY DATES
        ;WITH History_CTE AS (
            SELECT zedid, CertificationType, MIN(CreatedDate) as DocDate
            FROM msmehistory 
            WHERE StatusType = 'BasicInfoStatus'
            GROUP BY zedid, CertificationType
        )

        -- 2. SELECT ONLY _R RECORDS
        SELECT M.ZedId, PUnitName, Paddress AS UnitAddress, PStateName, PDistrictName, Ppin AS Pincode, 
               M.EnterpriseTypee AS EnterpriseType, C.Certification, 
               -- Logic: If it'<redacted>'s a Recertification unit. 
               -- We still show '<redacted>' or '<redacted>' based on the status.
               CASE 
                    WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 6) THEN 'Certified'
                    WHEN (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16) THEN 'Certified'
                    ELSE 'Active' 
               END AS ZedIdStatus, 
               P.Total AS CertificationFee, ApplicantContributionAfterSubsidy, T.Amount AS AmountPaid, 
               (P.Total - ApplicantContributionAfterSubsidy) AS FinancialSupport,
               CASE WHEN P.UnitGstin = 'Yes' THEN T.Gstin WHEN P.UnitGstin = 'No' THEN NULL ELSE P.UnitGstin END AS UnitGstin,
               T.TanNumber, T.Tds, P.UseCoupon AS JoiningReward, SubsidyPercentage, Gender, SocialCategoryName, B.PanNo,
               DATEDIFF(DAY, '18991230', M.CreatedDate) AS RegdDate,
               DATEDIFF(DAY, '18991230', P.CreatedDate) AS PaymentDate,
               DATEDIFF(DAY, '18991230', CASE WHEN C.CertificationStatus IN (6, 16) THEN C.CertificationStatusDate ELSE NULL END) AS [Certified/RejectedDate],
               DATEDIFF(DAY, '18991230', H.DocDate) AS DocumentUploadDate,
               NULL AS ApproverDateOfReceiptOfPayment
        FROM msme M 
        INNER JOIN MsmeCertifications C ON M.ZedId = REPLACE(REPLACE(C.Zedid, '_S',''), '_'+CAST(C.Id AS VARCHAR), '')
        INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
        INNER JOIN MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
        LEFT JOIN History_CTE H ON C.ZedId = H.zedid AND C.Certification = H.CertificationType
        LEFT JOIN PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND T.PaymentStatus = 'Success'
        WHERE
		--P.CreatedDate >= @StartDate AND P.CreatedDate < @RangeEnd
           C.ZedId LIKE '%\_S%' ESCAPE '\'  -- Filters specifically for IDs containing _S
		  -- b.ReSurveillance >1
          AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
        ORDER BY M.ZedId

	END
	ELSE
	BEGIN
		SELECT NULL AS DATAS
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_ZED_BASIC_INFO]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
