CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_ZED_BASIC_INFO] 
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	SET NOCOUNT ON;

		select M.ZedId,M.PUnitName,PStateName,PDistrictName,M.OwnerName,M.EnterpriseName,M.MobileNo,M.EmailId,PAddress,TwoDigitActivity,SocialCategoryName,Gender,
		C.Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,R.RawMaterialName,R.Percentage,R.CountryName,
		OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,
		CertificationBodyUserId,U.UserName as AgencyName, DesktopAssessorId,UD.UserName as DesktopAssessor, 
		SiteAssessorId,US.UserName as SiteasessorName, CoAssessorId,
		SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,
		SR.RawMaterialName,SR.Percentage,SR.CountryName,
		SaOutsourcedProcesses,SaEnergySources,
		ManufacturingCapacityUnits,ManufacturingCapacityValue,MonthlyUtilizationUnits,MonthlyUtilizationValue,
		SaManufacturingCapacityUnits,SaManufacturingCapacityValue, SaMonthlyUtilizationUnits,SaMonthlyUtilizationValue
		from msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=C.ZedId)
		inner join Users U on (U.UserId=C.CertificationBodyUserId)
		inner join Users UD on (UD.UserId=C.DesktopAssessorId)
		inner join Users US on (US.UserId=C.SiteAssessorId)
		left join MsmeRawMaterials R on (C.ZedId=R.ZedId and C.Certification=R.Certification)
		left join SaRawMaterials SR on (C.ZedId=SR.ZedId and C.Certification=SR.Certification)
		where CertificationStatus in (6,16) order by ZedId,CertificationStatusDate
	
END

GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_ZED_SURVEILLANCE_MASTER_REPORT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_ZED_SURVEILLANCE_MASTER_REPORT]  --null,'<redacted>',10
(
    @UlbCode VARCHAR(100) = NULL,
    @Userid  VARCHAR(100) = NULL,
    @RoleId  VARCHAR(100) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

    /* =========================================================================
       STEP 1: PRE-PROCESS HISTORY DATES INTO TEMP TABLE (FOR PERFORMANCE)
       ========================================================================= */
    IF OBJECT_ID('tempdb..#MSME_HISTORY_PRE') IS NOT NULL DROP TABLE #MSME_HISTORY_PRE;

    SELECT 
        ZedId, 
        CertificationType,
        MAX(CASE WHEN StatusType = 'Nc1Raised'    THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc1Raised,
        MAX(CASE WHEN StatusType = 'Nc1Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc1Submitted,
        MAX(CASE WHEN StatusType = 'Nc2Raised'    THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc2Raised,
        MAX(CASE WHEN StatusType = 'Nc2Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc2Submitted,
        MAX(CASE WHEN StatusType = 'Nc3Raised'    THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc3Raised,
        MAX(CASE WHEN StatusType = 'Nc3Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc3Submitted,
        MAX(CASE WHEN StatusType = 'Nc4Raised'    THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc4Raised,
        MAX(CASE WHEN StatusType = 'Nc4Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc4Submitted,
        MAX(CASE WHEN StatusType = 'Nc5Raised'    THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc5Raised,
        MAX(CASE WHEN StatusType = 'Nc5Submitted' THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS Nc5Submitted,
        MAX(CASE WHEN StatusType = 'NcClosed'     THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS NcClosed,
        MAX(CASE WHEN StatusType = 'Completed'    THEN CONVERT(VARCHAR, CreatedDate, 107) END) AS CompletedOn
    INTO #MSME_HISTORY_PRE
    FROM MsmeHistory
    WHERE StatusType IS NOT NULL
    GROUP BY ZedId, CertificationType;

    -- Index for lightning-fast joins
    CREATE INDEX IX_Temp_History_Zed ON #MSME_HISTORY_PRE(ZedId, CertificationType);


    /* =========================================================================
       STEP 2: MAIN REPORT QUERY (Approved, Rejected, Partial & Inprogress)
       ========================================================================= */
    IF @RoleId = 10
    BEGIN
        SELECT 
             M.zedid AS [ZEDID],
             M.punitname AS [Unit Name],
             M.Paddress AS [Paddress],
             B.UdyogAadharNo AS [Udyamno],
             M.PStateName AS [Pstate],
             M.PDistrictName AS [PDistrictName],
             C.certification AS [Certification level],

             CASE 
                WHEN (C.Certification = 'Bronze' AND C.PreviousCertificationStatus IN (1, 2, 3) AND C.CertificationStatus=99) 
                  OR (C.Certification IN ('Silver', 'Gold') AND C.PreviousCertificationStatus IN (8, 9, 13)  AND C.CertificationStatus=99) 
                THEN '' 
                ELSE u.username 
             END as [Agency Name],

             DATEDIFF(DAY, '18991230', P.createddate) AS [Surveillance Assessment Allottment Date],

             CASE 
                WHEN C.Certification = 'Bronze' THEN DATEDIFF(DAY, '18991230', C.EvidenceSubmissionDate)
                WHEN C.Certification IN ('Silver', 'Gold') THEN DATEDIFF(DAY, '18991230', C.AssessmentDate)
                ELSE DATEDIFF(DAY, '18991230', ISNULL(C.AssessmentDate, C.EvidenceSubmissionDate)) 
             END AS [Surveillance Conducted Date (assessment date)],
             
             DATEDIFF(DAY, '18991230', C.CertificationStatusDate) AS [Surveillance Compltion/Rejection Date],

             -- COMPREHENSIVE STATUS MAPPING (Covers Approved, Rejected, Partial, NC & Inprogress)
             CASE
                WHEN C.CertificationStatus = 99 
                THEN 'Rejected'

                WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 6)
                  OR (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16) 
                THEN 'Certified'

                WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 7) 
                  OR (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 17) 
                THEN 'PartialRejection'

                WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 4) 
                  OR (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 14) 
                THEN 'Non Conformance'

                WHEN C.CertificationStatus = 1 THEN 'Scheduled But Not Started'
                WHEN C.CertificationStatus = 2 THEN 'Evidence Submitted'
                WHEN C.CertificationStatus = 3 THEN 'Verification in progress'
                WHEN C.CertificationStatus IN (8, 9) THEN 'Surveillance Planned'
                WHEN C.CertificationStatus = 13 THEN 'Surveillance in progress'
                WHEN C.CertificationStatus = 15 THEN 'Surveillance Completed'
                
                ELSE 'Inprogress'
             END as [ZedidStatus],

             CASE 
                WHEN P.ZedId LIKE '%\_S\_%' ESCAPE '\' THEN '1st Surveillance'
                WHEN B.ReSurveillance = 2 THEN '2nd Surveillance'
                ELSE '1st Surveillance'
             END AS SurveillanceNo,

             -- MSME HISTORY DATES INCLUDED
             H.Nc1Raised, 
             H.Nc1Submitted, 
             H.Nc2Raised, 
             H.Nc2Submitted,
             H.Nc3Raised, 
             H.Nc3Submitted, 
             H.Nc4Raised, 
             H.Nc4Submitted,
             H.Nc5Raised, 
             H.Nc5Submitted, 
             H.NcClosed, 
             H.CompletedOn

        FROM ZED_SURVEILLANCE.DBO.msme M
        LEFT JOIN ZED_SURVEILLANCE.DBO.MsmeCertifications C 
            ON (M.ZedId = REPLACE(REPLACE(REPLACE(C.ZedId, CONCAT('_D_', C.Id), ''), CONCAT('_S_', C.Id), ''), '_D',''))
        LEFT JOIN users u 
            ON (u.userid = c.certificationbodyuserid)
        INNER JOIN ZED_SURVEILLANCE.DBO.MsmeBasicInformation B 
            ON M.ZedId = B.ZedId
        LEFT JOIN ZED_SURVEILLANCE.DBO.MsmePaymentInfo P 
            ON C.ZedId = P.ZedId AND C.Certification = P.Certification
        LEFT JOIN ZED_SURVEILLANCE.DBO.PaymentGateWayTransactions T 
            ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND T.PaymentStatus = 'Success'
        
        -- CLEAN HISTORY JOIN (Linked directly to Base MSME M.ZedId)
        LEFT JOIN #MSME_HISTORY_PRE H 
            ON H.ZedId = M.ZedId AND H.CertificationType = C.Certification

        -- REMOVED LIVE DB FILTERS TO AVOID CONFUSION
        -- (Optional: You can filter out test Udyog Aadhar numbers here if needed)
        WHERE (B.UdyogAadharNo IS NULL OR B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476'));
    END

    /* =========================================================================
       STEP 3: CLEANUP TEMP TABLES
       ========================================================================= */
    IF OBJECT_ID('tempdb..#MSME_HISTORY_PRE') IS NOT NULL DROP TABLE #MSME_HISTORY_PRE;

END
GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_ZED_SURVEILLANCE_REPORT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
