CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_ZED_SURVEILLANCE_REPORT] --null,'<redacted>',10
(
    @UlbCode VARCHAR(100) = NULL,
    @Userid  VARCHAR(100) = NULL,
    @RoleId  VARCHAR(100) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

	IF @RoleId = 10
    BEGIN

    select

     M.zedid as [ZEDID],
     m.punitname as [Unit Name],
     m.Paddress as [Paddress],
     b.UdyogAadharNo as [Udyamno],
     m.PStateName as [Pstate],
     m.PDistrictName as [PDistrictName],
     c.certification as [Certification level],

	 CASE 
                WHEN (C.Certification = 'Bronze' AND C.PreviousCertificationStatus IN (1, 2, 3) AND C.CertificationStatus=99) 
                  OR (C.Certification IN ('Silver', 'Gold') AND C.PreviousCertificationStatus IN (8, 9, 13)  AND C.CertificationStatus=99) 
                THEN '' 
                ELSE u.username 
            END as [Agency Name],

 
     DATEDIFF(DAY, '18991230', p.createddate) AS [Surveillance Assessment Allottment Date],

     CASE 
                WHEN c.Certification = 'Bronze' THEN DATEDIFF(DAY, '18991230', c.EvidenceSubmissionDate)
                WHEN c.Certification IN ('Silver', 'Gold') THEN DATEDIFF(DAY, '18991230', c.AssessmentDate)
                ELSE DATEDIFF(DAY, '18991230', ISNULL(c.AssessmentDate, c.EvidenceSubmissionDate)) 
     END AS [Surveillance Conducted Date (assessment date)],
     
                DATEDIFF(DAY, '18991230', c.CertificationStatusDate) AS [Surveillance Compltion/Rejection Date],

    CASE
        WHEN C.Certification IN ('Bronze', 'Silver', 'Gold')
             AND C.CertificationStatus = 99
        THEN 'Rejected'

        WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 6)
          OR (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 16)
        THEN 'Certified'

		WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 7) 
          OR (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 17) 
        THEN 'PartialRejection'

        -- Updated Non Conformance Logic
        WHEN (C.Certification = 'Bronze' AND C.CertificationStatus = 4) 
          OR (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus = 14) 
        THEN 'Non Conformance'

        ELSE 'Inprogress'
    END as [ZedidStatus],

     CASE WHEN P.ZedId LIKE '%\_S\_%' ESCAPE '\' THEN '1st Surveillance'
          WHEN B.ReSurveillance = 2 THEN '2nd Surveillance'
          ELSE '1st Surveillance'
          END AS SurveillanceNo

		 -- CASE
   --             WHEN (C.Certification = '<redacted>' AND C.PreviousCertificationStatus IN (1, 2,3)) 
   --               OR (C.Certification IN ('<redacted>', '<redacted>') AND C.PreviousCertificationStatus IN (8, 9, 13)) 
   --             THEN '<redacted>'
   --             ELSE '<redacted>'
   --         END AS [Eligibility For Agency Claim Status],
			--PreviousCertificationStatus
		  

     
     
    FROM ZED_SURVEILLANCE.DBO.msme M
    inner join ZED_SURVEILLANCE.DBO.MsmeCertifications C ON (M.ZedId = REPLACE(REPLACE(REPLACE(C.ZedId, CONCAT('_D_', C.Id), ''), CONCAT('_S_', C.Id), ''), '_D',''))
    left join users u on (u.userid = c.certificationbodyuserid)
    INNER JOIN ZED_SURVEILLANCE.DBO.MsmeBasicInformation B ON M.ZedId = B.ZedId
    INNER JOIN ZED_SURVEILLANCE.DBO.MsmePaymentInfo P ON C.ZedId = P.ZedId AND C.Certification = P.Certification
    LEFT JOIN ZED_SURVEILLANCE.DBO.PaymentGateWayTransactions T ON P.ZedId = T.ZedId AND P.Certification = T.Certification AND P.PaymentRefId = T.PaymentRefId AND T.PaymentStatus = 'Success'

    --WHERE c.CertificationBodyUserId is not null;

    WHERE

        (
		(C.Certification = 'Bronze' AND C.CertificationStatus in (6,7,99))
        OR
        (C.Certification IN ('Silver', 'Gold') AND C.CertificationStatus in (16,17,99))
		)
		AND NOT (
                (C.Certification = 'Bronze' AND C.PreviousCertificationStatus IN (1, 2, 3) AND C.CertificationStatus = 99)
                OR 
                (C.Certification IN ('Silver', 'Gold') AND C.PreviousCertificationStatus IN (8, 9, 13) AND C.CertificationStatus = 99)
            )
	END


END
GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_ZEDID_STATUS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
