-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_ZEDID_STATUS]  --NULL,'<redacted>',8
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	
			select C.ZedId,M.PUnitName UnitName,B.UdyogAadharNo,m.PAddress Address,
			BasicInfoStatus DocsubmissionDate,DocVerifiAllot,
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			CompletedOn
			 from MsmeCertifications C
			INNER join Msme M on (M.ZedId=C.Zedid)
			INNER join MsmeBasicInformation B on (B.ZedId=C.Zedid)
			left join
			(select ZedId,CertificationType,
			ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
			case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then 'In-progress' else [DesktopVerification] end as [DesktopVerification],
			case when  [BasicInfoStatus] is not null  then 'In-progress' else NULL end as [BronzeDesktopVerification],DocVerifiAllot,
			[ScheduledOn],
			Completed as [CompletedOn],
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			[GetCertified],
			[ApplicationReceived],
			[NcFinalClosureDate]			
			from 
			(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType from MsmeHistory where StatusType is not null) A
			pivot (
			max(CreatedOn) for StatusType in (
			[BasicInfoStatus],
			[DesktopVerification],
			[ScheduledOn],
			DocVerifiAllot,
			[Completed],
			[Nc1Raised],
			[Nc1Submitted],
			[Nc2Raised],
			[Nc2Submitted],
			[Nc3Raised],
			[Nc3Submitted],
			[Nc4Raised],
			[Nc4Submitted],
			[Nc5Raised],
			[Nc5Submitted],
			[NcClosed],
			[GetCertified],
			[ApplicationReceived],
			[NcFinalClosureDate]) ) as Pvt
		) PVD
		on (C.ZedId=PVD.ZedId and C.Certification=PVD.CertificationType ) 
		where c.CertificationStatus!=99
		order by m.CreatedDate



		--select * from MsmeHistory where zedid='<redacted>' order by id

END


