/****** Object:  StoredProcedure [dbo].[SP_EXTEND_NC_CLOSURE_DATE]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_EXTEND_NC_CLOSURE_DATE] 
(
	 @ZedId varchar(50)=NULL
	,@CertificationType varchar(50)
	,@NoOfDays int =NULL
	,@UserId varchar(200) = NULL
	,@RoleId int = NULL
	
)
AS
BEGIN

	IF @NoOfDays>0 AND @NoOfDays IS NOT NULL 
	BEGIN
     
		 Declare @HistoryDate datetime = NULL

		

		UPDATE MsmeCertifications set NcFinalClosureDt = DATEADD(DAY, @NoOfDays, NcFinalClosureDt) where ZedId=@ZedId and Certification=@CertificationType and NcFinalClosureDt is not null
		select @HistoryDate=NcFinalClosureDt from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType

		insert into NcClosureDateHistory (ZedId,Certification,NoOfDays,FnNcCloseDt)
		values (@ZedId,@CertificationType,@NoOfDays,@HistoryDate)

		UPDATE MsmeHistory set Descrip=concat('Final Closure Date: ',FORMAT(@HistoryDate, 'MMMM d, yyyy')) where ZedId=@ZedId and CertificationType=@CertificationType and  StatusType='NcFinalClosureDate'

	END

	
END



