CREATE PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_GET_CURRENT_CERTIFICATE] --'<redacted>'
(
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Gold' AND CertificationStatus=16 )
	BEGIN
		select 'Gold' CertificationType
	END
	ELSE
	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Silver' AND CertificationStatus=16 )
	BEGIN
		select 'Silver' CertificationType
	END
	ELSE
	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Bronze' AND CertificationStatus=6 )
	BEGIN
		select 'Bronze' CertificationType 
	END
	
END
