BEGIN
	
	SET NOCOUNT ON;

	SELECT * FROM FinancialAssistance WHERE ZedId=@ZedId AND CertificationType='Bronze' AND VerificationStatus<=6 AND VerificationStatus!=5 order by id desc
	SELECT * FROM FinancialAssistance WHERE ZedId=@ZedId AND CertificationType='Silver' AND VerificationStatus<=6 AND VerificationStatus!=5order by id desc
	SELECT * FROM FinancialAssistance WHERE ZedId=@ZedId AND CertificationType='Gold' AND VerificationStatus<=6  AND VerificationStatus!=5order by id desc
	SELECT P.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) WHERE P.ZedId=@ZedId AND P.CertificationType='Bronze' AND F.VerificationStatus<=6
	SELECT P.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) WHERE P.ZedId=@ZedId AND P.CertificationType='Silver' AND F.VerificationStatus<=6
	SELECT P.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) WHERE P.ZedId=@ZedId AND P.CertificationType='Gold' AND F.VerificationStatus<=6
	SELECT C.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) inner join FinancialAssistanceScreenshotPhotos C on (P.Id=C.PhotoId) WHERE P.ZedId=@ZedId AND P.CertificationType='Bronze' AND F.VerificationStatus<=6
	SELECT C.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) inner join FinancialAssistanceScreenshotPhotos C on (P.Id=C.PhotoId) WHERE P.ZedId=@ZedId AND P.CertificationType='Silver' AND F.VerificationStatus<=6
	SELECT C.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) inner join FinancialAssistanceScreenshotPhotos C on (P.Id=C.PhotoId) WHERE P.ZedId=@ZedId AND P.CertificationType='Gold' AND F.VerificationStatus<=6

	--SELECT * FROM FinancialAssistance WHERE ZedId=@ZedId AND CertificationType='<redacted>' AND VerificationStatus<5
	--SELECT * FROM FinancialAssistance WHERE ZedId=@ZedId AND CertificationType='<redacted>' AND VerificationStatus<5
	--SELECT * FROM FinancialAssistance WHERE ZedId=@ZedId AND CertificationType='<redacted>' AND VerificationStatus<5 
	--SELECT P.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) WHERE P.ZedId=@ZedId AND P.CertificationType='<redacted>' AND F.VerificationStatus<5
	--SELECT P.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) WHERE P.ZedId=@ZedId AND P.CertificationType='<redacted>' AND F.VerificationStatus<5
	--SELECT P.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) WHERE P.ZedId=@ZedId AND P.CertificationType='<redacted>' AND F.VerificationStatus<5
	--SELECT C.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) inner join FinancialAssistanceScreenshotPhotos C on (P.Id=C.PhotoId) WHERE P.ZedId=@ZedId AND P.CertificationType='<redacted>' AND F.VerificationStatus<5
	--SELECT C.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) inner join FinancialAssistanceScreenshotPhotos C on (P.Id=C.PhotoId) WHERE P.ZedId=@ZedId AND P.CertificationType='<redacted>' AND F.VerificationStatus<5
	--SELECT C.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) inner join FinancialAssistanceScreenshotPhotos C on (P.Id=C.PhotoId) WHERE P.ZedId=@ZedId AND P.CertificationType='<redacted>' AND F.VerificationStatus<5


