/****** Object:  StoredProcedure [dbo].[SP_FINANCIAL_ASSISTANCE_GET_LIST]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
-- [SP_FINANCIAL_ASSISTANCE_GET_LIST] '<redacted>', '<redacted>','<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_GET_LIST]
(
	@UserId varchar(50) = NULL,
	@Status int =null,
	@CertificationType varchar(50) = NULL,
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @RoleId INT 
	SELECT @RoleId=ROLEID FROM USERS WHERE USERID=@UserId

	IF @RoleId=7
	BEGIN

		IF @Status=4
		BEGIN
			SELECT P.Id, M.ZedId, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, PCity, PStateName, PDistrictName, PPin, EnterpriseName, 
				U.UserName CertificationBodyName, CertificationBodyUserId, P.ReasonForRejection, FinancialAssessorId,NULL VerificationDate,UA.UserName FaAssessorName, P.CertificationType, UamNumber, @RoleId RoleId
			FROM FinancialAssistance P
			left join Msme M on (P.ZedId=M.ZedId)
			LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
			LEFT JOIN Users UA on (P.FinancialAssessorId=UA.UserId)
			WHERE VerificationStatus IN (4,6)
			ORDER By Id desc
		END
		ELSE
		BEGIN
			SELECT P.Id, M.ZedId, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, PCity, PStateName, PDistrictName, PPin, EnterpriseName, 
				U.UserName CertificationBodyName, CertificationBodyUserId, P.ReasonForRejection, FinancialAssessorId,NULL VerificationDate,UA.UserName FaAssessorName, P.CertificationType, UamNumber, @RoleId RoleId
			FROM FinancialAssistance P
			left join Msme M on (P.ZedId=M.ZedId)
			LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
			LEFT JOIN Users UA on (P.FinancialAssessorId=UA.UserId)
			WHERE VerificationStatus=@Status 
			ORDER By Id desc
		END
		

		SELECT ISNULL([1],0) New, ISNULL([2],0) InProgress, ISNULL([3],0) Qc, ISNULL([4],0)+ISNULL([6],0) Approved, ISNULL([5],0) Rejected FROM 
		(SELECT VerificationStatus, Count(*) Cnt FROM FinancialAssistance GROUP BY VerificationStatus) src
		PIVOT
		(max(cnt) for VerificationStatus in ([1],[2],[3],[4],[5],[6])) pvt
	END

	IF @RoleId=2
	BEGIN

		IF @Status=4
		BEGIN
			SELECT P.Id, M.ZedId, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, PCity, PStateName, PDistrictName, PPin, EnterpriseName, 
				U.UserName CertificationBodyName, CertificationBodyUserId, P.ReasonForRejection, FinancialAssessorId,NULL VerificationDate, UA.UserName FaAssessorName, P.CertificationType, UamNumber, @RoleId RoleId
			FROM FinancialAssistance P
			left join Msme M on (P.ZedId=M.ZedId)
			LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
			LEFT JOIN Users UA on (P.FinancialAssessorId=UA.UserId)
			WHERE VerificationStatus IN (4,6) AND CertificationBodyUserId=@UserId 
			ORDER By Id desc
		END
		ELSE
		BEGIN
			SELECT P.Id, M.ZedId, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, PCity, PStateName, PDistrictName, PPin, EnterpriseName, 
				U.UserName CertificationBodyName, CertificationBodyUserId, P.ReasonForRejection, FinancialAssessorId,NULL VerificationDate, UA.UserName FaAssessorName, P.CertificationType, UamNumber, @RoleId RoleId
			FROM FinancialAssistance P
			left join Msme M on (P.ZedId=M.ZedId)
			LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
			LEFT JOIN Users UA on (P.FinancialAssessorId=UA.UserId)
			WHERE VerificationStatus=@Status AND CertificationBodyUserId=@UserId AND ((p.ReasonForRejection is NULL and VerificationStatus<5) OR (p.ReasonForRejection is NOT NULL and VerificationStatus=5))
			ORDER By Id desc
		END
		--SELECT ISNULL([1],0) New, ISNULL([2],0) InProgress, ISNULL([3],0) Qc, ISNULL([4],0)+ISNULL([6],0) Approved, ISNULL([5],0) Rejected FROM 
		--(SELECT VerificationStatus, Count(*) Cnt FROM FinancialAssistance where CertificationBodyUserId=@UserId and ((ReasonForRejection is NULL and VerificationStatus<5) OR (ReasonForRejection is NOT NULL and VerificationStatus=5)) GROUP BY VerificationStatus) src
		--PIVOT
		--(max(cnt) for VerificationStatus in ([1],[2],[3],[4],[5],[6])) pvt

		SELECT ISNULL([1],0) New, ISNULL([2],0) InProgress, ISNULL([3],0) Qc, ISNULL([4],0)+ISNULL([6],0) Approved, ISNULL([5],0) Rejected FROM 
		(SELECT VerificationStatus, Count(*) Cnt FROM FinancialAssistance where CertificationBodyUserId=@UserId  GROUP BY VerificationStatus) src
		PIVOT
		(max(cnt) for VerificationStatus in ([1],[2],[3],[4],[5],[6])) pvt
	END


	IF @RoleId=3
	BEGIN
		SELECT P.Id, M.ZedId, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, PCity, PStateName, PDistrictName, PPin, EnterpriseName, 
			U.UserName CertificationBodyName, CertificationBodyUserId, P.ReasonForRejection, FinancialAssessorId,NULL VerificationDate, P.CertificationType, UamNumber, @RoleId RoleId,
			UA.UserName as FinAssessorName,FinancialAssessorId
		FROM FinancialAssistance P
		left join Msme M on (P.ZedId=M.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.FinancialAssessorId=UA.UserId)
		WHERE VerificationStatus=@Status AND FinancialAssessorId=@UserId
		ORDER By Id desc
		
		SELECT ISNULL([1],0) New, ISNULL([2],0) InProgress, ISNULL([3],0) Qc, ISNULL([4],0) Approved, ISNULL([5],0) Rejected FROM 
		(SELECT VerificationStatus, Count(*) Cnt FROM FinancialAssistance where FinancialAssessorId=@UserId GROUP BY VerificationStatus) src
		PIVOT
		(max(cnt) for VerificationStatus in ([1],[2],[3],[4],[5])) pvt
	END



	--SELECT P.Id, M.ZedId, CONCAT(PAddress, '<redacted>', PDistrictName, '<redacted>', PStateName, '<redacted>', PPin) UnitAddress, PCity, PStateName, PDistrictName, PPin, EnterpriseName, 
	--	U.UserName CertificationBodyName, CertificationBodyUserId, ReasonForRejection, FinancialAssessorId,NULL VerificationDate, P.CertificationType, UamNumber, @RoleId RoleId
	--FROM FinancialAssistance P
	--left join Msme M on (P.ZedId=M.ZedId)
	--LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
	--WHERE VerificationStatus=@Status AND (@RoleId!=2 OR CertificationBodyUserId=@UserId) AND (@RoleId!=3 OR FinancialAssessorId=@UserId)
	--ORDER By Id desc
		

	--SELECT ISNULL([1],0) New, ISNULL([2],0) InProgress, ISNULL([3],0) Qc, ISNULL([4],0) Approved, ISNULL([5],0) Rejected FROM 
	--(SELECT VerificationStatus, Count(*) Cnt FROM FinancialAssistance GROUP BY VerificationStatus) src
	--PIVOT
	--(max(cnt) for VerificationStatus in ([1],[2],[3],[4],[5])) pvt

END







