/****** Object:  StoredProcedure [dbo].[SP_GET_INCENTIVES]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_INCENTIVES] --'', '<redacted>'
(
	@State varchar(100) = NULL,
	@CertificationType  varchar(100) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @State=''
		SET @State=NULL

	IF @CertificationType='Bronze'
	BEGIN
		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2
		FROM Incentives WHERE IncentiveType='Common' AND ApplicableForBronze = 1 AND ActiveStatus=1  ORDER By OrderNo

		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2  FROM Incentives WHERE IncentiveType in (SELECT StateName FROM States WHERE StateCode=ISNULL(@State,StateCode)) AND ApplicableForBronze = 1 AND ActiveStatus=1 ORDER By OrderNo

		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2 FROM Incentives WHERE IncentiveType='Other' AND ApplicableForBronze = 1 AND ActiveStatus=1 ORDER By OrderNo

		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2 FROM Incentives WHERE IncentiveType='Financial' AND ApplicableForBronze = 1 AND ActiveStatus=1 ORDER By OrderNo

		select distinct MinistryOrDepartment from Incentives where IncentiveType='Financial' and ApplicableForBronze=1 AND ActiveStatus=1 order by MinistryOrDepartment
	END

	ELSE IF @CertificationType='Silver'
	BEGIN
		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2  FROM Incentives WHERE IncentiveType='Common' AND ApplicableForSilver = 1 AND ActiveStatus=1  ORDER By OrderNo

		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2  FROM Incentives WHERE IncentiveType in (SELECT StateName FROM States WHERE StateCode=ISNULL(@State,StateCode)) AND ApplicableForSilver = 1 AND ActiveStatus=1 ORDER By OrderNo

		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2 FROM Incentives WHERE IncentiveType='Other' AND ApplicableForSilver = 1 AND ActiveStatus=1 ORDER By OrderNo

		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2 FROM Incentives WHERE IncentiveType='Financial' AND ApplicableForSilver = 1 AND ActiveStatus=1 ORDER By OrderNo

		select distinct MinistryOrDepartment from Incentives where IncentiveType='Financial' and ApplicableForSilver=1 AND ActiveStatus=1 order by MinistryOrDepartment
	END

	ELSE IF @CertificationType='Gold'
	BEGIN
		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2  FROM Incentives WHERE IncentiveType='Common' AND ApplicableForGold = 1 AND ActiveStatus=1 ORDER By OrderNo

		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2  FROM Incentives WHERE IncentiveType in (SELECT StateName FROM States WHERE StateCode=ISNULL(@State,StateCode)) AND ApplicableForGold = 1 AND ActiveStatus=1 ORDER By OrderNo

		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2 FROM Incentives WHERE IncentiveType='Other' AND ApplicableForGold = 1 AND ActiveStatus=1 ORDER By OrderNo

		select *, null ApplicableFor, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File1.pdf') as FilePath1, concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE\Uploads\Incentives/',Id, 'File2.pdf') as FilePath2 FROM Incentives WHERE IncentiveType='Financial' AND ApplicableForGold = 1 AND ActiveStatus=1 ORDER By OrderNo

		select distinct MinistryOrDepartment from Incentives where IncentiveType='Financial' and ApplicableForGold=1 AND ActiveStatus=1 order by MinistryOrDepartment
	END
	ELSE 
	BEGIN
		select *, null ApplicableFor, NULL FilePath1, NULL FilePath2   FROM Incentives WHERE IncentiveType='Common' AND 1=2

		select *, null ApplicableFor, NULL FilePath1, NULL FilePath2   FROM Incentives WHERE IncentiveType in (SELECT StateName FROM States WHERE StateCode=ISNULL(@State,StateCode)) AND 1=2

		select *, null ApplicableFor, NULL FilePath1, NULL FilePath2  FROM Incentives WHERE IncentiveType='Other' AND 1=2

		select *, null ApplicableFor, NULL FilePath1, NULL FilePath2  FROM Incentives WHERE IncentiveType='Financial' AND 1=2

		select distinct MinistryOrDepartment from Incentives where IncentiveType='Financial' AND 1=2 order by MinistryOrDepartment
	END

	
END
