CREATE PROCEDURE [dbo].[SP_GET_SELF_ASSESSMENT_DETAILS_BY_REG_NUMBER] --'<redacted>'
(
	@RegistrationNumber varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
    SELECT  S.[Id]
      ,[StateCode]
      ,[StateName]
      ,[DistrictCode]
      ,[DistrictName]
      ,[RespondentName]
      ,[MobileNo]
      ,[EmailId]
      ,S.[CreatedDate]
      ,[Gender]
      ,[RespondentAge]
      ,[Service]
      ,[Experience]
      ,[Email]
      ,[Status]
      ,[IsTerminated]
      ,[FinalSubmitDate]
      ,[EstablishmentType]
      ,[RespondentMobileNo]
      ,UPPER([EstablishmentName]) EstablishmentName
      ,[EstablishmentAddress]
      ,[EstablishmentPinCode]
      ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[IsDeclarationAccepted]
      ,[CurrentQuestion]
      ,[CertificateNo]
      ,[Name]
      ,[IssuedOn]
      ,Convert(varchar, FinalSubmitDate, 100) [FinalSubmittedDate]
      ,[EstablishmentCity]
      ,[EstablishmentWebsite]
      ,S.[Acommodationtype]
      ,[TotalRooms]
      ,[RegistrationNumber]
      ,[Category]
	  ,[CertificateNo]
	  ,[RestaurantType]
	  ,REPLACE(UPPER(case when EstablishmentCity is null then '' else EstablishmentCity + ', ' end + case when DistrictName is null then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress
	  --isnull(EstablishmentCity,'') + '<redacted>' + isnull(DistrictName,'') + '<redacted>' + StateName EstablishmentFullAddress
	  ,QuestionnaireName
	  ,WebinarId
	  ,convert(varchar,W.WebinarStartTime,100) WebinarStartTime, convert(varchar,W.WebinarEndTime,100) WebinarEndTime
	  ,convert(varchar, W.WebinarDate, 100) WebinarDate
	  ,(select TOP 1 WebinarId from WebinarRegistrations where RegistrationNumber=@RegistrationNumber) WebinarUrl,
	  --(select WebinarCertificateNo from WebinarRegistrations where RegistrationNumber=@RegistrationNumber) WebinarCertificateNo,
	  --(select FeedbackLink from WebinarRegistrations where RegistrationNumber=@RegistrationNumber) FeedbackLink,
	  NULL WebinarCertificateNo,
	  NULL FeedbackLink,
	 (select count(*) RegCount from WebinarRegistrations where RegistrationNumber=@RegistrationNumber) RegCount,
	  SaDate,
	  PaymentDate,
	  SaCertificateNo
	FROM SelfAssessments S 
	LEFT JOIN AcommodationTypes A on (S.Acommodationtype=A.Acommodationtype) 
	LEFT JOIN Webinars W on (S.WebinarId=W.Id) 
	WHERE [RegistrationNumber]=@RegistrationNumber

END


