CREATE PROCEDURE [dbo].[SP_GET_SELF_ASSESSMENT_STATUS] --null, '<redacted>'
(
	@MobileNo varchar(50) = NULL,
	@RegNo varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
    SELECT  S.[Id]
      ,[StateCode]
      ,[StateName]
      ,[DistrictCode]
      ,[DistrictName]
      ,[RespondentName]
      ,[MobileNo]
      ,[EmailId]
      ,S.[CreatedDate]
      ,[Gender]
      ,[RespondentAge]
      ,[Service]
      ,[Experience]
      ,[Email]
      ,[Status]
      ,[IsTerminated]
      ,[FinalSubmitDate]
      ,[EstablishmentType]
      ,[RespondentMobileNo]
      ,UPPER([EstablishmentName]) EstablishmentName
      ,[EstablishmentAddress]
      ,[EstablishmentPinCode]
      ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[IsDeclarationAccepted]
      ,[CurrentQuestion]
      ,[CertificateNo]
      ,[Name]
      ,[IssuedOn]
      --,Convert(varchar, FinalSubmitDate, 100) [FinalSubmittedDate]
	  , FORMAT(FinalSubmitDate, 'MMMM d, yyyy h:mm tt') [FinalSubmittedDate]
      ,[EstablishmentCity]
      ,[EstablishmentWebsite]
      ,S.[Acommodationtype]
      ,[TotalRooms]
      ,[RegistrationNumber]
      ,[Category]
	  ,[CertificateNo]
	  ,[RestaurantType]
	  ,REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress
	  --isnull(EstablishmentCity,'') + '<redacted>' + isnull(DistrictName,'') + '<redacted>' + StateName EstablishmentFullAddress
	  ,QuestionnaireName
	  ,WebinarId
	  ,convert(varchar,W.WebinarStartTime,100) WebinarStartTime, convert(varchar,W.WebinarEndTime,100) WebinarEndTime
