CREATE PROCEDURE [dbo].[SP_GET_SUB_ROLE] --'<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	IF @RoleId = 3
	BEGIN
		--select CONVERT(int,DesktopVerification) DesktopVerification, CONVERT(int,SiteVerification) SiteVerification, CONVERT(int,FinancialVerification) FinancialVerification FROM Users WHERE UserId=@UserId
		select CONVERT(int,AllowBronzeSurveillance) DesktopVerification, CONVERT(int,SiteVerification) SiteVerification, CONVERT(int,FinancialVerification) FinancialVerification FROM Users WHERE UserId=@UserId
	END
	ELSE IF @RoleId = 2
	BEGIN

		--select CONVERT(int,DesktopVerification) DesktopVerification, CONVERT(int,SiteVerification) SiteVerification, CONVERT(int,FinancialVerification) FinancialVerification FROM Users WHERE UserId=@UserId
		select CONVERT(int,AllowBronzeSurveillance) DesktopVerification, CONVERT(int,SiteVerification) SiteVerification, CONVERT(int,FinancialVerification) FinancialVerification FROM Users WHERE UserId=@UserId

	END
	ELSE
	BEGIn
		select 1 DesktopVerification, 1 SiteVerification, 1 FinancialVerification
	END
END

