-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_USER_DETAILS_BY_ID] --38
(
	@Id varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	select * from Users where Id=@Id
	select A.* from Users U inner join AgencyUserStates A on (U.UserId=A.UserId AND U.RoleId=A.RoleId) where U.Id=@Id order by States
	select U.Id,A.UserId,U.RoleId,NicSectorCode as States,A.IsActive from Users U inner join UserNicSectors A on (U.UserId=A.UserId AND U.RoleId=A.RoleId) where U.Id=@Id order by NicSectorCode
	select U.Id,A.UserId,U.RoleId,AreaOfKnowledge as States,A.IsActive from Users U inner join UserAreaOfKnowledge A on (U.UserId=A.UserId AND U.RoleId=A.RoleId) where U.Id=@Id order by AreaOfKnowledge
	--select TOP 0 A.* from Users U inner join UserNicSectors A on (U.UserId=A.UserId AND U.RoleId=A.RoleId) where U.Id=@Id order by NicSectorCode
	select A.* from Users U inner join AgencyUserDistricts A on (U.UserId=A.UserId AND U.RoleId=A.RoleId) where U.Id=@Id order by Districts

END

