      ,[EstablishmentAddress]
      ,[EstablishmentPinCode]
      ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[IsDeclarationAccepted]
      ,[CurrentQuestion]
      ,[CertificateNo]
      ,[Name]
      ,[IssuedOn]
      ,[ResetDate]
      ,[EstablishmentCity]
      ,[EstablishmentWebsite]
      ,[Acommodationtype]
      ,[TotalRooms]
      ,[RegistrationNumber]
      ,[Category]
      ,[RestaurantType]
      ,[WebinarId]
      ,[WebinarDate]
      ,[WebinarUrl]
      ,[IpAddress])

	SELECT [Id]
      ,[StateCode]
      ,[StateName]
      ,[DistrictCode]
      ,[DistrictName]
      ,[RespondentName]
      ,[MobileNo]
      ,[EmailId]
      ,[CreatedDate]
      ,[Gender]
      ,[RespondentAge]
      ,[Service]
      ,[Experience]
      ,[Email]
      ,[Status]
      ,[IsTerminated]
      ,[FinalSubmitDate]
      ,[EstablishmentType]
      ,[RespondentMobileNo]
      ,[EstablishmentName]
      ,[EstablishmentAddress]
      ,[EstablishmentPinCode]
      ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[IsDeclarationAccepted]
      ,[CurrentQuestion]
      ,[CertificateNo]
      ,[Name]
      ,[IssuedOn]
      ,[ResetDate]
      ,[EstablishmentCity]
      ,[EstablishmentWebsite]
      ,[Acommodationtype]
      ,[TotalRooms]
      ,[RegistrationNumber]
      ,[Category]
      ,[RestaurantType]
      ,[WebinarId]
      ,[WebinarDate]
      ,[WebinarUrl]
      ,[IpAddress]
	  from SelfAssessments WHERE RegistrationNumber=@RegistrationNo


	UPDATE SelfAssessments SET IsDeclarationAccepted=NULL, CurrentQuestion=NULL,FinalSubmitDate=NULL,CertificateNo=NULL,
	EstablishmentName=@Name, EstablishmentAddress=@PostalAddress, EstablishmentCity=@City, DistrictName=@District, StateName=@State,NidhiStateName=@NidhiStateName,
	EstablishmentPinCode=@PinCode, EstablishmentPhoneNo=@PhoneNumber,EstablishmentFaxNo=@FaxNumber,  EstablishmentWebsite=@Website, RespondentName=@ContactPerson,
	Email=@Email, RespondentMobileNo=@MobileNumber, Acommodationtype=@Acommodationtype, TotalRooms=@TotalRooms, EmailId=@EmailId, MobileNo=@MobileNo 	
	WHERE RegistrationNumber=@RegistrationNo



END



