CREATE PROCEDURE [dbo].[SP_JOB_FOR_INSERT_BRONZE_SURVEILLANCE_DATA] 
(
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @ErrorMessage NVARCHAR(MAX), @ErrorSeverity INT, @ErrorState INT;

	BEGIN TRY
		BEGIN TRANSACTION;


				/* Place this inside your SP, right after '<redacted>' */

		---- 0. AUTOMATIC UPGRADE CHECK
		---- Rename existing ZedId to _UPGRADED so the new certificate can be inserted below.
		--UPDATE M
		--SET M.ZedId = M.ZedId + '<redacted>'
		--FROM [ZED_SURVEILLANCE].[dbo].[Msme] M
		--INNER JOIN [ZED_SURVEILLANCE].[dbo].[msmebasicinformation] B ON B.ZedId = M.ZedId
		--INNER JOIN [ZEDCS_V2_LIVE].[dbo].[msmebasicinformation] LIVE_B ON LIVE_B.ZedId = M.ZedId
		--LEFT JOIN [ZED_SURVEILLANCE].[dbo].[MsmeCertifications] P ON P.ZedId = M.ZedId
		--WHERE 
		--	M.ZedId NOT LIKE '<redacted>'
		--	AND B.lastestCertification != LIVE_B.lastestCertification
		--	AND (P.CertificationStatus IS NULL OR P.CertificationStatus = 0)
		--	AND NOT EXISTS (
		--		SELECT 1 FROM [ZED_SURVEILLANCE].[dbo].[msmepaymentinfo] PAY 
		--		WHERE PAY.ZedId = M.ZedId AND PAY.Certification = B.lastestCertification
		--	)
		--	AND (
		--		(B.lastestCertification = '<redacted>' AND LIVE_B.lastestCertification IN ('<redacted>', '<redacted>'))
		--		OR (B.lastestCertification = '<redacted>' AND LIVE_B.lastestCertification = '<redacted>')
		--	);




		-- 1. Insert into Msme table
		INSERT INTO Msme (
		  MsmeId, ZedId, StateId, StateName, DistrictId, DistrictName, OwnerName, EnterpriseName, OrganisationType, OrganisationTypeName,
		  EnterpriseType, EnterpriseTypee, MobileNo, EmailId, ApplicationId, UamNumber, PFlat, PBuilding, PRoad, PArea, PCity, PAddress,
		  PPin, PStateId, PStateName, PLgDistrictCode, PDistrictName, PPlantDetailId, Activity, TwoDigitActivity, FourDigitActivity,
		  FiveDigitActivity, ActivityDetailId, PledgeEmailId, IsBronzePaymentDone, IsSilverPaymentDone, IsGoldPaymentDone, IsCouponUsed,
		  PledgeCertificateNo, RegistrationType, IncorporationDate, WhetherProdCommenced, PlantIdNo, PUnitName, PUnitIdNo, CreatedDate,
		  RegistrationFrom, FinancialAssistanceStatus, WashWebinarCertificateNo, WashCertificateNo, QrCodeNo, IsCouponExpired, 
		  TechnologyUpgradation, TblMsmeSchemeId, TblMsmeSchemeName, IsSurBronzePaymentDone, IsSurSilverPaymentDone, IsSurGoldPaymentDone, InsertedFor
		)
		SELECT 
		  MsmeId, ZedId, StateId, StateName, DistrictId, DistrictName, OwnerName, EnterpriseName, OrganisationType, OrganisationTypeName,
		  EnterpriseType, EnterpriseTypee, MobileNo, EmailId, ApplicationId, UamNumber, PFlat, PBuilding, PRoad, PArea, PCity, PAddress,
		  PPin, PStateId, PStateName, PLgDistrictCode, PDistrictName, PPlantDetailId, Activity, TwoDigitActivity, FourDigitActivity,
		  FiveDigitActivity, ActivityDetailId, PledgeEmailId, NULL, NULL, NULL, 1,
		  PledgeCertificateNo, RegistrationType, IncorporationDate, WhetherProdCommenced, PlantIdNo, PUnitName, PUnitIdNo, CreatedDate,
		  RegistrationFrom, FinancialAssistanceStatus, WashWebinarCertificateNo, WashCertificateNo, QrCodeNo, IsCouponExpired, 
		  TechnologyUpgradation, TblMsmeSchemeId, TblMsmeSchemeName, IsSurBronzePaymentDone, IsSurSilverPaymentDone, IsSurGoldPaymentDone, 'Bronze'
		FROM ZEDCS_V2_LIVE.DBO.Msme AS SourceMsme
		WHERE ZedId IN (
			SELECT Distinct ZedId
			FROM ZEDCS_V2_LIVE.DBO.MsmeCertifications
			WHERE CertificationStatus = 6 AND Certification='Bronze'
			  AND DaCertificateNo IS NOT NULL
			  AND RestrictMail IS NULL
			  AND CAST(CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH,-14, GETDATE()) AS DATE)
		)
		AND NOT EXISTS (
			SELECT 1
			FROM Msme AS TargetMsme
			WHERE TargetMsme.ZedId = SourceMsme.ZedId
		);

		-- 2. Insert into MsmeBasicInformation table
		-- Logic: Directly joining to MsmeCertifications to get the Date since there is no recertification for Bronze
		INSERT INTO MsmeBasicInformation(
			MsmeId, ApplicationId, UdyogAadharNo, OwnerName, EnterpriseName, OrganisationType, OrganisationTypeName,
			SocialCategory, SocialCategoryName, Gender, PH, PanNo, Address, StateId, StateName, DistrictId, DistrictName,
			LgDistrictCode, Pincode, MobileNo, EmailId, MajorActivity, MajorActivityName, EnterpriseType, EnterpriseTypee,
			CommmenceDate, PreviousEMType, PreviousEMNumber, TotalEmp, InvestmentCost, DicName, AppliedDate, ZedId, LastestCertification,
			ZedCertifiedDate
		)
		SELECT 
			SourceMsmeBasic.MsmeId, ApplicationId, UdyogAadharNo, OwnerName, EnterpriseName, OrganisationType, OrganisationTypeName,
			SocialCategory, SocialCategoryName, Gender, PH, PanNo, Address, StateId, StateName, DistrictId, DistrictName,
			LgDistrictCode, Pincode, MobileNo, EmailId, MajorActivity, MajorActivityName, EnterpriseType, EnterpriseTypee,
			CommmenceDate, PreviousEMType, PreviousEMNumber, TotalEmp, InvestmentCost, DicName, AppliedDate, SourceMsmeBasic.ZedId, LastestCertification,
			ZP.CertificationStatusDate -- Simple direct copy
		FROM ZEDCS_V2_LIVE.DBO.MsmeBasicInformation AS SourceMsmeBasic
		INNER JOIN ZEDCS_V2_LIVE.DBO.MsmeCertifications ZP 
			ON SourceMsmeBasic.ZedId = ZP.ZedId 
			AND ZP.Certification = 'Bronze' 
			AND ZP.CertificationStatus = 6
		WHERE SourceMsmeBasic.ZedId IN (
			SELECT Distinct ZedId
			FROM ZEDCS_V2_LIVE.DBO.MsmeCertifications
			WHERE CertificationStatus = 6 AND Certification='Bronze'
			  AND DaCertificateNo IS NOT NULL
			  AND RestrictMail IS NULL
			  AND CAST(CertificationStatusDate AS DATE) <= CAST(DATEADD(MONTH,-14, GETDATE()) AS DATE)
		)
		AND NOT EXISTS (
			SELECT 1
			FROM MsmeBasicInformation AS TargetMsmeBasic
			WHERE TargetMsmeBasic.ZedId = SourceMsmeBasic.ZedId
		);

		COMMIT;

	END TRY
	BEGIN CATCH
		SELECT 
			@ErrorMessage = ERROR_MESSAGE(), 
			@ErrorSeverity = ERROR_SEVERITY(), 
			@ErrorState = ERROR_STATE();

		IF @@TRANCOUNT > 0
			ROLLBACK;

		INSERT INTO ErrorLog (ProcedureName, ErrorMessage, ErrorSeverity, ErrorState, ErrorDate)
		VALUES ('SP_JOB_FOR_INSERT_BRONZE_SURVEILLANCE_DATA', @ErrorMessage, @ErrorSeverity, @ErrorState, GETDATE());

		THROW @ErrorSeverity, @ErrorMessage, @ErrorState;
	END CATCH
END
GO
