/****** Object:  StoredProcedure [dbo].[SP_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_LIST_OF_FINANCIAL_SUPPORT_ZEDIDS]  --NULL,NULL,null,null,null,10
(
	@ZedId varchar(50) = NULL,
	@Status varchar(50) =null,
	@State varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@Gender varchar(50) = NULL,
	@MsmeSize varchar(50) = NULL,
	@PageNo int = 1,
	@NoOfRecords int = 25000
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	IF @State='' 
	SET @State = NULL

	--IF @CertificationType='' 
	--SET @CertificationType = NULL

	IF @Gender='' 
	SET @Gender = NULL

	IF @MsmeSize='' 
	SET @MsmeSize = NULL

	IF @State IS NULL OR @State=''
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	IF @RoleId=10 OR @RoleId=11

	BEGIN
	
		select M.EnterpriseName,PUnitName,Paddress UnitAddress,M.EnterpriseTypee EnterpriseType, 'Bronze' Certification, M.ZedId,case when RIGHT(C.ZedId,2)='_D' then 'Rejected' else 'Active' end as ZedIdStatus, 10000 CertificationFee,ApplicantContributionAfterSubsidy Amount, 10000-ApplicantContributionAfterSubsidy FinancialSupport
		,M.PStateName,Gender from msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy from MsmePaymentInfo) P on (replace(C.ZedId,'_D','')=replace(P.ZedId,'_D','') and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (replace(C.ZedId,'_D','')=replace(T.ZedId,'_D','') and C.Certification=T.Certification and PaymentStatus='Success' )
		where P.Certification='Bronze' and CertificationStatus>=2
		and (@State is null or M.StateId=@State)
		AND (@CertificationType IS NULL OR C.Certification=@CertificationType) 
		AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)

		union all

		select M.EnterpriseName,PUnitName,Paddress UnitAddress,M.EnterpriseTypee EnterpriseType, 'Silver' Certification, M.ZedId,case when RIGHT(C.ZedId,2)='_D' then 'Rejected' else 'Active' end as ZedIdStatus,40000 CertificationFee,ApplicantContributionAfterSubsidy Amount, 40000-ApplicantContributionAfterSubsidy FinancialSupport
		,M.PStateName,Gender from msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy from MsmePaymentInfo) P on (replace(C.ZedId,'_D','')=replace(P.ZedId,'_D','') and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (replace(C.ZedId,'_D','')=replace(T.ZedId,'_D','') and C.Certification=T.Certification and PaymentStatus='Success' )
		where P.Certification='Silver' and CertificationStatus>=2
		and (@State is null or M.StateId=@State)
		AND (@CertificationType IS NULL OR C.Certification=@CertificationType) 
		AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)

		union all

		select M.EnterpriseName,PUnitName,Paddress UnitAddress,M.EnterpriseTypee EnterpriseType, 'Gold' Certification, M.ZedId,case when RIGHT(C.ZedId,2)='_D' then 'Rejected' else 'Active' end as ZedIdStatus,90000 CertificationFee,ApplicantContributionAfterSubsidy Amount, 90000-ApplicantContributionAfterSubsidy FinancialSupport
		,M.PStateName,Gender from msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join 
		(select distinct zedid,certification,paymentrefid,ApplicantContributionAfterSubsidy from MsmePaymentInfo) P on (replace(C.ZedId,'_D','')=replace(P.ZedId,'_D','') and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (replace(C.ZedId,'_D','')=replace(T.ZedId,'_D','') and C.Certification=T.Certification and PaymentStatus='Success' )
		where P.Certification='Gold' and CertificationStatus>=2
		and (@State is null or M.StateId=@State)
		AND (@CertificationType IS NULL OR C.Certification=@CertificationType) 
		AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)

		union all

		select M.EnterpriseName,PUnitName,Paddress UnitAddress,EnterpriseTypee EnterpriseType,CertificationType Certification,F.ZedId,null,null,null,isnull(ApproverAmount,0) FinancialSupport, M.PStateName,null Gender
		from FinancialAssistance F left join Msme m on (F.ZedId=M.ZedId) 
		where isnull(ApproverAmount,0)>0
		and (@State is null or M.StateId=@State)
		AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize)
		
	END

	ELSE 

		select M.EnterpriseName,PUnitName,Paddress UnitAddress,EnterpriseTypee EnterpriseType,CertificationType Certification,F.ZedId,null ZedIdStatus,null CertificationFee,null Amount,isnull(ApproverAmount,0) FinancialSupport
		from FinancialAssistance F left join Msme m on (F.ZedId=M.ZedId) 
		where 1=2

END


GO
