	@AssessmentFeeAfterCoupon [decimal](10, 2) = NULL,
	@GstAfterCoupon [decimal](10, 2) = NULL,
	@TotalAfterCoupon [decimal](10, 2) = NULL,
	@SubsidyPer [decimal](10, 2),
	@SubsidyAmount [decimal](10, 2),
	@GstAfterSubsidy [decimal](10, 2),
	@ApplicantContributionAfterSubsidy [decimal](10, 2),
	@Tds15 [decimal](10, 2),
	@Tds75 [decimal](10, 2),
	@NetPaybleTds15 [decimal](10, 2),
	@NetPaybleTds75 [decimal](10, 2)
)
AS
BEGIN
	
	SET NOCOUNT ON;

	Update AssessmentFee 
	SET [EnterpriseTypee] = @EnterpriseTypee
      ,[Certification] = @Certification
      ,[AssessmentFee] = @AssessmentFee
      ,[Gst] = @Gst
      ,[Total] = @Total
      ,[Coupon] = @Coupon
      ,[AssessmentFeeAfterCoupon] = @AssessmentFeeAfterCoupon
      ,[GstAfterCoupon] = @GstAfterCoupon
      ,[TotalAfterCoupon] = @TotalAfterCoupon
      ,[SubsidyPer] = @SubsidyPer
      ,[SubsidyAmount] = @SubsidyPer
      ,[GstAfterSubsidy] = @GstAfterSubsidy
      ,[ApplicantContributionAfterSubsidy] = @ApplicantContributionAfterSubsidy
      ,[Tds15] = @Tds15
      ,[Tds75] = @Tds75
      ,[NetPaybleTds15] = @NetPaybleTds15
      ,[NetPaybleTds75] = @NetPaybleTds75	
	WHERE Id=@Id 
		AND EnterpriseTypee=@EnterpriseTypee 
		AND Certification=@Certification

END


