/****** Object:  StoredProcedure [dbo].[SP_MONITORING_DA_FINAL_SUBMIT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MONITORING_DA_FINAL_SUBMIT] --'<redacted>'
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@QrCodeSeqNo varchar(50) = NULL
)
AS
BEGIN
		Declare @CertificateNo varchar(50)= NULL,
			@SerialNo varchar(50)
		--SET  @SerialNo = Next Value For CertificateSequence; 
		 select @SerialNo=right(ZedId,6) from MsmeCertifications where ZedId=@ZedId

		Declare @PlantIdNo varchar(50) = NULL
		select @PlantIdNo=PlantIdNo from Msme where ZedId=@ZedId


		IF @CertificationType='Bronze'
		BEGIN
			--select @CertificateNo=concat(replace(convert(varchar, getdate(),103),'<redacted>',''),'<redacted>',@SerialNo)				
			select @CertificateNo=DaCertificateNo, @QrCodeSeqNo=QrCodeSeqNo from ZEDCS_V2_LIVE.dbo.MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType

			UPDATE MsmeCertifications SET   DaCertificateNo=@CertificateNo, CertificationStatusDate=getdate(),CertificationStatus=6 where  ZedId=@ZedId and Certification=@CertificationType
			UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications SET CertificationPhase='ACTIVE' where  ZedId=@ZedId and Certification=@CertificationType and CertificationPhase NOT IN ('ACTIVE', 'EXPIRED', 'UPGRADED')
			UPDATE B SET IsEligibleForBenefits=1  from ZEDCS_V2_LIVE.DBO.MsmeBasicInformation B inner join ZEDCS_V2_LIVE.DBO.MsmeCertifications C on (b.zedid=c.zedid) where  C.ZedId=@ZedId and Certification=@CertificationType and CertificationPhase NOT IN ('EXPIRED', 'UPGRADED')
			
			Update MsmeCertifications set QrCodeSeqNo=@QrCodeSeqNo where ZedId=@ZedId and Certification=@CertificationType

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Completed On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Completed')

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Certificate & Report generated on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'GetCertified')

			UPDATE Msme SET FinancialAssistanceStatus=1 WHERE ZedId=@ZedId
			UPDATE MsmeBasicInformation SET LastestCertification='Bronze' WHERE ZedId=@ZedId


			--------STARTING ADDING THE COMPLETED RECORD IN ZED CONSULTANT DATABASE-----------------------

			IF NOT EXISTS (SELECT ZedId from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId)
			BEGIN
				INSERT INTO ZED_CONSULTANT.dbo.Msme
				 ([MsmeId],[ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType]
				,[OrganisationTypeName], [EnterpriseType], [EnterpriseTypee], [MobileNo], [EmailId], [ApplicationId], [UamNumber]
				,[PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode]
				,[PDistrictName], [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId]
				,[PledgeEmailId], [IsBronzePaymentDone], [IsSilverPaymentDone], [IsGoldPaymentDone], [IsCouponUsed], [PledgeCertificateNo]
				,[RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo], [CreatedDate]
				,[RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo])

				SELECT
				[MsmeId],[ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType]
				,[OrganisationTypeName], [EnterpriseType], [EnterpriseTypee], [MobileNo], [EmailId], [ApplicationId], [UamNumber]
				,[PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode]
				,[PDistrictName], [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId]
				,[PledgeEmailId], NULL, NULL, NULL, 1, [PledgeCertificateNo]
				,[RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo], getdate()
				,[RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo]
				from Msme where ZedId=@ZedId


				INSERT INTO ZED_CONSULTANT.dbo.MsmeBasicInformation(
				[MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory]
				,[SocialCategoryName], [Gender], [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName]
				,[LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName], [EnterpriseType], [EnterpriseTypee]
				,[CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId]
				,[LastestCertification])
								
				SELECT
				[MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory]
				,[SocialCategoryName], [Gender], [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName]
				,[LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName], [EnterpriseType], [EnterpriseTypee]
				,[CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId]
				,[LastestCertification] from MsmeBasicInformation where ZedId=@ZedId

			END

			-------------------END ADDING THE COMPLETED RECORD IN ZED CONSULTANT DATABASE-------------------------------------------------
			

		END

		ELSE
		BEGIN
			UPDATE MsmeCertifications SET    CertificationStatusDate=getdate(),CertificationStatus=6 where  ZedId=@ZedId and Certification=@CertificationType 
			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Completed On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'DesktopVerification')
		END

END


GO
/****** Object:  StoredProcedure [dbo].[SP_MONITORING_GET_COMPLETED_LIST]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MONITORING_GET_COMPLETED_LIST] --'<redacted>', '<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@Status int =null,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	 DECLARE @RoleId INT 
	 SELECT @RoleId=ROLEID FROM USERS WHERE USERID=@UserId

		IF @RoleId=7
		BEGIN
			SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,
			CASE WHEN Certification='Bronze' then 'Onsite' else 'Remote' end as ModeOfAssessment,
			AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, EnterpriseName, U.UserName 
			FROM MsmeCertifications P
			inner join Msme M on (P.ZedId=M.ZedId)
			LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
			WHERE CertificationStatus=6
			and Certification=@CertificationType 
			ORDER By Id
		
		END
		
		


		IF @RoleId=2
		BEGIN
			SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,
			CASE WHEN Certification='Bronze' then 'Onsite' else 'Remote' end as ModeOfAssessment,
			AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin, EnterpriseName , U.UserName 
			FROM MsmeCertifications P
			inner join Msme M on (P.ZedId=M.ZedId)
			LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
			WHERE CertificationStatus=6
			and Certification=@CertificationType and CertificationBodyUserId=@UserId
			ORDER By Id
		
		END

		IF @RoleId=3
		BEGIN
			SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,
			CASE WHEN Certification='Bronze' then 'Onsite' else 'Remote' end as ModeOfAssessment,
			AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin, EnterpriseName , U.UserName 
			FROM MsmeCertifications P
			inner join Msme M on (P.ZedId=M.ZedId)
			LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
			WHERE CertificationStatus=6
			and Certification=@CertificationType and ((DesktopAssessorId=@UserId OR SiteAssessorId=@UserId))
			ORDER By Id
		
		END


END



GO
/****** Object:  StoredProcedure [dbo].[SP_MONITORING_GET_LIST]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MONITORING_GET_LIST] --'<redacted>', 6,'<redacted>',null,null,null,null,null,null,null,'<redacted>'
(
	@UserId varchar(50) = NULL,
	@Status int =null,
	@CertificationType varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@State varchar(100) = NULL,
	@RoleId varchar(50) = NULL,
	@Gender varchar(50) = NULL,
	@MsmeSize varchar(50) = NULL,
	@PageNo int = 1,
	@NoOfRecords int = 25000,
	@NcClosingDate varchar(50) = NULL

)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @State='' 
	SET @State = NULL

	IF  @CertificationType='' 
	SET @CertificationType = NULL

	IF @Status!=4
	SET @NcClosingDate = NULL

	IF @Gender='' 
	SET @Gender = NULL

	IF @MsmeSize='' 
	SET @MsmeSize = NULL

	--DECLARE @RoleId INT 
	SELECT @RoleId=ROLEID FROM USERS WHERE USERID=@UserId

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	IF @RoleId=7
	BEGIN
		SELECT  P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,
			CASE WHEN Certification='Bronze' then 'Onsite' else 'Remote' end as ModeOfAssessment,
			FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, M.EnterpriseName, U.UserName AgencyName,
			concat(@CurrentUrl, '/PDFs/SA/',P.ZedId,'/',@CertificationType,'_Report.pdf') ReportPath,
			PV.BasicInfoStatus, PV.DocVerifiAllot, PV.DesktopVerification DesktopVerificationCompleted,PV.ScheduledOn, PV.Completed SaCompletedOn,
			UA.UserName as DesktopAssessorName,
			UL.UserName as SiteAssessorName,
			UC.UserName as CoAssessorName,
			CoAssessorId,
			CASE when DesktopAssessorId=@UserId then 'D' else '' end as DeskAssessment, 
			CASE when SiteAssessorId=@UserId then 'S' else '' end as SiteAssessment,
			M.OwnerName as UnitSpocName, M.MobileNo as UnitSpocMobileNo, M.EmailId as UnitSpocEmailId,

			case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'
			WHEN cs.MonitoringGetList is not null then MonitoringGetList
			
			when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Done By MSME'
		end as AssessmentStatus,
		ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber, NcStatus, FORMAT(P.NcFinalClosureDt, 'MMMM d, yyyy') NcFinalClosureDt,
		P.NcFinalClosureDt as NcFinalClosureDtOrg,P.ZedId as RejectedZedId, U.AllowBronzeSurveillance,
		--CASE WHEN P.ZedId LIKE '<redacted>' THEN '<redacted>' ELSE '<redacted>' END AS SurveillanceNo


	  CASE WHEN P.ZedId LIKE '%\_S\_%' ESCAPE '\' THEN '1st Surveillance'
      WHEN B.ReSurveillance = 2 THEN '2nd Surveillance'
	  ELSE '1st Surveillance'
      END AS SurveillanceNo, 
	  CASE WHEN CAST(P.CertificationStatusDate AS DATE) < CAST(GETDATE() AS DATE) THEN 'Certifications' ELSE 'Certificates' END AS CertificationPath
		
		FROM MsmeCertifications P
		--inner join Msme M on (REPLACE(REPLACE(P.Zedid,'<redacted>',''),concat('<redacted>',P.Id),'')=M.ZedId)
		inner join Msme M ON (M.ZedId = REPLACE(REPLACE(REPLACE(P.ZedId, CONCAT('_D_', P.Id), ''), CONCAT('_S_', P.Id), ''), '_D',''))
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		LEFT JOIN CertificationStatuses CS on (P.CertificationStatus=CS.SNo)
		LEFT JOIN Users U on  (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users UL on (P.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
		

		LEFT JOIN
		(select * from 
		(
		  select ZedId, StatusType, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,CertificationType
		  from MsmeHistory where CertificationType is not null and StatusType is not null  and (@CertificationType IS NULL OR CertificationType=@CertificationType)
		) src
		pivot
		(
		  max(CreatedOn)
		  for StatusType in ([BasicInfoStatus], [DocVerifiAllot], [DesktopVerification],[ScheduledOn],[Completed])
		) piv) PV
		on (P.ZedId=PV.ZedId and P.Certification=PV.CertificationType)

		--WHERE ((CertificationStatus=ISNULL(@Status,0) and @Status not in (2,3,6)) OR (@Status=2 AND CertificationStatus=1 and DesktopAccepted=1) OR (@Status=3 AND CertificationStatus IN (2,3)) OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='<redacted>') OR (@Status=3 AND CertificationStatus=13) OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='<redacted>') OR (@Status=2 AND CertificationStatus=8) OR (@Status=7 AND CertificationStatus=7) OR (@Status=7 AND CertificationStatus=17) OR (@Status=99 AND CertificationStatus=99) OR (@Status=2 AND P.ModeOfAssessment='<redacted>' AND CertificationStatus=9 AND JoinRoomStatus=0) OR (@Status=5 AND CertificationStatus=15) OR (@Status=4 AND CertificationStatus=14) OR (@Status=6 AND ((P.Certification='<redacted>' and CertificationStatus=6) OR ( P.Certification!='<redacted>' and CertificationStatus=16))))
		--	 AND (@ZedId IS NULL OR p.ZedId=@ZedId) and (@NcClosingDate IS NULL OR CONVERT(NVARCHAR(10), P.NcFinalClosureDt, 101)=@NcClosingDate)
		--	and (DesktopAccepted = 1 OR CertificationStatus = 17)
		--	and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender) 
			
		--ORDER By p.CertificationStatusDate desc

		WHERE ((CertificationStatus=ISNULL(@Status,0) and @Status not in (2,3,6)) 
			OR (@Status=2 AND CertificationStatus=1 and DesktopAccepted=1) 
			OR (@Status=3 AND CertificationStatus IN (2,3)) 
			
			-- మార్పు 1: '<redacted>' కు Selfie Sync అవ్వాలి (Remote కాని వాటికి)
			OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='Remote Assessment' AND IsSelfieSynced = 1) 
			
			OR (@Status=3 AND CertificationStatus=13) 
			OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='Remote Assessment') 
			OR (@Status=2 AND CertificationStatus=8) 
			
			-- మార్పు 2: '<redacted>' కు Selfie Sync అవ్వకూడదు (Remote కాని వాటికి)
			OR (@Status=2 AND CertificationStatus=9 AND P.ModeOfAssessment!='Remote Assessment' AND ISNULL(IsSelfieSynced,0) = 0) 
			
			OR (@Status=7 AND CertificationStatus=7) 
			OR (@Status=7 AND CertificationStatus=17) 
			OR (@Status=99 AND CertificationStatus=99) 
			OR (@Status=2 AND P.ModeOfAssessment='Remote Assessment' AND CertificationStatus=9 AND JoinRoomStatus=0) 
			OR (@Status=5 AND CertificationStatus=15) 
			OR (@Status=4 AND CertificationStatus=14) 
			OR (@Status=6 AND ((P.Certification='Bronze' and CertificationStatus=6) OR ( P.Certification!='Bronze' and CertificationStatus=16))))
			
			AND (@ZedId IS NULL OR p.ZedId=@ZedId) and (@NcClosingDate IS NULL OR CONVERT(NVARCHAR(10), P.NcFinalClosureDt, 101)=@NcClosingDate)
			and (DesktopAccepted = 1 OR CertificationStatus = 17)
			and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender) 
			
		ORDER By p.CertificationStatusDate desc


		
		--IF @CertificationType='<redacted>'
		--BEGIN
		--	SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM 
		--	--(SELECT CertificationStatus, Count(*) Cnt FROM (select CASE WHEN JoinRoomStatus=0 and CertificationStatus=9 then 8 else CertificationStatus end as CertificationStatus from MsmeCertifications 
		--	(SELECT CertificationStatus, Count(*) Cnt FROM (select CASE WHEN JoinRoomStatus=0 and CertificationStatus=9 then 9 else CertificationStatus end as CertificationStatus from MsmeCertifications 
		--	WHERE Certification=@CertificationType and (DesktopAccepted = 1 OR CertificationStatus = 17)) MsmeCertifications  GROUP BY CertificationStatus) src
		--	PIVOT
		--	(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		--END
		--ELSE
		--BEGIN
		--	SELECT ISNULL([1],0)+ISNULL([8],0) NotStarted, ISNULL([2],0)+ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM 
		--	(SELECT CertificationStatus, Count(*) Cnt FROM MsmeCertifications WHERE Certification=@CertificationType and (DesktopAccepted = 1 OR CertificationStatus = 17) GROUP BY CertificationStatus) src
		--	PIVOT
		--	(max(cnt) for CertificationStatus in ([1],[2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		--END

		IF @CertificationType='Silver'
		BEGIN
			SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM 
			(SELECT CertificationStatus, Count(*) Cnt FROM 
				(
					SELECT CASE 
						-- if Selfie not synced then change it to 8 (Not Started)
						WHEN (CertificationStatus=9 AND ISNULL(IsSelfieSynced, 0)=0) THEN 8 
						ELSE CertificationStatus 
					END AS CertificationStatus 
					FROM MsmeCertifications 
					WHERE Certification=@CertificationType and (DesktopAccepted = 1 OR CertificationStatus = 17)
				) MsmeCertifications  
			GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END

		ELSE
		BEGIN
			SELECT ISNULL([1],0)+ISNULL([8],0) NotStarted, ISNULL([2],0)+ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM 
			(SELECT CertificationStatus, Count(*) Cnt FROM 
				(
					SELECT CASE 
						-- Selfie not synced then 8 (Not Started)
						WHEN CertificationStatus=9 AND ISNULL(IsSelfieSynced,0)=0 THEN 8 
						ELSE CertificationStatus 
					END AS CertificationStatus 
					FROM MsmeCertifications 
					WHERE Certification=@CertificationType and (DesktopAccepted = 1 OR CertificationStatus = 17)
				) MsmeCertifications 
			GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([1],[2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END



			
	END

	ELSE IF @RoleId=2
	BEGIN
		SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
		AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,
		CASE WHEN Certification='Bronze' then 'Onsite' else 'Remote' end as ModeOfAssessment,
		FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
		case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
		DaCertificateNo,SaCertificateNo,
		CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
		P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, M.EnterpriseName , U.UserName AgencyName,
		PV.BasicInfoStatus, PV.DocVerifiAllot, PV.DesktopVerification DesktopVerificationCompleted,PV.ScheduledOn, PV.Completed SaCompletedOn,
		UA.UserName as DesktopAssessorName,
		UL.UserName as SiteAssessorName,
		UC.UserName as CoAssessorName,
		CoAssessorId,
		CASE when DesktopAssessorId=@UserId then 'D' else '' end as DeskAssessment, 
		CASE when SiteAssessorId=@UserId then 'S' else '' end as SiteAssessment,
		M.OwnerName as UnitSpocName, M.MobileNo as UnitSpocMobileNo, M.EmailId as UnitSpocEmailId,

		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'	
			WHEN cs.MonitoringGetList is not null then MonitoringGetList
			
			when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Done By MSME'
		end as AssessmentStatus,
		ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber, NcStatus, FORMAT(P.NcFinalClosureDt, 'MMMM d, yyyy') NcFinalClosureDt,
		P.NcFinalClosureDt as NcFinalClosureDtOrg,P.ZedId as RejectedZedId, U.AllowBronzeSurveillance,
		case when B.ReSurveillance>=1 then '2nd Surveillance' else '1st Surveillance' end as SurveillanceNo

		FROM MsmeCertifications P
		inner join Msme M on (REPLACE(REPLACE(P.Zedid,'_D',''),concat('_',P.Id),'')=M.ZedId)
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN CertificationStatuses CS on (P.CertificationStatus=CS.SNo)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users UL on (P.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)

		LEFT JOIN
		(select * from 
		(
		  select ZedId, StatusType, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,CertificationType
		  from MsmeHistory where CertificationType is not null and StatusType is not null and (@CertificationType IS NULL OR CertificationType=@CertificationType)
		) src
		pivot
		(
		  max(CreatedOn)
		  for StatusType in ([BasicInfoStatus], [DocVerifiAllot], [DesktopVerification],[ScheduledOn],[Completed])
		) piv) PV
		on (P.ZedId=PV.ZedId and P.Certification=PV.CertificationType)

		--WHERE ((CertificationStatus=ISNULL(@Status,0) and @Status not in (2,3,6)) OR (@Status=2 AND CertificationStatus=1 and DesktopAccepted=1) OR (@Status=3 AND CertificationStatus IN (2,3))  OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='<redacted>')  OR (@Status=3 AND CertificationStatus=13) OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='<redacted>') OR (@Status=2 AND CertificationStatus=8) OR (@Status=7 AND CertificationStatus=7) OR (@Status=7 AND CertificationStatus=17) OR (@Status=99 AND CertificationStatus=99) OR (@Status=2 AND P.ModeOfAssessment='<redacted>' AND CertificationStatus=9 AND JoinRoomStatus=0) OR (@Status=5 AND CertificationStatus=15) OR (@Status=4 AND CertificationStatus=14) OR (@Status=6 AND ((P.Certification='<redacted>' and CertificationStatus=6) OR ( P.Certification!='<redacted>' and CertificationStatus=16))))
		----WHERE (CertificationStatus=ISNULL(@Status,0)  OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='<redacted>')  OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='<redacted>') OR (@Status=2 AND CertificationStatus=8) OR (@Status=2 AND P.ModeOfAssessment='<redacted>' AND CertificationStatus=9 AND JoinRoomStatus=0) OR (@Status=5 AND CertificationStatus=15) OR (@Status=4 AND CertificationStatus=14) OR (@Status=6 AND CertificationStatus=16))
		-- and CertificationBodyUserId=@UserId AND (@ZedId IS NULL OR p.ZedId=@ZedId)  and (@NcClosingDate IS NULL OR CONVERT(NVARCHAR(10), P.NcFinalClosureDt, 101)=@NcClosingDate)
		----and (DesktopAccepted = 1 OR CertificationStatus = 17)
		--and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender) 
		--ORDER By p.CertificationStatusDate desc

		WHERE ((CertificationStatus=ISNULL(@Status,0) and @Status not in (2,3,6)) 
			OR (@Status=2 AND CertificationStatus=1 and DesktopAccepted=1) 
			OR (@Status=3 AND CertificationStatus IN (2,3))  
			
			
			OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='Remote Assessment' AND IsSelfieSynced = 1)  
			
			OR (@Status=3 AND CertificationStatus=13) 
			OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='Remote Assessment') 
			OR (@Status=2 AND CertificationStatus=8) 
			
			
			OR (@Status=2 AND CertificationStatus=9 AND P.ModeOfAssessment!='Remote Assessment' AND ISNULL(IsSelfieSynced,0) = 0) 
			
			OR (@Status=7 AND CertificationStatus=7) 
			OR (@Status=7 AND CertificationStatus=17) 
			OR (@Status=99 AND CertificationStatus=99) 
			OR (@Status=2 AND P.ModeOfAssessment='Remote Assessment' AND CertificationStatus=9 AND JoinRoomStatus=0) 
			OR (@Status=5 AND CertificationStatus=15) 
			OR (@Status=4 AND CertificationStatus=14) 
			OR (@Status=6 AND ((P.Certification='Bronze' and CertificationStatus=6) OR ( P.Certification!='Bronze' and CertificationStatus=16))))
		 and CertificationBodyUserId=@UserId AND (@ZedId IS NULL OR p.ZedId=@ZedId)  and (@NcClosingDate IS NULL OR CONVERT(NVARCHAR(10), P.NcFinalClosureDt, 101)=@NcClosingDate)
		and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender) 
		ORDER By p.CertificationStatusDate desc



		--IF @CertificationType='<redacted>'
		--BEGIN
		--	SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM
		--	(SELECT CertificationStatus, Count(*) Cnt FROM 

		--	(select CASE WHEN JoinRoomStatus=0 and CertificationStatus=9 then 9 else CertificationStatus end as CertificationStatus from MsmeCertifications 
		--	WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and (DesktopAccepted = 1 OR CertificationStatus = 17))
		--	MsmeCertifications  GROUP BY CertificationStatus) src
		--	PIVOT
		--	(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		--END

		--ELSE
		--BEGIN
		--	SELECT ISNULL([1],0)+ISNULL([8],0) NotStarted, ISNULL([2],0)+ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM
		--	(SELECT CertificationStatus, Count(*) Cnt FROM MsmeCertifications WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and (DesktopAccepted = 1 OR CertificationStatus = 17) GROUP BY CertificationStatus) src
		--	PIVOT
		--	(max(cnt) for CertificationStatus in ([1],[2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		--END

		IF @CertificationType='Silver'
		BEGIN
			SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM
			(SELECT CertificationStatus, Count(*) Cnt FROM 
				(
					SELECT CASE 
						WHEN (CertificationStatus=9 AND ISNULL(IsSelfieSynced,0)=0) THEN 8 
						ELSE CertificationStatus 
					END as CertificationStatus 
					FROM MsmeCertifications 
					WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and (DesktopAccepted = 1 OR CertificationStatus = 17)
				) MsmeCertifications  
			GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END
		ELSE
		BEGIN
			SELECT ISNULL([1],0)+ISNULL([8],0) NotStarted, ISNULL([2],0)+ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM
			(SELECT CertificationStatus, Count(*) Cnt FROM 
				(
					SELECT CASE 
						WHEN CertificationStatus=9 AND ISNULL(IsSelfieSynced,0)=0 THEN 8 
						ELSE CertificationStatus 
					END as CertificationStatus 
					FROM MsmeCertifications 
					WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and (DesktopAccepted = 1 OR CertificationStatus = 17)
				) MsmeCertifications 
			GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([1],[2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END




	END

	ELSE IF @RoleId=3
	BEGIN
		SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
		AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,
		CASE WHEN Certification='Bronze' then 'Onsite' else 'Remote' end as ModeOfAssessment,
		FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
		case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
		DaCertificateNo,SaCertificateNo,
		CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
		P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, M.EnterpriseName , U.UserName AgencyName,
		PV.BasicInfoStatus, PV.DocVerifiAllot, PV.DesktopVerification DesktopVerificationCompleted,PV.ScheduledOn, PV.Completed SaCompletedOn,
		UA.UserName as DesktopAssessorName,
		UL.UserName as SiteAssessorName,
		UC.UserName as CoAssessorName,
		CoAssessorId,
		CASE when DesktopAssessorId=@UserId then 'D' else '' end as DeskAssessment, 
		CASE when SiteAssessorId=@UserId then 'S' else '' end as SiteAssessment,
		M.OwnerName as UnitSpocName, M.MobileNo as UnitSpocMobileNo, M.EmailId as UnitSpocEmailId,

		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'	
			WHEN cs.MonitoringGetList is not null then MonitoringGetList
			
			when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Done By MSME'
		end as AssessmentStatus,
		ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber, NcStatus, FORMAT(P.NcFinalClosureDt, 'MMMM d, yyyy') NcFinalClosureDt,
		P.NcFinalClosureDt as NcFinalClosureDtOrg,P.ZedId as RejectedZedId, U.AllowBronzeSurveillance,
		case when B.ReSurveillance>=1 then '2nd Surveillance' else '1st Surveillance' end as SurveillanceNo

		FROM MsmeCertifications P
		--inner join Msme M on (replace(P.ZedId,'<redacted>','')=M.ZedId)
		inner join Msme M on (REPLACE(REPLACE(P.Zedid,'_D',''),concat('_',P.Id),'')=M.ZedId)
		INNER JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN CertificationStatuses CS on (P.CertificationStatus=CS.SNo)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users UL on (P.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)

		LEFT JOIN
		(select * from 
		(
		  select ZedId, StatusType, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,CertificationType
		  from MsmeHistory where CertificationType is not null and StatusType is not null and (@CertificationType IS NULL OR CertificationType=@CertificationType)
		) src
		pivot
		(
		  max(CreatedOn)
		  for StatusType in ([BasicInfoStatus], [DocVerifiAllot], [DesktopVerification],[ScheduledOn],[Completed])
		) piv) PV
		on (P.ZedId=PV.ZedId and P.Certification=PV.CertificationType)
		

		--WHERE ((CertificationStatus=ISNULL(@Status,0) and @Status not in (2,3,6)) OR (@Status=2 AND CertificationStatus=1 and DesktopAccepted=1) OR (@Status=3 AND CertificationStatus IN (2,3))  OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='<redacted>')  OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='<redacted>') OR (@Status=2 AND CertificationStatus=8) OR (@Status=7 AND CertificationStatus=7) OR (@Status=7 AND CertificationStatus=17) OR (@Status=99 AND CertificationStatus=99) OR (@Status=2 AND P.ModeOfAssessment='<redacted>' AND CertificationStatus=9 AND JoinRoomStatus=0) OR (@Status=5 AND CertificationStatus=15) OR (@Status=4 AND CertificationStatus=14) OR (@Status=6 AND ((P.Certification='<redacted>' and CertificationStatus IN (5,6)) OR ( P.Certification!='<redacted>' and CertificationStatus IN (15,16)))))
		----WHERE (CertificationStatus=ISNULL(@Status,0)  OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='<redacted>')  OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='<redacted>') OR (@Status=2 AND CertificationStatus=8) OR (@Status=2 AND P.ModeOfAssessment='<redacted>' AND CertificationStatus=9 AND JoinRoomStatus=0) OR (@Status=5 AND CertificationStatus=15) OR (@Status=4 AND CertificationStatus=14) OR (@Status=6 AND CertificationStatus IN (5,15,16)))
		--and ((DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId)) AND (@ZedId IS NULL OR p.ZedId=@ZedId)  and (@NcClosingDate IS NULL OR CONVERT(NVARCHAR(10), P.NcFinalClosureDt, 101)=@NcClosingDate)
		--and DesktopAccepted=1 
		--and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender) 
		--ORDER By p.CertificationStatusDate desc

		WHERE ((CertificationStatus=ISNULL(@Status,0) and @Status not in (2,3,6)) 
			OR (@Status=2 AND CertificationStatus=1 and DesktopAccepted=1) 
			OR (@Status=3 AND CertificationStatus IN (2,3))  
			
			-- మార్పు: '<redacted>' కి Selfie Sync అవ్వాలి (Remote కాని వాటికి)
			OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='Remote Assessment' AND IsSelfieSynced = 1)  
			
			OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='Remote Assessment') 
			OR (@Status=2 AND CertificationStatus=8) 
			
			-- మార్పు: '<redacted>' కి Selfie Sync అవ్వకూడదు (Remote కాని వాటికి)
			OR (@Status=2 AND CertificationStatus=9 AND P.ModeOfAssessment!='Remote Assessment' AND ISNULL(IsSelfieSynced,0) = 0) 
			
			OR (@Status=7 AND CertificationStatus=7) 
			OR (@Status=7 AND CertificationStatus=17) 
			OR (@Status=99 AND CertificationStatus=99) 
			OR (@Status=2 AND P.ModeOfAssessment='Remote Assessment' AND CertificationStatus=9 AND JoinRoomStatus=0) 
			OR (@Status=5 AND CertificationStatus=15) 
			OR (@Status=4 AND CertificationStatus=14) 
			OR (@Status=6 AND ((P.Certification='Bronze' and CertificationStatus IN (5,6)) OR ( P.Certification!='Bronze' and CertificationStatus IN (15,16)))))
		and ((DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId)) AND (@ZedId IS NULL OR p.ZedId=@ZedId)  and (@NcClosingDate IS NULL OR CONVERT(NVARCHAR(10), P.NcFinalClosureDt, 101)=@NcClosingDate)
		and DesktopAccepted=1 
		and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender) 
		ORDER By p.CertificationStatusDate desc


		--IF @CertificationType='<redacted>'
		--BEGIN
		--	SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM
		--	(SELECT CertificationStatus, Count(*) Cnt FROM 
		--	(select CASE WHEN JoinRoomStatus=0 and CertificationStatus=9 then 8 else CertificationStatus end as CertificationStatus from MsmeCertifications 
		--	WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and DesktopAccepted=1)
		--	MsmeCertifications  GROUP BY CertificationStatus) src
		--	PIVOT
		--	(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		--END

		--ELSE
		--BEGIN
		--	SELECT ISNULL([1],0)+ISNULL([8],0) NotStarted, ISNULL([2],0)+ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc,ISNULL([7],0)+ISNULL([17],0) Rj FROM
		--	(SELECT CertificationStatus, Count(*) Cnt FROM MsmeCertifications WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and DesktopAccepted=1 GROUP BY CertificationStatus) src
		--	PIVOT
		--	(max(cnt) for CertificationStatus in ([1],[2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		--END

		IF @CertificationType='Silver'
		BEGIN
			SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM
			(SELECT CertificationStatus, Count(*) Cnt FROM 
				(
					SELECT CASE 
						WHEN  (CertificationStatus=9 AND ISNULL(IsSelfieSynced,0)=0) THEN 8 
						ELSE CertificationStatus 
					END as CertificationStatus 
					FROM MsmeCertifications 
					WHERE Certification=@CertificationType 
					  AND DesktopAccepted=1
					  AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId) -- ఇక్కడ యాడ్ చేశాను
				) MsmeCertifications  
			GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END
		ELSE
		BEGIN
			SELECT ISNULL([1],0)+ISNULL([8],0) NotStarted, ISNULL([2],0)+ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc,ISNULL([7],0)+ISNULL([17],0) Rj FROM
			(SELECT CertificationStatus, Count(*) Cnt FROM 
				(
					SELECT CASE 
						WHEN CertificationStatus=9 AND ISNULL(IsSelfieSynced,0)=0 THEN 8 
						ELSE CertificationStatus 
					END as CertificationStatus 
					FROM MsmeCertifications 
					WHERE Certification=@CertificationType 
					  AND DesktopAccepted=1
					  AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId) -- ఇక్కడ యాడ్ చేశాను
				) MsmeCertifications 
			GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([1],[2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END



	END

END







GO
/****** Object:  StoredProcedure [dbo].[SP_MONITORING_RA_APPLICANT_ACCEPTANCE]    Script Date: 9/19/2026 4:33:27 AM ******/
