		declare @NcCount int = 0
		declare @Agency varchar(100) = NULL

		select @CertificationType=Certification,@NcCount=NcCount,@Agency=CertificationBodyUserId from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@UserId and CertificationStatus=16

