/****** Object:  StoredProcedure [dbo].[SP_MONITORING_REJECT_FINAL_SUBMIT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MONITORING_REJECT_FINAL_SUBMIT] 
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN

	
				--IF @CertificationType='<redacted>'
				--BEGIN
				--	UPDATE Msme SET IsBronzePaymentDone=null where ZedId=@ZedId
				--END
			
				--IF @CertificationType='<redacted>'
				--BEGIN
				--	UPDATE Msme SET IsSilverPaymentDone=null where ZedId=@ZedId
				--END
			
				--IF @CertificationType='<redacted>'
				--BEGIN
				--	UPDATE Msme SET IsGoldPaymentDone=null where ZedId=@ZedId
				--END
			

				UPDATE MsmeCertifications SET CertificationStatusDate=getdate(),CertificationStatus=99 where  ZedId=@ZedId and Certification=@CertificationType

				update ZEDCS_V2_LIVE.dbo.MsmeCertifications set CertificationPhase = 'WITHDRAWN' where  ZedId=@ZedId and Certification=@CertificationType

				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('Unit Rejected due to Non submission of docs in nc5 On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Unit Rejected due to NCs')

				-- 2. STOP BENEFITS IMMEDIATELY
				UPDATE ZEDCS_V2_LIVE.dbo.MsmeBasicInformation SET IsEligibleForBenefits = 0 WHERE ZedId = @ZedId AND IsEligibleForBenefits = 1;

				-- ENABLE RECERTIFICATION BUTTON FOR SILVER AND GOLD
				IF @CertificationType IN ('Silver', 'Gold')
				BEGIN
					DECLARE @CustomHistoryMsg2 VARCHAR(255) = 'ReCertification Enabled due to Surveillance Rejection (NC Docs)';					
					EXEC ZEDCS_V2_LIVE.[dbo].[SP_JOB_ENABLE_FOR_RE_CERTIFICATION] @ZedId, @CertificationType, @CustomHistoryMsg2;
				END

END


