/****** Object:  StoredProcedure [dbo].[SP_MONITORING_SEND_BACK_TO_ASSESSOR]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MONITORING_SEND_BACK_TO_ASSESSOR] --'<redacted>', null, null,'<redacted>', '<redacted>'
(
	@ZedId varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId	varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@SendBackRemarks varchar(2000) = NULL
    
	
)
AS
BEGIN

	DECLARE @NcNumber int = NULL,
	@CertiStatus int = NULL,
	@NewCertiStatus int = NULL,
	@ExactNcStatus int = NULL,
	@Nc5Status int = NULL

	----FINDING THE PRESENT CERTIFICATION STATUS, NCCOUNT
	select @NcNumber=NcCount,@CertiStatus=CertificationStatus,
	@NewCertiStatus=case 
	WHEN PreviousCertificationStatus IS NOT NULL THEN PreviousCertificationStatus
	when (NcCount=0 and Certification='Bronze') then 3 when (NcCount>0 and Certification='Bronze') then 4 
	when (NcCount=0 and Certification in ('Silver','Gold')) then 13 when  (NcCount>0 and Certification in ('Silver','Gold')) then 14
	end		
	from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType

	------FINDING THE EXACT NC COUNT TO SEND BACK REJECTION TO ASSESSOR------
	SELECT @Nc5Status=Nc5Status, @ExactNcStatus= CASE
        WHEN Nc5Status <> 0 THEN 5
        WHEN Nc4Status <> 0 THEN 4
        WHEN Nc3Status <> 0 THEN 3
        WHEN Nc2Status <> 0 THEN 2
        WHEN Nc1Status <> 0 THEN 1
        ELSE 0 END
FROM MsmeCertifications where ((Certification='Bronze' and CertificationStatus=7) OR (Certification!='Bronze' and CertificationStatus=17)) 
and ZedId=@ZedId and Certification=@CertificationType



	---THIS BLOCK IS TO CHECK AND UPDATE FROM QC TO ASSESSOR-------
	IF @NcNumber<=5 AND (@CertiStatus=5 OR @CertiStatus=15)
	BEGIN
		IF @CertificationType='Bronze'
		BEGIN
			UPDATE MsmeCertifications set CertificationStatus=@NewCertiStatus, SendBackStatus=1, PreviousCertificationStatus = NULL where ZedId=@ZedId and Certification=@CertificationType and NcCount<=5 AND CertificationStatus=5

			INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
			VALUES (@ZedId,@CertificationType,@NcNumber,@SendBackRemarks,GETDATE(),'SB')
			
			insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Send back from QC to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Send back from QC to Assessor' )
		END
		ELSE
		BEGIN
			UPDATE MsmeCertifications set CertificationStatus=@NewCertiStatus, SendBackStatus=1, PreviousCertificationStatus = NULL where ZedId=@ZedId and Certification=@CertificationType and NcCount<=5 AND CertificationStatus=15

			INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
			VALUES (@ZedId,@CertificationType,@NcNumber,@SendBackRemarks,GETDATE(),'SB')

			insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Send back from QC to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Send back from QC to Assessor' )
		END
		

	END

	ELSE
	BEGIN
		IF @CertificationType='Bronze'
		BEGIN
			UPDATE MsmeCertifications set NcCount=@ExactNcStatus,CertificationStatus=@NewCertiStatus,SendBackStatus=1, CertificationStatusDate=getdate(), PreviousCertificationStatus = NULL where ZedId=@ZedId and Certification=@CertificationType and NcCount=6
			IF @Nc5Status=2
			BEGIN
				UPDATE MsmeCertifications set NcStatus=2, CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and Nc5Status=2

				INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
				VALUES (@ZedId,@CertificationType,6,@SendBackRemarks,GETDATE(),'RJ')

				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('Agency send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Agency Send back to Assessor' )
			END
			ELSE
			BEGIN
				INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
				VALUES (@ZedId,@CertificationType,6,@SendBackRemarks,GETDATE(),'RJ')

				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('MasterAdmin send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'MasterAdmin Send back to Assessor from Rejection' )

				insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('MasterAdmin send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'MasterAdmin Send back to Assessor from Rejection' )
			END
		END
		ELSE
		BEGIN
			UPDATE MsmeCertifications set NcCount=@ExactNcStatus,CertificationStatus=@NewCertiStatus,SendBackStatus=1, CertificationStatusDate=getdate(), PreviousCertificationStatus = NULL where ZedId=@ZedId and Certification=@CertificationType and NcCount=6
			IF @Nc5Status=2
			BEGIN
				UPDATE MsmeCertifications set NcStatus=2, CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and Nc5Status=2

				INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
				VALUES (@ZedId,@CertificationType,6,@SendBackRemarks,GETDATE(),'RJ')

				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('Agency send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Agency Send back to Assessor' )
			END

			ELSE
			BEGIN
				INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
				VALUES (@ZedId,@CertificationType,6,@SendBackRemarks,GETDATE(),'RJ')

				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('MasterAdmin send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'MasterAdmin Send back to Assessor from Rejection' )

				insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('MasterAdmin send back to Assessor On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'MasterAdmin Send back to Assessor from Rejection' )
			END

		END

		--BEGIN
		--	UPDATE MsmeCertifications set NcCount=5,CertificationStatus=4,NcStatus=2, SendBackStatus=1,CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and NcCount=6
		--END
		--ELSE
		--BEGIN
		--	UPDATE MsmeCertifications set NcCount=5,CertificationStatus=14,NcStatus=2, SendBackStatus=1,CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and NcCount=6
		--END

		--INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
		--VALUES (@ZedId,@CertificationType,6,@SendBackRemarks,GETDATE(),'<redacted>')

		--insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		--values (@ZedId,concat('<redacted>',FORMAT(getdate(), '<redacted>')),getdate(),@CertificationType,'<redacted>' )
	END

END




