CREATE PROCEDURE [dbo].[SP_MOVING_TO_MASTERADMIN_FOR_REALLOCATION] --'<redacted>','<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	

	SET NOCOUNT ON;

	IF EXISTS (select * from MsmeCertifications where ZedId=@ZedId and Certification=@Certification and CertificationStatus in (2,3))
	BEGIN

		UPDATE MsmeCertifications set CertificationBodyUserId=null,AcceptOrRejectDate=null,DesktopAssessorId=null,CertificationStatus=2,
		DesktopAccepted=null,DesktopAcceptOrRejectDate=null where ZedId=@ZedId and CertificationStatus in (2,3) and Certification=@Certification

		UPDATE MsmeHistory set ZedId=zedid+'delete' where ZedId=@ZedId and StatusType='DocVerifiAllot' and CertificationType=@Certification


		insert into BackendChangesHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Revert to Master admin for Re-Allocation On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@certification,'Revert to Master Admin for Re-allocation' )
	
	END
	ELSE
	BEGIN
		SELECT 'PLEASE ENTER CORRECT DETAILS'
	END

END

