/****** Object:  StoredProcedure [dbo].[SP_MSME_AUTO_ALLOT_AGENCY_ROUND_ROBIN]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

--[SP_SEND_MAIL_AUTO_ALLOT_AGENCY] '<redacted>', '<redacted>'

CREATE PROCEDURE [dbo].[SP_MSME_AUTO_ALLOT_AGENCY_ROUND_ROBIN] --'<redacted>', '<redacted>'
(
	@ZedId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	
			DECLARE @LastUserId varchar(50) = NULL
			DECLARE @LastId int = NULL
			DECLARE @NextUserId varchar(50) = NULL
			DECLARE @AgencyId varchar(100) = NULL
			DECLARE @DistrictCode varchar(100) = NULL
			DECLARE @StateCode varchar(100) = NULL
			DECLARE @DistrictLevelExists int = 0

			select @StateCode=StateId from Msme where ZedId=@ZedId
			select @DistrictCode=LgDistrictCode from MsmeBasicInformation where ZedId=@ZedId

			select @DistrictLevelExists=count(*) from AgencyUserDistricts where Districts = @DistrictCode

			SELECT TOP 1 @LastUserId = AgencyId FROM AgencyAllotmentHistory WHERE AllotType = 'Auto' AND CertificationType = 'Bronze' ORDER BY Id DESC
			SELECT @LastId = Id FROM Users WHERE UserId = @LastUserId

			IF @DistrictLevelExists>0
			BEGIN
				SELECT TOP 1 @NextUserId = U.UserId FROM Users U WHERE U.RoleId = 2 AND U.AllowBronzeSurveillance = 1 AND U.IsActive = 1 AND TuPreferredState=@StateCode --AND U.UserId NOT IN ('<redacted>','<redacted>','<redacted>')
				  AND (
						EXISTS (
							SELECT 1 FROM AgencyUserDistricts AUD
							WHERE AUD.UserId = U.UserId AND AUD.Districts = @DistrictCode
						)					
					)
				  AND U.Id > @LastId 
				ORDER BY U.Id
			END
			ELSE
			BEGIN
				SELECT TOP 1 @NextUserId = U.UserId FROM Users U WHERE U.RoleId = 2 AND U.AllowBronzeSurveillance = 1 AND U.IsActive = 1 AND TuPreferredState=@StateCode --AND U.UserId NOT IN ('<redacted>','<redacted>','<redacted>')
				  AND U.Id > @LastId 
				ORDER BY U.Id

			END

			IF (@NextUserId IS NULL)
			BEGIN
				IF @DistrictLevelExists>0
				BEGIN
					SELECT TOP 1 @NextUserId = U.UserId FROM Users U WHERE U.RoleId = 2 AND U.AllowBronzeSurveillance = 1 AND U.IsActive = 1 AND TuPreferredState=@StateCode --AND U.UserId NOT IN ('<redacted>','<redacted>','<redacted>')
					  AND (
							EXISTS (
								SELECT 1 FROM AgencyUserDistricts AUD
								WHERE AUD.UserId = U.UserId AND AUD.Districts = @DistrictCode
							)					
						)
				  
					ORDER BY U.Id
				END
				ELSE
				BEGIN
					SELECT TOP 1 @NextUserId = U.UserId FROM Users U WHERE U.RoleId = 2 AND U.AllowBronzeSurveillance = 1 AND U.IsActive = 1 AND TuPreferredState=@StateCode --AND U.UserId NOT IN ('<redacted>','<redacted>','<redacted>')
				   
					ORDER BY U.Id

				END
				
			END

			if @NextUserId is not null
			BEGIN
			-- Update certification with selected agency
			UPDATE MsmeCertifications SET CertificationBodyUserId = @NextUserId, AutoAllocationDate=getdate() WHERE ZedId = @ZedId 
			AND Certification = @CertificationType AND CertificationBodyUserId IS NULL AND NcCount = 0

			-- Insert into history
			
				INSERT INTO AgencyAllotmentHistory (AgencyId, ZedId, CertificationType, AllotType, CreatedDate)
				VALUES (@NextUserId, @ZedId, @CertificationType, 'Auto', GETDATE())
			END


				--EXEC [SP_SEND_MAIL_AUTO_ALLOT_AGENCY_ROUND_ROBIN] @ZedId, @NextUserId



END
GO
