-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

--[SP_SEND_MAIL_AUTO_ALLOT_AGENCY] '<redacted>', '<redacted>'

CREATE PROCEDURE [dbo].[SP_MSME_AUTO_ALLOT_AGENCY_ROUND_ROBIN_OLD] --'<redacted>', '<redacted>'
(
	@ZedId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	
			DECLARE @LastUserId varchar(50) = NULL
			DECLARE @LastId varchar(50) = NULL
			DECLARE @NextUserId varchar(50) = NULL

			select TOP 1 @LastUserId=AgencyId from AgencyAllotmentHistory where AllotType='Auto' and CertificationType='Bronze' order by Id desc
			select @LastId=Id from Users where UserId=@LastUserId

			select top 1 @NextUserId=UserId from Users where RoleId=2 and AllowBronzeSurveillance=1 and IsActive=1 and Id>@LastId order by id

			IF (@NextUserId is null)
			BEGIN
				select top 1 @NextUserId=UserId from Users where RoleId=2 and AllowBronzeSurveillance=1 and IsActive=1 order by id
			END


			----update certifications table with auto agency-----
			UPDATE MsmeCertifications SET CertificationBodyUserId=@NextUserId WHERE ZedId=@ZedId and Certification=@CertificationType and CertificationBodyUserId is null and NcCount=0

						-- Insert record into AgencyAllotmentHistory
			INSERT INTO AgencyAllotmentHistory (AgencyId, ZedId, CertificationType, AllotType,  CreatedDate)
			VALUES (@NextUserId, @ZedId, @CertificationType, 'Auto', GETDATE())

		--	EXEC [SP_SEND_MAIL_AUTO_ALLOT_AGENCY_ROUND_ROBIN] @ZedId, @NextUserId


	


END
