CREATE PROC [dbo].[SP_MSME_DISABLE_PLANT]
(
	@ZedId varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId	varchar(50) = NULL,
	@DisableRemarks varchar(2000) = NULL
	
)
AS


BEGIN

		BEGIN TRY
			BEGIN TRAN

	insert into MsmeDeletedRecords 
		  (MsmeId,ZedId,StateId,StateName,DistrictId,DistrictName,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,EnterpriseType,EnterpriseTypee,MobileNo,EmailId,ApplicationId
		  ,UamNumber,PFlat,PBuilding,PRoad,PArea,PCity,PAddress,PPin,PStateId,PStateName,PLgDistrictCode,PDistrictName,PPlantDetailId,Activity,TwoDigitActivity,FourDigitActivity,FiveDigitActivity
		  ,ActivityDetailId,PledgeEmailId,IsBronzePaymentDone,IsSilverPaymentDone,IsGoldPaymentDone,IsCouponUsed,PledgeCertificateNo,RegistrationType,IncorporationDate,WhetherProdCommenced
		  ,PlantIdNo,PUnitName,PUnitIdNo,CreatedDate,RegistrationFrom,FinancialAssistanceStatus,WashWebinarCertificateNo,WashCertificateNo,QrCodeNo,DisableRemarks, DisabledBy, DisabledRole)

	SELECT MsmeId,ZedId,StateId,StateName,DistrictId,DistrictName,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,EnterpriseType,EnterpriseTypee,MobileNo,EmailId,ApplicationId
		  ,UamNumber,PFlat,PBuilding,PRoad,PArea,PCity,PAddress,PPin,PStateId,PStateName,PLgDistrictCode,PDistrictName,PPlantDetailId,Activity,TwoDigitActivity,FourDigitActivity,FiveDigitActivity
		  ,ActivityDetailId,PledgeEmailId,IsBronzePaymentDone,IsSilverPaymentDone,IsGoldPaymentDone,IsCouponUsed,PledgeCertificateNo,RegistrationType,IncorporationDate,WhetherProdCommenced
		  ,PlantIdNo,PUnitName,PUnitIdNo,CreatedDate,RegistrationFrom,FinancialAssistanceStatus,WashWebinarCertificateNo,WashCertificateNo,QrCodeNo,@DisableRemarks, @UserId, @RoleId 
		  FROM MSME where ZedId=@ZedId

		 
	
	INSERT INTO MsmeBasicInformationDeletedRecords(
		   Id,MsmeId,ApplicationId,UdyogAadharNo,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,SocialCategory,SocialCategoryName,Gender,PH,PanNo,Address,StateId,StateName,DistrictId
		  ,DistrictName,LgDistrictCode,Pincode,MobileNo,EmailId,MajorActivity,MajorActivityName,EnterpriseType,EnterpriseTypee,CommmenceDate,PreviousEMType,PreviousEMNumber,TotalEmp,InvestmentCost
		  ,DicName,AppliedDate,ZedId,LastestCertification)

	SELECT Id,MsmeId,ApplicationId,UdyogAadharNo,OwnerName,EnterpriseName,OrganisationType,OrganisationTypeName,SocialCategory,SocialCategoryName,Gender,PH,PanNo,Address,StateId,StateName,DistrictId
		  ,DistrictName,LgDistrictCode,Pincode,MobileNo,EmailId,MajorActivity,MajorActivityName,EnterpriseType,EnterpriseTypee,CommmenceDate,PreviousEMType,PreviousEMNumber,TotalEmp,InvestmentCost
		  ,DicName,AppliedDate,ZedId,LastestCertification FROM MsmeBasicInformation where ZedId=@ZedId

		  

	INSERT INTO MsmeCertificationsDeletedRecords(
		   Id,ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId
		  ,AcceptOrRejectDate,ReasonForRejection,DesktopAssessorId,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection
		  ,NcCount,CertificationStatus,CertificationStatusDate,DaCertificateNo,SaCertificateNo,AssessorRemarks,NcStatus,Nc1Status,Nc2Status,Nc3Status,Nc4Status,Nc5Status,SaAssessorRemarks
		  ,IsSaVerified,IsSaSelfieSubmitted,SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources,CreatedDate,JoinRoomStatus
		  ,QrCodeSeqNo,NcFinalClosureDt)

	SELECT Id,ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId
		  ,AcceptOrRejectDate,ReasonForRejection,DesktopAssessorId,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection
		  ,NcCount,CertificationStatus,CertificationStatusDate,DaCertificateNo,SaCertificateNo,AssessorRemarks,NcStatus,Nc1Status,Nc2Status,Nc3Status,Nc4Status,Nc5Status,SaAssessorRemarks
		  ,IsSaVerified,IsSaSelfieSubmitted,SaAuditsConducted,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources,CreatedDate,JoinRoomStatus
		  ,QrCodeSeqNo,NcFinalClosureDt FROM MsmeCertifications where ZedId=@ZedId


		  UPDATE Users SET IsActive=0 where UserId=@ZedId

		  DELETE FROM Msme where ZedId=@ZedId
		  DELETE FROM MsmeBasicInformation where ZedId=@ZedId
		  DELETE FROM MsmeCertifications where ZedId=@ZedId	

			COMMIT TRAN

		  END TRY

     BEGIN CATCH
             ROLLBACK TRAN
			 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

     END CATCH



END




GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_GET_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_MSME_GET_DETAILS] null, '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_MSME_GET_DETAILS] --null, '<redacted>', '<redacted>'
(
	@MsmeId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

		DECLARE @CurrentUrl varchar(100) = NULL
		SELECT @CurrentUrl=UrlName from UrlsMasterData

		DECLARE @LatestCertification varchar(100) = NULL,
				@DateOfAvail varchar(50) = NULL,
				@JoiningRewardAmount varchar(50) = '10000',

				@LevelOfCertificationForFa varchar(100) = NULL,
				@DateOfFaAvail varchar(100) = NULL,
				@FaAmount varchar(100) = NULL,
				@FaReferenceNo varchar(100) = NULL,
				@FaCertificationCategory varchar(100) = NULL


				select top 1 @LatestCertification=Certification,@DateOfAvail=FORMAT(CreatedDate, 'MMMM d, yyyy') from MsmePaymentInfo where ZedId=@ZedId and UseCoupon='Yes' order by CreatedDate desc

				select top 1 @LevelOfCertificationForFa=CertificationType,
				@DateOfFaAvail=ApproverDateOfReceiptOfPayment, @FaAmount=ApproverAmount, @FaReferenceNo=ApproverReferenceNo,
				@FaCertificationCategory=CategoryOfCertificate
				from FinancialAssistance where ZedId=@ZedId order by CreatedDate desc

		if @MsmeId IS NULL
			SELECT @MsmeId = MsmeId from msme where ZedId=@ZedId

		SELECT M.*,FORMAT(M.CreatedDate, 'MMMM d, yyyy') as PledgeOn,@LatestCertification LatestCertification,@DateOfAvail DateOfAvail,@JoiningRewardAmount JoiningRewardAmount,
		case when B.ReSurveillance>0 then 2 ELSE 0 end as MileStoneNo FROM Msme M inner join MsmeBasicInformation B on (M.ZedId=B.Zedid) Where M.MsmeId=@MsmeId
		
		--SELECT * FROM MsmeBasicInformation Where MsmeId=@MsmeId


		SELECT *, case when ReSurveillance>0 then concat(@CertificationType,'_Milestone2_Payment_Receipt.pdf') ELSE concat(@CertificationType,'_Milestone0_Payment_Receipt.pdf') end as PaymentReceiptName,
		case when ReSurveillance>0 then 'Second Surveillance' ELSE 'Surveillance' end as SurveOrReSurve
		FROM MsmeBasicInformation Where ZedId=@ZedId --MsmeId=@MsmeId
		
		

		DECLARE @StateId int = NULL
		SELECT @StateId=StateId from Msme where ZedId=@ZedId

	

				SELECT
			CASE WHEN EXISTS (SELECT CertificationStatus from MsmeCertifications where ZedId=@Zedid AND Certification='Bronze' ) THEN 
				(SELECT ISNULL((SELECT ISNULL(CertificationStatus,0) BronzeStatus FROM MsmeCertifications where ZedId=@Zedid AND Certification='Bronze'),0))
			ELSE
			(SELECT ISNULL(IsBronzePaymentDone,0) BronzeStatus from Msme where ZedId=@Zedid) END AS BronzeStatus,

			CASE WHEN EXISTS (SELECT CertificationStatus from MsmeCertifications where ZedId=@Zedid AND Certification='Silver' ) THEN 
				(SELECT ISNULL((SELECT ISNULL(CertificationStatus,0) SilverStatus FROM MsmeCertifications where ZedId=@Zedid AND Certification='Silver'),0))
			ELSE
			(SELECT ISNULL(IsSilverPaymentDone,0) SilverStatus from Msme where ZedId=@Zedid) END AS SilverStatus,

			CASE WHEN EXISTS (SELECT CertificationStatus from MsmeCertifications where ZedId=@Zedid AND Certification='Gold' ) THEN 
				(SELECT ISNULL((SELECT ISNULL(CertificationStatus,0) GoldStatus FROM MsmeCertifications where ZedId=@Zedid AND Certification='Gold'),0))
			ELSE
			(SELECT ISNULL(IsGoldPaymentDone,0) GoldStatus from Msme where ZedId=@Zedid) END AS GoldStatus,
			(select FinancialAssistanceStatus from Msme where ZedId=@ZedId)  FinancialAssistanceStatus,
			(select count(*) from ZED_CONSULTANT.dbo.MsmePaymentInfo where ZedId=@Zedid)  ConsultancyStatus,
			@LevelOfCertificationForFa LevelOfCertificationForFa,
				@DateOfFaAvail DateOfFaAvail,
				@FaAmount FaAmount,
				@FaReferenceNo FaReferenceNo,
				@FaCertificationCategory FaCertificationCategory,

				(SELECT 
			CASE WHEN CertificationStatusDate < DATEADD(HOUR, 1, CAST(CAST(GETDATE() AS DATE) AS DATETIME))  THEN 'Surveillance/Certifications' ELSE 'Surveillance/Certificates' END AS CertificationPath
			FROM MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType) SurveCertPath


			 --'<redacted>'  SurveCertPath

				select 
				[ApplicationReceived],
				ISNULL([BasicInfoStatus], 'In-progress') [BasicInfoStatus],
				1 as [DesktopVerification],
				1 as [BronzeDesktopVerification],
				--case when  [BasicInfoStatus] is not null and  [DesktopVerification] is null then '<redacted>' else [DesktopVerification] end as [DesktopVerification],
				--case when  [BasicInfoStatus] is not null  then '<redacted>' else NULL end as [BronzeDesktopVerification],
				[ScheduledOn],
				Completed as [CompletedOn],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],			
				case when @CertificationType='Bronze' then concat(@CurrentUrl + '/Incentive/Details/',@StateId,'?ct=Bronze') 
					 when @CertificationType='Silver' then concat(@CurrentUrl + '/Incentive/Details/',@StateId,'?ct=Silver') 
					 when @CertificationType='Gold' then concat(@CurrentUrl + '/Incentive/Details/',@StateId,'?ct=Gold') end as AvailIncentive,
				[ApplicationReceived],
				[NcFinalClosureDate]			
				from 
				(select Descrip,StatusType from MsmeHistory where ZedId=@ZedId and CertificationType=@CertificationType and statustype is not null) A
				pivot (
				max(descrip) for StatusType in (
				[BasicInfoStatus],
				[DesktopVerification],
				[ScheduledOn],
				[Completed],
				[Nc1Raised],
				[Nc1Submitted],
				[Nc2Raised],
				[Nc2Submitted],
				[Nc3Raised],
				[Nc3Submitted],
				[Nc4Raised],
				[Nc4Submitted],
				[Nc5Raised],
				[Nc5Submitted],
				[NcClosed],
				[GetCertified],
				[ApplicationReceived],
				[NcFinalClosureDate]) ) as Pvt
	

		select top 1 *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) SubsidyCoupon,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel from MsmePaymentInfo where ZedId=@ZedId and (@CertificationType is null OR Certification=@CertificationType) order by id desc

		select U.Email AutoEmailForAgency from MsmeCertifications M
		inner join Users U on (M.CertificationBodyUserId=U.UserId and RoleId=2 and U.IsActive=1)
		where ZedId=@zedid and Certification=@CertificationType and NcCount=0
	
END

GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_GET_FILE_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_GET_FILE_DETAILS] --'<redacted>',5,'<redacted>','<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@Type varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @RoleId=5
	BEGIN
	SET @ZedId=@UserId
	END

	DECLARE @Url varchar(100) = NULL
	SET @Url = 'E:\Publish\ZED_SURVEILLANCE\ZED_SURVEILLANCE\'

	DECLARE @WebinarCertificateNo varchar(50) = NULL,
			@WashId varchar(50) = NULL

	IF @Certification in ('Pledge','Wash','Webinar')
	BEGIN
		IF(select count(*) from Msme where zedid=@ZedId AND (@RoleId=7 OR (@ZedId=@UserId AND @RoleId=5)))=0
		SET @ZedId='000'
		ELSE 
		SET @ZedId=@ZedId					
	END
	ELSE IF (@Type='Evidence')
	BEGIN
		IF(select count(*) from MsmeCertifications where zedid=@ZedId and ((DesktopAssessorId=@UserId and @RoleId=3) OR (SiteAssessorId=@UserId and @RoleId=3) OR (CoAssessorId=@UserId and @RoleId=3) OR (CertificationBodyUserId=@UserId AND @RoleId=2) OR (@RoleId=7) OR (@RoleId=10) OR (@RoleId=11) OR (@RoleId=8) OR (ZedId=@UserId AND ( @RoleId=5))))=0
		BEGIN
			SET @ZedId='000'
		END
		ELSE 
		SET @ZedId=@ZedId	
	END
	ELSE
	BEGIN
		IF(select count(*) from MsmeCertifications where zedid=@ZedId and Certification=@Certification and ((DesktopAssessorId=@UserId and @RoleId=3) OR (SiteAssessorId=@UserId and @RoleId=3) OR (CertificationBodyUserId=@UserId AND @RoleId=2) OR (@RoleId=7) OR (@RoleId=10) OR (@RoleId=11) OR (@RoleId=8) OR (ZedId=@UserId AND ( @RoleId=5))))=0
		BEGIN
			SET @ZedId='000'
		END
	END

	
	IF @Type='Certificate'
	BEGIN
		IF @Certification='Pledge'
		BEGIN
			SELECT CONCAT(@Url,'Certificates\',@ZedId,'\Pledge.pdf') FilePath, 'Pledge.pdf' FileName
		END
		ELSE IF @Certification='Bronze'
		BEGIN
			SELECT CONCAT(@Url,'Certificates\DA\',@ZedId,'\Bronze.pdf') FilePath, 'Bronze.pdf' FileName
		END
		ELSE IF @Certification='Silver'
		BEGIN
			SELECT CONCAT(@Url,'Certificates\SA\',@ZedId,'\Silver.pdf') FilePath, 'Silver.pdf' FileName
		END
		ELSE IF @Certification='Gold'
		BEGIN
			SELECT CONCAT(@Url,'Certificates\SA\',@ZedId,'\Gold.pdf') FilePath, 'Gold.pdf' FileName
		END
		ELSE IF @Certification='Wash'
		BEGIN
			SELECT @WashId=ZedId FROM Kawach.dbo.MsmeCertifications WHERE DaCertificateNo in (select WashCertificateNo from Msme where ZedId=@ZedId)
			SELECT CONCAT('D:\Publish\KAWACH\Certificates\DA\',@WashId,'\Bronze.pdf') FilePath, 'Wash.Pdf' FileName
		END
		ELSE IF @Certification='Webinar'
		BEGIN
			SELECT @WebinarCertificateNo=WashWebinarCertificateNo FROM Msme WHERE ZedId=@ZedId			
			SELECT CONCAT('D:\Publish\KAWACH\WebinarCertificates\',@WebinarCertificateNo,'.pdf') FilePath, 'Webinar.Pdf' FileName
		END
		ELSE
		BEGIN
			SELECT '' FilePath, '' FileName
		END
	END

	ELSE IF @Type='Report'
	BEGIN
		IF @Certification='Bronze'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Bronze_Report.pdf') FilePath, 'Bronze_Report.pdf' FileName
		END
		ELSE IF @Certification='Silver'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Silver_Report.pdf') FilePath, 'Silver_Report.pdf' FileName
		END
		ELSE IF @Certification='Gold'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Gold_Report.pdf') FilePath, 'Gold_Report.pdf' FileName
		END
		--ELSE IF @Certification='<redacted>'
		--BEGIN
		--	SELECT CONCAT('<redacted>',@ZedId,'<redacted>') FilePath, '<redacted>' FileName
		--END
		ELSE
		BEGIN
			SELECT '' FilePath, '' FileName
		END
	END
	
	ELSE IF @Type='Receipt'
	BEGIN
		IF @Certification='Bronze'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Bronze_Payment_Receipt.pdf') FilePath, 'Bronze_Payment_Receipt.pdf' FileName
		END
		ELSE IF @Certification='Silver'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Silver_Payment_Receipt.pdf') FilePath, 'Silver_Payment_Receipt.pdf' FileName
		END
		ELSE IF @Certification='Gold'
		BEGIN
			SELECT CONCAT(@Url,'PDFs\SA\',@ZedId,'\Gold_Payment_Receipt.pdf') FilePath, 'Gold_Payment_Receipt.pdf' FileName
		END
		ELSE
		BEGIN
			SELECT '' FilePath, '' FileName
		END
	END

	ELSE IF @Type='Document'
	BEGIN
		SELECT CONCAT(@Url,'Uploads\Documents\',@Certification) FilePath, @Certification FileName
	END

	ELSE IF @Type='Evidence'
		BEGIN
			---D:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos\ZEDMSME000020\Bronze\Evidences\20.pdf
			SELECT CONCAT('E:\Publish\ZED_SURVEILLANCE\ZED_SURVEILLANCE_SERVICES\Photos\',@ZedId,'/',SectionType,'/Evidences/',@Certification,'.pdf') FilePath, EvidenceName+'.pdf' FileName from MsmeEvidences where ZedId=@ZedId and EvidenceId=@Certification
		END
	ELSE
		BEGIN
			SELECT '' FilePath, '' FileName
		END

END

GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_GET_MY_DOCUMENTS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_GET_MY_DOCUMENTS] --'<redacted>'
(
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	SELECT @ZedId ZedId, DocumentName, @CurrentUrl + '/' + DocumentPath DocumentPath, OrderNo FROM MyDocuments ORDER BY OrderNo

    SELECT @ZedId ZedId, @CurrentUrl + '/Certificates/'+@ZedId+'/Pledge.pdf' Pledge,
	(select case when DaCertificateNo is null then NULL else @CurrentUrl + '/Certificates/DA/'+@ZedId+'/Bronze.pdf' end as Bronze from MsmeCertifications where ZedId=@ZedId and Certification='Bronze') Bronze, 
	(select case when SaCertificateNo is null then NULL else @CurrentUrl + '/Certificates/SA/'+@ZedId+'/Silver.pdf' end as Bronze from MsmeCertifications where ZedId=@ZedId and Certification='Silver') Silver, 
	(select case when SaCertificateNo is null then NULL else @CurrentUrl + '/Certificates/SA/'+@ZedId+'/Gold.pdf' end as Bronze from MsmeCertifications where ZedId=@ZedId and Certification='Gold') Gold, 
	

	(select case when DaCertificateNo is null then NULL else 'https://msmekawach.org.in/Certificates/DA/'+ZedId+'/Bronze.pdf' end as Wash
	from KAWACH.dbo.MsmeCertifications where DaCertificateNo in (
	SELECT WashCertificateNo from msme where zedid=@ZedId)) Wash,
	(select case when WebinarCertificateNo is null then NULL else 'https://msmekawach.org.in/WebinarCertificates/'+WashWebinarCertificateNo+'.pdf' end as Webinar
	from KAWACH.dbo.WebinarRegistrations where WebinarCertificateNo in (
	SELECT WashWebinarCertificateNo from msme where zedid=@ZedId)) Webinar 
	FROM Msme WHERE ZedId=@ZedId

    SELECT @ZedId ZedId, case when IsBronzePaymentDone is null then NULL else @CurrentUrl + '/PDFs/SA/'+@ZedId+'/Bronze_Payment_Receipt.pdf' end as BronzeReceipt,
	case when IsSilverPaymentDone is null then NULL else @CurrentUrl + '/PDFs/SA/'+@ZedId+'/Silver_Payment_Receipt.pdf' end as SilverReceipt,
	case when IsGoldPaymentDone is null then NULL else @CurrentUrl + '/PDFs/SA/'+@ZedId+'/Gold_Payment_Receipt.pdf' end as GoldReceipt, NULL WashReceipt, NULL WebinarReceipt, NULL ConsultancyReceipt FROM Msme WHERE ZedId=@ZedId
END

GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_GET_PAYMENT_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_GET_PAYMENT_DETAILS] --NULL, '<redacted>','<redacted>'
(
	@MsmeId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CertGstNo varchar(50) = null, @CertTanNo varchar(50) = null, @CertTds varchar(50) = null, @CertUnitGstin varchar(50) = null, @CertTdsDeductable varchar(50) = null
	print @CertGstNo
	select @CertGstNo=GstinNumber,@CertTanNo=TanNumber,@CertTds=Tds,@CertUnitGstin=UnitGstin,@CertTdsDeductable=TdsDeductible  from ZEDCS_V2_LIVE.DBO.MsmePaymentInfo where ZedId=@ZedId AND Certification=@Certification
	print concat('gst-',@CertGstNo,' tan-', @CertTanNo,' tds-', @CertTds)


	DECLARE @EnterpriseTypee varchar(50), @SpecialCategory varchar(50), @IsAspirationalDt varchar(50), @SubsidyUsed bit = 0,
	@PanNo varchar(50) =NULL
	
	select @IsAspirationalDt=IsAspirationalDt from Districts where DistrictCode in (select PLgDistrictCode from Msme where ZedId=@ZedId)

	if @MsmeId IS NULL
		SELECT @MsmeId = MsmeId from msme where ZedId=@ZedId

		SELECT @EnterpriseTypee=EnterpriseTypee FROM Msme Where ZedId=@ZedId

		IF EXISTS(SELECT * FROM PaymentGateWayTransactions  where Certification=@Certification and PaymentStatus='success' and ZedId=CONCAT(@ZedId,'_D'))
		SET @SubsidyUsed = 1

    --SELECT @SpecialCategory=1 FROM MsmeBasicInformation Where MsmeId=@MsmeId
	SELECT   @PanNo=PanNo,@SpecialCategory = CASE WHEN Gender='Female' then 1 WHEN SocialCategoryName in ('SC','ST') THEN 1 WHEN @IsAspirationalDt=1 then 1 else 0 END FROM MsmeBasicInformation Where MsmeId=@MsmeId

	IF (select count(*) from MsmeCertifications where ZedId=CONCAT(@ZedId,'_D') and Certification=@Certification)>0 AND @SubsidyUsed=1
	BEGIN
		
		SELECT *,@PanNo UdyamPanNo,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel, @CertGstNo CertGstNo ,@CertTanNo CertTanNo,@CertTds CertTds,@CertUnitGstin CertUnitGstin, @CertTdsDeductable CertTdsDeductable  FROM AssessmentFee WHERE EnterpriseTypee='REJECTED' AND Certification=@Certification AND Coupon IS NOT NULL --AND SpecialCategory IS  NULL	
		print 1
		SELECT *,@PanNo UdyamPanNo,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel, @CertGstNo CertGstNo ,@CertTanNo CertTanNo,@CertTds CertTds,@CertUnitGstin CertUnitGstin, @CertTdsDeductable CertTdsDeductable  FROM AssessmentFee WHERE EnterpriseTypee='REJECTED' AND Certification=@Certification AND Coupon IS NULL --AND SpecialCategory IS  NULL	
		print 2

	END

	ELSE
	BEGIN
		
		SELECT *,@PanNo UdyamPanNo,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel, @CertGstNo CertGstNo ,@CertTanNo CertTanNo,@CertTds CertTds,@CertUnitGstin CertUnitGstin, @CertTdsDeductable CertTdsDeductable  FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory = @SpecialCategory
		print 3
		SELECT *,@PanNo UdyamPanNo,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel, @CertGstNo CertGstNo ,@CertTanNo CertTanNo,@CertTds CertTds,@CertUnitGstin CertUnitGstin, @CertTdsDeductable CertTdsDeductable  FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NULL AND SpecialCategory = @SpecialCategory
		print 4
		--IF @SpecialCategory = 1
		--BEGIN
		--	SELECT *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('<redacted>',cast(SubsidyPercentage as int),'<redacted>','<redacted>') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory = @SpecialCategory
		--	print 3
		--	SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('<redacted>',cast(SubsidyPercentage as int),'<redacted>','<redacted>') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NULL AND SpecialCategory = @SpecialCategory
		--	print 4
		--END
		--ELSE
		--BEGIN
		--	SELECT *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('<redacted>',cast(SubsidyPercentage as int),'<redacted>','<redacted>') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory IS NULL
		--	print 5
		--	SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('<redacted>',cast(SubsidyPercentage as int),'<redacted>','<redacted>') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NULL AND SpecialCategory IS NULL
		--	print 6
		--END
	END

	SELECT  case when IsCouponUsed=1 then 1 else 0 end as IsCouponUsed from msme where ZedId=@ZedId
END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_GET_PAYMENT_DETAILS_old]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
