-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_GET_PAYMENT_DETAILS_old] --NULL, '<redacted>','<redacted>'
(
	@MsmeId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
	DECLARE @EnterpriseTypee varchar(50), @SpecialCategory varchar(50), @IsAspirationalDt varchar(50), @SubsidyUsed bit = 0
	
	select @IsAspirationalDt=IsAspirationalDt from Districts where DistrictCode in (select PLgDistrictCode from Msme where ZedId=@ZedId)

	if @MsmeId IS NULL
		SELECT @MsmeId = MsmeId from msme where ZedId=@ZedId

		SELECT @EnterpriseTypee=EnterpriseTypee FROM Msme Where ZedId=@ZedId

		IF EXISTS(SELECT * FROM PaymentGateWayTransactions  where Certification=@Certification and PaymentStatus='success' and ZedId=CONCAT(@ZedId,'_D'))
		SET @SubsidyUsed = 1

    --SELECT @SpecialCategory=1 FROM MsmeBasicInformation Where MsmeId=@MsmeId
	SELECT  @SpecialCategory = CASE WHEN SocialCategoryName in ('SC','ST') THEN 1 WHEN Gender='Female' then 1 WHEN @IsAspirationalDt=1 then 1 else 0 END FROM MsmeBasicInformation Where MsmeId=@MsmeId

	IF (select count(*) from MsmeCertifications where ZedId=CONCAT(@ZedId,'_D') and Certification=@Certification)>0 AND @SubsidyUsed=1
	BEGIN
		
		SELECT *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee='REJECTED' AND Certification=@Certification AND Coupon IS NOT NULL --AND SpecialCategory IS  NULL	
		print 1
		SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee='REJECTED' AND Certification=@Certification AND Coupon IS NULL --AND SpecialCategory IS  NULL	
		print 2

	END

	ELSE
	BEGIN
		IF @SpecialCategory = 1
		BEGIN
			SELECT *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory IS NOT NULL
			print 3
			SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NULL AND SpecialCategory IS NOT NULL
			print 4
		END
		ELSE
		BEGIN
			SELECT *,cast((TotalAfterCoupon*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NOT NULL AND SpecialCategory IS NULL
			print 5
			SELECT *,cast((Total*SubsidyPercentage)/100 as int) Subsidy, concat('(',cast(SubsidyPercentage as int),'%',')') SubsidyLabel FROM AssessmentFee WHERE EnterpriseTypee=@EnterpriseTypee AND Certification=@Certification AND Coupon IS NULL AND SpecialCategory IS NULL
			print 6
		END
	END

	SELECT  case when IsCouponUsed=1 then 1 else 0 end as IsCouponUsed from msme where ZedId=@ZedId
END
GO
