/****** Object:  StoredProcedure [dbo].[SP_MSME_MANUAL_UPDATE_PAYMENT_GATEWAY_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MSME_MANUAL_UPDATE_PAYMENT_GATEWAY_DETAILS] --'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	--@PaymentStatus varchar(50) = NULL,
	--@PaymentResponse varchar(5000) = NULL,
	--@IpAddress varchar(50) = NULL,
	--@PgType varchar(50) = NULL,
	--@BankRefNumber varchar(50) = NULL,
	--@BankCode varchar(50) = NULL,
	--@ErrorMessage varchar(2000) = NULL,
	--@AmountPaid varchar(50) = NULL,
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL ,
	@Certification varchar(50) = NULL,
	@PaymentRemarks varchar(2000) = NULL
)
AS
BEGIN

	IF @RoleId=10
	BEGIN
	
		DECLARE @PaymentStatus varchar(50) = 'Success'

		DECLARE @SecondSurveillance int = 0;

	SELECT @SecondSurveillance=EnableSurveillance1 FROM ZEDCS_V2_LIVE.dbo.MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

	IF @SecondSurveillance=2 and @PaymentStatus='success'
	BEGIN
		UPDATE MsmeBasicInformation set ReSurveillance=2 WHERE ZedId=@ZedId and ReSurveillanceLevel=@Certification
		EXEC [SP_ADD_CERTIFICATION_ID] @ZedId, @Certification
		EXEC [SP_RESET_FOR_SECOND_SURVEILLANCE] NULL, @ZedId, @Certification, NULL
	END


		declare @Agency varchar(100) = NULL

		select @Agency=CertificationBodyUserId from ZEDCS_V2_LIVE.dbo.MsmeCertifications where ZedId=@ZedId AND Certification=@Certification and CertificationStatus=16 --and RestrictMail IS NULL

		IF NOT EXISTS (select * from ZEDCS_V2_LIVE.dbo.Users where UserId=@Agency and IsActive=1 and RoleId=2)
		BEGIN
		set @Agency=NULL
		END

		BEGIN TRY
				BEGIN TRAN

		UPDATE PaymentGatewayTransactions 
		SET PaymentStatus	= @PaymentStatus,
			--PaymentResponse	= @PaymentResponse,
			--IpAddress		= @IpAddress,
			--PgType			= @PgType,
			--BankRefNumber   = @BankRefNumber,
			--BankCode        = @BankCode,
			--ErrorMessage    = @ErrorMessage,
			IsManuallyUpdated=1,
			PaymentRemarks= @PaymentRemarks
			--UpdatedDate		= GETDATE()
		WHERE ZedId=@ZedId and TransactionId=@TransactionId	and Certification=@Certification

	
			IF @Certification = 'Bronze'
			BEGIN
				UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
				UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurBronzePaymentDone=1 WHERE ZEDId=@ZedId
			END
			ELSE IF @Certification = 'Silver'
			BEGIN
				UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
				UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurSilverPaymentDone=1 WHERE ZEDId=@ZedId
			END
			ELSE IF @Certification = 'Gold'
			BEGIN
				UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId
				UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurGoldPaymentDone=1 WHERE ZEDId=@ZedId
			END
		
	
			IF (SELECT UseCoupon FROM PaymentGatewayTransactions WHERE ZedId=@ZedId and TransactionId=@TransactionId and Certification=@Certification) = 'Yes'
				UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId


					DECLARE @NewInvoiceNumber VARCHAR(50);
				EXEC ZEDCS_V2_LIVE.DBO.[SP_GENERATE_NEXT_ZED_INVOICE_NO] 
				@NewTADAInvoiceNo = @NewInvoiceNumber OUTPUT; 


			INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
				[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [PaymentType], [SubsidyPercentage],TaDaInvoiceNo
			)
			SELECT @ZedId, [EnterpriseTypee], @Certification, UseCoupon, UnitGstin, Gstin, TdsDeductible, Tds, TanNumber, 
				PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], 'PaymentGateway', [SubsidyPercentage],@NewInvoiceNumber
			FROM AssessmentFee F, PaymentGatewayTransactions P
			WHERE F.Id=P.PaymentRefId AND TransactionId=@TransactionId AND ZedId=@ZedId and P.Certification=@Certification

		
			-----INSERTING EXTRA FIELDS IN SEPARATE TABLE --------------
			INSERT INTO ManualUpdatePaymentDetails (ZedId,Certification,TransactionNumber,TransactionDate,GstNumber,TanNumber,TdsPercentage)
			SELECT @ZedId,@Certification,@TransactionId,GETDATE(),Gstin,TanNumber,CAST(Tds AS VARCHAR) FROM PaymentGatewayTransactions 
			WHERE ZedId = @ZedId AND TransactionId=@TransactionId AND Certification=@Certification;

			declare @PaidAmount varchar(50) = NULL
			select @PaidAmount=Amount from PaymentGateWayTransactions where ZedId=@ZedId and Certification=@Certification and PaymentStatus='Success'

			declare @MinimumParameters int = 0
			IF @Certification='Silver'
			set @MinimumParameters=9
			IF @Certification='Gold'
			set @MinimumParameters=13

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment of Rs. ',@PaidAmount ,' successfully received on ',FORMAT(getdate(), 'MMMM d, yyyy'),' after adjustment of  subsidy/reward as applicable.'),getdate(),@Certification,'ApplicationReceived')

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment is done through PaymentGateway for ',@Certification),getdate(),@Certification,'Manual Update of Payment Status')

			
			--INSERTION OF ELEMENTS DATA
			INSERT INTO MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType)
			SELECT SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType 
			FROM ZEDCS_V2_LIVE.DBO.MsmeSections WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode

			INSERT INTO MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType, 
			OpenedFlag)
			SELECT RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType, OpenedFlag 
			FROM ZEDCS_V2_LIVE.DBO.MsmeRequirements WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode, RequirementCode

			INSERT INTO MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType)
			SELECT OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType 
			FROM ZEDCS_V2_LIVE.DBO.MsmeOptions WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode, RequirementCode, OptionCode

			INSERT INTO MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType)
			SELECT SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType 
			FROM ZEDCS_V2_LIVE.DBO.MsmeSubOptions WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

			IF @SecondSurveillance=2
			BEGIN

				INSERT INTO MsmeCertifications(ZedId, Certification, CertificationBodyUserId, CertificationStatus, MinimumParameters, LeadInCertification, CoInCertification, NcFinalClosureDt)
                SELECT @ZedId, @Certification, @Agency, 8, @MinimumParameters, SiteAssessorId, CoAssessorId, DATEADD(MONTH, 31, CertificationStatusDate) 
                FROM ZEDCS_V2_LIVE.DBO.MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification
				
				INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
				SELECT EvidenceId+100,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText 
				FROM ZEDCS_V2_LIVE.DBO.MsmeEvidences WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
				and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
				ORDER BY SectionCode, RequirementCode, EvidenceCode

				UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications set RestrictMail='S2 Payment Completed' WHERE ZedId=@ZedId AND Certification=@Certification
			END

			ELSE
			BEGIN

				INSERT INTO MsmeCertifications(ZedId, Certification, CertificationBodyUserId, CertificationStatus, MinimumParameters, LeadInCertification, CoInCertification, NcFinalClosureDt)
                SELECT @ZedId, @Certification, @Agency, 8, @MinimumParameters, SiteAssessorId, CoAssessorId, DATEADD(MONTH, 19, CertificationStatusDate) 
                FROM ZEDCS_V2_LIVE.DBO.MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification

				INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
				SELECT EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText 
				FROM ZEDCS_V2_LIVE.DBO.MsmeEvidences WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
				and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
				ORDER BY SectionCode, RequirementCode, EvidenceCode

				UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications set RestrictMail='Payment Completed' WHERE ZedId=@ZedId AND Certification=@Certification
			END

			UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and concat(sectioncode,'_',RequirementCode) not in 
			(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=0)

			  --CALL SP FOR AUTOMAIL FOR AUTOAGENCY ALLOCATION
				IF EXISTS (select * from ZEDCS_V2_LIVE.dbo.Users where UserId=@Agency and IsActive=1 and RoleId=2)
				BEGIN
				 EXEC [SP_SEND_AUTO_MAIL_FOR_AUTO_ALLOT_AGENCY] @ZedId, @Certification
				END

			--UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications set RestrictMail='<redacted>' WHERE ZedId=@ZedId AND Certification=@Certification



			COMMIT TRAN

			  END TRY

		 BEGIN CATCH
				 ROLLBACK TRAN
				 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

		 END CATCH
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_MANUAL_UPDATE_PAYMENT_GATEWAY_DETAILS_WITH_INFO]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MSME_MANUAL_UPDATE_PAYMENT_GATEWAY_DETAILS_WITH_INFO] --'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	--@PaymentStatus varchar(50) = NULL,
	--@PaymentResponse varchar(5000) = NULL,
	--@IpAddress varchar(50) = NULL,
	@PgType varchar(50) = NULL,
	@BankRefNumber varchar(50) = NULL,
	@BankCode varchar(50) = NULL,
	@PaymentReceivedDate    DATETIME = NULL,
	--@ErrorMessage varchar(2000) = NULL,
	--@AmountPaid varchar(50) = NULL,
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL ,
	@Certification varchar(50) = NULL,
	@PaymentRemarks varchar(2000) = NULL,
	@TrackingId varchar(50) = NULL,
	@GstNumber varchar(50) = NULL
)
AS
BEGIN

	IF @RoleId=10
	BEGIN

		DECLARE @IsGstinManualUpdated int = 0;
	
		DECLARE @PaymentStatus varchar(50) = 'Success'

		DECLARE @SecondSurveillance int = 0;

	SELECT @SecondSurveillance=EnableSurveillance1 FROM ZEDCS_V2_LIVE.dbo.MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

	IF @SecondSurveillance=2 and @PaymentStatus='success'
	BEGIN
		UPDATE MsmeBasicInformation set ReSurveillance=2 WHERE ZedId=@ZedId and ReSurveillanceLevel=@Certification
		EXEC [SP_ADD_CERTIFICATION_ID] @ZedId, @Certification
		EXEC [SP_RESET_FOR_SECOND_SURVEILLANCE] NULL, @ZedId, @Certification, NULL
	END


		declare @Agency varchar(100) = NULL

		select @Agency=CertificationBodyUserId from ZEDCS_V2_LIVE.dbo.MsmeCertifications where ZedId=@ZedId AND Certification=@Certification and CertificationStatus=16 --and RestrictMail IS NULL

		IF NOT EXISTS (select * from ZEDCS_V2_LIVE.dbo.Users where UserId=@Agency and IsActive=1 and RoleId=2)
		BEGIN
		set @Agency=NULL
		END

		IF @GstNumber IS NOT NULL
				BEGIN
					SET @IsGstinManualUpdated = 1;
				END


				-- Convert incoming UTC Date to IST (+5 hours 30 mins)
			IF @PaymentReceivedDate IS NOT NULL
			BEGIN
				SET @PaymentReceivedDate = DATEADD(MINUTE, 330, @PaymentReceivedDate);
			END


		BEGIN TRY
				BEGIN TRAN

		UPDATE PaymentGatewayTransactions 
		SET PaymentStatus	= @PaymentStatus,
			--PaymentResponse	= @PaymentResponse,
			--IpAddress		= @IpAddress,
			PgType			= @PgType,
			BankRefNumber   = @BankRefNumber,
			BankCode        = @BankCode,
			--ErrorMessage    = @ErrorMessage,
			IsManuallyUpdated=1,
			PaymentRemarks= @PaymentRemarks,
			TransactionDate     = ISNULL(@PaymentReceivedDate, TransactionDate),
			UpdatedDate		= GETDATE(),
			TrackingId=@TrackingId,
			Gstin=ISNULL(Gstin,@GstNumber)
		WHERE ZedId=@ZedId and TransactionId=@TransactionId	and Certification=@Certification

	
			IF @Certification = 'Bronze'
			BEGIN
				UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
				UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurBronzePaymentDone=1 WHERE ZEDId=@ZedId
			END
			ELSE IF @Certification = 'Silver'
			BEGIN
				UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
				UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurSilverPaymentDone=1 WHERE ZEDId=@ZedId
			END
			ELSE IF @Certification = 'Gold'
			BEGIN
				UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId
				UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurGoldPaymentDone=1 WHERE ZEDId=@ZedId
			END
		
	
			IF (SELECT UseCoupon FROM PaymentGatewayTransactions WHERE ZedId=@ZedId and TransactionId=@TransactionId and Certification=@Certification) = 'Yes'
				UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId


					DECLARE @NewInvoiceNumber VARCHAR(50);
				EXEC ZEDCS_V2_LIVE.DBO.[SP_GENERATE_NEXT_ZED_INVOICE_NO] 
				@NewTADAInvoiceNo = @NewInvoiceNumber OUTPUT; 


			INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
				[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [PaymentType], [SubsidyPercentage],TaDaInvoiceNo
			)
			SELECT @ZedId, [EnterpriseTypee], @Certification, UseCoupon, UnitGstin, Gstin, TdsDeductible, Tds, TanNumber, 
				PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], 'PaymentGateway', [SubsidyPercentage],@NewInvoiceNumber
			FROM AssessmentFee F, PaymentGatewayTransactions P
			WHERE F.Id=P.PaymentRefId AND TransactionId=@TransactionId AND ZedId=@ZedId and P.Certification=@Certification

		
			-----INSERTING EXTRA FIELDS IN SEPARATE TABLE --------------
			INSERT INTO ManualUpdatePaymentDetails (ZedId,Certification,TransactionNumber,TransactionDate,GstNumber,TanNumber,TdsPercentage,IsGstinManualUpdated,PaymentRemarks)
			SELECT @ZedId,@Certification,@TransactionId,GETDATE(),Gstin,TanNumber,CAST(Tds AS VARCHAR),@IsGstinManualUpdated,@PaymentRemarks FROM PaymentGatewayTransactions 
			WHERE ZedId = @ZedId AND TransactionId=@TransactionId AND Certification=@Certification;

			declare @PaidAmount varchar(50) = NULL
			select @PaidAmount=Amount from PaymentGateWayTransactions where ZedId=@ZedId and Certification=@Certification and PaymentStatus='Success'

			declare @MinimumParameters int = 0
			IF @Certification='Silver'
			set @MinimumParameters=9
			IF @Certification='Gold'
			set @MinimumParameters=13

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment of Rs. ',@PaidAmount ,' successfully received on ',FORMAT(getdate(), 'MMMM d, yyyy'),' after adjustment of  subsidy/reward as applicable.'),getdate(),@Certification,'ApplicationReceived')

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment is done through PaymentGateway for ',@Certification),getdate(),@Certification,'Manual Update of Payment Status')

			
			--INSERTION OF ELEMENTS DATA
			INSERT INTO MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType)
			SELECT SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType 
			FROM ZEDCS_V2_LIVE.DBO.MsmeSections WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode

			INSERT INTO MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType, 
			OpenedFlag)
			SELECT RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType, OpenedFlag 
			FROM ZEDCS_V2_LIVE.DBO.MsmeRequirements WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode, RequirementCode

			INSERT INTO MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType)
			SELECT OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType 
			FROM ZEDCS_V2_LIVE.DBO.MsmeOptions WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode, RequirementCode, OptionCode

			INSERT INTO MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType)
			SELECT SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType 
			FROM ZEDCS_V2_LIVE.DBO.MsmeSubOptions WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

			IF @SecondSurveillance=2
			BEGIN

				INSERT INTO MsmeCertifications(ZedId, Certification, CertificationBodyUserId, CertificationStatus, MinimumParameters, LeadInCertification, CoInCertification, NcFinalClosureDt)
                SELECT @ZedId, @Certification, @Agency, 8, @MinimumParameters, SiteAssessorId, CoAssessorId, DATEADD(MONTH, 31, CertificationStatusDate) 
                FROM ZEDCS_V2_LIVE.DBO.MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification
				
				INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
				SELECT EvidenceId+100,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText 
				FROM ZEDCS_V2_LIVE.DBO.MsmeEvidences WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
				and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
				ORDER BY SectionCode, RequirementCode, EvidenceCode

				UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications set RestrictMail='S2 Payment Completed' WHERE ZedId=@ZedId AND Certification=@Certification
			END

			ELSE
			BEGIN

				INSERT INTO MsmeCertifications(ZedId, Certification, CertificationBodyUserId, CertificationStatus, MinimumParameters, LeadInCertification, CoInCertification, NcFinalClosureDt)
                SELECT @ZedId, @Certification, @Agency, 8, @MinimumParameters, SiteAssessorId, CoAssessorId, DATEADD(MONTH, 19, CertificationStatusDate) 
                FROM ZEDCS_V2_LIVE.DBO.MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification

				INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
				SELECT EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText 
				FROM ZEDCS_V2_LIVE.DBO.MsmeEvidences WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
				and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
				ORDER BY SectionCode, RequirementCode, EvidenceCode

				UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications set RestrictMail='Payment Completed' WHERE ZedId=@ZedId AND Certification=@Certification
			END

			UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and concat(sectioncode,'_',RequirementCode) not in 
			(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=0)

			  --CALL SP FOR AUTOMAIL FOR AUTOAGENCY ALLOCATION
				IF EXISTS (select * from ZEDCS_V2_LIVE.dbo.Users where UserId=@Agency and IsActive=1 and RoleId=2)
				BEGIN
				 EXEC [SP_SEND_AUTO_MAIL_FOR_AUTO_ALLOT_AGENCY] @ZedId, @Certification
				END

			--UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications set RestrictMail='<redacted>' WHERE ZedId=@ZedId AND Certification=@Certification



			COMMIT TRAN

			  END TRY

		 BEGIN CATCH
				 ROLLBACK TRAN
				 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

		 END CATCH
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_NEFT_PAYMENT_DETAILS_notusing]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_NEFT_PAYMENT_DETAILS_notusing] --'<redacted>', '<redacted>'
(
	@ZedId	varchar(50)	= NULL,
	@Certification	varchar(50)	= NULL,
	@UseCoupon	varchar(100)	= NULL,
	@UnitGstin	varchar(50)	= NULL,
	@Gstin	varchar(100)	= NULL,
	@TdsDeductible	varchar(200)	= NULL,
	@Tds	varchar(250)	= NULL,
	@Tan	varchar(50)	= NULL,
	@UtrNumber	varchar(50)	= NULL,
	@PaymentRefId	varchar(50)	= NULL
)
AS
BEGIN
	IF @Certification = 'Bronze'
		UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
	ELSE IF @Certification = 'Silver'
		UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
	ELSE IF @Certification = 'Gold'
		UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId
		
	DECLARE @AmountToBePaid varchar(50)

	IF @UseCoupon = 'Yes'
		UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId

		IF @TdsDeductible='No'
		BEGIN
			select @AmountToBePaid=ApplicantContributionAfterSubsidy from AssessmentFee where Id=@PaymentRefId
		END
	IF @TdsDeductible='Yes'
		BEGIN			
				select @AmountToBePaid = CASE WHEN @Tds='1.5' THEN NetPaybleTds15 WHEN @Tds='7.5' THEN NetPaybleTds75 END from AssessmentFee where Id=@PaymentRefId
		END


	INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], [UtrNumber],
		[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
		[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [PaymentType], [AmountPaid], [SubsidyPercentage]
	)
	SELECT @ZedId, [EnterpriseTypee], @Certification, @UseCoupon, @UnitGstin, @Gstin, @TdsDeductible, @Tds, @Tan, @UtrNumber,
		@PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
		[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], 'NEFT', @AmountToBePaid, [SubsidyPercentage]
	FROM AssessmentFee 
	WHERE Id=@PaymentRefId



END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_PAYMENT_BASIC_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MSME_PAYMENT_BASIC_DETAILS] --'<redacted>'
(
	@ZedId	varchar(50)	= NULL,
	@Certification	varchar(50)	= NULL,
	@UseCoupon	varchar(100)	= NULL,
	@UnitGstin	varchar(50)	= NULL,
	@Gstin	varchar(100)	= NULL,
	@TdsDeductible	varchar(200)	= NULL,
	@Tds	varchar(250)	= NULL,
	@Tan	varchar(50)	= NULL,
	@UtrNumber	varchar(50)	= NULL,
	@PaymentRefId	varchar(50)	= NULL,
	@TransactionId varchar(50) = NULL
)
AS
BEGIN
	DECLARE @AmountToBePaid varchar(50)

	
	IF @TransactionId IS NULL 
	BEGIN
		UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'
	END
	ELSE
	BEGIN
		IF @TdsDeductible='No'
			BEGIN
				select @AmountToBePaid=ApplicantContributionAfterSubsidy from AssessmentFee where Id=@PaymentRefId
			END
		IF @TdsDeductible='Yes'
			BEGIN	
				IF @Tds='15' 
					SET @Tds='1.5'

				IF @Tds='75' 
					SET @Tds='7.5'

					select @AmountToBePaid = CASE WHEN @Tds='1.5' THEN NetPaybleTds15 WHEN @Tds='7.5' THEN NetPaybleTds75 END from AssessmentFee where Id=@PaymentRefId
			END

		Insert into PaymentGatewayTransactions (ZedId,TransactionId,TransactionStatus,Amount,TransactionDate, Certification, UseCoupon, UnitGstin, Gstin, TdsDeductible, Tds, TanNumber, PaymentRefId)
		values (@ZedId,@TransactionId,1,@AmountToBePaid,getdate(), @Certification, @UseCoupon, @UnitGstin, @Gstin, @TdsDeductible, @Tds, @Tan, @PaymentRefId)

		IF @ZedId in ('ZEDMSME117997','ZEDMSME005895','ZEDMSME005898','ZEDMSME006274','ZEDMSME006944','ZEDMSME009119','ZEDMSME012337','ZEDMSME031062','ZEDMSME122204','ZEDMSME185598',
		'ZEDMSME010118','ZEDMSME011942','ZEDMSME013502','ZEDMSME013583','ZEDMSME013889','ZEDMSME016650','ZEDMSME017215','ZEDMSME018700','ZEDMSME018746','ZEDMSME021670','ZEDMSME129350','ZEDMSME389759'
		,'ZEDMSME778108','ZEDMSME727192','ZEDMSME816083','ZEDMSME741661','ZEDMSME579532')
		BEGIN
		SET @AmountToBePaid=1.00  ---to test the payment gateway
		END

		IF EXISTS(select * from MsmeBasicInformation where ZedId=@ZedId and ReSurveillanceLevel=@Certification and ReSurveillance=1)
		BEGIN
			IF (select count(*) from MsmePaymentInfo where zedid=@ZedId and Certification=@Certification AND ReSurveillance=0)>0
			BEGIN
				SET @ZedId='0000'
			END
		END

		ELSE IF (select count(*) from MsmePaymentInfo where zedid=@ZedId and Certification=@Certification)>0
		BEGIN
			SET @ZedId='0000'
		END


		--IF (select count(*) from MsmePaymentInfo where zedid=@ZedId and Certification=@Certification)>0
		--BEGIN
		--	SET @ZedId='<redacted>'
		--END

		SELECT @AmountToBePaid AmountToBePaid, @TransactionId TransactionId,'Surveillance 1' MerchantParam3, * FROM Msme WHERE ZedId=@ZedId

	END

END



GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_PAYMENT_GATEWAY_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MSME_PAYMENT_GATEWAY_DETAILS] --'<redacted>'
(
	@ZedId varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	@PaymentStatus varchar(50) = NULL,
	@PaymentResponse varchar(5000) = NULL,
	@IpAddress varchar(50) = NULL,
	@PgType varchar(50) = NULL,
	@BankRefNumber varchar(50) = NULL,
	@BankCode varchar(50) = NULL,
	@ErrorMessage varchar(2000) = NULL,
	@AmountPaid varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@ApiType varchar(50) = NULL
)
AS
BEGIN
		-- Extracting the ID from the incoming @PaymentResponse string
			DECLARE @ExtractedTrackingId VARCHAR(100) = NULL;
			IF @PaymentResponse LIKE '%tracking_id=%'
			BEGIN
				SET @ExtractedTrackingId = SUBSTRING(
					@PaymentResponse, 
					CHARINDEX('tracking_id=', @PaymentResponse) + 12, 
					CHARINDEX('&', @PaymentResponse + '&', CHARINDEX('tracking_id=', @PaymentResponse)) - (CHARINDEX('tracking_id=', @PaymentResponse) + 12)
				)
			END


	DECLARE @SecondSurveillance int = 0;

	SELECT @SecondSurveillance=EnableSurveillance1 FROM ZEDCS_V2_LIVE.dbo.MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

	IF @SecondSurveillance=2 and @PaymentStatus='success'
	BEGIN
		UPDATE MsmeBasicInformation set ReSurveillance=2 WHERE ZedId=@ZedId and ReSurveillanceLevel=@Certification
		EXEC [SP_ADD_CERTIFICATION_ID] @ZedId, @Certification
		EXEC [SP_RESET_FOR_SECOND_SURVEILLANCE] NULL, @ZedId, @Certification, NULL
	END


		declare @Agency varchar(100) = NULL

		select @Agency=CertificationBodyUserId from ZEDCS_V2_LIVE.dbo.MsmeCertifications where ZedId=@ZedId AND Certification=@Certification and CertificationStatus=16 --and RestrictMail IS NULL

		IF NOT EXISTS (select * from ZEDCS_V2_LIVE.dbo.Users where UserId=@Agency and IsActive=1 and RoleId=2)
		BEGIN
		set @Agency=NULL
		END

	IF (select count(*) from PaymentGatewayTransactions where ZedId=@ZedId and TransactionId=@TransactionId and (PaymentStatus is null OR PaymentStatus!='Success')) > 0
	BEGIN

		UPDATE PaymentGatewayTransactions 
		SET PaymentStatus	= @PaymentStatus,
			PaymentResponse	= @PaymentResponse,
			IpAddress		= @IpAddress,
			PgType			= @PgType,
			BankRefNumber   = @BankRefNumber,
			BankCode        = @BankCode,
			ErrorMessage    = @ErrorMessage,
			UpdatedDate		= GETDATE(),
			ApiType			=@ApiType,
			TrackingId      =@ExtractedTrackingId
		WHERE ZedId=@ZedId and TransactionId=@TransactionId	

		IF @PaymentStatus='success'
		BEGIN
			IF @Certification = 'Bronze'
				BEGIN
					UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
					UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurBronzePaymentDone=1 WHERE ZEDId=@ZedId
				END
			ELSE IF @Certification = 'Silver'
				BEGIN
					UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
					UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurSilverPaymentDone=1 WHERE ZEDId=@ZedId
				END
			ELSE IF @Certification = 'Gold'
				BEGIN
				UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId
				UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurGoldPaymentDone=1 WHERE ZEDId=@ZedId
				END
		
	
			IF (SELECT UseCoupon FROM PaymentGatewayTransactions WHERE ZedId=@ZedId and TransactionId=@TransactionId) = 'Yes'
				UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId

				DECLARE @NewInvoiceNumber VARCHAR(50);
				EXEC ZEDCS_V2_LIVE.DBO.[SP_GENERATE_NEXT_ZED_INVOICE_NO] 
				@NewTADAInvoiceNo = @NewInvoiceNumber OUTPUT; 


			INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
				[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [PaymentType], [SubsidyPercentage],TaDaInvoiceNo
			)
			SELECT @ZedId, [EnterpriseTypee], @Certification, UseCoupon, UnitGstin, Gstin, TdsDeductible, Tds, TanNumber, 
				PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], [SubsidyAmount], 
				[GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], 'PaymentGateway', [SubsidyPercentage], @NewInvoiceNumber
			FROM AssessmentFee F, PaymentGatewayTransactions P
			WHERE F.Id=P.PaymentRefId AND TransactionId=@TransactionId AND ZedId=@ZedId

		
		END


		IF @PaymentStatus='success'
			BEGIN 

			declare @PaidAmount varchar(50) = NULL
			select @PaidAmount=Amount from PaymentGateWayTransactions where ZedId=@ZedId and Certification=@Certification and PaymentStatus='Success'

			declare @MinimumParameters int = 0
			IF @Certification='Silver'
			set @MinimumParameters=9
			IF @Certification='Gold'
			set @MinimumParameters=13
			

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment of Rs. ',@PaidAmount ,' successfully received on ',FORMAT(getdate(), 'MMMM d, yyyy'),' after adjustment of  subsidy/reward as applicable.'),getdate(),@Certification,'ApplicationReceived')

			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment is done through PaymentGateway for ',@Certification),getdate(),@Certification,NULL)

			--INSERTION OF ELEMENTS DATA
			INSERT INTO MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType)
			SELECT SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType 
			FROM ZEDCS_V2_LIVE.DBO.MsmeSections WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode

			INSERT INTO MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType, 
			OpenedFlag)
			SELECT RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType, OpenedFlag 
			FROM ZEDCS_V2_LIVE.DBO.MsmeRequirements WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode, RequirementCode

			INSERT INTO MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType)
			SELECT OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType 
			FROM ZEDCS_V2_LIVE.DBO.MsmeOptions WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode, RequirementCode, OptionCode

			INSERT INTO MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType)
			SELECT SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType 
			FROM ZEDCS_V2_LIVE.DBO.MsmeSubOptions WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
			and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
			ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

			IF @SecondSurveillance=2
			BEGIN

				INSERT INTO MsmeCertifications(ZedId, Certification, CertificationBodyUserId, CertificationStatus, MinimumParameters, LeadInCertification, CoInCertification, NcFinalClosureDt)
                SELECT @ZedId, @Certification, @Agency, 8, @MinimumParameters, SiteAssessorId, CoAssessorId, DATEADD(MONTH, 31, CertificationStatusDate) 
                FROM ZEDCS_V2_LIVE.DBO.MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification
				
				INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
				SELECT EvidenceId+100,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText 
				FROM ZEDCS_V2_LIVE.DBO.MsmeEvidences WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
				and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
				ORDER BY SectionCode, RequirementCode, EvidenceCode

				UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications set RestrictMail='S2 Payment Completed' WHERE ZedId=@ZedId AND Certification=@Certification
			END
			ELSE
			BEGIN

				INSERT INTO MsmeCertifications(ZedId, Certification, CertificationBodyUserId, CertificationStatus, MinimumParameters, LeadInCertification, CoInCertification, NcFinalClosureDt)
                SELECT @ZedId, @Certification, @Agency, 8, @MinimumParameters, SiteAssessorId, CoAssessorId, DATEADD(MONTH, 19, CertificationStatusDate) 
                FROM ZEDCS_V2_LIVE.DBO.MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification

				INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
				SELECT EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText 
				FROM ZEDCS_V2_LIVE.DBO.MsmeEvidences WHERE SectionType=@Certification and ZedId=@ZedId and NcCount=0 
				and SectionCode in (select SectionCode from ZEDCS_V2_LIVE.DBO.Sections where SectionType=@Certification and SurveMandatories='Yes')
				ORDER BY SectionCode, RequirementCode, EvidenceCode

				UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications set RestrictMail='Payment Completed' WHERE ZedId=@ZedId AND Certification=@Certification
			END



			--INSERT INTO MsmeCertifications(ZedId, Certification, CertificationBodyUserId,  CertificationStatus, MinimumParameters, LeadInCertification, CoInCertification)
			--SELECT @ZedId,@Certification,@Agency,8,@MinimumParameters,SiteAssessorId,CoAssessorId FROM ZEDCS_V2_LIVE.DBO.MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification


			UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and concat(sectioncode,'_',RequirementCode) not in 
			(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=0)

			  --CALL SP FOR AUTOMAIL FOR AUTOAGENCY ALLOCATION
				IF EXISTS (select * from ZEDCS_V2_LIVE.dbo.Users where UserId=@Agency and IsActive=1 and RoleId=2)
				BEGIN
				 EXEC [SP_SEND_AUTO_MAIL_FOR_AUTO_ALLOT_AGENCY] @ZedId, @Certification
				END

			--UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications set RestrictMail='<redacted>' WHERE ZedId=@ZedId AND Certification=@Certification

			END
		ELSE
			BEGIN
			Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Payment failed through PaymentGateway for ',@Certification),getdate(),@Certification,NULL)
			END
	END

	ELSE
	BEGIN
	--MsmeHistoryForDuplicates
		Insert into MsmeHistoryForDuplicates (ZedId,Descrip,CreatedDate,CertificationType,StatusType,ApiType)
		values (@ZedId,concat('Response came again from PaymentGateway for ',@Certification),getdate(),@Certification,NULL,@ApiType)

		UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

	END

END
GO
