/****** Object:  StoredProcedure [dbo].[SP_MSME_UPDATE_PROFILE]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_UPDATE_PROFILE]
(
	@ZedId varchar(50) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@EnterpriseName	varchar(250) = NULL,
	@OwnerName	varchar(200) = NULL,
	@PUnitName varchar(500) = NULL,
	@EmailId	varchar(200) = NULL

)
AS
BEGIN
	

	SET NOCOUNT ON;

	IF  @RoleId=10
	BEGIN
		INSERT INTO MsmeUpdatedRecords([MsmeId], [ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [EnterpriseType], [EnterpriseTypee]
		, [MobileNo], [EmailId], [ApplicationId], [UamNumber], [PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode], [PDistrictName]
		, [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId], [PledgeEmailId], [IsBronzePaymentDone], [IsSilverPaymentDone]
		, [IsGoldPaymentDone], [IsCouponUsed], [PledgeCertificateNo], [RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo]
		, [RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo])

		SELECT [MsmeId], [ZedId], [StateId], [StateName], [DistrictId], [DistrictName], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [EnterpriseType], [EnterpriseTypee]
		, [MobileNo], [EmailId], [ApplicationId], [UamNumber], [PFlat], [PBuilding], [PRoad], [PArea], [PCity], [PAddress], [PPin], [PStateId], [PStateName], [PLgDistrictCode], [PDistrictName]
		, [PPlantDetailId], [Activity], [TwoDigitActivity], [FourDigitActivity], [FiveDigitActivity], [ActivityDetailId], [PledgeEmailId], [IsBronzePaymentDone], [IsSilverPaymentDone]
		, [IsGoldPaymentDone], [IsCouponUsed], [PledgeCertificateNo], [RegistrationType], [IncorporationDate], [WhetherProdCommenced], [PlantIdNo], [PUnitName], [PUnitIdNo]
		, [RegistrationFrom], [FinancialAssistanceStatus], [WashWebinarCertificateNo], [WashCertificateNo], [QrCodeNo] FROM Msme WHERE ZedId=@ZedId


		INSERT INTO MsmeBasicInformationUpdatedRecords([Id], [MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory], [SocialCategoryName], [Gender]
		, [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName], [LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName]
		, [EnterpriseType], [EnterpriseTypee], [CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId], [LastestCertification])

		SELECT [Id], [MsmeId], [ApplicationId], [UdyogAadharNo], [OwnerName], [EnterpriseName], [OrganisationType], [OrganisationTypeName], [SocialCategory], [SocialCategoryName], [Gender]
		, [PH], [PanNo], [Address], [StateId], [StateName], [DistrictId], [DistrictName], [LgDistrictCode], [Pincode], [MobileNo], [EmailId], [MajorActivity], [MajorActivityName]
		, [EnterpriseType], [EnterpriseTypee], [CommmenceDate], [PreviousEMType], [PreviousEMNumber], [TotalEmp], [InvestmentCost], [DicName], [AppliedDate], [ZedId], [LastestCertification]
		FROM MsmeBasicInformation where ZedId=@ZedId


		UPDATE MSME SET EnterpriseName=@EnterpriseName,OwnerName=@OwnerName,PUnitName=@PUnitName,EmailId=@EmailId,PledgeEmailId=@EmailId where ZedId=@ZedId
		UPDATE MsmeBasicInformation SET EnterpriseName=@EnterpriseName,OwnerName=@OwnerName,EmailId=@EmailId where ZedId=@ZedId
		UPDATE Users SET UserName=@EnterpriseName,Email=@EmailId where UserId=@ZedId and RoleId=5
	END
	

END
GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_VALIDATE_UDYAM_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_VALIDATE_UDYAM_DETAILS] --'<redacted>', '<redacted>',NULL,NULL,'<redacted>'
(
	@UdyogAadharNo varchar(50) = NULL,
	@PlantIdNo varchar(50) = NULL,
	@TwoDigitActivity varchar(200) = NULL,
	@IpAddress varchar(200) = NULL,
	@EmailId varchar(100) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT * FROM MsmeBasicInformation B inner join Msme M on (B.ZedId=M.ZedId) Where UdyogAadharNo=@UdyogAadharNo AND PlantIdNo=@PlantIdNo --and 1=2

	SELECT * FROM Sectors WHERE @TwoDigitActivity like SectorCode+'%'

	--- to check the email id counter
	IF @EmailId IS NOT NULL AND ( SELECT COUNT(*) FROM Msme where EmailId=@EmailId) >= 5
	BEGIN
		SELECT 1 EmailCountStatus, 'This Email Id is already registered' ErrorMessage
	END
	ELSE
	BEGIN
		SELECT 0 EmailCountStatus, '' ErrorMessage
	END


END

GO
/****** Object:  StoredProcedure [dbo].[SP_MSME_ZERO_PAYMENT_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_ZERO_PAYMENT_DETAILS] --'<redacted>', '<redacted>'
(
	@ZedId	varchar(50)	= NULL,
	@Certification	varchar(50)	= NULL,
	@UseCoupon	varchar(100)	= NULL,
	@UnitGstin	varchar(50)	= NULL,
	@Gstin	varchar(100)	= NULL,
	@TdsDeductible	varchar(200)	= NULL,
	@Tds	varchar(250)	= NULL,
	@Tan	varchar(50)	= NULL,
	@PaymentRefId	varchar(50)	= NULL
)
AS
BEGIN

	IF NOT EXISTS (select * from Msme where ZedId=@ZedId and IsBronzePaymentDone=1)
	BEGIN

		IF @Certification = 'Bronze'
				BEGIN
					UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
					UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurBronzePaymentDone=1 WHERE ZEDId=@ZedId
				END
			ELSE IF @Certification = 'Silver'
				BEGIN
					UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
					UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurSilverPaymentDone=1 WHERE ZEDId=@ZedId
				END
			ELSE IF @Certification = 'Gold'
				BEGIN
				UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId
				UPDATE ZEDCS_V2_LIVE.DBO.Msme SET IsSurGoldPaymentDone=1 WHERE ZEDId=@ZedId
				END

	
		IF @UseCoupon = 'Yes'
			UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId

		


		INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
			[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], 
			[SubsidyAmount], [GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [SubsidyPercentage]
		)
		SELECT @ZedId, [EnterpriseTypee], @Certification, @UseCoupon, @UnitGstin, @Gstin, @TdsDeductible, @Tds, @Tan, 
			@PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], 
			[SubsidyAmount], [GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [SubsidyPercentage]
		FROM AssessmentFee 
		WHERE Id=@PaymentRefId

		--INSERT INTO MsmeCertifications ([ZedId], [Certification])
		--SELECT @ZedId, @Certification

		Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Payment of Rs. 0 successfully received on ',FORMAT(getdate(), 'MMMM d, yyyy'),' after adjustment of  subsidy/reward as applicable.'),getdate(),@Certification,'ApplicationReceived')


			--INSERTION OF ELEMENTS DATA
			INSERT INTO MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,IsAssessmentExcempted)
			SELECT Id,@ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,'No' FROM ZEDCS_V2_LIVE.DBO.Sections WHERE SectionType=@Certification ORDER BY SectionCode

			INSERT INTO MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType)
			SELECT Id,@ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType FROM ZEDCS_V2_LIVE.DBO.Requirements WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode

			INSERT INTO MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType)
			SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM ZEDCS_V2_LIVE.DBO.Options WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode

			INSERT INTO MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType)
			SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM ZEDCS_V2_LIVE.DBO.SubOptions WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

			INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
			SELECT Id,@ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,HelpText FROM ZEDCS_V2_LIVE.DBO.Evidences WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, EvidenceCode
		
			INSERT INTO MsmeCertifications(ZedId, Certification, CertificationStatus, MinimumParameters)
			SELECT @ZedId,@Certification,1,7 FROM ZEDCS_V2_LIVE.DBO.MsmeCertifications WHERE ZedId=@ZedId AND Certification=@Certification

			UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and concat(sectioncode,'_',RequirementCode) not in 
			(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=0)

			

			UPDATE ZEDCS_V2_LIVE.DBO.MsmeCertifications set RestrictMail='Payment Completed' WHERE ZedId=@ZedId AND Certification=@Certification

			
		--	-----------ALLOTING AGENCY START HERE-------------
		--declare @Agencyid varchar(50) = null

		--select @Agencyid=U.UserId from Msme M 
		--inner join AgencyUserDistricts D on (M.PLgDistrictCode=D.Districts) 
		--inner join Users U on (D.UserId=U.UserId)
		--WHERE ZedId=@ZedId AND U.IsActive=1 and AllowBronzeSurveillance=1 and U.RoleId=2 

		--IF @Agencyid IS NULL AND (SELECT count(*) FROM Msme M inner join Users U on (M.StateId=U.TuPreferredState) WHERE ZedId=@ZedId AND U.IsActive=1 and AllowBronzeSurveillance=1 and U.RoleId=2 )=1
		--BEGIN
		--	SELECT @Agencyid=UserId FROM Msme M inner join Users U on (M.StateId=U.TuPreferredState) WHERE ZedId=@ZedId AND U.IsActive=1 and AllowBronzeSurveillance=1 and U.RoleId=2			
		--END

		--IF @Agencyid IS NOT NULL
		--BEGIN
		--	UPDATE MsmeCertifications set CertificationBodyUserId=@Agencyid where ZedId=@ZedId and Certification=@Certification
		--	INSERT INTO MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		--	VALUES (@ZedId,concat(@Agencyid, '<redacted>',FORMAT(getdate(), '<redacted>')),getdate(),@Certification,'<redacted>')
			 

		--END
		--	EXEC [SP_SEND_AUTO_MAIL_FOR_AUTO_ALLOT_AGENCY] @ZedId, @Certification

		-----------ALLOTING AGENCY END HERE-------------


		---------AUTO ROUND ROBIN START HERE ------------

		 EXEC [SP_MSME_AUTO_ALLOT_AGENCY_ROUND_ROBIN] @ZedId, @Certification
		 EXEC [SP_SEND_AUTO_MAIL_FOR_AUTO_ALLOT_AGENCY] @ZedId, @Certification
	

		---------AUTO ROUND ROBIN END HERE --------------



	END

	--ELSE
	--BEGIN
	--UPDATE DummyUsersForError SET IsActive='<redacted>' where UserId='<redacted>'
	--END

	BEGIN
        -- FIX: Changed '<redacted>' to a valid BIT (0) or just a PRINT
        PRINT 'Skipping ' + ISNULL(@ZedId, 'NULL') + ': Already Processed';
        -- UPDATE DummyUsersForError SET IsActive = 0 where UserId = '<redacted>' 
    END

END
