/****** Object:  StoredProcedure [dbo].[SP_RA_GET_CERTIFICATE_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_RA_GET_CERTIFICATE_DETAILS]  --'<redacted>','<redacted>'
(
	@ZedId Varchar(100) =NULL,
	@CertificationType Varchar(100) =NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @DateOfCertification varchar(50) = NULL
	select @DateOfCertification=FORMAT(CertificationStatusDate, 'MMMM d, yyyy')  from ZEDCS_V2_LIVE.dbo.MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType and CertificationStatus=16

	SELECT  UPPER(M.PUnitName) EnterpriseName,SaCertificateNo,@DateOfCertification DateOfCertification,
	case when RegistrationType='UAM' THEN B.Address ELSE concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin) end as Address ,	
	B.UdyogAadharNo,M.MobileNo,M.EmailId,M.EnterpriseName EstablishmentName, TwoDigitActivity NicCode, case when Certification='Bronze' then '' else U.UserName end as AssessmentAgency,
	CASE WHEN Certification='Silver' then concat('https://loginzed.msme.gov.in/Verify/SC/',QrCodeSeqNo) else concat('https://loginzed.msme.gov.in/Verify/GC/',QrCodeSeqNo) end as QrCodeSeqNo,
	UPPER(PUnitName) PUnitName,concat(C.ZedId,'_D_',C.Id) as RejectedZedId,
	FORMAT(CertificationStatusDate, 'MMMM d, yyyy') DateOfSurveillance, CASE WHEN B.ReSurveillance > 1 THEN 2 ELSE 1 END AS SurveillanceNo
	from Msme M inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
	left join Users U on (U.UserId=C.CertificationBodyUserId)
	where Certification=@CertificationType and C.ZedId=@ZedId

	--select * from MsmeBasicInformation

END


GO
/****** Object:  StoredProcedure [dbo].[SP_REPORT_GET_DETAILS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
-- [SP_REPORT_GET_DETAILS] '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_REPORT_GET_DETAILS]
(
	@Certification Varchar(50) = NULL,
	@ZedId Varchar(100) =NULL,
	@UserId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	DECLARE @CleanZedId Varchar(100) = SUBSTRING(@ZedId, 1, CHARINDEX('_D', @ZedId + '_D') - 1)
	
	IF @Certification='Bronze'
	BEGIN
		SELECT C.ZedId, C.Certification, M.EnterpriseName,M.PUnitName, UdyogAadharNo, M.EnterpriseTypee, CONCAT(PAddress,' ', PDistrictName,' ',PStateName,'-', PPin) PlantAddress, PDistrictName, PStateName, TwoDigitActivity,
			C.DesktopAssessorId, U.UserName DesktopAssessorName, C.AuditsConducted, C.DomesticCustomers, C.InternationalCustomers, C.RawMaterialImported, C.OutsourcedProcesses, REPLACE(C.EnergySources,',',', ') EnergySources,
			C.AssessorRemarks, FORMAT(CertificationStatusDate, 'MMMM d, yyyy') AssessmentDate,
			C.IsSaVerified, C.SaAssessorRemarks, FORMAT(CertificationStatusDate, 'MMMM d, yyyy') AssessmentDate, Certification,CertificationStatus,PhotosPath
		FROM MsmeCertifications C, Msme M, MsmeBasicInformation B, Users U
		WHERE REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')=M.ZedId 
			AND M.ZedId=B.ZedId 
			AND C.DesktopAssessorId=U.UserId
			AND Certification=@Certification
			AND C.ZedId=@ZedId
	END
	ELSE
	BEGIN
	SELECT C.ZedId, C.Certification, M.EnterpriseName,M.PUnitName, UdyogAadharNo, M.EnterpriseTypee, CONCAT(PAddress,' ', PDistrictName,' ',PStateName,'-', PPin) PlantAddress, PDistrictName, PStateName, TwoDigitActivity,
			C.DesktopAssessorId, U.UserName DesktopAssessorName, Z.AuditsConducted, Z.SaDomesticCustomers DomesticCustomers, Z.SaInternationalCustomers InternationalCustomers, Z.RawMaterialImported, Z.SaOutsourcedProcesses OutsourcedProcesses, REPLACE(Z.SaEnergySources,',',', ') EnergySources,
			C.AssessorRemarks, FORMAT(C.CertificationStatusDate, 'MMMM d, yyyy') AssessmentDate,
			case when ReSurveillance>=1 then 2 else 1 end as SurveillanceNo,
			C.IsSaVerified, C.SaAssessorRemarks, FORMAT(C.CertificationStatusDate, 'MMMM d, yyyy') AssessmentDate, C.Certification,C.CertificationStatus,C.PhotosPath
		FROM 		 
			MsmeCertifications C
		JOIN 
			Msme M ON REPLACE(REPLACE(C.ZedId, '_D', ''), CONCAT('_', C.Id), '') = M.ZedId 
		JOIN 
			MsmeBasicInformation B ON M.ZedId = B.ZedId 
		JOIN 
			Users U ON C.SiteAssessorId = U.UserId
		LEFT JOIN 
			ZEDCS_V2_LIVE.dbo.MsmeCertifications Z ON (C.ZedId = Z.ZedId and C.Certification=Z.Certification)
				WHERE REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')=M.ZedId 
			AND M.ZedId=B.ZedId 
			AND C.SiteAssessorId=U.UserId
			AND C.Certification=@Certification
			AND C.ZedId=@ZedId
	END
	
	IF @Certification='Bronze'
	BEGIN
		SELECT *,
		concat('this.src="',concat('https://loginzed.msme.gov.in/mobileapi/Photos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/BasicInfo/',ProductPhoto),'"') as OldProductPhoto,
		concat('this.src="',concat('https://loginzed.msme.gov.in/mobileapi/Photos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/BasicInfo/',ProductDescriptionPhoto),'"') as OldProductDescPhoto,
		concat('https://loginzed.msme.gov.in/mobileapi/Photos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/BasicInfo/',ProductDescriptionPhoto) as OldProductDescPhotoPdf,
		concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos\',ZedId, '/',Certification,'/BasicInfo/',ProductDescriptionPhoto) as NewProductDescPhotoPdfSys
		--E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos\ZEDMSME005568\Bronze\BasicInfo
		FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=0
		SELECT * FROM MsmeRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId
	END
	ELSE IF @Certification='Silver'
	BEGIN
		--SELECT Id,ZedId,Certification,ProductName,Exported,IsVerified,AssessorRemarks,UpdatedDate,NcCount,MsmeRemarks,SaProductPhoto ProductPhoto,SaProductDescriptionPhoto ProductDescriptionPhoto
		--,IsSaVerified,SaAssessorRemarks,SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,ProductParentId,PreviousAssessorRemarks,PreviousAssessorUpdatedDate,MsmeUpdatedDate,
		SELECT Id,ZedId,Certification,ProductName,Exported,IsVerified,AssessorRemarks,UpdatedDate,NcCount,MsmeRemarks, ProductPhoto, ProductDescriptionPhoto
		,'' IsSaVerified,'' SaAssessorRemarks,'' SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,'' ProductParentId,'' PreviousAssessorRemarks,'' PreviousAssessorUpdatedDate,MsmeUpdatedDate,
		concat('this.src="',concat('https://loginzed.msme.gov.in/mobileapi/SaPhotos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/BasicInfo/',ProductPhoto),'"') as OldProductPhoto,
		concat('this.src="',concat('https://loginzed.msme.gov.in/mobileapi/SaPhotos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/BasicInfo/',ProductDescriptionPhoto),'"') as OldProductDescPhoto,
		concat('https://loginzed.msme.gov.in/mobileapi/Photos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/BasicInfo/',ProductDescriptionPhoto) as OldProductDescPhotoPdf,
		concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos\',ZedId, '/',Certification,'/BasicInfo/',ProductDescriptionPhoto) as NewProductDescPhotoPdfSys
		FROM ZEDCS_V2_LIVE.dbo.SaProducts WHERE Certification=@Certification AND ZedId=@CleanZedId	AND NcCount=0

		SELECT * FROM MsmeRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId
	END
	ELSE
	BEGIN
		SELECT Id,ZedId,Certification,ProductName,Exported,IsVerified,AssessorRemarks,UpdatedDate,NcCount,MsmeRemarks, ProductPhoto, ProductDescriptionPhoto
		,'' IsSaVerified,'' SaAssessorRemarks,'' SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,'' ProductParentId,'' PreviousAssessorRemarks,'' PreviousAssessorUpdatedDate,MsmeUpdatedDate,
		concat('this.src="',concat('https://loginzed.msme.gov.in/mobileapi/SaPhotos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/BasicInfo/',ProductPhoto),'"') as OldProductPhoto,
		concat('this.src="',concat('https://loginzed.msme.gov.in/mobileapi/SaPhotos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/BasicInfo/',ProductDescriptionPhoto),'"') as OldProductDescPhoto,
		concat('https://loginzed.msme.gov.in/mobileapi/Photos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/BasicInfo/',ProductDescriptionPhoto) as OldProductDescPhotoPdf,
		concat('E:\Publish\ZEDCS_LIVE\ZEDCS_V2_LIVE_SERVICES\Photos\',ZedId, '/',Certification,'/BasicInfo/',ProductDescriptionPhoto) as NewProductDescPhotoPdfSys
		FROM ZEDCS_V2_LIVE.dbo.SaProducts WHERE Certification=@Certification AND ZedId=@CleanZedId	AND NcCount=0
		SELECT * FROM MsmeRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId
	END

	IF @Certification='Bronze'
	BEGIN
   		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,'' OfiComments,'' IsAssessmentExcempted  FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=0 ORDER BY cast(SectionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
	END
	ELSE
	BEGIN
   		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,OfiComments,IsAssessmentExcempted FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=0 ORDER BY cast(SectionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,SaConformance Conformance,SaAssessorRemarks AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, '' SaConformance,'' SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		--SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, '<redacted>' TableName, DocumentOpenedTime,'<redacted>' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=0 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
		SELECT 
			R.Id ,	R.ZedId,	Certification,	M.SectionCode,M.RequirementCode, EvidenceId, '' EvidenceCode,Name EvidenceName,Certification SectionType,'' EvidenceType,'' ValidationRequired, IsVerified, '' SourceOfValidation,R.AssessorRemarks,'SaPhotos' TableName,'' DocumentOpenedTime,PhotoExtension as Pdf,	PhotoType,	R.RequirementId,  	
			Photo,CreatedDate	
			,Photo src,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime,PhotoId
			FROM SaPhotos R inner join MsmeRequirements M on (R.RequirementId=M.RequirementId and r.NcCount=m.NcCount and r.ZedId=m.ZedId and r.Certification=m.SectionType) WHERE  (PhotoType in ('Evidence Photo')) and Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=0
			union
			SELECT 
			R.Id,	R.ZedId,	R.Certification, M.SectionCode, M.RequirementCode,null EvidenceId,'' EvidenceCode,R.Name EvidenceName,Certification SectionType,'' EvidenceType,'' ValidationRequired,null IsVerified,'' SourceOfValidation,null AssessorRemarks,'SaPhotos' TableName,'' DocumentOpenedTime,null Pdf,R.PhotoType,M.RequirementId,		
			case when R.PhotoType='Evidences' then isnull(R.Photo,CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Evidences/',R.PhotoId,'.jpg')) else
			isnull(R.Photo,CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) end as Photo,R.CreatedDate,	
			R.Photo src,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime,PhotoId
			FROM  SaRequirementPhotos R	inner join MsmeRequirements M on (R.RequirementId=M.Id)
			WHERE  R.Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=0 and (R.PhotoType='Evidence Photo')
	END
		
	IF @Certification='Bronze'
	BEGIN
		SELECT *,SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1) as OldZedId,
		concat('this.src="',
		concat('https://loginzed.msme.gov.in/mobileapi/Photos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/SiteExteriorPhotos/',PhotoId,'.',PhotoExtension),'"') as OldPath
		FROM MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=0
	END
	ELSE IF @Certification='Gold'
	BEGIN
		SELECT Id,ZedId,Certification,PhotoId,Name,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,
		UpdatedDate,NcCount,PhotoExtension,RequirementId,CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/',Name,'.jpg') Photo,
		CreatedDate,ProductId,DocumentOpenedTime,MsmeRemarks,
		concat('this.src="',
		concat('https://loginzed.msme.gov.in/surveillancemobileapi/SaPhotos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/',Name,'.jpg'),'"') as OldPath
		
		FROM SaPhotos 
		WHERE Certification=@Certification AND ZedId=@ZedId AND (name in ('Site Exterior Photo','Site Interior Photo') or (PhotoType='SiteExteriorPhotos')) AND NcCount=0
	END
	ELSE
	BEGIN
		SELECT *,
		concat('this.src="',
		concat('https://loginzed.msme.gov.in/mobileapi/SaPhotos/',SUBSTRING(ZedId, 1, CHARINDEX('_D', ZedId + '_D') - 1), '/',Certification,'/',Name,'.jpg'),'"') as OldPath
		FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=0
	END
	-- Lat Longs
	IF @Certification='Bronze'
	BEGIN
		SELECT TOP 1 Latitude, Longitude FROM MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='ProductPhotos' AND NcCount=0
	END
	ELSE
	BEGIN
		SELECT TOP 1 Latitude, Longitude FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteTour' AND NcCount=0
	END

