CREATE PROCEDURE [dbo].[SP_REPORT_GET_DETAILS_NC] --'<redacted>', '<redacted>'
(
	@Certification Varchar(50) = NULL,
	@ZedId Varchar(100) =NULL,
	@NcCount int = NULL,
	@UserId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
		
	SELECT * FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=@NcCount

   	SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=@NcCount ORDER BY cast(SectionCode as int)

	SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
	
	SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
	
	SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
	
	SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)

		
	SELECT *,'.jpg' as Jpg FROM MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=@NcCount
END


