/****** Object:  StoredProcedure [dbo].[SP_RESET_DOCUMENT_UPLOAD_PAYMENT_RESET]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_RESET_DOCUMENT_UPLOAD_PAYMENT_RESET] --'<redacted>', '<redacted>'
(	
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
	
)
AS
BEGIN

	SET NOCOUNT ON;

	UPDATE MsmeSections SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND SectionType = @Certification
	UPDATE MsmeRequirements SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND SectionType = @Certification
	UPDATE MsmeOptions SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND SectionType = @Certification
	UPDATE MsmeSubOptions SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND SectionType = @Certification
	UPDATE MsmeEvidences SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND SectionType = @Certification


	UPDATE MsmeCertifications SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification

	UPDATE MsmePhotos SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification

	UPDATE MsmePaymentInfo SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification
	UPDATE PaymentGateWayTransactions SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification

	UPDATE AssessorComments SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification
	UPDATE ScreenshotPhotos SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification
	UPDATE MsmeProducts SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND Certification = @Certification

	UPDATE MsmeHistory SET ZedId = CONCAT(ZedId, '_RESET') WHERE ZedId = @ZedId AND CertificationType = @Certification and statustype='ApplicationReceived'

	UPDATE Msme
	SET 
		IsGoldPaymentDone   = CASE WHEN @Certification = 'Gold' THEN NULL ELSE IsGoldPaymentDone END,
		IsSilverPaymentDone = CASE WHEN @Certification = 'Silver' THEN NULL ELSE IsSilverPaymentDone END,
		IsBronzePaymentDone = CASE WHEN @Certification = 'Bronze' THEN NULL ELSE IsBronzePaymentDone END
	WHERE ZedId = @ZedId

	UPDATE ZEDCS_V2_LIVE.dbo.Msme
	SET 
		IsSurGoldPaymentDone   = CASE WHEN @Certification = 'Gold' THEN NULL ELSE IsSurGoldPaymentDone END,
		IsSurSilverPaymentDone = CASE WHEN @Certification = 'Silver' THEN NULL ELSE IsSurSilverPaymentDone END,
		IsSurBronzePaymentDone = CASE WHEN @Certification = 'Bronze' THEN NULL ELSE IsSurBronzePaymentDone END
	WHERE ZedId = @ZedId

	INSERT INTO MsmeHistory(ZedId, Descrip, CreatedDate, CertificationType)
	VALUES (@ZedId, 'Reset  Payment  on the request of QCI', GETDATE(), @Certification)

END

GO
/****** Object:  StoredProcedure [dbo].[SP_RESET_FOR_SECOND_SURVEILLANCE]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_RESET_FOR_SECOND_SURVEILLANCE] 
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN		
				

		BEGIN TRY

				BEGIN TRAN

				DECLARE @CertId VARCHAR(20);

				SELECT TOP 1 @CertId = CAST(Id AS VARCHAR(20))
				FROM MsmeCertifications WITH (NOLOCK)
				WHERE ZedId = @ZedId 
				  AND Certification = @CertificationType
				ORDER BY Id DESC;


				update SaRequirementPhotos set ZedId=concat(ZedId,'_S_',SaReqCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeCertifications set ZedId=concat(ZedId,'_S_',Id) where ZedId=@ZedId and Certification=@CertificationType
				update SaRawMaterials set ZedId=concat(ZedId,'_S_',SaRawCertId) where ZedId=@ZedId and Certification=@CertificationType
				update AssessorComments set ZedId=concat(ZedId,'_S_',AsCmtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeLocations set ZedId=concat(ZedId,'_S_',MsmeLocCertId) where ZedId=@ZedId and Certification=@CertificationType
				update ScreenshotPhotos set ZedId=concat(ZedId,'_S_',SrnCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeRawMaterials set ZedId=concat(ZedId,'_S_',MsmeRawCertId) where ZedId=@ZedId and Certification=@CertificationType
				update PaymentGateWayTransactions set ZedId=concat(ZedId,'_S_',PmtGtCertId) where ZedId=@ZedId and Certification=@CertificationType and GwReSurveillance=1 
				update MsmePaymentInfo set ZedId=concat(ZedId,'_S_',MsmePmtCertId) where ZedId=@ZedId and Certification=@CertificationType and ReSurveillance=1 
				update MsmeSections set ZedId=concat(ZedId,'_S_',SecCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeRequirements set ZedId=concat(ZedId,'_S_',ReqCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeOptions set ZedId=concat(ZedId,'_S_',OptCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeSubOptions set ZedId=concat(ZedId,'_S_',SubCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmeEvidences set ZedId=concat(ZedId,'_S_',EviCertId) where ZedId=@ZedId and SectionType=@CertificationType
				update MsmePhotos set ZedId=concat(ZedId,'_S_',MsPtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeProducts set ZedId=concat(ZedId,'_S_',MsPrdCertId) where ZedId=@ZedId and Certification=@CertificationType
				update SaPhotos set ZedId=concat(ZedId,'_S_',SaPtCertId) where ZedId=@ZedId and Certification=@CertificationType
				update SaProducts set ZedId=concat(ZedId,'_S_',SaPrdCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeSelfies set ZedId=concat(ZedId,'_S_',MsSelfCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MsmeHistory set ZedId=concat(ZedId,'_S_',MsHistCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update MeetingParticipants set ZedId=concat(ZedId,'_S_',MeetPartCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update Meetings set ZedId=concat(ZedId,'_S_',MeetCertId) where ZedId=@ZedId and CertificationType=@CertificationType
				update EsgCheckList set ZedId=concat(ZedId,'_S_',EsgCertId) where ZedId=@ZedId and Certification=@CertificationType
				update MeetingRecordingLinks set ZedId=concat(ZedId,'_S_',MeetingsCertid) where ZedId=@ZedId and Certificationtype=@CertificationType


				IF @CertId IS NOT NULL
				BEGIN
					UPDATE [ZEDCS_V2_LIVE].[dbo].[ApiFinanceUnitDetailsResponse]
					SET ZedId = CONCAT(ZedId, '_S_', @CertId)
					WHERE ZedId = @ZedId
					  AND Certification = @CertificationType
					  AND ModuleName = 'SURVEILLANCE'
					  AND ApiType IN ('InvoiceData', 'ReceiptData')
					  ;

					UPDATE [ZEDCS_V2_LIVE].[dbo].[ApiFinanceUnitDetailsResponseErrors]
					SET ZedId = CONCAT(ZedId, '_S_', @CertId)
					WHERE ZedId = @ZedId
					  AND Certification = @CertificationType
					  AND ModuleName = 'SURVEILLANCE'
					  AND ApiType IN ('InvoiceData', 'ReceiptData')
					  ;
				END


				--UPDATE MsmeCertifications SET CertificationStatusDate=getdate(),CertificationStatus=101 where  ZedId=@ZedId and Certification=@CertificationType
				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('Unit data of ', @CertificationType,' is reset for Second Surveillance On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Unit data reset for Second Surveillance')
				

			COMMIT TRAN
		END TRY


		BEGIN CATCH

             ROLLBACK TRAN
			 UPDATE DummyUsersForError SET IsActive='ABC' where UserId='ZEDMSME000112'

		END CATCH

END



GO
/****** Object:  StoredProcedure [dbo].[SP_REVERT_SECOND_SURVEILLANCE_RESET]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_REVERT_SECOND_SURVEILLANCE_RESET]
(
    @OriginalZedId varchar(50),      -- The ID you want to restore (e.g., '<redacted>')
    @CorruptedZedId varchar(50),     -- The ID that was changed (e.g., '<redacted>')
    @CertificationType varchar(50)   -- e.g., '<redacted>', '<redacted>', '<redacted>'
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRANSACTION;

    BEGIN TRY
        -- Reverting all tables that were updated in the original reset SP
        UPDATE SaRequirementPhotos SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE MsmeCertifications SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE SaRawMaterials SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE AssessorComments SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE MsmeLocations SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE ScreenshotPhotos SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE MsmeRawMaterials SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
       -- UPDATE PaymentGateWayTransactions SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
      --  UPDATE MsmePaymentInfo SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE MsmeSections SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND SectionType = @CertificationType;
        UPDATE MsmeRequirements SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND SectionType = @CertificationType;
        UPDATE MsmeOptions SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND SectionType = @CertificationType;
        UPDATE MsmeSubOptions SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND SectionType = @CertificationType;
        UPDATE MsmeEvidences SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND SectionType = @CertificationType;
        UPDATE MsmePhotos SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE MsmeProducts SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE SaPhotos SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE SaProducts SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE MsmeSelfies SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE MsmeHistory SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND CertificationType = @CertificationType;
        UPDATE MeetingParticipants SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND CertificationType = @CertificationType;
        UPDATE Meetings SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND CertificationType = @CertificationType;
        UPDATE EsgCheckList SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certification = @CertificationType;
        UPDATE MeetingRecordingLinks SET ZedId = @OriginalZedId WHERE ZedId = @CorruptedZedId AND Certificationtype = @CertificationType;

        -- Cleanup: Remove the "Reset" log entry from MsmeHistory for the original ID
       

        COMMIT TRANSACTION;
        PRINT 'Revert completed successfully for ' + @OriginalZedId;
    END TRY

    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_SA_APP_CHECK_STATUS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_APP_CHECK_STATUS] --'<redacted>', '<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@AssessorId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @LeadAssessor varchar(50) = NULL,
			@CoAssessor   varchar(50) = NULL,
			@True bit = 1,
			@False bit = 0

			SELECT @LeadAssessor=SiteAssessorId,@CoAssessor=CoAssessorId FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

	SELECT 
		1 SaStatus,
		CASE WHEN 
		(select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@LeadAssessor and MeetingType='Open Meeting')>0 THEN @True ELSE @False end as OpenMeetingSubmitted, 

		CASE WHEN
		(select  count(*) from MsmeRequirements E inner join MsmeSections S on (S.SectionCode=E.SectionCode and S.ZedId=E.ZedId and S.NcCount=E.NcCount and E.NcCount=0 and S.SectionType=E.SectionType)
		left join SaRequirementPhotos P on (E.Id=P.RequirementId and E.ZedId=P.ZedId and E.NcCount=P.NcCount and E.NcCount=0 and P.Certification=E.SectionType)
		where AssessorId=@LeadAssessor and E.zedid=@ZedId and E.sectiontype=@Certification and (IsAssessmentExcempted='No' OR IsAssessmentExcempted IS NULL) 
		and ((E.SaConformance='Yes' and P.RequirementId is null) OR E.SaConformance IS NULL))=0 THEN @True ELSE @False end as AllParametersSyncedByLead,

		CASE WHEN
		(select  count(*) from MsmeRequirements E inner join MsmeSections S on (S.SectionCode=E.SectionCode and S.ZedId=E.ZedId and S.NcCount=E.NcCount and E.NcCount=0 and S.SectionType=E.SectionType)
		left join SaRequirementPhotos P on (E.Id=P.RequirementId and E.ZedId=P.ZedId and E.NcCount=P.NcCount and E.NcCount=0 and P.Certification=E.SectionType) 
		where AssessorId=@CoAssessor and E.zedid=@ZedId and E.sectiontype=@Certification and (IsAssessmentExcempted='No' OR IsAssessmentExcempted IS NULL) 
		and ((E.SaConformance='Yes' And  P.RequirementId is null) OR E.SaConformance IS NULL))=0 THEN @True ELSE @False end as AllParametersSyncedByCo,

		CASE 
		WHEN @CoAssessor IS NULL THEN @True
		WHEN (select count(*) from MsmeSections where zedid=@ZedId and SectionType=@Certification and AssessorId=@CoAssessor)=0 then @True
		WHEN (select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@CoAssessor and MeetingType='Final Submit')>0 THEN @True ELSE @False end as FinalSubmissionDone,

		CASE WHEN
		(select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@LeadAssessor and MeetingType='Close Meeting')>0 THEN @True ELSE @False end as ClosingMeetingSubmitted,

		CASE WHEN
		(SELECT count(*) FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification and SiteAssessorId=@AssessorId)>0 THEN @True ELSE @False end as LeadAssessor



	--select 1 SaStatus, 
	--	1 OpenMeetingSubmitted, 
	--	1 AllParametersSyncedByLead, 
	--	1 AllParametersSyncedByCo,
	--	1 FinalSubmissionDone, 
	--	1 ClosingMeetingSubmitted,
	--	1 LeadAssessor

	--from MsmeCertifications 
	--where ZedId=@ZedId 
	--	and Certification=@Certification
	
END






GO
/****** Object:  StoredProcedure [dbo].[SP_SA_APP_INSERT_CLOSE_MEETING]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_APP_INSERT_CLOSE_MEETING] 
(
	@RefId                    VarChar(50)			= NULL,
	@RegistrationNumber       VarChar(200)			= NULL,
	@AssessorId               VarChar(200)			= NULL,
	@Latitude                 VarChar(200)			= NULL,
	@Longitude                VarChar(200)			= NULL,
	@Comments                 VarChar(5000)			= NULL,
	@ParticipantsList   DynamicParticipants  READONLY
)
AS
BEGIN
	      
	SET NOCOUNT ON;
	
	
	DELETE FROM Meetings where MeetingType='CLOSE' and RegistrationNumber=@RegistrationNumber

	INSERT INTO Meetings(RefId,RegistrationNumber,AssessorId,Latitude,Longitude,Comments,FieldComments,MeetingType)
	values(@RefId,@RegistrationNumber,@AssessorId,@Latitude,@Longitude,@Comments,@Comments,'CLOSE')

	DELETE FROM MeetingParticipants where MeetingType='CLOSE' and RegistrationNumber=@RegistrationNumber

	INSERT INTO MeetingParticipants (RefId,RegistrationNumber,Name,Designation,MeetingType)
	select @RefId,@RegistrationNumber,Name,Designation,'CLOSE' from @ParticipantsList

	Update SelfAssessments set SaStatus=2,SaLastSyncTime=getdate() where RegistrationNumber=@RegistrationNumber 

	
END



GO
