-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_APP_INSERT_OPEN_MEETING] 
(
	@RefId                    VarChar(50)			= NULL,
	@ZedId				      VarChar(200)			= NULL,
	@AssessorId               VarChar(200)			= NULL,
	@CertificationType        VarChar(200)			= NULL,
	@PhotoType			      VarChar(200)			= NULL,
	@Latitude                 VarChar(200)			= NULL,
	@Longitude                VarChar(200)			= NULL,
	@Comments                 VarChar(5000)			= NULL,
	@ParticipantsList DynamicParticipants  READONLY,

	@PhotoList	DynamicPhotoList2	READONLY
)
