	BEGIN
		
		INSERT INTO Meetings(RefId,ZedId,AssessorId,Latitude,Longitude,Comments,FieldComments,MeetingType,CertificationType)
		values(@RefId,@ZedId,@AssessorId,@Latitude,@Longitude,@Comments,@Comments,@PhotoType,@CertificationType)

		INSERT INTO MeetingParticipants (RefId,ZedId,Name,Designation,MeetingType,CertificationType)
		select @RefId,@ZedId,Name,Designation,@PhotoType,@CertificationType from @ParticipantsList 

		INSERT INTO SaPhotos (ZedId,AssessorId,  Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount)
		SELECT @ZedId, @AssessorId,  @CertificationType, @PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,@NcCount FROM @PhotoList

		update MsmeCertifications set IsSaVerified='Yes' where ZedId=@ZedId and Certification=@CertificationType

		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Open Meeting Done by ',@AssessorId, 'for',  @CertificationType),getdate(),@CertificationType,NULL)

