/****** Object:  StoredProcedure [dbo].[SP_SA_APP_INSERT_REQUIREMENT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE  PROCEDURE [dbo].[SP_SA_APP_INSERT_REQUIREMENT] 
(
	@RegistrationNumber VarChar(200)			= NULL,
	@RefId VarChar(200)		                    = NULL,
	@ElementId VarChar(300)			            = NULL,
	@SubElementId VarChar(300)			        = NULL,	
	@RequirementId varchar(300)		            = NULL, 
	@RequirementCode varchar(300)        		= NULL, 
	@AnswerCode varchar(300)		            = NULL,
	@Remarks varchar(2000)               		= NULL,	

	@PhotoList  DynamicPhotoList			READONLY,
	@OfiComments varchar(5000)                  = NULL,
	@UserId varchar(200)						= NULL
                             
	 
)
AS
BEGIN
	
	IF EXISTS
	(Select * from SaRequirements where RegistrationNumber=@RegistrationNumber AND RequirementId=@RequirementId)
	BEGIN
		Update SaRequirements SET AnswerCode=@AnswerCode, Remarks=@Remarks,FieldRemarks=@Remarks where RegistrationNumber=@RegistrationNumber AND RequirementId=@RequirementId
	END
	ELSE
	BEGIN
	  INSERT INTO SaRequirements (RegistrationNumber,RefId,ElementId,SubElementId,RequirementId,RequirementCode,AnswerCode,Remarks,FieldRemarks) 
	  VALUES(@RegistrationNumber,@RefId,@ElementId,@SubElementId,@RequirementId,@RequirementCode,@AnswerCode,@Remarks,@Remarks)
	END

	IF EXISTS
	(Select * from SaPhotoList where RegistrationNumber=@RegistrationNumber AND RequirementId=@RequirementId)
	BEGIN
		Delete from SaPhotoList where RegistrationNumber=@RegistrationNumber AND RequirementId=@RequirementId
	END
	  INSERT INTO SaPhotoList(RegistrationNumber,ElementId,SubElementId,RequirementId,RequirementCode,PhotoId,Name,TimeStamp,Latitude,Longitude) 
	  SELECT @RegistrationNumber,@ElementId,@SubElementId,@RequirementId,@RequirementCode,PhotoId,Name,TimeStamp,Latitude,Longitude FROM   @PhotoList
   


   IF (SELECT COUNT(*) FROM SaOfiComments WHERE RegistrationNumber=@RegistrationNumber AND ElementId=@ElementId)>0
     BEGIN
	   UPDATE SaOfiComments SET OfiComments=@OfiComments,FieldOfiComments=@OfiComments  WHERE RegistrationNumber=@RegistrationNumber AND ElementId=@ElementId
	 END
  ELSE  
     BEGIN
	   INSERT INTO SaOfiComments (RegistrationNumber,RefId,ElementId,OfiComments,FieldOfiComments,UserId)
	   VALUES(@RegistrationNumber,@RefId,@ElementId,@OfiComments,@OfiComments,@UserId) 
     END

   Update SelfAssessments set SaLastSyncTime=getdate() where RegistrationNumber=@RegistrationNumber 

END

GO
/****** Object:  StoredProcedure [dbo].[SP_SA_CHECK_LOGIN_saathi]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_CHECK_LOGIN_saathi] --'<redacted>', '<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@Password varchar(50) = NULL,
	@RegId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	Declare @Acommodationtype Varchar(50)
	Declare @StateName Varchar(100)
	Declare @AllowFinalSubmit bit
	
	SET NOCOUNT ON;

	SELECT @StateName=StateName , 
		@Acommodationtype=CASE WHEN QuestionnaireName in ('Restaurants','Bed and Breakfast')  then QuestionnaireName 
							   WHEN  RestaurantType='With in-house restaurant' then 'Hotel and Restaurants' 
							   else 'Hotel' 
						  end
	FROM SelfAssessments S left join Acommodationtypes A on (S.Acommodationtype=A.Acommodationtype) WHERE	RegistrationNumber=@RegId 

	if exists(SELECT Q.Id FROM Requirements Q LEFT JOIN SaRequirements R on (Q.Id=R.RequirementId and R.RegistrationNumber=@RegId) where Q.SectionType =@Acommodationtype and R.Id IS NULL)
		SET @AllowFinalSubmit = 0
	else
		SET @AllowFinalSubmit = 1
	

	SELECT * FROM Users WHERE RoleId=3 AND IsActive=1 AND UserId=@UserId AND Password=@Password 

    SELECT S.Id, StateName, DistrictName, RespondentName, MobileNo, S.CreatedDate, Email, Status, IsTerminated, FinalSubmitDate, EstablishmentType, RespondentMobileNo, 
		EstablishmentName, EstablishmentAddress, EstablishmentCity, EstablishmentPinCode, EstablishmentPhoneNo, EstablishmentFaxNo, EstablishmentWebsite, 
		Acommodationtype, TotalRooms, RegistrationNumber, IsDeclarationAccepted, CertificateNo, RestaurantType,
		ISNULL(CurrentQuestion,-1) + 1 CurrentQuestion,
	    WebinarId,W.WebinarUrl,
	    convert(varchar,W.WebinarStartTime,100) WebinarStartTime, convert(varchar,W.WebinarEndTime,100) WebinarEndTime, convert(varchar, W.WebinarDate, 100) WebinarDate,
		EstablishmentAddress + ',' + case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName + ', ' + case when EstablishmentPinCode is null or EstablishmentPinCode='' then '' else EstablishmentPinCode end EstablishmentFullAddress,
		REPLACE(ISNULL(SAStatus,0),3,2) SAStatus, Convert(bit,case when SaStatus>0 then 1 else 0 end) IsOpenMeetingSynced, @AllowFinalSubmit AllowFinalSubmit
	FROM SelfAssessments S
	LEFT JOIN Webinars W on (S.WebinarId=W.Id) 
	WHERE RegistrationNumber=@RegId AND AssessorUserId=@UserId --and sastatus in (0,1)

	select S.Id,CASE WHEN T.OrderNo=2 then 'S' + S.SectionCode else S.SectionCode end as SectionCode,S.SectionName,S.OrderNo,iButton,SectionImage,S.SectionType, T.OrderNo QType from Sections S inner join SectionTypes T on (S.SectionType=T.SectionType)
	where S.SectionType in (@Acommodationtype,@statename) 
	order by T.OrderNo,S.OrderNo

	SELECT CASE WHEN T.OrderNo=2 then (select count(*) from Sections where SectionType = @Acommodationtype) + convert(int,S.SectionCode) else convert(int,S.SectionCode) end as SectionSno, ROW_NUMBER() OVER(ORDER BY S.OrderNo, Q.OrderNo) SNo, CASE WHEN T.OrderNo=2 then 'S' + S.SectionCode else S.SectionCode end as SectionCode, S.SectionName, S.iButton,NULL AnswerCode, 
		Q.Id, Q.QuestionCode, Q.QuestionName, Q.OrderNo, Q.iButton iButtonQ, Q.QuestionImage,S.SectionType
	FROM Questions Q 
	inner join Sections S on (Q.SectionCode=S.SectionCode and Q.SectionType=S.SectionType)
    inner join SectionTypes T on (Q.SectionType=T.SectionType) 
	where Q.SectionType in (@Acommodationtype,@statename) and S.SectionType in (@Acommodationtype,@statename)
	ORDER By T.OrderNo, cast(S.SectionCode as int)


	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, QuestionCode, RequirementCode) SNo, Id, CASE WHEN T.OrderNo=2 then 'S' + Q.SectionCode else Q.SectionCode end as SectionCode,
	SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,Q.OrderNo,Q.SectionType
	FROM Requirements Q inner join SectionTypes T on (Q.SectionType=T.SectionType) 
	where Q.SectionType in (@Acommodationtype,@statename)
	ORDER By T.OrderNo, cast(SectionCode as int), QuestionCode, RequirementCode

	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, QuestionCode, RequirementCode, OptionCode) SNo, 	Id,CASE WHEN T.OrderNo=2 then 'S' + Q.SectionCode else Q.SectionCode end as SectionCode,
	QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,Q.SectionType
	FROM Options Q inner join SectionTypes T on (Q.SectionType=T.SectionType) 
	where Q.SectionType in (@Acommodationtype,@statename)
	ORDER By T.OrderNo, cast(SectionCode as int), QuestionCode, RequirementCode, OptionCode

	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, QuestionCode, RequirementCode, OptionCode, SubOptionCode) SNo, Id,CASE WHEN T.OrderNo=2 then 'S' + Q.SectionCode else Q.SectionCode end as SectionCode,
	QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,Q.SectionType
	FROM SubOptions Q inner join SectionTypes T on (Q.SectionType=T.SectionType) 
	where Q.SectionType in (@Acommodationtype,@statename)
	ORDER By T.OrderNo, SectionCode, QuestionCode, RequirementCode, OptionCode, SubOptionCode

END

GO
/****** Object:  StoredProcedure [dbo].[SP_SA_CHECK_VALID_DATE]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_CHECK_VALID_DATE] --'<redacted>', '<redacted>'
(
	@RegistrationNumber varchar(50) = NULL,
	@SaDate varchar(100) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	select case when convert(datetime, @SaDate) >=  ISNULL(PaymentDate, GETDATE()) + 6 then 1 else 0 end ValidDate from SelfAssessments where RegistrationNumber=@RegistrationNumber

END

