SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_SA_GET_DASHBOARD_DETAILS] --NULL,NULL
(
	@UserId varchar(50)=NULL,
    @RoleId varchar(50)=NULL

)
AS
BEGIN
	
 
    SELECT [RegistrationNumber]
	   ,EstablishmentName as [Unit Name]  
	  ,[Acommodationtype] [Acommodation Type]
      ,[TotalRooms] [Total Rooms]
	  ,RestaurantType
	  ,Category
	  ,[EstablishmentCity]
	  ,[DistrictName]
      ,[StateName]
      ,[EstablishmentPinCode]
	  ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[RespondentName]
      ,[MobileNo]
      ,[EmailId]
	  ,[AssessorUserId]
	FROM SelfAssessments 
	ORDER BY SelfCertificationDate  

select  sq.RegistrationNumber,sq.RefId,sq.ElementId,sq.SubElementId,sq.RequirementId,sq.RequirementCode,AnswerCode,Remarks,CreatedDate,PhotoId,Name,TimeStamp
		from  SaRequirements  sq left join SaPhotoList sp 
		on sq.RegistrationNumber=sp.RegistrationNumber and sq.elementid=sp.elementid and sq.elementid=sp.elementid and sq.RequirementId=sp.RequirementId
		and sq.RequirementCode=sp.RequirementCode


END



