GO

CREATE PROC [dbo].[SP_SA_PAYMENT_BASIC_DETAILS] --'<redacted>'
(
	@RegistrationNo varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	@AmountToBePaid varchar(50) = NULL
)
AS
BEGIN

	DECLARE @NoofRooms int = NULL
	SELECT @NoofRooms=TotalRooms from SelfAssessments where RegistrationNumber=@RegistrationNo
	SELECT @AmountToBePaid=Total from SaPaymentCases where @NoofRooms>=MinNumOfRooms and @NoofRooms<= Isnull(MaxNumOfRooms,@NoofRooms)

	--SET @AmountToBePaid=1.00 -- For Testing
	
	Insert into PaymentGatewayTransactions (RegistrationNumber,TransactionId,TransactionStatus,Amount,TransactionDate)
	values (@RegistrationNo,@TransactionId,1,@AmountToBePaid,getdate())

	Select EstablishmentName,MobileNo,EmailId,@AmountToBePaid AmountToBePaid,RegistrationNumber from SelfAssessments where RegistrationNumber=@RegistrationNo
	

END



