CREATE PROCEDURE [dbo].[SP_SEND_AUTO_MAIL_FOR_AUTO_ALLOT_AGENCY] --'<redacted>', '<redacted>'
(
	@ZedId varchar(200) = NULL,
	@Certification varchar(200) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @Subject NVARCHAR(500)
	DECLARE @htmlBody NVARCHAR(MAX)
	DECLARE @htmlBodyPart1 NVARCHAR(MAX)
    DECLARE @htmlBodyPart2 NVARCHAR(MAX)
	DECLARE @RecipientEmail NVARCHAR(500)

	DECLARE @Agency NVARCHAR(500)
	DECLARE @EstablishmentName NVARCHAR(500)
	DECLARE @Address NVARCHAR(2000)
	DECLARE @CurrentYear NVARCHAR(4) = CONVERT(NVARCHAR(4), YEAR(GETDATE()))

	DECLARE @ModeOfAssessment NVARCHAR(500)

	IF @Certification='Bronze'
	BEGIN
		SET @ModeOfAssessment='OnSite Assessment'
	END
	ELSE
	BEGIN
		SET @ModeOfAssessment='Remote Assessment'
	END
	
	SET @Subject = CONCAT('Allocation of MSME for ZED Surveillance Assessment under “MSME Sustainable (ZED) Certification” Scheme - ',@ZedId)

	--select @Agency=CertificationBodyUserId, @RecipientEmail=U.Email from ZEDCS_V2_LIVE.dbo.MsmeCertifications C inner join Users U on (C.CertificationBodyUserId=U.UserId) where ZedId=@ZedId AND Certification=@Certification and CertificationStatus=16 and U.RoleId=2 AND RestrictMail is null

	select @Agency=CertificationBodyUserId, @RecipientEmail=U.Email
	from MsmeCertifications C inner join Users U on (C.CertificationBodyUserId=U.UserId) 
	where ZedId=@ZedId AND Certification=@Certification and U.RoleId=2 and IsActive=1

	select @EstablishmentName=PUnitName,@Address=concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin) from Msme where ZedId=@ZedId

	

	 SET @htmlBodyPart1 = 
			'<html>
				<link href="https://fonts.googleapis.com/css2?family=Work+Sans:wght@400;600;700&display=swap" rel="stylesheet">
				<div>
					<table width="65%" bgcolor="#45A5AD" border="0" cellpadding="0" cellspacing="0" >
						<tr>
							<td>
								<br><br>
								<div style="text-align: center;margin: 0 auto;box-shadow: 0px 4px 8px 0px #00000026;
									background: #ffffff;margin-bottom: 15px;max-width: 600px;">
									<img src="http://loginzed.msme.gov.in/Images/header/zed-logo.png" height="120" alt="ZED Logo" />
								</div>
								<table class="content" bgcolor="#ffffff" align="center" cellpadding="0" cellspacing="0" border="0" style="box-shadow:0px 4px 8px 0px #00000026; max-width: 600px;">
									<tr>
										<td style="padding: 0 3em;line-height: 26px;">
											<p style="font-size: 13px; margin-bottom: 0;">Dear Madam/Sir,</p>
											<p style="font-size: 13px; margin-bottom: 0;">Greetings of the day!</p>
											<p style="font-size: 13px; margin-bottom: 0;">An MSME Unit has been allocated to you for ZED Surveillance Assessment. The details are as follows: </p>
											<table style="width: 100%; table-layout: fixed; font-size: 13px;padding: 15px;  background: #F0F0F0;" cellpadding="0" cellspacing="0" border="0">
												<tbody bgcolor="#ffffff">
													<tr>
														<td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">MSME ZED ID</td>
														<td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@ZedId, '') + '</td>
													</tr>
													<tr>
														<td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Unit Name</td>
														<td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@EstablishmentName, '') + '</td>
													</tr>
													<tr>
														<td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Unit Address</td>
														<td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Address, '') + '</td>
													</tr>
													<tr>
														<td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Certification Level</td>
														<td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@Certification, '') + '</td>
													</tr>
													<tr>
														<td style="border-bottom:2px solid #f0f0f0;padding: 15px; width: 30%; font-size: 13px; text-align: left; padding-right: 20px;">Mode of Assessment</td>
														<td style="border-bottom:2px solid #f0f0f0;font-weight: 700;">' + COALESCE(@ModeOfAssessment, '') + '</td>
													</tr>
												</tbody>
											</table>
											<span></span>
											<div style="text-align: center; padding: 30px 0;">
												<a href="http://loginzed.msme.gov.in/Surveillance/User/Login" target="_blank" style="display: block; margin: 0 auto; width: 300px; line-height: 42px; color: #ffffff; background-color: #555555; text-decoration: none; border-radius: 4px; text-align: center;">Click here to Login</a>
											</div>
											<p style="font-size: 13px; margin-bottom: 0;">In case of any query, please mail us at: zed@qcin.org. Please mention your Agency ID in all your correspondence.</p>
											<p style="font-size: 13px; margin-bottom: 0px;">Thanks and Regards,</p>
											<p style="font-size: 13px; margin-bottom: 20px;">ZED Team</p>
										</td>
									</tr>
								</table>'
                    
SET @htmlBodyPart2 =
			'                   <div style="text-align: center; padding-top: 30px; padding-bottom: 30px;"><small style="font-size: 12px; color: #ffffff;">&copy; ZED ' + @CurrentYear + '</small></div>
							</td>
