	select @Agency=CertificationBodyUserId, 
	 @AgencyName=UserName,@SpocEmailId=U.Email,@SpocMobileNo=MobileNo,@SpocName=SpocName
	from MsmeCertifications C inner join Users U on (C.CertificationBodyUserId=U.UserId) 
	where ZedId=@ZedId AND Certification=@Certification and U.RoleId=2 and IsActive=1


	select @EstablishmentName=PUnitName,@Address=concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin),@RecipientEmail=EmailId  from Msme where ZedId=@ZedId

	

