/****** Object:  StoredProcedure [dbo].[SP_SEND_BACK_TO_AGENCY_BRONZE_REALLOCATION]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_SEND_BACK_TO_AGENCY_BRONZE_REALLOCATION] --'<redacted>','<redacted>'
(
    @ZedId VARCHAR(50),
    @Certification VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRAN;

        UPDATE MsmeCertifications SET EvidenceSubmissionDate=NULL, CertificationStatusDate=NULL,
		AuditsConducted = NULL,DomesticCustomers = NULL,InternationalCustomers =  NULL,RawMaterialImported = NULL,EnergySources = NULL,
		OutsourcedProcesses = NULL,CertificationStatus=1, DesktopAssessorId=NULL, AcceptOrRejectDate=NULL
		WHERE ZedId=@ZedId AND Certification=@Certification;

		UPDATE ZED_SURVEILLANCE.dbo.MsmeRequirements set AssessorRemarks=null,OpenedFlag=null where zedid=@ZedId and SectionType=@Certification;
		
		UPDATE ZED_SURVEILLANCE.dbo.MsmeEvidences set DocumentOpenedTime=null ,SyncedDate=NULL where zedid=@ZedId and SectionType=@Certification ;

		UPDATE ZED_SURVEILLANCE.dbo.MsmePhotos SET ZedId=CONCAT(@ZedId,'_del') WHERE ZedId=@ZedId AND Certification=@Certification;

		UPDATE ZED_SURVEILLANCE.dbo.AssessorComments SET ZedId=CONCAT(@ZedId,'_del') WHERE ZedId=@ZedId AND Certification=@Certification;

		Update ZED_SURVEILLANCE.dbo.MsmeProducts SET ZedId=CONCAT(@ZedId,'_del') WHERE ZedId=@ZedId AND Certification=@Certification;


		--Update ZED_SURVEILLANCE.dbo.MsmeHistory SET ZedId=CONCAT(@ZedId,'<redacted>') WHERE ZedId=@ZedId AND CertificationType=@Certification and StatusType != '<redacted>';


		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,'Send back to agency for allocation request of QCI',getdate(),@Certification,null)

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        ROLLBACK TRAN;
        THROW;
    END CATCH
END
GO
