      ,[EstablishmentFaxNo]
      ,[IsDeclarationAccepted]
      ,[CurrentQuestion]
      ,[CertificateNo]
      ,[Name]
      ,[IssuedOn]
      ,[ResetDate]
      ,[EstablishmentCity]
      ,[EstablishmentWebsite]
      ,[Acommodationtype]
      ,[TotalRooms]
      ,[RegistrationNumber]
      ,[Category]
      ,[RestaurantType]
      ,[WebinarId]
      ,[WebinarDate]
      ,[WebinarUrl]
      ,[IpAddress])

	SELECT [Id]
      ,[StateCode]
      ,[StateName]
      ,[DistrictCode]
      ,[DistrictName]
