	INNER JOIN SelfAssessments S on (R.RegistrationNumber=S.RegistrationNumber)
	WHERE (R.RegistrationNumber=@RegistrationNumber AND CertificateVersion=1) OR (WebinarCertificateId=@RegistrationNumber)

END


