-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_WEBINAR_GET_NEW_LIST] --'<redacted>'
(
	@RegistrationNo varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
    

	SELECT Id, FORMAT(WebinarStartTime, 'MMM d, yyyy h:mm tt') WebinarStartTime, FORMAT(WebinarEndTime, 'MMM d, yyyy h:mm tt') WebinarEndTime, 
		WebinarUrl, FeedbackUrl, RegistrationCount, CreatedDate, 
		--CASE WHEN IsRegistrationsClosed=1 OR isnull(B.NoOfRegistrations,0)>=RegistrationCount OR WebinarStartTime <= getdate()  THEN '<redacted>' ELSE '<redacted>' END AS WebinarStatus
		CASE WHEN IsRegistrationsClosed=1 OR isnull(B.NoOfRegistrations,0)>=200 OR WebinarStartTime <= getdate()  THEN 'Closed' ELSE 'Open' END AS WebinarStatus,
		CASE WHEN WebinarEndTime < GETDATE() THEN 'Conducted' 
			ELSE '' END AS WebinarConductedStatusDisplay

	FROM Webinars W 
	left join 
	(select WebinarId,count(*) [NoOfRegistrations] from WebinarRegistrations group by WebinarId) B 
	on (W.Id=B.WebinarId)
	ORDER BY  convert(datetime, WebinarStartTime) DESC
 

	--SELECT W.* FROM WebinarRegistrations W Inner join SelfAssessments S on (W.WebinarId=S.WebinarId AND W.RegistrationNumber=S.RegistrationNumber) WHERE W.RegistrationNumber=@RegistrationNo
	SELECT W.*,FORMAT(WebinarStartTime, 'MMM d, yyyy h:mm tt') WebinarStartTime, FORMAT(WebinarEndTime, 'MMM d, yyyy h:mm tt') WebinarEndTime,
	WebinarUrl FROM WebinarRegistrations W Inner join Webinars S on (W.WebinarId=S.Id) WHERE W.RegistrationNumber=@RegistrationNo order by convert(datetime,WebinarStartTime)

END


