CREATE PROCEDURE [dbo].[SP_WEBINAR_GET_REGISTRATIONS] --7
(
	@WebinarId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
    
	SELECT W.*, S.EstablishmentName, S.EstablishmentPinCode, FORMAT(S.FinalSubmitDate, 'MMMM d, yyyy h:mm tt') SelfCertificateDate, FORMAT(W.CreatedDate, 'MMMM d, yyyy h:mm tt') WebinarRegistrationDate,
		REPLACE(UPPER(case when S.EstablishmentCity is null or S.EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when S.DistrictName is null or S.DistrictName='' then '' else DistrictName + ', ' end + S.StateName),'*','') EstablishmentFullAddress,
