/****** Object:  StoredProcedure [dbo].[SURVEILLANCE_REJECTION_NOTSTARTED_ASSESSMENT]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [dbo].[SURVEILLANCE_REJECTION_NOTSTARTED_ASSESSMENT]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CurrentZedId VARCHAR(50);
    DECLARE @CurrentCertType VARCHAR(50);
    DECLARE @CustomRemark VARCHAR(255) = 'Direct rejection due to inactivity';

    -- 1. Declare the cursor based on your specific Silver/Gold criteria
    DECLARE InactivityCursor CURSOR FOR 
    SELECT 
        ZedId, 
        Certification 
    FROM 
        msmecertifications 
    WHERE 
        CertificationStatus = 17 
        AND PreviousCertificationStatus in ( 8,9)
        AND Certification IN ('Silver', 'Gold');

    OPEN InactivityCursor;
    FETCH NEXT FROM InactivityCursor INTO @CurrentZedId, @CurrentCertType;

    -- 2. Processing Loop
    WHILE @@FETCH_STATUS = 0
    BEGIN
        PRINT 'Processing Inactive Unit: ' + @CurrentZedId;

        BEGIN TRY
            BEGIN TRAN;

            -- A. TAKE BACKUP
            -- Ensuring we track exactly what we are about to change
             INSERT INTO MsmeCertifications_Backup_Upgrade (
		Id,ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported
		,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,AcceptOrRejectDate
		,ReasonForRejection,DesktopAssessorId,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate
		,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus
		,CertificationStatusDate,DaCertificateNo,SaCertificateNo,AssessorRemarks,NcStatus,Nc1Status
		,Nc2Status,Nc3Status,Nc4Status,Nc5Status,SaAssessorRemarks,IsSaVerified,IsSaSelfieSubmitted,SaAuditsConducted
		,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources
		,CreatedDate,JoinRoomStatus,QrCodeSeqNo,NcFinalClosureDt,SendBackStatus,IsAutoReject,ManufacturingCapacityUnits
		,ManufacturingCapacityValue,MonthlyUtilizationUnits,MonthlyUtilizationValue,SaManufacturingCapacityUnits,SaManufacturingCapacityValue
		,SaMonthlyUtilizationUnits,SaMonthlyUtilizationValue,AllowFinalSubmitManual,IdDisabled,CertificationLevel
		,MeetingLink,MinimumParameters,AutoMailSend,LeadInCertification,CoInCertification,PhotosPath,AutoAllocationDate,PreviousCertificationStatus
		)
        SELECT 
		Id,ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported
		,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,AcceptOrRejectDate
		,ReasonForRejection,DesktopAssessorId,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate
		,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus
		,CertificationStatusDate,DaCertificateNo,SaCertificateNo,AssessorRemarks,NcStatus,Nc1Status
		,Nc2Status,Nc3Status,Nc4Status,Nc5Status,SaAssessorRemarks,IsSaVerified,IsSaSelfieSubmitted,SaAuditsConducted
		,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources
		,CreatedDate,JoinRoomStatus,QrCodeSeqNo,NcFinalClosureDt,SendBackStatus,IsAutoReject,ManufacturingCapacityUnits
		,ManufacturingCapacityValue,MonthlyUtilizationUnits,MonthlyUtilizationValue,SaManufacturingCapacityUnits,SaManufacturingCapacityValue
		,SaMonthlyUtilizationUnits,SaMonthlyUtilizationValue,AllowFinalSubmitManual,IdDisabled,CertificationLevel
		,MeetingLink,MinimumParameters,AutoMailSend,LeadInCertification,CoInCertification,PhotosPath,AutoAllocationDate,PreviousCertificationStatus
		FROM MsmeCertifications  
        WHERE ZedId = @CurrentZedId AND Certification = @CurrentCertType;

			IF @CurrentCertType = 'Bronze'
			BEGIN
				UPDATE MsmeCertifications 
					SET 
						CertificationStatusDate = GETDATE(), 
						CertificationStatus = 99,
						CertificationBodyUserId = NULL,
						DesktopAssessorId = NULL,
						AssessorRemarks = @CustomRemark
					WHERE 
						ZedId = @CurrentZedId 
						AND Certification = @CurrentCertType;
			END
			ELSE
			BEGIN
					UPDATE MsmeCertifications 
					SET 
						CertificationStatusDate = GETDATE(), 
						CertificationStatus = 99,
						-- We nullify the CB ID so they cannot claim they performed the rejection
						CertificationBodyUserId = NULL,
						SiteAssessorId = NULL,
						SaAssessorRemarks = @CustomRemark
					WHERE 
						ZedId = @CurrentZedId 
						AND Certification = @CurrentCertType;
			END
            

            -- C. INSERT HISTORY
            INSERT INTO MsmeHistory (ZedId, Descrip, CreatedDate, CertificationType, StatusType)
            VALUES (
                @CurrentZedId, 
                @CustomRemark, 
                GETDATE(), 
                @CurrentCertType, 
                'Unit moved Final Rejection due to inactivity'
            );

            -- D. ARCHIVE / MONITORING NOTIFICATION
            EXEC [dbo].[SP_MONITORING_REJECT_CERTIFICATION] 
                @UserId = 'Inactivity_Cleanup_Script', 
                @ZedId = @CurrentZedId, 
                @CertificationType = @CurrentCertType, 
                @RoleId = NULL;

            COMMIT TRAN;
            PRINT 'Successfully rejected and unassigned: ' + @CurrentZedId;
        END TRY
        BEGIN CATCH
            IF @@TRANCOUNT > 0 ROLLBACK TRAN;
            PRINT 'Error processing ' + @CurrentZedId + ': ' + ERROR_MESSAGE();
        END CATCH

        FETCH NEXT FROM InactivityCursor INTO @CurrentZedId, @CurrentCertType;
    END

    CLOSE InactivityCursor;
    DEALLOCATE InactivityCursor;
    PRINT 'Inactivity Cleanup Complete.';

END
GO
/****** Object:  StoredProcedure [dbo].[SURVEILLANCE_REJECTION_UPGRADED_MAINSYSTEM]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[SURVEILLANCE_REJECTION_UPGRADED_MAINSYSTEM]
AS
BEGIN
    SET NOCOUNT ON;
   

   DECLARE @CurrentZedId VARCHAR(50);
DECLARE @CurrentCertType VARCHAR(50);
DECLARE @CustomRemark VARCHAR(255) = 'Certification upgraded in ZED, surveillance not required';

-- 1. Declare the cursor (Original Joins)
DECLARE UpgradeCursor CURSOR FOR 
SELECT 
    sb.zedid, 
    sb.lastestcertification AS Surveillance_Basic_Cert
FROM 
    zed_surveillance.dbo.msme M 
INNER JOIN 
    zed_surveillance.dbo.msmebasicinformation sb ON m.zedid = sb.zedid
INNER JOIN 
    zed_surveillance.dbo.msmecertifications sc ON sb.zedid = sc.zedid
INNER JOIN 
    zedcs_v2_live.dbo.msmecertifications lc ON sb.ZedId = lc.zedid
WHERE 
    sb.lastestcertification = 'Bronze'
    AND sc.Certification = 'Bronze' AND sc.CertificationStatus < 6
    AND lc.Certification IN ('Silver', 'Gold')
    AND lc.CertificationStatus = 16;

OPEN UpgradeCursor;
FETCH NEXT FROM UpgradeCursor INTO @CurrentZedId, @CurrentCertType;

-- 2. Processing Loop
WHILE @@FETCH_STATUS = 0
BEGIN
    PRINT 'Processing ZedId: ' + @CurrentZedId;

    BEGIN TRY
        BEGIN TRAN;

        -- A. TAKE BACKUP (Now works without Identity errors)
        INSERT INTO MsmeCertifications_Backup_Upgrade (
		Id,ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported
		,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,AcceptOrRejectDate
		,ReasonForRejection,DesktopAssessorId,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate
		,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus
		,CertificationStatusDate,DaCertificateNo,SaCertificateNo,AssessorRemarks,NcStatus,Nc1Status
		,Nc2Status,Nc3Status,Nc4Status,Nc5Status,SaAssessorRemarks,IsSaVerified,IsSaSelfieSubmitted,SaAuditsConducted
		,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources
		,CreatedDate,JoinRoomStatus,QrCodeSeqNo,NcFinalClosureDt,SendBackStatus,IsAutoReject,ManufacturingCapacityUnits
		,ManufacturingCapacityValue,MonthlyUtilizationUnits,MonthlyUtilizationValue,SaManufacturingCapacityUnits,SaManufacturingCapacityValue
		,SaMonthlyUtilizationUnits,SaMonthlyUtilizationValue,AllowFinalSubmitManual,IdDisabled,CertificationLevel
		,MeetingLink,MinimumParameters,AutoMailSend,LeadInCertification,CoInCertification,PhotosPath,AutoAllocationDate,PreviousCertificationStatus
		)
        SELECT 
		Id,ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported
		,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,AcceptOrRejectDate
		,ReasonForRejection,DesktopAssessorId,SiteAssessorId,CoAssessorId,ModeOfAssessment,AssessmentDate
		,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus
		,CertificationStatusDate,DaCertificateNo,SaCertificateNo,AssessorRemarks,NcStatus,Nc1Status
		,Nc2Status,Nc3Status,Nc4Status,Nc5Status,SaAssessorRemarks,IsSaVerified,IsSaSelfieSubmitted,SaAuditsConducted
		,SaDomesticCustomers,SaInternationalCustomers,SaRawMaterialImported,SaOutsourcedProcesses,SaEnergySources
		,CreatedDate,JoinRoomStatus,QrCodeSeqNo,NcFinalClosureDt,SendBackStatus,IsAutoReject,ManufacturingCapacityUnits
		,ManufacturingCapacityValue,MonthlyUtilizationUnits,MonthlyUtilizationValue,SaManufacturingCapacityUnits,SaManufacturingCapacityValue
		,SaMonthlyUtilizationUnits,SaMonthlyUtilizationValue,AllowFinalSubmitManual,IdDisabled,CertificationLevel
		,MeetingLink,MinimumParameters,AutoMailSend,LeadInCertification,CoInCertification,PhotosPath,AutoAllocationDate,PreviousCertificationStatus
		FROM MsmeCertifications 
        WHERE ZedId = @CurrentZedId AND Certification = @CurrentCertType;

        -- B. UPDATE & NULLIFY IDS (Original logic + team request)
        IF @CurrentCertType = 'Bronze'
        BEGIN
            UPDATE MsmeCertifications 
            SET CertificationStatusDate = GETDATE(), 
                CertificationStatus = 99,
                AssessorRemarks = @CustomRemark,
                DesktopAssessorId = NULL,       -- Set to NULL
                CertificationBodyUserId = NULL  -- Set to NULL
            WHERE ZedId = @CurrentZedId AND Certification = @CurrentCertType;
        END
        ELSE
        BEGIN
            UPDATE MsmeCertifications 
            SET CertificationStatusDate = GETDATE(), 
                CertificationStatus = 99,
                SaAssessorRemarks = @CustomRemark,
                DesktopAssessorId = NULL,       -- Set to NULL
                CertificationBodyUserId = NULL  -- Set to NULL
            WHERE ZedId = @CurrentZedId AND Certification = @CurrentCertType;
        END

        -- C. INSERT HISTORY (Original Logic)
        INSERT INTO MsmeHistory (ZedId, Descrip, CreatedDate, CertificationType, StatusType)
        VALUES (@CurrentZedId, @CustomRemark, GETDATE(), @CurrentCertType, 'Unit moved to Rejection due to Upgradation');

        -- D. ARCHIVE SP (Original Logic)
        EXEC [dbo].[SP_MONITORING_REJECT_CERTIFICATION] 
            @UserId = 'Upgrade_Cleanup_Script', 
            @ZedId = @CurrentZedId, 
            @CertificationType = @CurrentCertType, 
            @RoleId = NULL;

        COMMIT TRAN;
        PRINT 'Successfully processed ' + @CurrentZedId;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRAN;
        PRINT 'Error processing ' + @CurrentZedId + ': ' + ERROR_MESSAGE();
    END CATCH

    FETCH NEXT FROM UpgradeCursor INTO @CurrentZedId, @CurrentCertType;
END

CLOSE UpgradeCursor;
DEALLOCATE UpgradeCursor;
PRINT 'Cleanup Complete.';



END
GO
/****** Object:  StoredProcedure [dbo].[USP_REFRESH_ADMIN_DASHBOARD_STATS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_REFRESH_ADMIN_DASHBOARD_STATS]
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @State varchar(100) = NULL; -- Static cache is global (NULL state)

    UPDATE [ZED_ADMIN_STATS_CACHE]
    SET 
        AssessmentAgencies = (select count(*) from Users where RoleId=2),
        DesktopAssessors = (select count(*) from Users where RoleId=3 and DesktopVerification=1),
        SiteAssessors = (select count(*) from Users where RoleId=3 and SiteVerification=1),
        FinancialAssessors = (select count(*) from Users where RoleId=3 and FinancialVerification=1),
        
        -- Exact Original Queries for Bronze, Silver, Gold
        BronzeCompleted = (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus=6 AND (@State is null or M.StateId=@State)),
        FaBronzeCompleted = (select count(*) from FinancialAssistance where CertificationType='Bronze' and IsApproved=1),
        BronzePending = (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Bronze' and CertificationStatus<6 and CertificationStatus>1 AND (@State is null or M.StateId=@State)),
        
        SilverCompleted = (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=16 AND (@State is null or M.StateId=@State)),
        FaSilverCompleted = (select count(*) from FinancialAssistance where CertificationType='Silver' and IsApproved=1),
        SilverPending = (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus>8 and CertificationStatus<14 AND (@State is null or M.StateId=@State)),
        
        GoldCompleted = (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=16 AND (@State is null or M.StateId=@State)),
        FaGoldCompleted = (select count(*) from FinancialAssistance where CertificationType='Gold' and IsApproved=1),
        GoldPending = (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus>8 and CertificationStatus<14 AND (@State is null or M.StateId=@State)),

        -- Totals using REPLACE logic
        BronzeTotal = (select count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification) where P.Certification='Bronze' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')),
        SilverTotal = (select count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification) where P.Certification='Silver' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')),
        GoldTotal = (select count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'_D',''),concat('_',C.Id),'')) inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification) where P.Certification='Gold' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')),

        -- NC and SA Logic
        SaSilverCompleted = (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=16 AND (@State is null or M.StateId=@State)),
        SaGoldCompleted = (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=16 AND (@State is null or M.StateId=@State)),
        SaSilverNcRaised = (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=14 AND (@State is null or M.StateId=@State)),
        SaGoldNcRaised = (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=14 AND (@State is null or M.StateId=@State)),

        -- Rejected Logic
        BronzeRejected = (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (@State is null or M.StateId=@State)),
        SilverRejected = (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 AND (@State is null or M.StateId=@State)),
        GoldRejected = (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 AND (@State is null or M.StateId=@State)),
        
        LastUpdated = GETDATE()
    WHERE Id = 1;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_UPDATE_DASHBOARD_STATS]    Script Date: 9/19/2026 4:33:27 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_UPDATE_DASHBOARD_STATS]
AS
BEGIN
    SET NOCOUNT ON;

    -- Pre-calculating counts
    DECLARE @Agencies int, @DA int, @SA int, @FA int;
    SELECT 
        @Agencies = SUM(CASE WHEN RoleId = 2 THEN 1 ELSE 0 END),
        @DA = SUM(CASE WHEN RoleId = 3 AND DesktopVerification = 1 THEN 1 ELSE 0 END),
        @SA = SUM(CASE WHEN RoleId = 3 AND SiteVerification = 1 THEN 1 ELSE 0 END),
        @FA = SUM(CASE WHEN RoleId = 3 AND FinancialVerification = 1 THEN 1 ELSE 0 END)
    FROM Users;

    -- Clean old stats
    TRUNCATE TABLE [DASHBOARD_STATS_SUMMARY];

    -- Insert new stats
    INSERT INTO [DASHBOARD_STATS_SUMMARY] (StatKey, StatValue)
    SELECT 'AssessmentAgencies', @Agencies UNION ALL
    SELECT 'DesktopAssessors', @DA UNION ALL
    SELECT 'SiteAssessors', @SA UNION ALL
    SELECT 'FinancialAssessors', @FA;

    -- Adding Certification Stats (Admin Role 7 logic)
    INSERT INTO [DASHBOARD_STATS_SUMMARY] (StatKey, StatValue)
    SELECT 'BronzeCompleted', COUNT(*) FROM MsmeCertifications WHERE Certification = 'Bronze' AND CertificationStatus = 6;
    -- ... Add other counts here similarly (Silver, Gold, Rejected, etc.)
    -- Note: Add all Role 7 SELECT counts here as rows
END
GO
